-- Neurology question bank: exactly 800 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Neurology/12-Cranial-Nerves.html
--   Notes/Neurology/Autonomic-Nervous-System.html
--   Notes/Neurology/Cerebral-Palsy.html
--   Notes/Neurology/Cerebral-Aneurysms.html
--   Notes/Neurology/Clonus.html
--   Notes/Neurology/Glasgow-Coma-Scale.html
--   Notes/Neurology/Increased-ICP.html
--   Notes/Neurology/Multiple-Sclerosis.html
--   Notes/Neurology/Neuro-Imaging-Diagnostics.html
--   Notes/Neurology/Orientation.html
--   Notes/Neurology/Parkinsons-Disease.html
--   Notes/Neurology/Seizure-Disorders.html
--   Notes/Neurology/Spinal-Cord-Injury.html
--   Notes/Neurology/Stroke.html
--   Notes/Neurology/Sympathetic-vs-Parasympathetic.html
--   Notes/Neurology/Vertigo-Menieres.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (800) exist after insert.
BEGIN;

CREATE TEMP TABLE _neuro_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _neuro_sources (source_key, source_path, category) VALUES
  ('cranial', 'Notes/Neurology/12-Cranial-Nerves.html', 'Neurology NCLEX seed v1 - cranial nerves'),
  ('ans', 'Notes/Neurology/Autonomic-Nervous-System.html', 'Neurology NCLEX seed v1 - autonomic nervous system'),
  ('cp', 'Notes/Neurology/Cerebral-Palsy.html', 'Neurology NCLEX seed v1 - cerebral palsy'),
  ('aneurysm', 'Notes/Neurology/Cerebral-Aneurysms.html', 'Neurology NCLEX seed v1 - cerebral aneurysms'),
  ('clonus', 'Notes/Neurology/Clonus.html', 'Neurology NCLEX seed v1 - clonus'),
  ('gcs', 'Notes/Neurology/Glasgow-Coma-Scale.html', 'Neurology NCLEX seed v1 - glasgow coma scale'),
  ('icp', 'Notes/Neurology/Increased-ICP.html', 'Neurology NCLEX seed v1 - increased ICP'),
  ('ms', 'Notes/Neurology/Multiple-Sclerosis.html', 'Neurology NCLEX seed v1 - multiple sclerosis'),
  ('imaging', 'Notes/Neurology/Neuro-Imaging-Diagnostics.html', 'Neurology NCLEX seed v1 - neuro imaging and diagnostics'),
  ('orientation', 'Notes/Neurology/Orientation.html', 'Neurology NCLEX seed v1 - orientation'),
  ('parkinsons', 'Notes/Neurology/Parkinsons-Disease.html', 'Neurology NCLEX seed v1 - parkinsons disease'),
  ('seizures', 'Notes/Neurology/Seizure-Disorders.html', 'Neurology NCLEX seed v1 - seizure disorders'),
  ('sci', 'Notes/Neurology/Spinal-Cord-Injury.html', 'Neurology NCLEX seed v1 - spinal cord injury'),
  ('stroke', 'Notes/Neurology/Stroke.html', 'Neurology NCLEX seed v1 - stroke'),
  ('symp_para', 'Notes/Neurology/Sympathetic-vs-Parasympathetic.html', 'Neurology NCLEX seed v1 - sympathetic vs parasympathetic'),
  ('vertigo', 'Notes/Neurology/Vertigo-Menieres.html', 'Neurology NCLEX seed v1 - vertigo and menieres disease');

CREATE TEMP TABLE _neuro_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _neuro_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'neurology'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Neurology"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'neurology'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _neuro_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Neurology subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Neurology points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _neuro_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Neurology seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _neuro_seed_map) <> 16 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 16 note mappings, found %.',
      (SELECT count(*) FROM _neuro_seed_map);
  END IF;

  INSERT INTO _neuro_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _neuro_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('cranial', 1, 'A client is admitted after a head injury. When the nurse holds a familiar scent under each nostril separately, the client cannot identify it. The nurse documents dysfunction of which cranial nerve?', '[{"id": "a", "text": "CN II (optic)"}, {"id": "b", "text": "CN I (olfactory)"}, {"id": "c", "text": "CN V (trigeminal)"}, {"id": "d", "text": "CN VII (facial)"}]'::jsonb, '["b"]', 'CN I (olfactory) carries smell, and its loss (anosmia) is seen in head trauma. CN II is the optic nerve, which carries vision rather than smell.'),
  ('cranial', 2, 'During a fundoscopic examination of a client with increased intracranial pressure, the nurse notes papilledema. This finding involves which cranial nerve?', '[{"id": "a", "text": "CN II (optic)"}, {"id": "b", "text": "CN III (oculomotor)"}, {"id": "c", "text": "CN VI (abducens)"}, {"id": "d", "text": "CN VIII (vestibulocochlear)"}]'::jsonb, '["a"]', 'Papilledema from increased ICP is seen on fundoscopy and is a key point for CN II, the optic nerve. CN III controls most eye movement and pupil constriction but is not the nerve viewed for papilledema.'),
  ('cranial', 3, 'A client with a head injury has a right pupil that is fixed and dilated, a drooping right eyelid, and a right eye that rests down and out. The nurse recognizes palsy of which cranial nerve?', '[{"id": "a", "text": "CN IV (trochlear)"}, {"id": "b", "text": "CN VI (abducens)"}, {"id": "c", "text": "CN III (oculomotor)"}, {"id": "d", "text": "CN II (optic)"}]'::jsonb, '["c"]', 'A fixed dilated pupil, ptosis, and an eye deviated down and out indicate CN III (oculomotor) palsy. CN IV damage instead causes diplopia on downward gaze with a compensatory head tilt.'),
  ('cranial', 4, 'A client reports double vision that is worst when walking down stairs and has begun tilting the head to compensate. The nurse suspects damage to which cranial nerve?', '[{"id": "a", "text": "CN VI (abducens)"}, {"id": "b", "text": "CN III (oculomotor)"}, {"id": "c", "text": "CN II (optic)"}, {"id": "d", "text": "CN IV (trochlear)"}]'::jsonb, '["d"]', 'CN IV (trochlear) damage causes diplopia on downward gaze, such as on stairs, with a head tilt to compensate. CN VI damage causes inability to abduct the eye (outward gaze).'),
  ('cranial', 5, 'During extra-ocular movement testing, a client''s left eye cannot move outward toward the left ear, and the client reports double vision. Which cranial nerve is most likely damaged?', '[{"id": "a", "text": "CN VI (abducens)"}, {"id": "b", "text": "CN IV (trochlear)"}, {"id": "c", "text": "CN V (trigeminal)"}, {"id": "d", "text": "CN VII (facial)"}]'::jsonb, '["a"]', 'CN VI (abducens) controls the lateral rectus for eye abduction, so damage leaves the eye unable to abduct, with diplopia. CN IV controls downward/inward rotation, not outward gaze.'),
  ('cranial', 6, 'A client reports episodes of severe, stabbing pain on one side of the face that are triggered by chewing. The nurse anticipates a prescription for which type of medication?', '[{"id": "a", "text": "An antibiotic"}, {"id": "b", "text": "An anticoagulant"}, {"id": "c", "text": "An anticonvulsant"}, {"id": "d", "text": "An antiemetic"}]'::jsonb, '["c"]', 'Severe unilateral facial pain triggered by chewing indicates trigeminal neuralgia (CN V), which is managed with anticonvulsants such as carbamazepine. The other drug classes are not the listed treatment for this condition.'),
  ('cranial', 7, 'A client has new left-sided facial drooping. The lower face droops, but the client can wrinkle the forehead on both sides. The nurse interprets this as most consistent with which condition?', '[{"id": "a", "text": "Bell''s palsy (peripheral CN VII lesion)"}, {"id": "b", "text": "Trigeminal neuralgia (CN V lesion)"}, {"id": "c", "text": "Hypoglossal injury (CN XII lesion)"}, {"id": "d", "text": "Stroke (central CN VII lesion)"}]'::jsonb, '["d"]', 'Unilateral facial droop with the forehead spared (upper facial muscles intact, lower face droops) indicates a central CN VII lesion such as stroke. Bell''s palsy is peripheral and involves the forehead as well.'),
  ('cranial', 8, 'A client''s entire right side of the face droops, including the forehead, and the client cannot raise the right eyebrow. The nurse recognizes this as consistent with which condition?', '[{"id": "a", "text": "Bell''s palsy (peripheral CN VII lesion)"}, {"id": "b", "text": "Stroke (central CN VII lesion)"}, {"id": "c", "text": "Trigeminal neuralgia (CN V lesion)"}, {"id": "d", "text": "Oculomotor palsy (CN III lesion)"}]'::jsonb, '["a"]', 'A peripheral CN VII lesion such as Bell''s palsy causes the entire ipsilateral face to droop, including the forehead. A central (stroke) lesion spares the forehead.'),
  ('cranial', 9, 'A client recovering from a brainstem injury is found to have an absent gag reflex. Which action should the nurse take first?', '[{"id": "a", "text": "Offer small sips of water"}, {"id": "b", "text": "Institute NPO status"}, {"id": "c", "text": "Place the client flat in bed"}, {"id": "d", "text": "Give oral medications in applesauce"}]'::jsonb, '["b"]', 'No gag reflex means high aspiration risk, so the nurse institutes NPO status, elevates the HOB, requests an SLP swallowing evaluation, and notifies the provider. Offering anything by mouth or lowering the head of bed works against these precautions.'),
  ('cranial', 10, 'When the nurse assesses a client''s gag reflex, none is present, and the client reports trouble swallowing. These findings indicate dysfunction of which cranial nerves?', '[{"id": "a", "text": "CN VII and VIII"}, {"id": "b", "text": "CN V and VII"}, {"id": "c", "text": "CN XI and XII"}, {"id": "d", "text": "CN IX and X"}]'::jsonb, '["d"]', 'Loss of the gag reflex with dysphagia reflects damage to CN IX and X together. CN VII and VIII serve facial expression/taste and hearing/balance, not the gag reflex.'),
  ('cranial', 11, 'Two days after a cervical lymph node biopsy, a client cannot shrug the left shoulder against resistance. The nurse suspects injury to which cranial nerve?', '[{"id": "a", "text": "CN X (vagus)"}, {"id": "b", "text": "CN XI (accessory)"}, {"id": "c", "text": "CN XII (hypoglossal)"}, {"id": "d", "text": "CN IX (glossopharyngeal)"}]'::jsonb, '["b"]', 'CN XI (accessory) supplies the trapezius for shoulder elevation and is often injured by neck surgery or lymph node biopsy. CN X damage causes hoarseness and dysphagia rather than loss of shoulder shrug.'),
  ('cranial', 12, 'When asked to stick out the tongue, a client''s tongue deviates to the left. How should the nurse interpret this finding?', '[{"id": "a", "text": "A lesion of the left hypoglossal nerve"}, {"id": "b", "text": "A lesion of the right hypoglossal nerve"}, {"id": "c", "text": "A lesion of the left glossopharyngeal nerve"}, {"id": "d", "text": "A lesion of the right facial nerve"}]'::jsonb, '["a"]', 'With CN XII (hypoglossal) damage, the tongue deviates toward the side of the lesion, so leftward deviation points to a left-sided lesion. Choosing the right side reverses the direction of deviation.'),
  ('cranial', 13, 'A client with vestibulocochlear nerve damage reports vertigo and has nystagmus and hearing loss. Which nursing assessment is the priority for this client?', '[{"id": "a", "text": "Assessing the corneal reflex"}, {"id": "b", "text": "Assessing jaw strength"}, {"id": "c", "text": "Assessing fall risk"}, {"id": "d", "text": "Assessing shoulder shrug strength"}]'::jsonb, '["c"]', 'Vertigo, nystagmus, and hearing loss indicate CN VIII damage, and the key nursing action is to assess fall risk. Corneal reflex and jaw strength test CN V, not CN VIII.'),
  ('cranial', 14, 'Which assessment should the nurse use to evaluate the hearing function of CN VIII?', '[{"id": "a", "text": "Snellen chart"}, {"id": "b", "text": "Corneal reflex"}, {"id": "c", "text": "Resisted shoulder shrug"}, {"id": "d", "text": "Whisper test"}]'::jsonb, '["d"]', 'CN VIII is assessed with the whisper test, Rinne/Weber tests, and the Romberg test for balance. The Snellen chart assesses visual acuity (CN II).'),
  ('cranial', 15, 'A nurse is preparing to test a client''s olfactory nerve. Which technique is correct?', '[{"id": "a", "text": "Have the client identify a familiar scent with both nostrils open"}, {"id": "b", "text": "Have the client identify a familiar scent with each nostril separately"}, {"id": "c", "text": "Have the client identify a taste placed on the front of the tongue"}, {"id": "d", "text": "Have the client read the letters on a Snellen eye chart"}]'::jsonb, '["b"]', 'CN I is tested by asking the client to identify a familiar scent, such as coffee or soap, with each nostril separately. Testing both nostrils together does not assess each side, and taste on the front of the tongue is a CN VII function.'),
  ('cranial', 16, 'Which assessment evaluates the function of CN II?', '[{"id": "a", "text": "Visual fields by confrontation"}, {"id": "b", "text": "''H'' pattern eye tracking"}, {"id": "c", "text": "Corneal reflex"}, {"id": "d", "text": "Romberg test"}]'::jsonb, '["a"]', 'CN II is assessed with visual acuity (Snellen chart), visual fields by confrontation, and the pupillary light reflex. ''H'' pattern tracking assesses extra-ocular movements controlled by CN III, IV, and VI.'),
  ('cranial', 17, 'The nurse asks a client to follow a penlight with the eyes through an ''H'' pattern. Which cranial nerves is the nurse assessing?', '[{"id": "a", "text": "CN II, III, and IV"}, {"id": "b", "text": "CN IV, V, and VI"}, {"id": "c", "text": "CN III, IV, and VI"}, {"id": "d", "text": "CN II, VI, and VIII"}]'::jsonb, '["c"]', 'Extra-ocular movements using ''H'' pattern tracking assess CN III, IV, and VI. CN II is the optic nerve for vision, and CN V is the trigeminal nerve for facial sensation and chewing.'),
  ('cranial', 18, 'While palpating the client''s masseter muscles, the nurse asks the client to bite down hard. Which cranial nerve is the nurse assessing?', '[{"id": "a", "text": "CN VII (facial)"}, {"id": "b", "text": "CN XII (hypoglossal)"}, {"id": "c", "text": "CN XI (accessory)"}, {"id": "d", "text": "CN V (trigeminal)"}]'::jsonb, '["d"]', 'The motor portion of CN V (trigeminal) controls the chewing muscles, including the masseter, so jaw strength (bite down) assesses CN V. CN VII controls facial expression rather than chewing.'),
  ('cranial', 19, 'The nurse is testing a client''s corneal reflex. Which nerve branch is being assessed?', '[{"id": "a", "text": "V2 maxillary branch of CN V"}, {"id": "b", "text": "V1 ophthalmic branch of CN V"}, {"id": "c", "text": "V3 mandibular branch of CN V"}, {"id": "d", "text": "Cochlear branch of CN VIII"}]'::jsonb, '["b"]', 'The corneal reflex assesses the V1 (ophthalmic) branch of the trigeminal nerve. V2 and V3 are the maxillary and mandibular branches, and the cochlear branch of CN VIII serves hearing.'),
  ('cranial', 20, 'Which instruction should the nurse give a client to assess the function of CN VII?', '[{"id": "a", "text": "\"Shrug your shoulders against my hands.\""}, {"id": "b", "text": "\"Stick out your tongue and move it side to side.\""}, {"id": "c", "text": "\"Follow my finger with your eyes only.\""}, {"id": "d", "text": "\"Raise your eyebrows and puff out your cheeks.\""}]'::jsonb, '["d"]', 'CN VII is assessed by having the client smile, raise the eyebrows, puff the cheeks, and close the eyes tightly while observing symmetry. Protruding the tongue side to side assesses CN XII.'),
  ('cranial', 21, 'After neck surgery, a client has a newly hoarse voice and difficulty swallowing. Injury to which cranial nerve is most consistent with these findings?', '[{"id": "a", "text": "CN XI (accessory)"}, {"id": "b", "text": "CN X (vagus)"}, {"id": "c", "text": "CN XII (hypoglossal)"}, {"id": "d", "text": "CN VII (facial)"}]'::jsonb, '["b"]', 'CN X (vagus) provides motor function to the pharynx and larynx, and damage causes hoarseness and dysphagia. CN XI damage causes inability to shrug the shoulder or turn the head instead.'),
  ('cranial', 22, 'A client with a right-sided facial droop also reports loss of taste on the front part of the tongue. Which cranial nerve is involved?', '[{"id": "a", "text": "CN IX (glossopharyngeal)"}, {"id": "b", "text": "CN V (trigeminal)"}, {"id": "c", "text": "CN VII (facial)"}, {"id": "d", "text": "CN XII (hypoglossal)"}]'::jsonb, '["c"]', 'CN VII (facial) controls facial expression and carries taste from the anterior 2/3 of the tongue. CN IX carries taste from the posterior 1/3 of the tongue.'),
  ('cranial', 23, 'Taste sensation from the posterior one-third of the tongue is carried by which cranial nerve?', '[{"id": "a", "text": "CN VII (facial)"}, {"id": "b", "text": "CN XII (hypoglossal)"}, {"id": "c", "text": "CN V (trigeminal)"}, {"id": "d", "text": "CN IX (glossopharyngeal)"}]'::jsonb, '["d"]', 'CN IX (glossopharyngeal) carries taste from the posterior 1/3 of the tongue. CN VII carries taste from the anterior 2/3, so it is the most tempting but incorrect choice.'),
  ('cranial', 24, 'Which cranial nerve is classified as purely sensory?', '[{"id": "a", "text": "CN V (trigeminal)"}, {"id": "b", "text": "CN VIII (vestibulocochlear)"}, {"id": "c", "text": "CN VII (facial)"}, {"id": "d", "text": "CN XII (hypoglossal)"}]'::jsonb, '["b"]', 'In the type sequence S S M M B M B S B B M M for CN I-XII, CN VIII is S (sensory) for hearing and balance. CN V and VII are both (mixed), and CN XII is motor.'),
  ('cranial', 25, 'Which cranial nerve is classified as mixed, having both sensory and motor functions?', '[{"id": "a", "text": "CN III (oculomotor)"}, {"id": "b", "text": "CN VI (abducens)"}, {"id": "c", "text": "CN XI (accessory)"}, {"id": "d", "text": "CN V (trigeminal)"}]'::jsonb, '["d"]', 'CN V (trigeminal) is mixed: sensory to the face, teeth, and sinuses, and motor to the chewing muscles. CN III, VI, and XI are all motor nerves.'),
  ('cranial', 26, 'A client is diagnosed with an accessory nerve injury. The nurse documents a deficit of which cranial nerve number?', '[{"id": "a", "text": "CN IX"}, {"id": "b", "text": "CN X"}, {"id": "c", "text": "CN XI"}, {"id": "d", "text": "CN XII"}]'::jsonb, '["c"]', 'The accessory nerve is CN XI. CN IX is the glossopharyngeal, CN X the vagus, and CN XII the hypoglossal nerve.'),
  ('cranial', 27, 'Imaging shows a lesion confined to a client''s midbrain. Which cranial nerves are most likely to be affected?', '[{"id": "a", "text": "CN I and II"}, {"id": "b", "text": "CN III and IV"}, {"id": "c", "text": "CN IX and X"}, {"id": "d", "text": "CN XI and XII"}]'::jsonb, '["b"]', 'CN III (oculomotor) and CN IV (trochlear) originate in the midbrain. CN IX through XII originate in the medulla oblongata.'),
  ('cranial', 28, 'A client suddenly develops facial numbness, inability to abduct one eye, facial droop, and hearing loss. How should the nurse interpret this combination of findings?', '[{"id": "a", "text": "Possible brainstem stroke involving the pons"}, {"id": "b", "text": "Isolated Bell''s palsy of the facial nerve"}, {"id": "c", "text": "Midbrain lesion involving CN III and IV"}, {"id": "d", "text": "Medullary lesion involving CN IX and X"}]'::jsonb, '["a"]', 'CN V, VI, VII, and VIII all originate in the pons, and multiple CN deficits from the same brainstem region are treated as a brainstem stroke until proven otherwise. Bell''s palsy affects only CN VII.'),
  ('cranial', 29, 'A client has a lesion of the medulla oblongata. Which finding should the nurse anticipate?', '[{"id": "a", "text": "Loss of the sense of smell"}, {"id": "b", "text": "Inability to abduct the eye"}, {"id": "c", "text": "Absent gag reflex"}, {"id": "d", "text": "Diplopia on downward gaze"}]'::jsonb, '["c"]', 'CN IX and X, which together produce the gag reflex, originate in the medulla oblongata. Inability to abduct the eye reflects CN VI, which originates in the pons.'),
  ('cranial', 30, 'Which cranial nerve provides parasympathetic innervation to the heart, lungs, and GI tract?', '[{"id": "a", "text": "CN VII (facial)"}, {"id": "b", "text": "CN IX (glossopharyngeal)"}, {"id": "c", "text": "CN III (oculomotor)"}, {"id": "d", "text": "CN X (vagus)"}]'::jsonb, '["d"]', 'CN X (vagus) provides parasympathetic supply to the heart, lungs, and GI tract. CN VII''s parasympathetic fibers go to the lacrimal and salivary glands instead.'),
  ('cranial', 31, 'In addition to facial expression, which function is served by CN VII?', '[{"id": "a", "text": "Lacrimal and salivary gland secretion"}, {"id": "b", "text": "Elevation of the shoulders"}, {"id": "c", "text": "Taste on the posterior tongue"}, {"id": "d", "text": "Contraction of the chewing muscles"}]'::jsonb, '["a"]', 'CN VII carries parasympathetic fibers to the lacrimal and salivary glands, plus taste from the anterior 2/3 of the tongue. Posterior tongue taste is CN IX, and chewing is CN V.'),
  ('cranial', 32, 'A client reports weakness when chewing food, and the nurse notes reduced jaw strength. Which cranial nerve should the nurse suspect is affected?', '[{"id": "a", "text": "CN VII (facial)"}, {"id": "b", "text": "CN V (trigeminal)"}, {"id": "c", "text": "CN IX (glossopharyngeal)"}, {"id": "d", "text": "CN XII (hypoglossal)"}]'::jsonb, '["b"]', 'CN V (trigeminal) provides face sensation and motor function for chewing. CN VII controls facial expression, and CN XII controls tongue movement.'),
  ('cranial', 33, 'Which list correctly names the three branches of the trigeminal nerve?', '[{"id": "a", "text": "Cochlear, vestibular, mandibular"}, {"id": "b", "text": "Ophthalmic, vestibular, maxillary"}, {"id": "c", "text": "Ophthalmic, maxillary, mandibular"}, {"id": "d", "text": "Cochlear, maxillary, ophthalmic"}]'::jsonb, '["c"]', 'The trigeminal nerve has three branches: V1 ophthalmic, V2 maxillary, and V3 mandibular. Cochlear and vestibular are the branches of CN VIII.'),
  ('cranial', 34, 'A client has problems with balance and equilibrium, but hearing tests are normal. Which nerve structure is most likely affected?', '[{"id": "a", "text": "Cochlear branch of CN VIII"}, {"id": "b", "text": "Mandibular branch of CN V"}, {"id": "c", "text": "Ophthalmic branch of CN V"}, {"id": "d", "text": "Vestibular branch of CN VIII"}]'::jsonb, '["d"]', 'The vestibular branch of CN VIII serves balance and equilibrium, while the cochlear branch serves hearing. Normal hearing with poor balance points to the vestibular branch.'),
  ('cranial', 35, 'The nurse performs a Romberg test on a client. Which cranial nerve function is the nurse assessing?', '[{"id": "a", "text": "Balance (CN VIII)"}, {"id": "b", "text": "Head rotation (CN XI)"}, {"id": "c", "text": "Vision (CN II)"}, {"id": "d", "text": "Downward gaze (CN IV)"}]'::jsonb, '["a"]', 'The Romberg test assesses balance as part of the CN VIII examination. Head rotation is tested by resisted head turn for CN XI.'),
  ('cranial', 36, 'A client has known damage to CN VIII. Which symptom would the nurse expect the client to report?', '[{"id": "a", "text": "Drooping eyelid"}, {"id": "b", "text": "Hoarse voice"}, {"id": "c", "text": "Tinnitus"}, {"id": "d", "text": "Tongue weakness"}]'::jsonb, '["c"]', 'CN VIII damage causes sensorineural hearing loss, tinnitus, vertigo, and nystagmus. A drooping eyelid (ptosis) reflects CN III damage, and hoarseness reflects CN X damage.'),
  ('cranial', 37, 'Which function is controlled by CN III (oculomotor)?', '[{"id": "a", "text": "Outward (lateral) eye movement"}, {"id": "b", "text": "Downward and inward eye rotation"}, {"id": "c", "text": "Sensation of the cornea"}, {"id": "d", "text": "Constriction of the pupil"}]'::jsonb, '["d"]', 'CN III controls most eye movement, pupil constriction, and eyelid elevation. Outward movement is CN VI, and downward/inward rotation is CN IV.'),
  ('cranial', 38, 'The trochlear nerve (CN IV) innervates which muscle?', '[{"id": "a", "text": "Lateral rectus"}, {"id": "b", "text": "Superior oblique"}, {"id": "c", "text": "Masseter"}, {"id": "d", "text": "Sternocleidomastoid"}]'::jsonb, '["b"]', 'CN IV supplies the superior oblique muscle for downward/inward eye rotation. The lateral rectus is supplied by CN VI.'),
  ('cranial', 39, 'The abducens nerve (CN VI) is responsible for which eye function?', '[{"id": "a", "text": "Constriction of the pupil"}, {"id": "b", "text": "Downward and inward rotation"}, {"id": "c", "text": "Outward gaze via the lateral rectus"}, {"id": "d", "text": "Elevation of the eyelid"}]'::jsonb, '["c"]', 'CN VI controls the lateral rectus muscle for eye abduction (outward gaze). Pupil constriction and eyelid elevation are CN III functions.'),
  ('cranial', 40, 'The nurse places a hand against the side of a client''s face and asks the client to turn the head against resistance. The client cannot do so. Which muscle and nerve are affected?', '[{"id": "a", "text": "Trapezius; CN XII"}, {"id": "b", "text": "Sternocleidomastoid; CN XI"}, {"id": "c", "text": "Masseter; CN V"}, {"id": "d", "text": "Sternocleidomastoid; CN X"}]'::jsonb, '["b"]', 'CN XI (accessory) supplies the sternocleidomastoid for head rotation and the trapezius for shoulder elevation. CN X supplies the pharynx and larynx, not the SCM.'),
  ('cranial', 41, 'Which pair of findings would the nurse expect in a client with damage to CN XII?', '[{"id": "a", "text": "Dysarthria and tongue deviation"}, {"id": "b", "text": "Hoarseness and dysphagia"}, {"id": "c", "text": "Ptosis and a dilated pupil"}, {"id": "d", "text": "Tinnitus and vertigo"}]'::jsonb, '["a"]', 'CN XII (hypoglossal) damage causes the tongue to deviate toward the side of the lesion and dysarthria. Hoarseness and dysphagia indicate CN X damage.'),
  ('cranial', 42, 'A nursing student is reviewing the cranial nerves. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"The olfactory nerve is a sensory nerve for smell.\""}, {"id": "b", "text": "\"The optic nerve carries vision from retina to occipital lobe.\""}, {"id": "c", "text": "\"The abducens nerve is a mixed nerve that controls chewing.\""}, {"id": "d", "text": "\"The hypoglossal nerve is a motor nerve for tongue movement.\""}]'::jsonb, '["c"]', 'The abducens nerve (CN VI) is a motor nerve that controls the lateral rectus for outward gaze; chewing is controlled by the trigeminal nerve. The other statements correctly describe CN I, II, and XII.'),
  ('cranial', 43, 'A new nurse is caring for a client who has no gag reflex. Which action by the new nurse requires the charge nurse to intervene?', '[{"id": "a", "text": "Elevating the head of the bed"}, {"id": "b", "text": "Requesting an SLP swallowing evaluation"}, {"id": "c", "text": "Notifying the provider of the finding"}, {"id": "d", "text": "Offering sips of water to test swallowing"}]'::jsonb, '["d"]', 'An absent gag reflex requires NPO status because of high aspiration risk, so offering water is unsafe. Elevating the HOB, requesting an SLP evaluation, and notifying the provider are all expected actions.'),
  ('cranial', 44, 'Which group contains only motor cranial nerves?', '[{"id": "a", "text": "CN III, IV, and VI"}, {"id": "b", "text": "CN I, II, and VIII"}, {"id": "c", "text": "CN V, VII, and IX"}, {"id": "d", "text": "CN III, V, and VII"}]'::jsonb, '["a"]', 'In the type sequence for CN I-XII (S S M M B M B S B B M M), CN III, IV, and VI are motor. CN I, II, and VIII are sensory, and CN V, VII, and IX are both (mixed).'),
  ('cranial', 45, 'A client has a new facial droop. Which instruction best helps the nurse distinguish a central (stroke) cause from a peripheral (Bell''s palsy) cause?', '[{"id": "a", "text": "\"Smile as widely as you can.\""}, {"id": "b", "text": "\"Raise your eyebrows.\""}, {"id": "c", "text": "\"Stick out your tongue.\""}, {"id": "d", "text": "\"Bite down hard.\""}]'::jsonb, '["b"]', 'The distinction depends on the forehead: it is spared in a central (stroke) lesion and involved in a peripheral (Bell''s palsy) lesion, so raising the eyebrows tests it. The lower face droops in both, so smiling does not distinguish them.'),
  ('cranial', 46, 'Which statement accurately describes the cranial nerves?', '[{"id": "a", "text": "They exit the spinal cord to serve the head and neck."}, {"id": "b", "text": "They are 10 pairs that serve only the face."}, {"id": "c", "text": "They are 12 pairs that bypass the spinal cord entirely."}, {"id": "d", "text": "They carry only sensory information to the brain."}]'::jsonb, '["c"]', 'The 12 cranial nerve pairs bypass the spinal cord and emerge directly from the brainstem and brain. They include sensory, motor, and mixed nerves, so they do not carry only sensory information.'),
  ('cranial', 47, 'How does a motor cranial nerve differ from a sensory cranial nerve?', '[{"id": "a", "text": "It carries information to the brain."}, {"id": "b", "text": "It carries smell, vision, and hearing."}, {"id": "c", "text": "It has both sensory and motor fibers."}, {"id": "d", "text": "It carries commands from the brain."}]'::jsonb, '["d"]', 'Motor nerves carry commands from the brain, such as eye movement and tongue movement. Sensory nerves carry information to the brain, and mixed nerves have both functions.'),
  ('cranial', 48, 'Which cranial nerve is considered the most widespread in the body?', '[{"id": "a", "text": "Trigeminal (CN V)"}, {"id": "b", "text": "Facial (CN VII)"}, {"id": "c", "text": "Vagus (CN X)"}, {"id": "d", "text": "Glossopharyngeal (CN IX)"}]'::jsonb, '["c"]', 'The vagus nerve (CN X) is the most widespread cranial nerve, serving the heart, lungs, GI tract, pharynx, and larynx. The trigeminal nerve serves the face and chewing muscles only.'),
  ('cranial', 49, 'A client has a lesion affecting the optic nerve. Which finding is the nurse most likely to observe?', '[{"id": "a", "text": "Visual field defects"}, {"id": "b", "text": "Ptosis of the eyelid"}, {"id": "c", "text": "Diplopia on downward gaze"}, {"id": "d", "text": "Inability to shrug"}]'::jsonb, '["a"]', 'Visual field defects are a key finding with CN II (optic) involvement. Ptosis reflects CN III damage, and diplopia on downward gaze reflects CN IV damage.'),
  ('cranial', 50, 'A nurse finds that a client has a new fixed, dilated pupil with ptosis and an eye deviated down and out. Which condition does the nurse recognize as a possible cause?', '[{"id": "a", "text": "Bell''s palsy"}, {"id": "b", "text": "Brain herniation"}, {"id": "c", "text": "Trigeminal neuralgia"}, {"id": "d", "text": "Lymph node biopsy"}]'::jsonb, '["b"]', 'This picture is oculomotor (CN III) palsy, which can result from herniation or aneurysm. Bell''s palsy affects CN VII, and lymph node biopsy is associated with CN XI injury.'),
  ('ans', 1, 'A client is brought to the emergency department after a motor vehicle crash and is anxious and in pain. Which pupil finding should the nurse expect as part of the body''s stress response?', '[{"id": "a", "text": "Bilaterally dilated pupils"}, {"id": "b", "text": "Bilaterally constricted pupils"}, {"id": "c", "text": "Increased tearing of both eyes"}, {"id": "d", "text": "Pupils that remain unchanged"}]'::jsonb, '["a"]', 'Trauma and pain trigger a sympathetic surge, whose signs include dilated pupils (mydriasis). Constricted pupils (miosis) are a parasympathetic effect.'),
  ('ans', 2, 'A client awaiting emergency surgery states, "I''m terrified." Which heart rate change should the nurse anticipate from this acute stress?', '[{"id": "a", "text": "Bradycardia from sympathetic activation"}, {"id": "b", "text": "Tachycardia from sympathetic activation"}, {"id": "c", "text": "Bradycardia from parasympathetic activation"}, {"id": "d", "text": "Tachycardia from parasympathetic activation"}]'::jsonb, '["b"]', 'Acute stress activates the sympathetic (fight-or-flight) division, which increases heart rate (tachycardia). The parasympathetic division decreases heart rate.'),
  ('ans', 3, 'A client is admitted with a suspected cocaine overdose. Which set of assessment findings is most consistent with this condition?', '[{"id": "a", "text": "Bradycardia, hypotension, and salivation"}, {"id": "b", "text": "Miosis, tearing, and vomiting"}, {"id": "c", "text": "Tachycardia, hypertension, and agitation"}, {"id": "d", "text": "Bronchospasm, urination, and bradycardia"}]'::jsonb, '["c"]', 'Cocaine/amphetamine overdose causes extreme SNS activation, with signs of tachycardia, hypertension, dilated pupils, and agitation. The other options describe parasympathetic excess.'),
  ('ans', 4, 'A farmworker is brought in after heavy exposure to an organophosphate pesticide. Which findings should the nurse expect?', '[{"id": "a", "text": "Dry mouth, urinary retention, and constipation"}, {"id": "b", "text": "Dilated pupils, tachycardia, and agitation"}, {"id": "c", "text": "Bronchodilation, tremor, and tachycardia"}, {"id": "d", "text": "Salivation, urination, and vomiting"}]'::jsonb, '["d"]', 'Organophosphate poisoning produces the SLUDGE cholinergic toxidrome (excess PNS), including salivation, urination, and emesis. Dry mouth and urinary retention are anticholinergic effects.'),
  ('ans', 5, 'A client with organophosphate poisoning is drooling, vomiting, and incontinent of urine. Which medication should the nurse anticipate the provider will order as the antidote?', '[{"id": "a", "text": "Atropine"}, {"id": "b", "text": "Bethanechol"}, {"id": "c", "text": "Metoprolol"}, {"id": "d", "text": "Pilocarpine"}]'::jsonb, '["a"]', 'Atropine, an anticholinergic, is the antidote for the SLUDGE cholinergic toxidrome. Bethanechol and pilocarpine are cholinergic agonists that would worsen excess PNS effects.'),
  ('ans', 6, 'A client with suspected organophosphate exposure is being assessed. Which cardiovascular findings would the nurse expect?', '[{"id": "a", "text": "Tachycardia and hypertension"}, {"id": "b", "text": "Bradycardia and hypotension"}, {"id": "c", "text": "Tachycardia and hypotension"}, {"id": "d", "text": "Bradycardia and hypertension"}]'::jsonb, '["b"]', 'Organophosphate poisoning causes parasympathetic excess, whose signs include bradycardia and hypotension. Tachycardia and hypertension indicate a sympathetic surge.'),
  ('ans', 7, 'A client faints while having blood drawn, and the event is described as a vasovagal response. This episode is best explained by which autonomic state?', '[{"id": "a", "text": "Sympathetic surge"}, {"id": "b", "text": "Beta-receptor stimulation"}, {"id": "c", "text": "Parasympathetic excess"}, {"id": "d", "text": "Alpha-receptor stimulation"}]'::jsonb, '["c"]', 'Vagal (vasovagal) syncope is listed as a parasympathetic excess state, with bradycardia and hypotension. A sympathetic surge raises heart rate and blood pressure.'),
  ('ans', 8, 'A client develops anaphylaxis after receiving an antibiotic. Which medication should the nurse prepare to administer first?', '[{"id": "a", "text": "Antihistamine intravenously"}, {"id": "b", "text": "Corticosteroid intravenously"}, {"id": "c", "text": "Atropine intravenously"}, {"id": "d", "text": "Epinephrine intramuscularly"}]'::jsonb, '["d"]', 'Epinephrine IM is first-line for anaphylaxis; antihistamines, corticosteroids, fluids, and oxygen follow, but epinephrine is always first.'),
  ('ans', 9, 'A nurse gives epinephrine to a client in anaphylaxis. Which combination of effects explains why this drug is effective?', '[{"id": "a", "text": "Vasoconstriction and bronchodilation"}, {"id": "b", "text": "Vasodilation and bronchoconstriction"}, {"id": "c", "text": "Vasodilation and bronchodilation"}, {"id": "d", "text": "Vasoconstriction and bronchoconstriction"}]'::jsonb, '["a"]', 'Epinephrine stimulates alpha and beta receptors, causing vasoconstriction plus bronchodilation. Bronchoconstriction and vasodilation are parasympathetic effects.'),
  ('ans', 10, 'A nurse is preparing intramuscular epinephrine for a client in anaphylaxis. Which concentration is appropriate for this route?', '[{"id": "a", "text": "1:10,000"}, {"id": "b", "text": "1:1000"}, {"id": "c", "text": "1:100"}, {"id": "d", "text": "1:100,000"}]'::jsonb, '["b"]', 'First-line anaphylaxis treatment is epinephrine IM at the 1:1000 concentration; the 1:10,000 concentration is the IV form.'),
  ('ans', 11, 'Two epinephrine products are stocked on a unit. Before giving epinephrine, which nursing action is the priority safety check?', '[{"id": "a", "text": "Confirm 1:10,000 for IM or 1:1000 for IV"}, {"id": "b", "text": "Use either strength for any route"}, {"id": "c", "text": "Confirm 1:1000 for IM or 1:10,000 for IV"}, {"id": "d", "text": "Confirm 1:1000 for both IM and IV"}]'::jsonb, '["c"]', 'Epinephrine concentration must always be checked: 1:1000 is for IM use and 1:10,000 is for IV use. Reversing these strengths would be a medication error.'),
  ('ans', 12, 'A client is due for metoprolol. The apical pulse is 54 beats/min. Which action should the nurse take?', '[{"id": "a", "text": "Give the scheduled dose"}, {"id": "b", "text": "Give double the dose"}, {"id": "c", "text": "Give the dose with atropine"}, {"id": "d", "text": "Hold the scheduled dose"}]'::jsonb, '["d"]', 'Beta blockers should be held if the heart rate is below 60, because bradycardia is a key adverse effect.'),
  ('ans', 13, 'A client taking atenolol has a heart rate of 72 beats/min and a blood pressure of 86/50 mm Hg. What is the nurse''s best action regarding the dose?', '[{"id": "a", "text": "Withhold the dose because of the systolic pressure"}, {"id": "b", "text": "Give the dose because the heart rate is normal"}, {"id": "c", "text": "Give the dose because the systolic is acceptable"}, {"id": "d", "text": "Withhold the dose because of the heart rate"}]'::jsonb, '["a"]', 'Beta blockers are held if the systolic BP is below 90, even when the heart rate is 60 or higher. Here the heart rate is acceptable, so the systolic value is the reason to hold.'),
  ('ans', 14, 'The nurse teaches a client about newly prescribed propranolol. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I should expect my heart rate to be slower.\""}, {"id": "b", "text": "\"I can stop this pill on my own once I feel better.\""}, {"id": "c", "text": "\"My blood pressure should come down on this drug.\""}, {"id": "d", "text": "\"I will not stop this medicine suddenly.\""}]'::jsonb, '["b"]', 'Beta blockers must never be stopped abruptly because of rebound tachycardia. A slower heart rate and lower blood pressure are expected effects.'),
  ('ans', 15, 'A client stopped taking metoprolol abruptly two days ago. Which finding should the nurse be most alert for?', '[{"id": "a", "text": "Rebound bradycardia"}, {"id": "b", "text": "Increased salivation"}, {"id": "c", "text": "Rebound tachycardia"}, {"id": "d", "text": "Pupil constriction"}]'::jsonb, '["c"]', 'Abruptly stopping a beta blocker can cause rebound tachycardia. Bradycardia is an adverse effect while taking the drug, not a rebound effect of stopping it.'),
  ('ans', 16, 'A client with a history of asthma has a new prescription for propranolol. Why should the nurse question this order?', '[{"id": "a", "text": "Beta blockade may cause bronchodilation"}, {"id": "b", "text": "Beta blockade may cause tachycardia"}, {"id": "c", "text": "Beta blockade may raise blood pressure"}, {"id": "d", "text": "Beta blockade may cause bronchospasm"}]'::jsonb, '["d"]', 'Beta blockers can cause bronchospasm and should not be given in asthma. They lower, not raise, heart rate and blood pressure.'),
  ('ans', 17, 'A nurse reviews a client''s medication list. Which drug name suggests the client is taking a beta blocker?', '[{"id": "a", "text": "Atenolol"}, {"id": "b", "text": "Albuterol"}, {"id": "c", "text": "Phenylephrine"}, {"id": "d", "text": "Bethanechol"}]'::jsonb, '["a"]', 'Beta blockers end in -lol, such as atenolol. Albuterol ends in -ol but is a beta agonist, not a -lol beta blocker.'),
  ('ans', 18, 'A client with hypertension begins metoprolol. Which therapeutic response should the nurse expect?', '[{"id": "a", "text": "Increased heart rate and blood pressure"}, {"id": "b", "text": "Decreased heart rate and blood pressure"}, {"id": "c", "text": "Decreased heart rate, increased blood pressure"}, {"id": "d", "text": "Increased heart rate, decreased blood pressure"}]'::jsonb, '["b"]', 'Beta blockers decrease SNS activity, lowering heart rate and blood pressure.'),
  ('ans', 19, 'A client with asthma uses albuterol frequently. Which adverse effects should the nurse monitor for?', '[{"id": "a", "text": "Bradycardia and tremor"}, {"id": "b", "text": "Bradycardia and miosis"}, {"id": "c", "text": "Tachycardia and tremor"}, {"id": "d", "text": "Salivation and tearing"}]'::jsonb, '["c"]', 'Beta agonists such as albuterol can cause tachycardia and tremor. Bradycardia is associated with beta blockers and cholinergic agonists.'),
  ('ans', 20, 'A client with COPD asks how salmeterol helps breathing. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It blocks beta-2 receptors to open the airways.\""}, {"id": "b", "text": "\"It mimics acetylcholine to open the airways.\""}, {"id": "c", "text": "\"It stimulates alpha receptors to open the airways.\""}, {"id": "d", "text": "\"It stimulates beta-2 receptors to open the airways.\""}]'::jsonb, '["d"]', 'Beta agonists such as salmeterol stimulate beta-2 receptors, increasing SNS effect and causing bronchodilation. Acetylcholine (PNS) causes bronchoconstriction.'),
  ('ans', 21, 'A client in septic shock is receiving a phenylephrine infusion. Which nursing action is the priority?', '[{"id": "a", "text": "Monitor blood pressure continuously"}, {"id": "b", "text": "Check blood pressure once per shift"}, {"id": "c", "text": "Assess for increased salivation"}, {"id": "d", "text": "Monitor for pupil constriction"}]'::jsonb, '["a"]', 'Alpha agonists such as phenylephrine are used in shock/sepsis and require continuous BP monitoring.'),
  ('ans', 22, 'A hypotensive client in shock receives phenylephrine. Which response indicates the drug is having its intended effect?', '[{"id": "a", "text": "Blood pressure rises from vasodilation"}, {"id": "b", "text": "Blood pressure rises from vasoconstriction"}, {"id": "c", "text": "Blood pressure falls from vasoconstriction"}, {"id": "d", "text": "Heart rate falls from bronchodilation"}]'::jsonb, '["b"]', 'Alpha agonists stimulate alpha receptors, causing vasoconstriction and increased blood pressure.'),
  ('ans', 23, 'An 82-year-old client is started on diphenhydramine at bedtime. Which nursing concern is the priority?', '[{"id": "a", "text": "Excess salivation and drooling"}, {"id": "b", "text": "Bradycardia and hypotension"}, {"id": "c", "text": "Confusion leading to falls"}, {"id": "d", "text": "Increased urinary frequency"}]'::jsonb, '["c"]', 'In older adults, anticholinergics require monitoring for confusion, urinary retention, constipation, and falls. Salivation and bradycardia are cholinergic (PNS) effects.'),
  ('ans', 24, 'A client receiving scopolamine reports a side effect. Which complaint is expected with this drug?', '[{"id": "a", "text": "\"My mouth keeps filling with saliva.\""}, {"id": "b", "text": "\"My eyes keep watering.\""}, {"id": "c", "text": "\"I have been having diarrhea.\""}, {"id": "d", "text": "\"My mouth feels very dry.\""}]'::jsonb, '["d"]', 'Anticholinergics reduce PNS effects, causing dry mouth, urinary retention, constipation, and tachycardia. Salivation, tearing, and diarrhea are cholinergic effects.'),
  ('ans', 25, 'After receiving atropine, a client reports a change in vision. Which visual complaint should the nurse recognize as an expected effect?', '[{"id": "a", "text": "Blurred vision"}, {"id": "b", "text": "Excessive tearing"}, {"id": "c", "text": "Constricted pupils"}, {"id": "d", "text": "Sharper near vision"}]'::jsonb, '["a"]', 'Anticholinergic effects include dry mouth, urinary retention, constipation, tachycardia, blurred vision, and confusion in the elderly. Tearing and pupil constriction are PNS effects.'),
  ('ans', 26, 'An older adult taking an anticholinergic medication reports no bowel movement for four days. How should the nurse interpret this finding?', '[{"id": "a", "text": "A sign of cholinergic toxicity"}, {"id": "b", "text": "An expected anticholinergic adverse effect"}, {"id": "c", "text": "A sign of excess parasympathetic activity"}, {"id": "d", "text": "An effect unrelated to the medication"}]'::jsonb, '["b"]', 'Anticholinergics block ACh and decrease PNS effects, so constipation is an expected adverse effect, especially in older adults. Excess PNS activity increases GI motility.'),
  ('ans', 27, 'A client with urinary retention receives a cholinergic agonist. Which bladder response does the nurse expect?', '[{"id": "a", "text": "The bladder relaxes to promote urination"}, {"id": "b", "text": "The bladder relaxes, worsening retention"}, {"id": "c", "text": "The bladder contracts to promote urination"}, {"id": "d", "text": "The bladder contracts, worsening retention"}]'::jsonb, '["c"]', 'Cholinergic agonists mimic ACh to increase PNS effects, and the PNS contracts the bladder to promote urination. Bladder relaxation with retention is a sympathetic effect.'),
  ('ans', 28, 'A client is starting pilocarpine therapy. Which medication should the nurse ensure is readily available?', '[{"id": "a", "text": "Epinephrine"}, {"id": "b", "text": "Metoprolol"}, {"id": "c", "text": "Albuterol"}, {"id": "d", "text": "Atropine"}]'::jsonb, '["d"]', 'For clients on cholinergics, the nurse monitors for SLUDGE symptoms and keeps atropine nearby, since atropine is the anticholinergic antidote.'),
  ('ans', 29, 'A client is receiving bethanechol. Which change in vital signs should the nurse monitor for?', '[{"id": "a", "text": "Bradycardia"}, {"id": "b", "text": "Tachycardia"}, {"id": "c", "text": "Hypertension"}, {"id": "d", "text": "Increased respiratory rate"}]'::jsonb, '["a"]', 'Cholinergic agonists mimic ACh and can cause SLUDGE effects plus bradycardia. Tachycardia is associated with anticholinergics and SNS stimulation.'),
  ('ans', 30, 'A client with symptomatic bradycardia receives atropine IV. Which outcome indicates the drug is effective?', '[{"id": "a", "text": "Heart rate decreases further"}, {"id": "b", "text": "Heart rate increases"}, {"id": "c", "text": "Pupils constrict"}, {"id": "d", "text": "Salivation increases"}]'::jsonb, '["b"]', 'Atropine is an anticholinergic used for symptomatic bradycardia; it increases heart rate. Pupil constriction and salivation are PNS effects that atropine blocks.'),
  ('ans', 31, 'A client in septic shock is receiving a dopamine infusion. For which complications should the nurse monitor closely?', '[{"id": "a", "text": "Hypotension and bradycardia"}, {"id": "b", "text": "Bronchospasm and salivation"}, {"id": "c", "text": "Hypertensive crisis and tachyarrhythmias"}, {"id": "d", "text": "Miosis and urinary frequency"}]'::jsonb, '["c"]', 'Clients receiving adrenergic/SNS drugs need continuous HR and BP monitoring for hypertensive crisis and tachyarrhythmias.'),
  ('ans', 32, 'Epinephrine is given to a client in cardiac arrest. The nurse understands that this adrenergic agonist acts on which receptors?', '[{"id": "a", "text": "Muscarinic and nicotinic receptors"}, {"id": "b", "text": "Muscarinic receptors only"}, {"id": "c", "text": "Nicotinic receptors only"}, {"id": "d", "text": "Alpha and beta receptors"}]'::jsonb, '["d"]', 'Adrenergic agonists such as epinephrine and dopamine stimulate alpha and beta receptors. Muscarinic and nicotinic receptors belong to the parasympathetic division.'),
  ('ans', 33, 'A client becomes frightened and develops a pounding, rapid heartbeat. Which neurotransmitters are primarily responsible for this response?', '[{"id": "a", "text": "Norepinephrine and epinephrine"}, {"id": "b", "text": "Acetylcholine alone"}, {"id": "c", "text": "Acetylcholine and epinephrine"}, {"id": "d", "text": "Norepinephrine and acetylcholine"}]'::jsonb, '["a"]', 'The sympathetic division, which increases heart rate, uses norepinephrine and epinephrine. Acetylcholine is the parasympathetic neurotransmitter.'),
  ('ans', 34, 'A client''s mouth waters while looking at a meal tray. Which neurotransmitter mediates this increase in salivation?', '[{"id": "a", "text": "Norepinephrine"}, {"id": "b", "text": "Acetylcholine"}, {"id": "c", "text": "Epinephrine"}, {"id": "d", "text": "Dopamine"}]'::jsonb, '["b"]', 'Increased salivation is a parasympathetic effect, and the PNS neurotransmitter is acetylcholine. Norepinephrine and epinephrine are sympathetic and decrease salivation.'),
  ('ans', 35, 'A medication acts on muscarinic receptors. The nurse anticipates the drug will primarily influence which division?', '[{"id": "a", "text": "Sympathetic division"}, {"id": "b", "text": "Both divisions equally"}, {"id": "c", "text": "Parasympathetic division"}, {"id": "d", "text": "Neither autonomic division"}]'::jsonb, '["c"]', 'Muscarinic and nicotinic receptors are the parasympathetic receptor types; alpha and beta receptors are sympathetic.'),
  ('ans', 36, 'A medication is described as an alpha-receptor stimulant. Which autonomic division does this drug mimic?', '[{"id": "a", "text": "Parasympathetic division"}, {"id": "b", "text": "Neither autonomic division"}, {"id": "c", "text": "Both divisions equally"}, {"id": "d", "text": "Sympathetic division"}]'::jsonb, '["d"]', 'Alpha and beta receptors are sympathetic receptor types. Muscarinic and nicotinic receptors are parasympathetic.'),
  ('ans', 37, 'A client with diabetes is admitted after a traumatic injury. Which change in blood glucose should the nurse anticipate from the stress response?', '[{"id": "a", "text": "Increased glucose from glycogenolysis"}, {"id": "b", "text": "Decreased glucose from glycogenolysis"}, {"id": "c", "text": "No change because the PNS dominates"}, {"id": "d", "text": "Decreased glucose from vasoconstriction"}]'::jsonb, '["a"]', 'The sympathetic response increases glucose release through glycogenolysis. The parasympathetic division has minimal effect on blood glucose.'),
  ('ans', 38, 'A client''s blood glucose rises during an acute stress episode. Which division is responsible?', '[{"id": "a", "text": "Parasympathetic, which increases glucose"}, {"id": "b", "text": "Sympathetic, which increases glucose"}, {"id": "c", "text": "Sympathetic, which decreases glucose"}, {"id": "d", "text": "Parasympathetic, which decreases glucose"}]'::jsonb, '["b"]', 'The sympathetic division increases blood glucose via glycogenolysis, whereas the parasympathetic division has minimal effect on blood glucose.'),
  ('ans', 39, 'A client is in severe acute pain after an injury. Which gastrointestinal effect should the nurse expect?', '[{"id": "a", "text": "Faster digestion from increased motility"}, {"id": "b", "text": "Slowed digestion from increased motility"}, {"id": "c", "text": "Slowed digestion from decreased motility"}, {"id": "d", "text": "Faster digestion from decreased motility"}]'::jsonb, '["c"]', 'Pain triggers a sympathetic surge, which decreases GI motility and slows digestion. Increased motility is a parasympathetic effect.'),
  ('ans', 40, 'A client is resting comfortably after finishing a large meal. Which physiologic change is expected at this time?', '[{"id": "a", "text": "Decreased GI motility"}, {"id": "b", "text": "Bronchodilation"}, {"id": "c", "text": "Pupil dilation"}, {"id": "d", "text": "Increased GI motility"}]'::jsonb, '["d"]', 'At rest the parasympathetic (rest-and-digest) division predominates, increasing GI motility and enhancing digestion. Bronchodilation and pupil dilation are sympathetic effects.'),
  ('ans', 41, 'A client has been in a prolonged state of intense anxiety. Which urinary problem is this client at risk for?', '[{"id": "a", "text": "Urinary retention from bladder relaxation"}, {"id": "b", "text": "Urinary frequency from bladder contraction"}, {"id": "c", "text": "Urinary retention from bladder contraction"}, {"id": "d", "text": "Urinary frequency from bladder relaxation"}]'::jsonb, '["a"]', 'Sympathetic activation relaxes the bladder, causing urinary retention. Bladder contraction promoting urination is a parasympathetic effect.'),
  ('ans', 42, 'A nurse explains to a client with asthma why the airways tend to narrow while the body is at rest. Which autonomic effect is responsible?', '[{"id": "a", "text": "Sympathetic bronchoconstriction"}, {"id": "b", "text": "Parasympathetic bronchoconstriction"}, {"id": "c", "text": "Parasympathetic bronchodilation"}, {"id": "d", "text": "Sympathetic bronchodilation"}]'::jsonb, '["b"]', 'The parasympathetic division causes bronchoconstriction (narrow airways at rest). The sympathetic division causes bronchodilation.'),
  ('ans', 43, 'A client receives pilocarpine, a cholinergic agonist. Which pupil response should the nurse expect?', '[{"id": "a", "text": "Mydriasis"}, {"id": "b", "text": "Unequal pupils"}, {"id": "c", "text": "Miosis"}, {"id": "d", "text": "Fixed pupils"}]'::jsonb, '["c"]', 'Cholinergic agonists mimic ACh and increase PNS effects; the PNS causes miosis (pupil constriction). Mydriasis is a sympathetic effect.'),
  ('ans', 44, 'A client receiving a cholinergic medication has watery eyes. This finding reflects stimulation of which division?', '[{"id": "a", "text": "Sympathetic"}, {"id": "b", "text": "Adrenergic"}, {"id": "c", "text": "Alpha-adrenergic"}, {"id": "d", "text": "Parasympathetic"}]'::jsonb, '["d"]', 'Increased lacrimation (tearing) is a parasympathetic effect and part of SLUDGE. Adrenergic and alpha effects belong to the sympathetic division.'),
  ('ans', 45, 'A nursing student explains the relationship between the sympathetic and parasympathetic divisions. Which statement is accurate?', '[{"id": "a", "text": "They have opposite effects on most organs"}, {"id": "b", "text": "They have identical effects on most organs"}, {"id": "c", "text": "They both use acetylcholine at the organs"}, {"id": "d", "text": "They act only on the heart and lungs"}]'::jsonb, '["a"]', 'The two divisions are antagonists with opposite effects on virtually every organ.'),
  ('ans', 46, 'Which description best fits the role of the parasympathetic nervous system?', '[{"id": "a", "text": "It increases energy output during stress"}, {"id": "b", "text": "It conserves and restores energy during rest"}, {"id": "c", "text": "It raises blood glucose during stress"}, {"id": "d", "text": "It dilates the pupils during rest"}]'::jsonb, '["b"]', 'The PNS (rest and digest) activates during rest to conserve and restore energy. Increasing energy output under stress describes the SNS.'),
  ('ans', 47, 'A nurse explains how parasympathetic stimulation lowers blood pressure. Which mechanism is correct?', '[{"id": "a", "text": "Vasoconstriction"}, {"id": "b", "text": "Bronchodilation"}, {"id": "c", "text": "Vasodilation"}, {"id": "d", "text": "Glycogenolysis"}]'::jsonb, '["c"]', 'The parasympathetic division decreases blood pressure through vasodilation; the sympathetic division raises blood pressure through vasoconstriction.'),
  ('ans', 48, 'A client''s blood pressure rises during a frightening event. Which mechanism accounts for this increase?', '[{"id": "a", "text": "Sympathetic vasodilation"}, {"id": "b", "text": "Parasympathetic vasoconstriction"}, {"id": "c", "text": "Parasympathetic vasodilation"}, {"id": "d", "text": "Sympathetic vasoconstriction"}]'::jsonb, '["d"]', 'The sympathetic division increases blood pressure through vasoconstriction. Parasympathetic activity decreases blood pressure via vasodilation.'),
  ('ans', 49, 'A client about to give a public speech says, "My mouth is so dry." The nurse recognizes this as an effect of which process?', '[{"id": "a", "text": "Sympathetic decrease in salivation"}, {"id": "b", "text": "Parasympathetic decrease in salivation"}, {"id": "c", "text": "Sympathetic increase in salivation"}, {"id": "d", "text": "Parasympathetic increase in salivation"}]'::jsonb, '["a"]', 'Sympathetic activation decreases salivation, producing dry mouth. The parasympathetic division increases salivation.'),
  ('ans', 50, 'A client is running to escape a dangerous situation. Which respiratory changes are expected?', '[{"id": "a", "text": "Decreased rate with bronchodilation"}, {"id": "b", "text": "Increased rate with bronchodilation"}, {"id": "c", "text": "Increased rate with bronchoconstriction"}, {"id": "d", "text": "Decreased rate with bronchoconstriction"}]'::jsonb, '["b"]', 'Fight-or-flight sympathetic activation increases respiratory rate and causes bronchodilation. Bronchoconstriction is a parasympathetic effect.'),
  ('cp', 1, 'The parent of a 3-year-old newly diagnosed with spastic cerebral palsy (CP) asks, ''Will the damage in my child''s brain keep getting worse?'' Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Yes, the brain injury slowly spreads as your child grows.\""}, {"id": "b", "text": "\"No, the injury is fixed, but symptoms may change with growth.\""}, {"id": "c", "text": "\"Yes, but early therapy can keep the injury from spreading.\""}, {"id": "d", "text": "\"No, the brain injury usually heals fully by school age.\""}]'::jsonb, '["b"]', 'In CP the brain lesion is static: it neither heals nor progresses, although the presentation of symptoms may change as the nervous system matures. Responses suggesting the injury spreads or heals are incorrect.'),
  ('cp', 2, 'A 6-year-old with cerebral palsy has had stable motor function for years. Over the past several weeks, the child has rapidly lost motor skills previously mastered. How should the nurse interpret this change?', '[{"id": "a", "text": "Expected worsening of CP as the child grows taller"}, {"id": "b", "text": "Normal effect of nervous system maturation in CP"}, {"id": "c", "text": "Sign that the child''s therapy plan should be reduced"}, {"id": "d", "text": "Change suggesting a cause other than CP alone"}]'::jsonb, '["d"]', 'CP does not get worse over time; rapidly declining motor function should prompt consideration of a different diagnosis. Attributing the decline to CP progression contradicts its non-progressive nature.'),
  ('cp', 3, 'A nurse is teaching a group of new parents about the core features of cerebral palsy. Along with motor impairment and postural abnormalities, which feature belongs to the core triad of CP?', '[{"id": "a", "text": "Progressive loss of motor skills"}, {"id": "b", "text": "Damage limited to peripheral nerves"}, {"id": "c", "text": "Associated cognitive or sensory deficits"}, {"id": "d", "text": "Steady worsening of the brain lesion"}]'::jsonb, '["c"]', 'The core triad is motor impairment, postural abnormalities, and associated deficits (cognitive, sensory, speech, epilepsy, behavioral) that vary by severity. CP is non-progressive and arises from injury to the developing brain, not the peripheral nerves.'),
  ('cp', 4, 'A nurse reviews the prenatal history of an infant being evaluated for cerebral palsy. Which finding is a prenatal (before birth) risk factor for CP?', '[{"id": "a", "text": "Maternal cytomegalovirus infection in pregnancy"}, {"id": "b", "text": "Forceps-assisted delivery after prolonged labor"}, {"id": "c", "text": "Meningitis diagnosed at 2 weeks of age"}, {"id": "d", "text": "Fall with head injury at 3 months of age"}]'::jsonb, '["a"]', 'Maternal infections such as rubella, CMV, and toxoplasmosis are prenatal risk factors. A traumatic forceps delivery is a perinatal factor, and meningitis or head trauma after birth are postnatal factors.'),
  ('cp', 5, 'The parents of a newborn with severe hyperbilirubinemia ask how jaundice could lead to cerebral palsy. The nurse explains that the risk comes from which process?', '[{"id": "a", "text": "Oxygen deprivation occurring during delivery"}, {"id": "b", "text": "Brain damage caused by bilirubin toxicity"}, {"id": "c", "text": "Maternal infection crossing the placenta"}, {"id": "d", "text": "Bleeding from fragile ventricular vessels"}]'::jsonb, '["b"]', 'Kernicterus is brain damage from severe neonatal jaundice due to bilirubin toxicity, a postnatal cause of CP. Birth asphyxia, maternal infection, and intraventricular hemorrhage are separate risk factors.'),
  ('cp', 6, 'A child born at 27 weeks'' gestation is diagnosed with spastic cerebral palsy. Which pattern of limb involvement is most common in children born preterm?', '[{"id": "a", "text": "One side of the body only"}, {"id": "b", "text": "All four limbs equally"}, {"id": "c", "text": "Writhing of face, arms, and trunk"}, {"id": "d", "text": "Both legs (diplegia)"}]'::jsonb, '["d"]', 'Spastic diplegia, involving both legs, is the most common pattern in preterm infants. Hemiplegia affects one side, quadriplegia affects all four limbs, and writhing movements describe dyskinetic CP.'),
  ('cp', 7, 'A NICU nurse explains to the parents of a 28-week preterm infant why prematurity increases the risk of cerebral palsy. Which explanation is accurate?', '[{"id": "a", "text": "The brain is still developing and its vessels are fragile."}, {"id": "b", "text": "The brain lesion becomes progressive after early birth."}, {"id": "c", "text": "Primitive reflexes disappear too early in preterm infants."}, {"id": "d", "text": "Preterm birth mainly damages the peripheral nerves."}]'::jsonb, '["a"]', 'In prematurity the brain is still developing and has fragile vasculature, creating a risk of intraventricular hemorrhage. CP lesions are non-progressive, and CP results from injury to the developing brain rather than peripheral nerves.'),
  ('cp', 8, 'A nurse is reviewing the histories of four infants. Which event represents a postnatal risk factor for cerebral palsy?', '[{"id": "a", "text": "Birth weight that was below normal"}, {"id": "b", "text": "Placental insufficiency during pregnancy"}, {"id": "c", "text": "Head trauma from shaken baby syndrome"}, {"id": "d", "text": "Maternal alcohol use during pregnancy"}]'::jsonb, '["c"]', 'Postnatal causes include head trauma such as shaken baby syndrome or falls. Low birth weight is perinatal, while placental insufficiency and toxin or alcohol exposure are prenatal factors.'),
  ('cp', 9, 'A nurse in a pediatric neurology clinic is caring for many children with cerebral palsy. Which type of CP should the nurse expect to see most often?', '[{"id": "a", "text": "Ataxic CP"}, {"id": "b", "text": "Dyskinetic CP"}, {"id": "c", "text": "Mixed CP"}, {"id": "d", "text": "Spastic CP"}]'::jsonb, '["d"]', 'Spastic CP is the most common type, accounting for 70–80% of cases. Ataxic CP is the least common type.'),
  ('cp', 10, 'A 5-year-old is diagnosed with spastic hemiplegic cerebral palsy. When planning care, the nurse anticipates motor involvement in which distribution?', '[{"id": "a", "text": "Both legs, with the arms largely spared"}, {"id": "b", "text": "One side of the body"}, {"id": "c", "text": "All four limbs of the body"}, {"id": "d", "text": "Face, arms, and trunk"}]'::jsonb, '["b"]', 'Hemiplegia affects one side of the body. Both legs describes diplegia, all four limbs describes quadriplegia, and face, arms, and trunk involvement describes dyskinetic CP.'),
  ('cp', 11, 'A nursing student is preparing to care for a child with spastic quadriplegic cerebral palsy. Which description of this type, stated by the student, is accurate?', '[{"id": "a", "text": "Both legs, with the arms largely spared"}, {"id": "b", "text": "One arm and one leg on the same side"}, {"id": "c", "text": "Face, arms, and trunk with writhing"}, {"id": "d", "text": "All four limbs, often with cognitive involvement"}]'::jsonb, '["d"]', 'Spastic quadriplegia involves all four limbs and often severe cognitive involvement. Both legs describes diplegia, one side describes hemiplegia, and writhing of the face, arms, and trunk describes dyskinetic CP.'),
  ('cp', 12, 'A nurse performs a neurological assessment on a 4-year-old with spastic cerebral palsy. Which finding should the nurse expect?', '[{"id": "a", "text": "Wide-based gait with a tremor"}, {"id": "b", "text": "Hyperreflexia and a positive Babinski"}, {"id": "c", "text": "Writhing that stops during sleep"}, {"id": "d", "text": "Twisting movements of face and trunk"}]'::jsonb, '["b"]', 'Spastic CP features hypertonia, and hyperreflexia, a positive Babinski, and clonus may be present. A wide-based gait with tremor indicates ataxic CP, and writhing or twisting movements indicate dyskinetic CP.'),
  ('cp', 13, 'The parent of a child with athetoid (dyskinetic) cerebral palsy reports that the child''s twisting movements get worse when upset and seem to improve while asleep. Which response by the nurse is best?', '[{"id": "a", "text": "\"This pattern suggests the brain injury is worsening.\""}, {"id": "b", "text": "\"This pattern suggests your child is having seizures.\""}, {"id": "c", "text": "\"This pattern is expected with this type of CP.\""}, {"id": "d", "text": "\"This pattern shows a change to the ataxic type of CP.\""}]'::jsonb, '["c"]', 'In dyskinetic/athetoid CP, involuntary writhing movements worsen with stress and improve during sleep. The pattern does not mean the brain injury is worsening, since CP is non-progressive.'),
  ('cp', 14, 'A 2-year-old had kernicterus as a newborn and is now being evaluated for cerebral palsy. Which type of CP is most often associated with this history?', '[{"id": "a", "text": "Dyskinetic (athetoid) CP"}, {"id": "b", "text": "Ataxic CP"}, {"id": "c", "text": "Spastic diplegic CP"}, {"id": "d", "text": "Spastic hemiplegic CP"}]'::jsonb, '["a"]', 'Dyskinetic/athetoid CP is often associated with kernicterus. Ataxic CP primarily affects balance and coordination, and spastic diplegia is most common in preterm infants.'),
  ('cp', 15, 'A nurse is planning care for a child with dyskinetic cerebral palsy. Which functions should the nurse anticipate are frequently impaired in this type?', '[{"id": "a", "text": "Depth perception and fine tremor"}, {"id": "b", "text": "Balance with a wide-based gait"}, {"id": "c", "text": "Leg position, with scissoring"}, {"id": "d", "text": "Speech and swallowing"}]'::jsonb, '["d"]', 'In dyskinetic CP, speech and swallowing are frequently impaired. Poor depth perception, tremor, and a wide-based gait are features of ataxic CP, and scissoring is a sign of spastic diplegia.'),
  ('cp', 16, 'A 7-year-old with cerebral palsy walks with the feet spread far apart, has a tremor, and has poor depth perception. Which type of CP do these findings suggest?', '[{"id": "a", "text": "Spastic CP"}, {"id": "b", "text": "Ataxic CP"}, {"id": "c", "text": "Dyskinetic CP"}, {"id": "d", "text": "Mixed spastic-dyskinetic CP"}]'::jsonb, '["b"]', 'Ataxic CP affects balance and coordination, producing a wide-based gait, tremor, and poor depth perception. Spastic CP features hypertonia and scissoring, and dyskinetic CP features writhing movements.'),
  ('cp', 17, 'A child with ataxic cerebral palsy is admitted to the pediatric unit. Which nursing intervention is the priority?', '[{"id": "a", "text": "Remove assistive devices to build balance"}, {"id": "b", "text": "Keep the head of the bed flat at all times"}, {"id": "c", "text": "Use a bed alarm and keep assistive devices nearby"}, {"id": "d", "text": "Delay range-of-motion exercises to limit fatigue"}]'::jsonb, '["c"]', 'Safety is the priority in ataxic CP because of high fall risk; bed/chair alarms, assistive devices, and a safe environment are indicated. Removing assistive devices would increase fall risk.'),
  ('cp', 18, 'A child with mixed cerebral palsy shows both spastic and dyskinetic features. Which approach should the nurse expect the care team to take?', '[{"id": "a", "text": "Address the dominant features first"}, {"id": "b", "text": "Treat only the spastic features"}, {"id": "c", "text": "Wait for one type to predominate"}, {"id": "d", "text": "Treat the least obvious features first"}]'::jsonb, '["a"]', 'Mixed CP is a combination of two or more types, most commonly spastic plus dyskinetic, and its complex presentation is managed by addressing the dominant features first.'),
  ('cp', 19, 'A nurse is reviewing ataxic cerebral palsy with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Ataxic CP mainly affects balance and coordination.\""}, {"id": "b", "text": "\"Ataxic CP is the most common type of CP.\""}, {"id": "c", "text": "\"Children with ataxic CP have a high fall risk.\""}, {"id": "d", "text": "\"A wide-based gait is typical of ataxic CP.\""}]'::jsonb, '["b"]', 'Ataxic CP is the least common type; spastic CP is the most common. The other statements correctly describe ataxic CP.'),
  ('cp', 20, 'A nurse is performing well-child assessments. Which finding should the nurse report as an early sign of possible cerebral palsy?', '[{"id": "a", "text": "Head lag in a 2-month-old"}, {"id": "b", "text": "Moro reflex in a 3-month-old"}, {"id": "c", "text": "Using both hands equally at 10 months"}, {"id": "d", "text": "Not sitting independently at 10 months"}]'::jsonb, '["d"]', 'Delayed milestones, such as not sitting by 8 months, are the most prominent early indicator of CP. Head lag is concerning only when it persists beyond 4 months, and primitive reflexes only when they persist beyond 6 months.'),
  ('cp', 21, 'The mother of a 5-month-old says, ''My baby feels floppy, like a rag doll, when I pick her up.'' How should the nurse interpret this report?', '[{"id": "a", "text": "Low tone can be an early sign of CP."}, {"id": "b", "text": "Only stiff muscle tone suggests CP."}, {"id": "c", "text": "Floppy muscle tone rules out CP."}, {"id": "d", "text": "Floppiness is expected until 18 months."}]'::jsonb, '["a"]', 'Abnormal muscle tone, either hypertonia (stiff) or hypotonia (floppy), is an early sign of CP, and tone abnormalities precede movement deficits. Stiff tone is not the only tone abnormality associated with CP.'),
  ('cp', 22, 'When pulled from a supine to a sitting position, a 6-month-old shows marked head lag. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "It is expected until 9 months of age."}, {"id": "b", "text": "It is an early sign needing follow-up."}, {"id": "c", "text": "It shows the infant is ready to sit."}, {"id": "d", "text": "It is expected until walking begins."}]'::jsonb, '["b"]', 'Head lag persisting beyond 4 months reflects early neuromuscular weakness and is an early sign of CP that warrants follow-up. It is not an expected finding at 6 months.'),
  ('cp', 23, 'A 9-month-old still demonstrates the Moro and asymmetric tonic neck (ATNR) reflexes. What is the significance of this finding?', '[{"id": "a", "text": "Normal, because these reflexes last until walking"}, {"id": "b", "text": "Expected sign of advanced motor development"}, {"id": "c", "text": "Possible cortical delay, as they should be gone"}, {"id": "d", "text": "Normal, because these reflexes fade by 18 months"}]'::jsonb, '["c"]', 'Primitive reflexes such as Moro, ATNR, and grasp should integrate and disappear; persistence beyond 6 months indicates cortical delay and is an early sign of CP.'),
  ('cp', 24, 'When the nurse lifts an 8-month-old under the arms, the infant''s legs cross over each other. This finding is a hallmark of which condition?', '[{"id": "a", "text": "Ataxic CP"}, {"id": "b", "text": "Dyskinetic CP"}, {"id": "c", "text": "Spastic hemiplegia"}, {"id": "d", "text": "Spastic diplegia"}]'::jsonb, '["d"]', 'Scissoring of the legs when the infant is held results from spastic adductors and is a hallmark of spastic diplegia. Ataxic CP affects balance, and dyskinetic CP causes writhing movements.'),
  ('cp', 25, 'An 11-month-old consistently reaches for toys using only the right hand and ignores the left hand. Which finding should the nurse suspect?', '[{"id": "a", "text": "Weakness of the left side of the body"}, {"id": "b", "text": "Weakness of the right side of the body"}, {"id": "c", "text": "Normal early hand dominance for age"}, {"id": "d", "text": "Balance problems from ataxic CP"}]'::jsonb, '["a"]', 'Consistent use of only one hand before 18 months suggests hemiplegia on the opposite side, so exclusive right-hand use suggests left-sided weakness. Early hand preference is not a normal finding at this age.'),
  ('cp', 26, 'A 4-month-old with suspected cerebral palsy has a poor suck and coughs and gags during bottle feeding. The nurse recognizes the infant is at greatest risk for which complication?', '[{"id": "a", "text": "Falls from impaired balance"}, {"id": "b", "text": "Aspiration"}, {"id": "c", "text": "Joint contractures"}, {"id": "d", "text": "Pressure injury"}]'::jsonb, '["b"]', 'Feeding difficulties such as poor suck, gag, or swallow reflect oral motor dysfunction and create an aspiration risk. Falls, contractures, and pressure injuries are not the risk most directly linked to these feeding findings.'),
  ('cp', 27, 'The parent of a toddler being evaluated for cerebral palsy asks, ''Which test will confirm whether my child has CP?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A blood test will confirm the diagnosis.\""}, {"id": "b", "text": "\"An EEG will confirm the diagnosis.\""}, {"id": "c", "text": "\"No single test; exam and imaging are combined.\""}, {"id": "d", "text": "\"A CT scan alone will confirm the diagnosis.\""}]'::jsonb, '["c"]', 'There is no single diagnostic test for CP; diagnosis is clinical plus imaging-based. Blood tests rule out metabolic or genetic causes, and EEG is used if seizures are present or suspected.'),
  ('cp', 28, 'A provider wants to identify brain lesions and white matter injury in a toddler with suspected cerebral palsy. The nurse anticipates which diagnostic study as the best choice?', '[{"id": "a", "text": "Electroencephalogram (EEG)"}, {"id": "b", "text": "Metabolic blood tests"}, {"id": "c", "text": "Developmental screening tool"}, {"id": "d", "text": "Magnetic resonance imaging (MRI)"}]'::jsonb, '["d"]', 'MRI is the best study for identifying brain lesions and white matter injury in CP. CT is used if MRI is unavailable or in an acute setting, and EEG evaluates seizures.'),
  ('cp', 29, 'A child with cerebral palsy has new episodes of staring and rhythmic jerking of the arms. Which diagnostic test should the nurse anticipate to evaluate these episodes?', '[{"id": "a", "text": "Electroencephalogram (EEG)"}, {"id": "b", "text": "Metabolic blood tests"}, {"id": "c", "text": "Developmental screening"}, {"id": "d", "text": "Swallowing assessment"}]'::jsonb, '["a"]', 'EEG is indicated when seizures are present or suspected in a child with CP. Blood tests are used to rule out metabolic or genetic causes rather than to evaluate seizures.'),
  ('cp', 30, 'During a cerebral palsy evaluation, the parent asks why the child needs blood drawn. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"To confirm that your child has CP.\""}, {"id": "b", "text": "\"To rule out metabolic or genetic causes.\""}, {"id": "c", "text": "\"To measure the size of the brain lesion.\""}, {"id": "d", "text": "\"To detect seizure activity in the brain.\""}]'::jsonb, '["b"]', 'Blood tests are used to rule out metabolic or genetic causes; no single test confirms CP. MRI identifies brain lesions, and EEG evaluates seizure activity.'),
  ('cp', 31, 'A school-age child with spastic diplegia needs help strengthening leg muscles, preventing contractures, and improving gait. Which discipline primarily addresses these goals?', '[{"id": "a", "text": "Occupational therapy"}, {"id": "b", "text": "Speech-language pathology"}, {"id": "c", "text": "Special education services"}, {"id": "d", "text": "Physical therapy"}]'::jsonb, '["d"]', 'Physical therapy strengthens muscles, prevents contractures, and improves gait. Occupational therapy focuses on ADL independence and adaptive equipment, and speech-language pathology addresses communication and swallowing.'),
  ('cp', 32, 'A 9-year-old with cerebral palsy wants to dress and feed himself more independently using adaptive equipment. The nurse should anticipate a referral to which service?', '[{"id": "a", "text": "Occupational therapy"}, {"id": "b", "text": "Physical therapy"}, {"id": "c", "text": "Speech-language pathology"}, {"id": "d", "text": "Special education services"}]'::jsonb, '["a"]', 'Occupational therapy targets ADL independence and adaptive equipment. Physical therapy focuses on strength, contracture prevention, and gait.'),
  ('cp', 33, 'A child with dyskinetic cerebral palsy has difficulty making speech understood and coughs during meals. The nurse should anticipate a referral to which service?', '[{"id": "a", "text": "Occupational therapy"}, {"id": "b", "text": "Physical therapy"}, {"id": "c", "text": "Speech-language pathology"}, {"id": "d", "text": "Orthopedic surgery"}]'::jsonb, '["c"]', 'Speech-language pathology addresses both communication and swallowing. Occupational therapy focuses on ADLs and adaptive equipment, and physical therapy on strength and gait.'),
  ('cp', 34, 'A child with spastic cerebral palsy is started on oral baclofen. The parent asks what the medication is for. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It prevents seizures.\""}, {"id": "b", "text": "\"It treats brain infection.\""}, {"id": "c", "text": "\"It decreases spasticity.\""}, {"id": "d", "text": "\"It repairs the brain lesion.\""}]'::jsonb, '["c"]', 'Baclofen, given orally or intrathecally, is a muscle relaxant that decreases spasticity. Seizures are treated with antiepileptics such as phenytoin or levetiracetam.'),
  ('cp', 35, 'A child with cerebral palsy has spasticity limited to the calf muscles of one leg. The provider prefers a local, nonsurgical treatment. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Selective dorsal rhizotomy"}, {"id": "b", "text": "Intrathecal baclofen pump"}, {"id": "c", "text": "Levetiracetam by mouth"}, {"id": "d", "text": "Botulinum toxin injections"}]'::jsonb, '["d"]', 'Botulinum toxin is given as local injections for focal spasticity. Selective dorsal rhizotomy and an intrathecal baclofen pump are surgical options, and levetiracetam treats seizures.'),
  ('cp', 36, 'A child with cerebral palsy receives diazepam for an episode of painful muscle spasms. The parent asks whether the child will take this drug every day from now on. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is used for short-term spasm relief.\""}, {"id": "b", "text": "\"It is a lifelong seizure medication.\""}, {"id": "c", "text": "\"It is delivered by a pump into the spine.\""}, {"id": "d", "text": "\"It is injected into one tight muscle.\""}]'::jsonb, '["a"]', 'Diazepam is used for short-term spasticity and spasm relief. Continuous spinal delivery describes the intrathecal baclofen pump, and local injection describes botulinum toxin.'),
  ('cp', 37, 'A nurse is reviewing the medication list of a child with cerebral palsy. Which medication is an alpha-2 agonist used to reduce spasticity?', '[{"id": "a", "text": "Levetiracetam"}, {"id": "b", "text": "Tizanidine"}, {"id": "c", "text": "Phenytoin"}, {"id": "d", "text": "Diazepam"}]'::jsonb, '["b"]', 'Tizanidine is an alpha-2 agonist that reduces spasticity. Levetiracetam and phenytoin are antiepileptics, and diazepam is used for short-term spasm relief.'),
  ('cp', 38, 'A child with cerebral palsy is diagnosed with a seizure disorder. Which medication should the nurse anticipate being prescribed for the seizures?', '[{"id": "a", "text": "Baclofen"}, {"id": "b", "text": "Tizanidine"}, {"id": "c", "text": "Levetiracetam"}, {"id": "d", "text": "Botulinum toxin"}]'::jsonb, '["c"]', 'Antiepileptics such as phenytoin and levetiracetam are used for seizures in CP. Baclofen, tizanidine, and botulinum toxin treat spasticity.'),
  ('cp', 39, 'The parents of a child with severe spastic diplegia ask what a selective dorsal rhizotomy involves. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It lengthens tight tendons to correct joints."}, {"id": "b", "text": "It delivers medication continuously to the spine."}, {"id": "c", "text": "It temporarily relaxes a single tight muscle."}, {"id": "d", "text": "It cuts sensory nerve roots to reduce spasticity."}]'::jsonb, '["d"]', 'Selective dorsal rhizotomy cuts sensory nerve roots and permanently reduces spasticity. Tendon lengthening is orthopedic surgery, and continuous spinal delivery describes the intrathecal baclofen pump.'),
  ('cp', 40, 'An adolescent with cerebral palsy has severe spasticity that is not controlled by oral medications. Which surgical option provides continuous spinal delivery of an antispasticity drug?', '[{"id": "a", "text": "Intrathecal baclofen pump"}, {"id": "b", "text": "Botulinum toxin injection"}, {"id": "c", "text": "Tendon lengthening surgery"}, {"id": "d", "text": "Selective dorsal rhizotomy"}]'::jsonb, '["a"]', 'An intrathecal baclofen pump provides continuous spinal delivery for severe spasticity. Selective dorsal rhizotomy cuts sensory nerve roots rather than delivering medication.'),
  ('cp', 41, 'A child with cerebral palsy is scheduled for orthopedic surgery. The parent asks the nurse what the surgery is intended to do. Which response is correct?', '[{"id": "a", "text": "\"It cuts sensory nerve roots in the spine.\""}, {"id": "b", "text": "\"It lengthens or releases tight tendons.\""}, {"id": "c", "text": "\"It places a medication pump in the spine.\""}, {"id": "d", "text": "\"It removes the injured area of the brain.\""}]'::jsonb, '["b"]', 'Orthopedic surgery in CP involves tendon lengthening or release and joint correction. Cutting sensory nerve roots is selective dorsal rhizotomy, and a spinal medication pump is the intrathecal baclofen pump.'),
  ('cp', 42, 'A child with cerebral palsy and dysphagia is about to eat lunch. How should the nurse position the child during and after the meal?', '[{"id": "a", "text": "Supine with the bed flat"}, {"id": "b", "text": "Head of bed raised 15 degrees"}, {"id": "c", "text": "Head of bed raised 30–45 degrees"}, {"id": "d", "text": "Side-lying with the bed flat"}]'::jsonb, '["c"]', 'To reduce aspiration risk, the head of the bed should be elevated at least 30–45 degrees during and after meals. A flat or minimally raised position does not meet this requirement.'),
  ('cp', 43, 'A child with spastic quadriplegic cerebral palsy has been NPO and now has a prescription to begin oral feedings. Which action should the nurse take first?', '[{"id": "a", "text": "Offer thin liquids to observe the child''s swallow"}, {"id": "b", "text": "Feed the child lying flat to conserve energy"}, {"id": "c", "text": "Give larger bites so the meal ends sooner"}, {"id": "d", "text": "Complete a swallowing assessment before feeding"}]'::jsonb, '["d"]', 'A swallowing assessment should be performed before initiating PO feeding because dysphagia is common in CP. Thickened liquids, upright positioning, and small bites are used to reduce aspiration risk.'),
  ('cp', 44, 'A nurse teaches the parent of a child with cerebral palsy and swallowing difficulty about safe feeding. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will give larger bites so meals finish faster.\""}, {"id": "b", "text": "\"I will keep my child upright while eating.\""}, {"id": "c", "text": "\"I will use thickened liquids as prescribed.\""}, {"id": "d", "text": "\"I will keep my child''s head raised after meals.\""}]'::jsonb, '["a"]', 'Feeding safety in CP calls for upright positioning and small bites, not larger bites. Thickened liquids if ordered and keeping the head elevated after meals are correct.'),
  ('cp', 45, 'A nurse is explaining why feeding safety is a top priority for a child with cerebral palsy who has dysphagia and poor oral motor control. These problems are a leading cause of which complications?', '[{"id": "a", "text": "Kernicterus and neonatal jaundice"}, {"id": "b", "text": "Aspiration pneumonia and malnutrition"}, {"id": "c", "text": "Progression of the brain lesion"}, {"id": "d", "text": "Joint contractures and scissoring"}]'::jsonb, '["b"]', 'Dysphagia and poor oral motor control in CP are the leading cause of aspiration pneumonia and malnutrition. They do not cause progression of the brain lesion, which is static.'),
  ('cp', 46, 'A child with cerebral palsy and a known seizure disorder is admitted to the pediatric unit. Which measures should the nurse ensure are in place as seizure precautions?', '[{"id": "a", "text": "Splints and braces on both legs"}, {"id": "b", "text": "Bed alarm and a walker at the bedside"}, {"id": "c", "text": "Padded side rails and bedside suction"}, {"id": "d", "text": "Thickened liquids kept at the bedside"}]'::jsonb, '["c"]', 'Seizures occur in about 35% of children with CP; precautions include padded rails, suction at the bedside, and available rescue medications. Splints, bed alarms, and thickened liquids address contractures, falls, and aspiration.'),
  ('cp', 47, 'A nurse is caring for an immobile child with spastic quadriplegic cerebral palsy. Which intervention helps prevent contractures?', '[{"id": "a", "text": "Limit movement to reduce muscle tone"}, {"id": "b", "text": "Reposition the child every 4 hours"}, {"id": "c", "text": "Avoid splints to protect the skin"}, {"id": "d", "text": "Perform passive range-of-motion exercises"}]'::jsonb, '["d"]', 'Contracture prevention includes passive ROM exercises, splints, braces, and repositioning every 2 hours. Repositioning only every 4 hours and avoiding splints do not meet these recommendations.'),
  ('cp', 48, 'A child with cerebral palsy has very limited mobility and spends most of the day in bed or a wheelchair. Which intervention best protects the child''s skin integrity?', '[{"id": "a", "text": "Use a pressure-relieving surface"}, {"id": "b", "text": "Reposition only if skin is red"}, {"id": "c", "text": "Limit position changes at night"}, {"id": "d", "text": "Keep the child in one position"}]'::jsonb, '["a"]', 'Immobility increases pressure ulcer risk, so care includes frequent repositioning and pressure-relieving surfaces. Waiting for redness or limiting position changes increases risk.'),
  ('cp', 49, 'A 14-year-old with dyskinetic cerebral palsy has severely impaired speech and uses an augmentative communication device. Which nursing action is most appropriate?', '[{"id": "a", "text": "Direct all questions to the parent only"}, {"id": "b", "text": "Speak to the teen and use the AAC device"}, {"id": "c", "text": "Use simple baby talk with the teen"}, {"id": "d", "text": "Avoid questions that need a reply"}]'::jsonb, '["b"]', 'AAC devices support communication when speech is impaired, and the nurse should never assume a cognitive deficit from motor impairment. Speaking only to the parent or using baby talk assumes a cognitive deficit.'),
  ('cp', 50, 'The mother of a child with severe cerebral palsy tells the nurse, ''I am exhausted. I never get a break from caring for him.'' Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"You should stop his therapy sessions for now.\""}, {"id": "b", "text": "\"His condition will get easier as the injury heals.\""}, {"id": "c", "text": "\"Let''s talk about respite and community resources.\""}, {"id": "d", "text": "\"Caregivers of children with CP rarely need help.\""}]'::jsonb, '["c"]', 'Family support includes guiding parents on therapy adherence, realistic expectations, community resources, and caregiver respite. Stopping therapy contradicts therapy adherence, and the brain injury in CP does not heal.'),
  ('aneurysm', 1, 'A 48-year-old client is brought to the emergency department reporting a sudden, severe headache described as “the worst headache of my life,” a stiff neck, and sensitivity to light. The nurse should suspect which condition?', '[{"id": "a", "text": "Unruptured aneurysm causing cranial nerve deficits"}, {"id": "b", "text": "Ruptured cerebral aneurysm with subarachnoid hemorrhage"}, {"id": "c", "text": "Hydrocephalus developing days after aneurysm clipping"}, {"id": "d", "text": "SIADH developing after treatment of an aneurysm"}]'::jsonb, '["b"]', 'A sudden thunderclap headache with nuchal rigidity and photophobia is the classic presentation of a ruptured aneurysm causing SAH, a neurological emergency. An unruptured aneurysm may be silent or cause headaches, vision problems, or cranial nerve deficits rather than this sudden triad.'),
  ('aneurysm', 2, 'A client newly diagnosed with a cerebral aneurysm asks the nurse what an aneurysm is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A buildup of cerebrospinal fluid that is blocked by old blood"}, {"id": "b", "text": "A clot that temporarily blocks blood flow to part of the brain"}, {"id": "c", "text": "A localized ballooning of a weakened artery wall in the brain"}, {"id": "d", "text": "A plaque that completely closes off an artery in the brain"}]'::jsonb, '["c"]', 'A cerebral aneurysm is a localized ballooning or dilation of a weakened arterial wall in the brain; if it ruptures, it causes a subarachnoid hemorrhage. Blocked CSF flow describes hydrocephalus, a complication rather than the aneurysm itself.'),
  ('aneurysm', 3, 'A client with a subarachnoid hemorrhage has nuchal rigidity. The client''s spouse asks why the client''s neck is so stiff. The nurse''s best response is that the stiffness is caused by:', '[{"id": "a", "text": "muscle spasm resulting from prolonged strict bed rest"}, {"id": "b", "text": "pressure from the aneurysm sac on the cranial nerves"}, {"id": "c", "text": "brain swelling resulting from a low serum sodium level"}, {"id": "d", "text": "blood in the subarachnoid space irritating the meninges"}]'::jsonb, '["d"]', 'Nuchal rigidity after rupture is a stiff neck from blood irritating the meninges. Cranial nerve deficits are associated with unruptured aneurysms, not with the stiff neck of SAH.'),
  ('aneurysm', 4, 'The nurse is caring for a client with a known unruptured cerebral aneurysm that is being monitored. Which finding is consistent with an unruptured aneurysm?', '[{"id": "a", "text": "Vision problems with eye pain"}, {"id": "b", "text": "Abrupt onset of nuchal rigidity"}, {"id": "c", "text": "Sudden loss of consciousness"}, {"id": "d", "text": "Thunderclap headache with vomiting"}]'::jsonb, '["a"]', 'Unruptured aneurysms may be silent or cause headaches, vision problems, eye pain, or cranial nerve deficits. Sudden loss of consciousness, nuchal rigidity, and a thunderclap headache with vomiting indicate rupture with SAH.'),
  ('aneurysm', 5, 'A client is told that a cerebral aneurysm was found on a scan ordered for an unrelated reason. The client says, “How can I have this when I never felt anything?” Which response by the nurse is accurate?', '[{"id": "a", "text": "“Aneurysms always cause severe pain, so yours must have ruptured.”"}, {"id": "b", "text": "“Unruptured aneurysms may be silent and are often found on imaging.”"}, {"id": "c", "text": "“The scan most likely found an old clot rather than an aneurysm.”"}, {"id": "d", "text": "“Silent aneurysms are harmless and will not need any follow-up.”"}]'::jsonb, '["b"]', 'Unruptured aneurysms may be silent and are often found incidentally on imaging. They are still monitored for size and growth with periodic imaging, so stating no follow-up is needed is incorrect.'),
  ('aneurysm', 6, 'A client with an unruptured cerebral aneurysm asks which risk factor is most important to change. The nurse should emphasize control of which factor?', '[{"id": "a", "text": "Smoking"}, {"id": "b", "text": "Head trauma"}, {"id": "c", "text": "Hypertension"}, {"id": "d", "text": "Polycystic kidney disease"}]'::jsonb, '["c"]', 'Hypertension is the #1 modifiable risk factor for cerebral aneurysm. Smoking is also modifiable but is not the top risk, and polycystic kidney disease is a genetic factor that cannot be changed.'),
  ('aneurysm', 7, 'The nurse reviews the health histories of four clients. Which client has a genetic disorder associated with an increased risk of cerebral aneurysm?', '[{"id": "a", "text": "A client with asthma"}, {"id": "b", "text": "A client with osteoarthritis"}, {"id": "c", "text": "A client with hypothyroidism"}, {"id": "d", "text": "A client with polycystic kidney disease"}]'::jsonb, '["d"]', 'Genetic disorders such as polycystic kidney disease are a structural/congenital cause of cerebral aneurysm. The other conditions are not listed as aneurysm risk factors.'),
  ('aneurysm', 8, 'A client with atherosclerosis asks how this condition is related to cerebral aneurysms. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“Fatty plaques can weaken the walls of the arteries.”"}, {"id": "b", "text": "“Fatty plaques block CSF flow and make vessels swell.”"}, {"id": "c", "text": "“Atherosclerosis is a defect present from birth.”"}, {"id": "d", "text": "“Atherosclerosis lowers blood pressure in the brain.”"}]'::jsonb, '["a"]', 'Atherosclerosis contributes to aneurysm formation because fatty plaques weaken arterial walls. Defects present at birth are congenital arterial wall defects, a separate cause.'),
  ('aneurysm', 9, 'A client arrives in the emergency department with a sudden, severe headache and nuchal rigidity. The nurse anticipates that which diagnostic test will be performed first?', '[{"id": "a", "text": "Lumbar puncture"}, {"id": "b", "text": "CT scan without contrast"}, {"id": "c", "text": "MRI/MRA of the brain"}, {"id": "d", "text": "Cerebral angiography"}]'::jsonb, '["b"]', 'A noncontrast CT scan is the first test because it is fast, widely available, and detects blood in the subarachnoid space after rupture. A lumbar puncture is ordered only after the CT.'),
  ('aneurysm', 10, 'A client with a suspected subarachnoid hemorrhage has a CT scan that shows no blood, but the provider''s suspicion remains high. The nurse prepares the client for which test next?', '[{"id": "a", "text": "MRI/MRA of the brain"}, {"id": "b", "text": "Cerebral angiography"}, {"id": "c", "text": "Lumbar puncture"}, {"id": "d", "text": "Serum sodium level"}]'::jsonb, '["c"]', 'If the CT is negative but suspicion for SAH is high, a lumbar puncture is done to check for xanthochromia. Cerebral angiography is used to confirm aneurysm location before surgery, not to rule out SAH after a negative CT.'),
  ('aneurysm', 11, 'Cerebrospinal fluid obtained by lumbar puncture from a client with a suspected subarachnoid hemorrhage is described as xanthochromic. The nurse understands that this finding indicates:', '[{"id": "a", "text": "infection of the meninges"}, {"id": "b", "text": "excess sodium in the CSF"}, {"id": "c", "text": "a normal CSF sample"}, {"id": "d", "text": "old blood in the CSF"}]'::jsonb, '["d"]', 'Xanthochromia is yellow-tinged CSF that indicates old blood, supporting blood in the subarachnoid space. It is not a normal finding.'),
  ('aneurysm', 12, 'A client with a confirmed subarachnoid hemorrhage is being prepared for surgical repair of the aneurysm. Which test is considered the gold standard for confirming the aneurysm''s location before surgery?', '[{"id": "a", "text": "Cerebral angiography"}, {"id": "b", "text": "Lumbar puncture"}, {"id": "c", "text": "CT scan without contrast"}, {"id": "d", "text": "Serum osmolality"}]'::jsonb, '["a"]', 'Cerebral angiography is the gold standard, providing detailed vessel imaging that confirms location before surgery. A noncontrast CT is the first test to detect subarachnoid blood, not the gold standard for vessel detail.'),
  ('aneurysm', 13, 'A client''s unruptured cerebral aneurysm needs further evaluation. Which diagnostic study does the nurse anticipate as best suited for evaluating an unruptured aneurysm?', '[{"id": "a", "text": "Lumbar puncture"}, {"id": "b", "text": "MRI/MRA"}, {"id": "c", "text": "CT scan without contrast"}, {"id": "d", "text": "Serum sodium level"}]'::jsonb, '["b"]', 'MRI/MRA detects aneurysm size, shape, and location and is better for unruptured aneurysms. A noncontrast CT is used first to detect subarachnoid blood after rupture.'),
  ('aneurysm', 14, 'The nurse is reviewing the diagnostic workup for subarachnoid hemorrhage with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "“A CT scan without contrast is usually the first test done.”"}, {"id": "b", "text": "“Xanthochromia in the CSF suggests subarachnoid blood.”"}, {"id": "c", "text": "“A lumbar puncture should be performed before the CT scan.”"}, {"id": "d", "text": "“Cerebral angiography provides detailed vessel imaging.”"}]'::jsonb, '["c"]', 'In suspected SAH, a CT scan is always done before a lumbar puncture; an LP is never done first. The other statements are correct.'),
  ('aneurysm', 15, 'A client with a ruptured cerebral aneurysm is unresponsive and has noisy, irregular respirations. Which action should the nurse take first?', '[{"id": "a", "text": "Administer the scheduled oral nimodipine"}, {"id": "b", "text": "Give the prescribed stool softener"}, {"id": "c", "text": "Prepare the client for cerebral angiography"}, {"id": "d", "text": "Ensure a patent airway and adequate breathing"}]'::jsonb, '["d"]', 'Emergency treatment of a ruptured aneurysm begins with stabilizing the ABCs (airway, breathing, circulation). Nimodipine, stool softeners, and angiography are important but come after the airway is secured.'),
  ('aneurysm', 16, 'A client scheduled for surgical clipping asks how the procedure treats a cerebral aneurysm. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A clip is placed on the aneurysm''s neck to stop blood from entering the sac."}, {"id": "b", "text": "Coils are threaded into the aneurysm to promote clotting inside the sac."}, {"id": "c", "text": "A clip is placed to drain old blood out of the subarachnoid space."}, {"id": "d", "text": "A catheter delivers medication into the sac to prevent vasospasm."}]'::jsonb, '["a"]', 'Clipping places a surgical clip on the neck of the aneurysm to stop blood flow into the sac. Inserting coils to promote clotting describes endovascular coiling, a different procedure.'),
  ('aneurysm', 17, 'The family of a client with a ruptured aneurysm asks about endovascular coiling. Which statement by the nurse is accurate?', '[{"id": "a", "text": "“A clip is placed on the aneurysm neck through an open surgical incision.”"}, {"id": "b", "text": "“Coils promote clotting in the aneurysm and the procedure is less invasive.”"}, {"id": "c", "text": "“Coiling is used to prevent vasospasm in place of giving nimodipine.”"}, {"id": "d", "text": "“Coiling is the first diagnostic step when a rupture is suspected.”"}]'::jsonb, '["b"]', 'Endovascular coiling inserts coils into the aneurysm to promote clotting and is less invasive. Placing a clip on the aneurysm neck describes surgical clipping.'),
  ('aneurysm', 18, 'The nurse teaches a client with a small unruptured aneurysm that is being managed without surgery. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "“I will have periodic imaging to see if it is growing.”"}, {"id": "b", "text": "“I will take my blood pressure medicine every day.”"}, {"id": "c", "text": "“Since it hasn''t ruptured, I can keep smoking for now.”"}, {"id": "d", "text": "“Surgery may be considered if my risk becomes high.”"}]'::jsonb, '["c"]', 'Management of an unruptured aneurysm includes smoking cessation, along with periodic imaging, BP control, and clipping or coiling in high-risk cases. Continuing to smoke shows the client needs more teaching.'),
  ('aneurysm', 19, 'The nurse is positioning a client admitted with a subarachnoid hemorrhage. Which position is most appropriate?', '[{"id": "a", "text": "Flat with knees flexed"}, {"id": "b", "text": "HOB 90° with neck flexed"}, {"id": "c", "text": "Trendelenburg with head turned"}, {"id": "d", "text": "HOB 30° with head midline"}]'::jsonb, '["d"]', 'To prevent increased ICP, the head of the bed is elevated 30° with the head midline. Neck flexion should be avoided because it can raise ICP.'),
  ('aneurysm', 20, 'The nurse is delegating care of a client with a subarachnoid hemorrhage to an assistive personnel. Which instruction is most appropriate?', '[{"id": "a", "text": "“Keep the head midline and avoid flexing the client''s neck.”"}, {"id": "b", "text": "“Help the client bear down when having a bowel movement.”"}, {"id": "c", "text": "“Encourage the client to cough forcefully every hour.”"}, {"id": "d", "text": "“Keep the room brightly lit and the television on.”"}]'::jsonb, '["a"]', 'Preventing increased ICP includes avoiding coughing, straining, and neck flexion and keeping the head midline. Forceful coughing and bearing down would increase ICP.'),
  ('aneurysm', 21, 'A client with a subarachnoid hemorrhage reports sensitivity to light and is restless. Which nursing intervention is most appropriate?', '[{"id": "a", "text": "Encourage frequent visits from many relatives"}, {"id": "b", "text": "Provide a quiet, low-stimulation environment"}, {"id": "c", "text": "Keep bright overhead lights on for safety checks"}, {"id": "d", "text": "Lower the head of the bed flat for comfort"}]'::jsonb, '["b"]', 'A quiet, low-stimulation environment is part of preventing increased ICP in SAH. Lowering the bed flat contradicts the standard HOB 30° position.'),
  ('aneurysm', 22, 'A client with a subarachnoid hemorrhage asks why a stool softener has been prescribed when constipation has not been a problem. The nurse''s best response is that the stool softener:', '[{"id": "a", "text": "increases urine output to reduce the effects of SIADH"}, {"id": "b", "text": "prevents the dehydration caused by nimodipine therapy"}, {"id": "c", "text": "prevents straining, which lowers the risk of rebleeding"}, {"id": "d", "text": "relaxes cerebral vessels to reduce the risk of vasospasm"}]'::jsonb, '["c"]', 'Stool softeners prevent straining and the Valsalva maneuver, which reduces the risk of rebleeding. Vasospasm prevention is the role of nimodipine, not stool softeners.'),
  ('aneurysm', 23, 'A client with a subarachnoid hemorrhage is receiving antihypertensive therapy. The client''s blood pressure has fallen well below the prescribed target range. The nurse recognizes this is a concern because hypotension:', '[{"id": "a", "text": "increases the risk of rebleeding"}, {"id": "b", "text": "triggers SIADH and fluid retention"}, {"id": "c", "text": "causes xanthochromia in the CSF"}, {"id": "d", "text": "worsens cerebral perfusion pressure"}]'::jsonb, '["d"]', 'Antihypertensives are used to maintain a stable BP, and hypotension must be avoided because it worsens CPP. BP control after SAH aims to be not too high and not too low.'),
  ('aneurysm', 24, 'A client was admitted yesterday with a ruptured cerebral aneurysm. Which prescription should the nurse question?', '[{"id": "a", "text": "Ambulate in hallway four times daily"}, {"id": "b", "text": "Stool softener once daily"}, {"id": "c", "text": "Nimodipine orally on schedule"}, {"id": "d", "text": "Seizure precautions at all times"}]'::jsonb, '["a"]', 'To prevent rebleeding, activity is limited with strict bed rest early after rupture, so frequent hallway ambulation should be questioned. Nimodipine, stool softeners, and seizure precautions are all expected.'),
  ('aneurysm', 25, 'A client with a subarachnoid hemorrhage is prescribed nimodipine. The nurse understands that this medication is a:', '[{"id": "a", "text": "osmotic diuretic given to reduce intracranial pressure"}, {"id": "b", "text": "calcium channel blocker given to prevent vasospasm"}, {"id": "c", "text": "antiepileptic given to prevent post-rupture seizures"}, {"id": "d", "text": "laxative given to prevent straining and rebleeding"}]'::jsonb, '["b"]', 'Nimodipine is a calcium channel blocker that prevents cerebral vasospasm after SAH. Reducing ICP is the role of mannitol, an osmotic diuretic.'),
  ('aneurysm', 26, 'The nurse observes a newly hired nurse preparing a scheduled dose of nimodipine for a client with a subarachnoid hemorrhage. Which action requires the nurse to intervene?', '[{"id": "a", "text": "Checking the client''s neurological status before the dose"}, {"id": "b", "text": "Giving the dose at the scheduled time"}, {"id": "c", "text": "Drawing the capsule contents into a syringe for IV push"}, {"id": "d", "text": "Monitoring the client''s blood pressure after the dose"}]'::jsonb, '["c"]', 'Nimodipine is given orally, not by IV push, so preparing it for IV push requires intervention. Giving it on schedule and monitoring neuro status and BP are appropriate.'),
  ('aneurysm', 27, 'A client recovering from a subarachnoid hemorrhage is receiving nimodipine. Which statement by the client indicates correct understanding of the therapy?', '[{"id": "a", "text": "“I will take it only when I have a bad headache.”"}, {"id": "b", "text": "“I will take it once a week to prevent seizures.”"}, {"id": "c", "text": "“I will stop it as soon as my neck stops hurting.”"}, {"id": "d", "text": "“I will take it by mouth on schedule for 21 days.”"}]'::jsonb, '["d"]', 'Nimodipine is given orally on a regular schedule for 21 days to prevent vasospasm after SAH. Taking it only as needed or stopping early does not match the prescribed course, and seizure prevention is the role of anticonvulsants.'),
  ('aneurysm', 28, 'The nurse is planning care for a client admitted with a subarachnoid hemorrhage. During which time frame should the nurse anticipate that the risk of cerebral vasospasm peaks?', '[{"id": "a", "text": "Within the first 24 hours after rupture"}, {"id": "b", "text": "Days 3 to 10 after rupture"}, {"id": "c", "text": "Days 21 to 30 after rupture"}, {"id": "d", "text": "Only after surgical clipping"}]'::jsonb, '["b"]', 'Vasospasm is a major complication after SAH that peaks on days 3 to 10. It is not limited to the first day or to the period after clipping.'),
  ('aneurysm', 29, 'A nursing student asks why cerebral vasospasm after a subarachnoid hemorrhage is considered so dangerous. The nurse explains that vasospasm can lead to:', '[{"id": "a", "text": "hydrocephalus"}, {"id": "b", "text": "ischemic stroke"}, {"id": "c", "text": "SIADH"}, {"id": "d", "text": "xanthochromia"}]'::jsonb, '["b"]', 'Vasospasm can cause an ischemic stroke, which is why it is a major complication after SAH. Hydrocephalus results from blood blocking CSF flow, not from vasospasm.'),
  ('aneurysm', 30, 'Four days after a subarachnoid hemorrhage, a client''s provider suspects that blood is obstructing the flow of cerebrospinal fluid. The nurse recognizes this complication as:', '[{"id": "a", "text": "vasospasm"}, {"id": "b", "text": "SIADH"}, {"id": "c", "text": "hydrocephalus"}, {"id": "d", "text": "rebleeding"}]'::jsonb, '["c"]', 'Hydrocephalus occurs when blood blocks CSF flow after SAH. Vasospasm is narrowing of cerebral vessels that can cause ischemic stroke.'),
  ('aneurysm', 31, 'A client with a ruptured cerebral aneurysm is prescribed levetiracetam. The nurse understands that the purpose of this medication is to:', '[{"id": "a", "text": "prevent cerebral vasospasm"}, {"id": "b", "text": "prevent straining with stools"}, {"id": "c", "text": "reduce intracranial pressure"}, {"id": "d", "text": "prevent post-rupture seizures"}]'::jsonb, '["d"]', 'Anticonvulsants such as phenytoin and levetiracetam are given to prevent post-rupture seizures. Vasospasm prevention is the role of nimodipine.'),
  ('aneurysm', 32, 'Several days after a subarachnoid hemorrhage, a client becomes newly confused. The client has gained weight, the urine is concentrated, and the serum sodium has dropped below normal. The nurse suspects which complication?', '[{"id": "a", "text": "SIADH"}, {"id": "b", "text": "Hydrocephalus"}, {"id": "c", "text": "Vasospasm"}, {"id": "d", "text": "Rebleeding"}]'::jsonb, '["a"]', 'SIADH after SAH presents with decreased sodium, concentrated urine, weight gain, and confusion. Hydrocephalus is caused by blood blocking CSF flow and does not explain the sodium and urine changes.'),
  ('aneurysm', 33, 'The nurse is monitoring a client with a subarachnoid hemorrhage for SIADH. Which set of assessments is most appropriate?', '[{"id": "a", "text": "Serum potassium, chest x-ray, and pulse oximetry"}, {"id": "b", "text": "Serum sodium, urine specific gravity, and daily weights"}, {"id": "c", "text": "CSF color, CT scan, and cerebral angiography"}, {"id": "d", "text": "Seizure activity, stool pattern, and pain scores"}]'::jsonb, '["b"]', 'Monitoring for SIADH includes serum sodium, urine specific gravity, and daily weights, along with I&O. The other assessments do not target SIADH.'),
  ('aneurysm', 34, 'A client who had a subarachnoid hemorrhage is receiving mannitol. Which assessments should the nurse monitor specifically for this medication?', '[{"id": "a", "text": "Seizure activity and drug levels"}, {"id": "b", "text": "Stool frequency and consistency"}, {"id": "c", "text": "Serum osmolality and urine output"}, {"id": "d", "text": "CSF color and xanthochromia"}]'::jsonb, '["c"]', 'Mannitol is an osmotic diuretic that reduces ICP, so the nurse monitors serum osmolality and urine output. Stool pattern relates to stool softeners, and seizure activity relates to anticonvulsants.'),
  ('aneurysm', 35, 'A client with a subarachnoid hemorrhage has several new prescriptions. Which medication is given primarily to reduce intracranial pressure?', '[{"id": "a", "text": "Nimodipine"}, {"id": "b", "text": "Phenytoin"}, {"id": "c", "text": "Stool softener"}, {"id": "d", "text": "Mannitol"}]'::jsonb, '["d"]', 'Mannitol, an osmotic diuretic, reduces ICP. Nimodipine prevents vasospasm, phenytoin prevents seizures, and stool softeners prevent straining.'),
  ('aneurysm', 36, 'When planning care to prevent increased intracranial pressure in a client with a subarachnoid hemorrhage, which assessment should the nurse perform closely and frequently?', '[{"id": "a", "text": "Neurological status and level of consciousness"}, {"id": "b", "text": "Peripheral pulses in the lower extremities"}, {"id": "c", "text": "Bowel sounds in all four quadrants"}, {"id": "d", "text": "Skin integrity over bony prominences"}]'::jsonb, '["a"]', 'Nursing priorities for preventing increased ICP include monitoring neuro status and LOC closely. The other assessments are not the focus for this priority.'),
  ('aneurysm', 37, 'The nurse receives report on four clients on a neurology unit. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with an unruptured aneurysm reporting mild eye pain"}, {"id": "b", "text": "A client reporting a sudden severe headache and a stiff neck"}, {"id": "c", "text": "A client on day 2 of nimodipine with a stable neuro exam"}, {"id": "d", "text": "A client awaiting periodic imaging of a small aneurysm"}]'::jsonb, '["b"]', 'A sudden severe headache with nuchal rigidity suggests SAH, which is an emergency. Mild eye pain can occur with an unruptured aneurysm and is not an emergency presentation.'),
  ('aneurysm', 38, 'A client being monitored for a known unruptured aneurysm develops nausea and vomiting and then suddenly loses consciousness. The nurse recognizes that these findings most likely indicate:', '[{"id": "a", "text": "expected symptoms of an unruptured aneurysm"}, {"id": "b", "text": "cranial nerve deficits from aneurysm growth"}, {"id": "c", "text": "rupture of the aneurysm causing an SAH"}, {"id": "d", "text": "a normal reaction to periodic imaging studies"}]'::jsonb, '["c"]', 'Sudden loss of consciousness with nausea and vomiting are signs of a ruptured aneurysm causing SAH. Unruptured aneurysms may be silent or cause headaches, vision problems, or cranial nerve deficits.'),
  ('aneurysm', 39, 'A client returns to the neurology unit after surgical clipping of a ruptured cerebral aneurysm. At which angle should the nurse maintain the head of the bed?', '[{"id": "a", "text": "Flat at 0°"}, {"id": "b", "text": "Elevated 30°"}, {"id": "c", "text": "Elevated 60°"}, {"id": "d", "text": "Elevated 90°"}]'::jsonb, '["b"]', 'A head-of-bed elevation of 30° is standard after neurosurgery and SAH. Lying flat does not match this standard.'),
  ('aneurysm', 40, 'A client with a subarachnoid hemorrhage is prescribed phenytoin. The client has not had a seizure, and the family asks why this drug is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "“It is given to prevent seizures that can occur after rupture.”"}, {"id": "b", "text": "“It is given to prevent spasm of the blood vessels in the brain.”"}, {"id": "c", "text": "“It is given to pull fluid from the brain and lower pressure.”"}, {"id": "d", "text": "“It is given to keep the stool soft and prevent straining.”"}]'::jsonb, '["a"]', 'Anticonvulsants such as phenytoin are given to prevent post-rupture seizures, even before a seizure occurs. Preventing vessel spasm is the purpose of nimodipine.'),
  ('aneurysm', 41, 'Which finding best indicates that nimodipine therapy is achieving its intended effect in a client recovering from a subarachnoid hemorrhage?', '[{"id": "a", "text": "Stools are soft and passed without straining"}, {"id": "b", "text": "No new ischemic deficits from vasospasm develop"}, {"id": "c", "text": "Serum osmolality remains within target range"}, {"id": "d", "text": "Urine output increases after each dose"}]'::jsonb, '["b"]', 'Nimodipine prevents vasospasm, which can cause ischemic stroke, so the absence of vasospasm-related ischemic deficits shows effectiveness. Serum osmolality is monitored with mannitol, not nimodipine.'),
  ('aneurysm', 42, 'A client with an unruptured cerebral aneurysm is prescribed an antihypertensive. The client asks why it is needed when the aneurysm has not bled. The nurse explains that the medication is used for:', '[{"id": "a", "text": "reducing intracranial pressure by increasing urine output"}, {"id": "b", "text": "preventing vasospasm until the aneurysm can be clipped"}, {"id": "c", "text": "managing the aneurysm by keeping blood pressure controlled"}, {"id": "d", "text": "preventing seizures caused by the unruptured aneurysm"}]'::jsonb, '["c"]', 'Management of an unruptured aneurysm includes BP control with antihypertensives, and hypertension is the #1 modifiable risk factor. Vasospasm prevention with nimodipine applies after SAH.'),
  ('aneurysm', 43, 'A client with a subarachnoid hemorrhage is coughing forcefully and frequently. The nurse is concerned because this activity can:', '[{"id": "a", "text": "speed nimodipine absorption"}, {"id": "b", "text": "lower the serum sodium level"}, {"id": "c", "text": "cause xanthochromia in the CSF"}, {"id": "d", "text": "raise intracranial pressure"}]'::jsonb, '["d"]', 'Coughing, straining, and neck flexion are avoided to prevent increased ICP after SAH. A low serum sodium level relates to SIADH, not coughing.'),
  ('aneurysm', 44, 'A 26-year-old client with no history of hypertension, smoking, or head injury is diagnosed with a cerebral aneurysm. The client asks what may have caused it. Which cause is most consistent with this history?', '[{"id": "a", "text": "A congenital arterial wall defect present since birth"}, {"id": "b", "text": "Repeated lumbar punctures performed in childhood"}, {"id": "c", "text": "Low serum sodium from long-term fluid retention"}, {"id": "d", "text": "Earlier treatment with an osmotic diuretic drug"}]'::jsonb, '["a"]', 'Congenital arterial wall defects present at birth are a structural cause of cerebral aneurysm. The other options are not listed causes.'),
  ('aneurysm', 45, 'A client is admitted with a suspected ruptured cerebral aneurysm. In addition to a severe headache, which assessment finding would the nurse expect?', '[{"id": "a", "text": "Absence of any symptoms until imaging is done"}, {"id": "b", "text": "Hemiparesis and altered level of consciousness"}, {"id": "c", "text": "Eye pain that has developed gradually over months"}, {"id": "d", "text": "A slowly progressing cranial nerve deficit"}]'::jsonb, '["b"]', 'A ruptured aneurysm can cause hemiparesis, confusion, and altered LOC. Silent courses, gradual eye pain, and cranial nerve deficits are associated with unruptured aneurysms.'),
  ('aneurysm', 46, 'A client with a subarachnoid hemorrhage is asleep when a scheduled dose of nimodipine is due. Which action should the nurse take?', '[{"id": "a", "text": "Give the dose IV push when the client wakes"}, {"id": "b", "text": "Skip this dose and give the next one on time"}, {"id": "c", "text": "Wake the client and give the dose on schedule"}, {"id": "d", "text": "Hold the dose until the client requests it"}]'::jsonb, '["c"]', 'Preventing rebleeding and vasospasm includes administering nimodipine on schedule, orally rather than IV push. Skipping or delaying doses does not meet this priority.'),
  ('aneurysm', 47, 'The nurse is reviewing possible complications of subarachnoid hemorrhage with a client''s family. Which statement by a family member indicates a need for further teaching?', '[{"id": "a", "text": "“Spasm of the brain''s blood vessels can lead to a stroke.”"}, {"id": "b", "text": "“Blood can block the flow of fluid around the brain.”"}, {"id": "c", "text": "“Seizures are a possible complication after the rupture.”"}, {"id": "d", "text": "“Sodium levels do not need to be watched after this bleed.”"}]'::jsonb, '["d"]', 'SIADH is a complication of SAH, so sodium, I&O, and urine output are monitored. Vasospasm causing ischemic stroke, hydrocephalus from blocked CSF flow, and seizures are all correctly identified complications.'),
  ('aneurysm', 48, 'A client''s unruptured cerebral aneurysm has been classified as high risk. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Surgical clipping or endovascular coiling"}, {"id": "b", "text": "Lumbar puncture to check for xanthochromia"}, {"id": "c", "text": "Mannitol to reduce intracranial pressure"}, {"id": "d", "text": "Nimodipine given by IV push every 4 hours"}]'::jsonb, '["a"]', 'Unruptured aneurysms are treated with surgical clipping or coiling in high-risk cases. Nimodipine is given orally, not IV push, to prevent vasospasm after SAH.'),
  ('aneurysm', 49, 'Which blood pressure goal is most appropriate for a client with a ruptured cerebral aneurysm who is awaiting repair?', '[{"id": "a", "text": "Keep BP as low as possible to prevent any rebleeding"}, {"id": "b", "text": "Keep BP stable, avoiding both high and low extremes"}, {"id": "c", "text": "Allow BP to rise freely to improve cerebral perfusion"}, {"id": "d", "text": "Check BP once daily because it does not affect bleeding"}]'::jsonb, '["b"]', 'To prevent rebleeding, BP is controlled so it is not too high and not too low. Keeping BP as low as possible is unsafe because hypotension worsens CPP.'),
  ('aneurysm', 50, 'A client reports headaches and is found to have a cranial nerve deficit, but has no neck stiffness or sudden change in consciousness. Imaging shows an aneurysm with no bleeding. The nurse recognizes these findings as consistent with:', '[{"id": "a", "text": "cerebral vasospasm"}, {"id": "b", "text": "a ruptured aneurysm with SAH"}, {"id": "c", "text": "an unruptured aneurysm"}, {"id": "d", "text": "hydrocephalus"}]'::jsonb, '["c"]', 'Unruptured aneurysms may cause headaches, vision problems, eye pain, and cranial nerve deficits. A ruptured aneurysm with SAH would present with a sudden thunderclap headache, nuchal rigidity, and possible loss of consciousness.'),
  ('clonus', 1, 'While examining a client''s lower extremity, the nurse quickly dorsiflexes the foot and holds it. The foot begins to beat in a rhythmic, repetitive pattern of contraction and relaxation. The nurse documents this finding as which of the following?', '[{"id": "a", "text": "Clonus"}, {"id": "b", "text": "Fasciculation"}, {"id": "c", "text": "Asterixis"}, {"id": "d", "text": "Babinski sign"}]'::jsonb, '["a"]', 'Clonus is a series of involuntary, rhythmic, repetitive contractions and relaxations triggered by sudden, sustained muscle stretch, most commonly elicited at the ankle. Fasciculations are visible muscle twitches of LMN lesions.'),
  ('clonus', 2, 'A nursing student asks why damage to the brain or spinal cord can produce clonus. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Peripheral nerve damage increases reflex firing."}, {"id": "b", "text": "UMN damage removes inhibition of reflex arcs."}, {"id": "c", "text": "Muscle atrophy triggers rhythmic contractions."}, {"id": "d", "text": "LMN damage removes normal muscle tone."}]'::jsonb, '["b"]', 'Healthy nervous systems suppress reflex arcs; when the UMN pathway is damaged, this inhibition is lost and exaggerated, sustained reflexes result. LMN damage produces flaccidity and hyporeflexia instead.'),
  ('clonus', 3, 'During a pre-employment physical, the nurse elicits ankle clonus in a healthy 25-year-old and observes a single beat that stops on its own. How should the nurse interpret this finding?', '[{"id": "a", "text": "Sustained clonus requiring a report"}, {"id": "b", "text": "Sign of an upper motor neuron lesion"}, {"id": "c", "text": "Normal finding with intact inhibition"}, {"id": "d", "text": "Sign of a lower motor neuron lesion"}]'::jsonb, '["c"]', 'Zero to one clonic beat is normal, indicating reflexes are intact and inhibited with no pathology. Sustained clonus continues as long as the stretch is maintained.'),
  ('clonus', 4, 'While eliciting ankle clonus, the nurse notes that the foot continues to beat rhythmically for as long as the dorsiflexion stretch is held. How should the nurse interpret this finding?', '[{"id": "a", "text": "Normal finding needing no action"}, {"id": "b", "text": "Equivocal finding to recheck later"}, {"id": "c", "text": "Sign of lower motor neuron damage"}, {"id": "d", "text": "Pathologic finding of neurological concern"}]'::jsonb, '["d"]', 'Sustained clonus continues as long as the stretch is maintained and is always pathologic, an immediate neurological concern. Clonus is not a sign of LMN damage.'),
  ('clonus', 5, 'When assessing ankle clonus in a client, the nurse counts 2 beats before the movement stops. Which interpretation is most accurate?', '[{"id": "a", "text": "Normal, with no pathology"}, {"id": "b", "text": "Equivocal, may need further evaluation"}, {"id": "c", "text": "Sustained, always pathologic"}, {"id": "d", "text": "Lower motor neuron lesion sign"}]'::jsonb, '["b"]', 'Two beats is equivocal and may warrant further evaluation. Zero to one beat is normal, and sustained clonus continues until the stretch is released.'),
  ('clonus', 6, 'A nurse is preparing to assess a client for ankle clonus. After positioning the leg, which technique should the nurse use?', '[{"id": "a", "text": "Sharply dorsiflex the foot and hold the stretch"}, {"id": "b", "text": "Slowly plantar flex the foot, then release it"}, {"id": "c", "text": "Quickly dorsiflex the foot, then let go at once"}, {"id": "d", "text": "Lock the knee straight, then flex the foot"}]'::jsonb, '["a"]', 'The foot is sharply dorsiflexed toward the shin and then held in the stretched position to observe for oscillations. Releasing the stretch immediately would not allow sustained clonus to be detected.'),
  ('clonus', 7, 'Before eliciting ankle clonus, how should the nurse position the client''s leg?', '[{"id": "a", "text": "Standing with weight on the foot"}, {"id": "b", "text": "Knee locked straight, leg tensed"}, {"id": "c", "text": "Knee slightly flexed, leg relaxed"}, {"id": "d", "text": "Prone with the foot pointed down"}]'::jsonb, '["c"]', 'The client is placed supine or sitting with the knee supported in slight flexion and the leg relaxed. A tensed, locked leg does not meet this positioning.'),
  ('clonus', 8, 'A nurse is teaching a new graduate how to assess for ankle clonus. Which sequence of steps is correct?', '[{"id": "a", "text": "Dorsiflex and hold; position the leg; grasp the foot; count beats"}, {"id": "b", "text": "Grasp the foot; count beats; position the leg; dorsiflex and hold"}, {"id": "c", "text": "Position the leg; dorsiflex and release; grasp the foot; count beats"}, {"id": "d", "text": "Position the leg; grasp the foot; dorsiflex and hold; count beats"}]'::jsonb, '["d"]', 'The steps are to position the client with the leg relaxed, grasp the foot around the sole and distal leg, sharply dorsiflex and maintain the stretch, then observe and count the beats.'),
  ('clonus', 9, 'A nurse elicits ankle clonus in a client admitted with a neurological condition. Which documentation is most complete?', '[{"id": "a", "text": "Clonus present in the left ankle"}, {"id": "b", "text": "Number of clonic beats and duration"}, {"id": "c", "text": "Reflexes noted to be abnormal"}, {"id": "d", "text": "Foot moved when it was stretched"}]'::jsonb, '["b"]', 'The nurse should count the beats and document the number of clonic beats and the duration. Simply noting clonus is present omits these details.'),
  ('clonus', 10, 'A student nurse asks what is meant by dorsiflexion of the foot when testing for ankle clonus. Which description is correct?', '[{"id": "a", "text": "Pointing the foot downward"}, {"id": "b", "text": "Turning the sole inward"}, {"id": "c", "text": "Moving the top of the foot toward the shin"}, {"id": "d", "text": "Curling the toes toward the sole"}]'::jsonb, '["c"]', 'Dorsiflexion moves the top of the foot toward the shin (upward). Pointing the foot downward, like pressing a gas pedal, is plantar flexion.'),
  ('clonus', 11, 'A client who had a stroke now has ankle clonus on the affected side. Which additional finding should the nurse expect on that side?', '[{"id": "a", "text": "Fasciculations"}, {"id": "b", "text": "Flaccid muscle tone"}, {"id": "c", "text": "Hyperreflexia"}, {"id": "d", "text": "Early muscle atrophy"}]'::jsonb, '["c"]', 'Stroke is an upper motor neuron lesion, which produces hyperreflexia, spasticity, and clonus without early muscle atrophy. Fasciculations and flaccidity are LMN findings.'),
  ('clonus', 12, 'A nurse is assessing a client admitted with Guillain-Barré syndrome. Which finding should the nurse expect?', '[{"id": "a", "text": "Sustained ankle clonus"}, {"id": "b", "text": "Spasticity with increased tone"}, {"id": "c", "text": "Positive Babinski sign"}, {"id": "d", "text": "Hyporeflexia with flaccidity"}]'::jsonb, '["d"]', 'Guillain-Barré is a lower motor neuron condition, producing hyporeflexia or absent DTRs, flaccidity, and no clonus. Clonus, spasticity, and a positive Babinski are UMN signs.'),
  ('clonus', 13, 'A client has sustained ankle clonus and exaggerated deep tendon reflexes. The nurse recognizes these findings most likely indicate involvement of which structure?', '[{"id": "a", "text": "Brain or spinal cord"}, {"id": "b", "text": "Peripheral nerves"}, {"id": "c", "text": "Lower motor neurons"}, {"id": "d", "text": "Skeletal muscle fibers"}]'::jsonb, '["a"]', 'Clonus indicates an upper motor neuron lesion, so clonus or hyperreflexia points to brain or spinal cord involvement, not peripheral nerve damage.'),
  ('clonus', 14, 'After finding ankle clonus, the nurse assesses the client for other upper motor neuron signs. Which response indicates a positive Babinski sign?', '[{"id": "a", "text": "The toes curl downward"}, {"id": "b", "text": "The great toe extends upward"}, {"id": "c", "text": "Visible muscle twitching"}, {"id": "d", "text": "Rhythmic foot oscillation"}]'::jsonb, '["b"]', 'A positive Babinski sign, a UMN finding, is upward extension of the great toe. Visible muscle twitches are fasciculations, and rhythmic oscillation of the foot is clonus.'),
  ('clonus', 15, 'A nurse is differentiating upper from lower motor neuron lesions. Which finding suggests a lower motor neuron lesion?', '[{"id": "a", "text": "Visible muscle twitches"}, {"id": "b", "text": "Sustained ankle clonus"}, {"id": "c", "text": "Spasticity of the limb"}, {"id": "d", "text": "Exaggerated reflexes"}]'::jsonb, '["a"]', 'Fasciculations, or visible muscle twitches, occur with LMN lesions along with atrophy and hyporeflexia. Clonus, spasticity, and hyperreflexia are UMN signs.'),
  ('clonus', 16, 'A nurse is assessing four clients for ankle clonus. Which client is most likely to have clonus?', '[{"id": "a", "text": "A client with a history of polio"}, {"id": "b", "text": "A client with Guillain-Barré syndrome"}, {"id": "c", "text": "A client with peripheral neuropathy"}, {"id": "d", "text": "A client with multiple sclerosis"}]'::jsonb, '["d"]', 'Multiple sclerosis is an upper motor neuron condition, and UMN lesions produce clonus. Polio, Guillain-Barré, and peripheral neuropathy are LMN examples with no clonus.'),
  ('clonus', 17, 'A client had an ischemic stroke affecting the left cerebral hemisphere. On which side should the nurse expect hemiplegia with hyperreflexia and clonus?', '[{"id": "a", "text": "The right (affected) side"}, {"id": "b", "text": "The left side, same as the lesion"}, {"id": "c", "text": "Both sides equally"}, {"id": "d", "text": "Neither side of the body"}]'::jsonb, '["a"]', 'Stroke causes contralateral hemiplegia with hyperreflexia on the affected side, so a left hemisphere stroke affects the right side.'),
  ('clonus', 18, 'A client with relapsing-remitting multiple sclerosis presents during a flare with new spasticity and ankle clonus. Which treatment should the nurse anticipate to address the underlying cause?', '[{"id": "a", "text": "Lactulose"}, {"id": "b", "text": "Thrombolytics"}, {"id": "c", "text": "Corticosteroids"}, {"id": "d", "text": "Calcium gluconate"}]'::jsonb, '["c"]', 'Management of clonus targets the underlying cause, and an MS flare is treated with corticosteroids. Thrombolytics are for stroke and lactulose for hepatic encephalopathy.'),
  ('clonus', 19, 'A client who sustained a T6 spinal cord injury 4 weeks ago has moved past the period of spinal shock and now has spasticity and clonus in both legs. How should the nurse interpret these findings?', '[{"id": "a", "text": "New peripheral nerve damage in the legs"}, {"id": "b", "text": "Expected UMN signs after spinal shock"}, {"id": "c", "text": "Lower motor neuron injury below the level"}, {"id": "d", "text": "Normal findings that need no follow-up"}]'::jsonb, '["b"]', 'SCI disrupts descending UMN tracts, producing spastic paralysis below the injury level after spinal shock resolves. Clonus reflects brain or spinal cord involvement, not peripheral nerve damage.'),
  ('clonus', 20, 'The parent of a child with spastic cerebral palsy asks why the child''s foot beats rhythmically when the ankle is stretched. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The nerves in the leg were damaged at birth.\""}, {"id": "b", "text": "\"The muscles in the leg are wasting away.\""}, {"id": "c", "text": "\"The brain injury is getting steadily worse.\""}, {"id": "d", "text": "\"Early brain injury affected motor neuron development.\""}]'::jsonb, '["d"]', 'In CP, early brain injury leads to abnormal UMN development, and spastic CP has hyperreflexia with clonus in severe cases. Clonus indicates CNS rather than peripheral nerve involvement.'),
  ('clonus', 21, 'A client with cirrhosis is admitted with confusion, jaundice, hyperreflexia, and ankle clonus. Which additional finding should the nurse assess for?', '[{"id": "a", "text": "Fasciculations"}, {"id": "b", "text": "Flaccid paralysis"}, {"id": "c", "text": "Proteinuria"}, {"id": "d", "text": "Asterixis"}]'::jsonb, '["d"]', 'Hepatic encephalopathy causes hyperreflexia from ammonia toxicity to the CNS; the nurse should also look for asterixis (flapping tremor), confusion, and jaundice. Proteinuria is a finding of pre-eclampsia.'),
  ('clonus', 22, 'A client with hepatic encephalopathy has hyperreflexia and clonus. Which medication should the nurse anticipate to treat the underlying cause?', '[{"id": "a", "text": "Lactulose"}, {"id": "b", "text": "Magnesium sulfate"}, {"id": "c", "text": "Thrombolytics"}, {"id": "d", "text": "Corticosteroids"}]'::jsonb, '["a"]', 'Hepatic encephalopathy is treated with lactulose as part of treating the underlying cause. Magnesium sulfate is for pre-eclampsia, and corticosteroids are for MS flares.'),
  ('clonus', 23, 'A client at 34 weeks'' gestation has a blood pressure of 162/104 mm Hg, proteinuria, a severe headache, and newly sustained ankle clonus. Which action should the nurse take first?', '[{"id": "a", "text": "Administer magnesium sulfate as prescribed"}, {"id": "b", "text": "Administer calcium gluconate as prescribed"}, {"id": "c", "text": "Recheck the blood pressure in 4 hours"}, {"id": "d", "text": "Document the clonus as an expected finding"}]'::jsonb, '["a"]', 'Clonus in pre-eclampsia signals an impending seizure, and the priority is magnesium sulfate to reduce CNS excitability. Calcium gluconate is the antidote for magnesium toxicity, not seizure prevention.'),
  ('clonus', 24, 'A pregnant client with pre-eclampsia who has not yet started any medications develops new ankle clonus. How should the nurse interpret this finding?', '[{"id": "a", "text": "Sign of magnesium toxicity"}, {"id": "b", "text": "Sign of an impending eclamptic seizure"}, {"id": "c", "text": "Expected finding of pregnancy"}, {"id": "d", "text": "Sign of peripheral nerve compression"}]'::jsonb, '["b"]', 'Clonus in a pre-eclamptic client indicates impending eclampsia (seizure). Magnesium toxicity causes loss of DTRs, not clonus.'),
  ('clonus', 25, 'A client with pre-eclampsia and hyperreflexia asks why she is receiving magnesium sulfate. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It will reverse your loss of reflexes.\""}, {"id": "b", "text": "\"It calms the nervous system to prevent seizures.\""}, {"id": "c", "text": "\"It is the main drug to lower your blood pressure.\""}, {"id": "d", "text": "\"It is the antidote for calcium toxicity.\""}]'::jsonb, '["b"]', 'Magnesium sulfate is given for seizure prophylaxis by reducing CNS excitability. Blood pressure is managed with antihypertensives such as labetalol or hydralazine.'),
  ('clonus', 26, 'A nurse is monitoring a client with pre-eclampsia who is receiving a magnesium sulfate infusion. Which finding should the nurse report immediately?', '[{"id": "a", "text": "Respiratory rate of 16/min"}, {"id": "b", "text": "Urine output of 40 mL/hr"}, {"id": "c", "text": "Patellar reflexes present"}, {"id": "d", "text": "Respiratory rate of 10/min"}]'::jsonb, '["d"]', 'During magnesium sulfate therapy the respiratory rate should be at least 12; a rate below 12 indicates respiratory depression from toxicity. The other findings meet monitoring parameters.'),
  ('clonus', 27, 'A client receiving magnesium sulfate for pre-eclampsia has the following assessment data. Which finding requires the nurse to notify the provider?', '[{"id": "a", "text": "Urine output of 20 mL/hr for 2 hours"}, {"id": "b", "text": "Respiratory rate of 14/min"}, {"id": "c", "text": "Patellar reflexes present bilaterally"}, {"id": "d", "text": "Urine output of 50 mL/hr"}]'::jsonb, '["a"]', 'Urinary output should be at least 30 mL/hr during magnesium sulfate therapy, so 20 mL/hr falls below the monitoring parameter. A respiratory rate of 14 and present reflexes are within expected limits.'),
  ('clonus', 28, 'A nurse is caring for a client receiving magnesium sulfate. Which assessment finding is the earliest sign of magnesium toxicity?', '[{"id": "a", "text": "Respiratory arrest"}, {"id": "b", "text": "Respiratory rate below 12/min"}, {"id": "c", "text": "Loss of the patellar reflex"}, {"id": "d", "text": "New onset of ankle clonus"}]'::jsonb, '["c"]', 'Magnesium toxicity causes loss of DTRs first, followed by respiratory depression and then respiratory arrest. Clonus is a sign of impending seizure, not magnesium toxicity.'),
  ('clonus', 29, 'A nurse is teaching a group of labor and delivery nurses about magnesium sulfate toxicity. Which sequence correctly reflects the order in which signs appear?', '[{"id": "a", "text": "RR below 12 → loss of DTRs → respiratory arrest"}, {"id": "b", "text": "Loss of DTRs → RR below 12 → respiratory arrest"}, {"id": "c", "text": "Respiratory arrest → RR below 12 → loss of DTRs"}, {"id": "d", "text": "Loss of DTRs → respiratory arrest → RR below 12"}]'::jsonb, '["b"]', 'Toxicity signs appear in order: loss of DTRs (patellar reflex), then respiratory depression (RR below 12), then respiratory arrest.'),
  ('clonus', 30, 'Before the next dose of magnesium sulfate, the nurse finds that a client''s patellar reflexes are absent. Which action should the nurse take?', '[{"id": "a", "text": "Hold the dose and notify the provider"}, {"id": "b", "text": "Give the dose and recheck in 1 hour"}, {"id": "c", "text": "Increase the dose to prevent seizures"}, {"id": "d", "text": "Document it as a therapeutic effect"}]'::jsonb, '["a"]', 'The patellar reflex is checked before each dose; if absent, the nurse holds the dose and notifies the provider, because loss of DTRs is the first sign of toxicity.'),
  ('clonus', 31, 'A client with severe pre-eclampsia is started on magnesium sulfate. Which medication should the nurse ensure is kept at the bedside as the antidote for toxicity?', '[{"id": "a", "text": "Lactulose syrup"}, {"id": "b", "text": "Oral baclofen"}, {"id": "c", "text": "Labetalol"}, {"id": "d", "text": "Calcium gluconate"}]'::jsonb, '["d"]', 'Calcium gluconate is the antidote for magnesium sulfate toxicity and should always be kept at the bedside. Labetalol is an antihypertensive, not an antidote.'),
  ('clonus', 32, 'A client with pre-eclampsia has a blood pressure of 168/110 mm Hg and hyperreflexia. In addition to magnesium sulfate, which medication should the nurse anticipate to manage the blood pressure?', '[{"id": "a", "text": "Baclofen"}, {"id": "b", "text": "Labetalol"}, {"id": "c", "text": "Lactulose"}, {"id": "d", "text": "Calcium gluconate"}]'::jsonb, '["b"]', 'The pre-eclampsia protocol includes antihypertensives such as labetalol or hydralazine. Calcium gluconate is the magnesium antidote, and baclofen treats chronic spasticity.'),
  ('clonus', 33, 'A client with pre-eclampsia and clonus is receiving magnesium sulfate. Which monitoring plan is consistent with the pre-eclampsia protocol?', '[{"id": "a", "text": "Fetal heart rate checks once per shift"}, {"id": "b", "text": "Maternal vital signs every 8 hours"}, {"id": "c", "text": "Continuous maternal and fetal monitoring"}, {"id": "d", "text": "Monitoring only after a seizure occurs"}]'::jsonb, '["c"]', 'The pre-eclampsia protocol includes continuous maternal and fetal monitoring along with magnesium sulfate, antihypertensives, and calcium gluconate at the bedside. Intermittent checks do not meet this standard.'),
  ('clonus', 34, 'A nurse is assessing pregnant clients at 35 weeks'' gestation. Which set of findings should the nurse report immediately as consistent with pre-eclampsia with CNS involvement?', '[{"id": "a", "text": "BP 118/74, no proteinuria, no headache"}, {"id": "b", "text": "BP 152/98, headache, visual changes, clonus"}, {"id": "c", "text": "BP 122/78, no visual changes, reflexes present"}, {"id": "d", "text": "BP 128/80, no proteinuria, no clonus"}]'::jsonb, '["b"]', 'Pre-eclampsia findings include BP of 140/90 or higher, proteinuria, headache, visual changes, hyperreflexia, and clonus. The other sets lack an elevated BP and CNS findings.'),
  ('clonus', 35, 'A nurse elicits ankle clonus in a client at 36 weeks'' gestation. Which additional assessments are the priority?', '[{"id": "a", "text": "Asterixis, jaundice, and confusion"}, {"id": "b", "text": "Fasciculations and muscle atrophy"}, {"id": "c", "text": "BP, urine protein, DTRs, headache, vision"}, {"id": "d", "text": "Plantar flexion strength and gait"}]'::jsonb, '["c"]', 'If the client is pregnant, the nurse checks BP, protein dipstick, deep tendon reflexes, headache, and vision changes to identify pre-eclampsia. Asterixis and jaundice relate to hepatic encephalopathy.'),
  ('clonus', 36, 'A nurse receives report on four clients. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with MS whose chronic clonus is documented at baseline"}, {"id": "b", "text": "A child with spastic CP and known clonus who is playing quietly"}, {"id": "c", "text": "A client with new ankle clonus who is newly confused"}, {"id": "d", "text": "A client with peripheral neuropathy and decreased reflexes"}]'::jsonb, '["c"]', 'Clonus with altered level of consciousness is a high-priority emergency. Clonus that is previously documented at baseline is less urgent, and peripheral neuropathy is an LMN condition.'),
  ('clonus', 37, 'A client with a spinal cord injury sustained 2 years ago is admitted with pneumonia. During the neurological assessment the nurse elicits sustained ankle clonus. Which action should the nurse take next?', '[{"id": "a", "text": "Check whether it is documented at baseline"}, {"id": "b", "text": "Administer magnesium sulfate immediately"}, {"id": "c", "text": "Document it as a normal finding"}, {"id": "d", "text": "Document it as a lower motor neuron sign"}]'::jsonb, '["a"]', 'Nursing assessment of clonus includes comparing to baseline to determine whether it is new or previously documented. Sustained clonus is never normal, and clonus is an UMN rather than LMN sign.'),
  ('clonus', 38, 'Management of clonus focuses on treating the underlying cause. For a client whose new clonus results from an acute stroke, which treatment aligns with this principle?', '[{"id": "a", "text": "Lactulose"}, {"id": "b", "text": "Magnesium sulfate"}, {"id": "c", "text": "Calcium gluconate"}, {"id": "d", "text": "Thrombolytics"}]'::jsonb, '["d"]', 'Stroke is treated with thrombolytics or intervention as part of treating the underlying cause. Lactulose is for hepatic encephalopathy and magnesium sulfate for pre-eclampsia.'),
  ('clonus', 39, 'A client is admitted with an acute spinal cord injury. When planning to treat the underlying cause of the client''s UMN signs, which priority should the nurse anticipate?', '[{"id": "a", "text": "Give lactulose to treat ammonia toxicity"}, {"id": "b", "text": "Give magnesium sulfate to prevent seizures"}, {"id": "c", "text": "Stabilize and prevent secondary injury"}, {"id": "d", "text": "Begin thrombolytic therapy right away"}]'::jsonb, '["c"]', 'For SCI, management is to stabilize and prevent secondary injury. Thrombolytics are for stroke, and lactulose is for hepatic encephalopathy.'),
  ('clonus', 40, 'A client with chronic spasticity and clonus from multiple sclerosis is prescribed baclofen. Which statement by the nurse correctly explains the medication''s purpose?', '[{"id": "a", "text": "\"It prevents eclamptic seizures.\""}, {"id": "b", "text": "\"It reduces muscle spasticity.\""}, {"id": "c", "text": "\"It lowers ammonia levels.\""}, {"id": "d", "text": "\"It reverses magnesium toxicity.\""}]'::jsonb, '["b"]', 'Baclofen is a GABA-B agonist that reduces spasticity in chronic spasticity and clonus. Magnesium sulfate prevents eclamptic seizures, and calcium gluconate reverses magnesium toxicity.'),
  ('clonus', 41, 'A client with chronic clonus after a spinal cord injury is started on tizanidine. The nurse identifies this medication as which type of agent?', '[{"id": "a", "text": "GABA-B agonist"}, {"id": "b", "text": "Magnesium antidote"}, {"id": "c", "text": "Alpha-2 agonist antispastic"}, {"id": "d", "text": "Seizure prophylaxis agent"}]'::jsonb, '["c"]', 'Tizanidine is an alpha-2 agonist antispastic. Baclofen is the GABA-B agonist, and calcium gluconate is the magnesium antidote.'),
  ('clonus', 42, 'A client with chronic spasticity and clonus asks about treatment options that do not involve medication. Which option should the nurse discuss?', '[{"id": "a", "text": "Botulinum toxin injections"}, {"id": "b", "text": "Short-term diazepam"}, {"id": "c", "text": "Oral baclofen therapy"}, {"id": "d", "text": "Physical therapy with stretching"}]'::jsonb, '["d"]', 'Physical therapy with stretching and splinting is the nonpharmacologic option for chronic spasticity and clonus. Botulinum toxin, diazepam, and baclofen are all medications.'),
  ('clonus', 43, 'A nurse teaches a client about the treatment plan for chronic spasticity and clonus. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Baclofen helps reduce my spasticity.\""}, {"id": "b", "text": "\"Stretching and splinting are part of my care.\""}, {"id": "c", "text": "\"Diazepam is my long-term daily spasticity drug.\""}, {"id": "d", "text": "\"Botox injections can help my spasticity.\""}]'::jsonb, '["c"]', 'Diazepam is a muscle relaxant intended for short-term use, so describing it as a long-term daily drug needs correction. Baclofen, physical therapy, and botulinum toxin are appropriate options.'),
  ('clonus', 44, 'A client who had a stroke has an arm that is stiff and resists passive movement because of increased muscle tone. The nurse documents this finding as which of the following?', '[{"id": "a", "text": "Flaccidity"}, {"id": "b", "text": "Spasticity"}, {"id": "c", "text": "Fasciculation"}, {"id": "d", "text": "Atrophy"}]'::jsonb, '["b"]', 'Spasticity is increased muscle tone (hypertonia) causing stiffness and is a UMN sign. Flaccidity, fasciculations, and atrophy are LMN findings.'),
  ('clonus', 45, 'A client has weakness of the legs with marked muscle atrophy, visible muscle twitching, and absent deep tendon reflexes. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "UMN lesion; expect sustained clonus"}, {"id": "b", "text": "UMN lesion; expect positive Babinski"}, {"id": "c", "text": "LMN lesion; expect hyperreflexia"}, {"id": "d", "text": "LMN lesion; clonus is not expected"}]'::jsonb, '["d"]', 'Atrophy, fasciculations, and absent DTRs indicate a lower motor neuron lesion, which does not produce clonus. Hyperreflexia, clonus, and a positive Babinski are UMN findings.'),
  ('clonus', 46, 'A client with multiple sclerosis asks why clonus develops during flares. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Demyelination disrupts motor inhibition pathways.\""}, {"id": "b", "text": "\"Ammonia builds up and irritates the brain.\""}, {"id": "c", "text": "\"Peripheral nerves in your legs are damaged.\""}, {"id": "d", "text": "\"Blood vessels in your brain go into spasm.\""}]'::jsonb, '["a"]', 'In MS, demyelination of UMN pathways disrupts motor inhibition, producing spasticity and clonus during flares. Ammonia toxicity describes hepatic encephalopathy, and vasospasm describes pre-eclampsia.'),
  ('clonus', 47, 'A nursing student asks why a client who had a stroke now has clonus on the affected side. Which mechanism should the nurse describe?', '[{"id": "a", "text": "Ammonia toxicity to the CNS"}, {"id": "b", "text": "Demyelination of motor pathways"}, {"id": "c", "text": "Loss of descending inhibitory UMN control"}, {"id": "d", "text": "Damage to peripheral nerves"}]'::jsonb, '["c"]', 'In stroke, brain damage causes loss of descending inhibitory UMN control. Demyelination is the mechanism in MS, and ammonia toxicity is the mechanism in hepatic encephalopathy.'),
  ('clonus', 48, 'A nurse is explaining to a pregnant client with pre-eclampsia why her reflexes are exaggerated and clonus is present. Which mechanism is responsible?', '[{"id": "a", "text": "Ammonia toxicity to the CNS"}, {"id": "b", "text": "Demyelination of motor pathways"}, {"id": "c", "text": "Lower motor neuron damage"}, {"id": "d", "text": "CNS hyperexcitability from vasospasm and edema"}]'::jsonb, '["d"]', 'In pre-eclampsia, CNS hyperexcitability results from cerebral vasospasm and edema. Ammonia toxicity describes hepatic encephalopathy, and clonus does not result from LMN damage.'),
  ('clonus', 49, 'A nurse is reviewing motor neuron function with a nursing student. Which statement by the student about upper motor neurons is correct?', '[{"id": "a", "text": "\"They send inhibitory signals to lower motor neurons.\""}, {"id": "b", "text": "\"They exit the spinal cord to reach the muscles.\""}, {"id": "c", "text": "\"Damage to them causes flaccidity and atrophy.\""}, {"id": "d", "text": "\"Damage to them causes absent reflexes.\""}]'::jsonb, '["a"]', 'Upper motor neurons in the brain and spinal cord send inhibitory signals to lower motor neurons; their damage causes hyperreflexia, spasticity, and clonus. Neurons exiting the cord to muscles are LMNs, whose damage causes flaccidity and atrophy.'),
  ('clonus', 50, 'A nurse is observing a nursing student prepare to assess a client for ankle clonus. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"I will support the knee in slight flexion.\""}, {"id": "b", "text": "\"I will grasp the foot around the sole.\""}, {"id": "c", "text": "\"I will count and document the beats.\""}, {"id": "d", "text": "\"I will quickly point the foot downward.\""}]'::jsonb, '["d"]', 'Pointing the foot downward is plantar flexion; clonus is elicited by sharply dorsiflexing the foot toward the shin and holding it. The other statements describe correct technique.'),
  ('gcs', 1, 'A client with a head injury opens the eyes when the nurse calls the client''s name, speaks in full sentences but states the wrong year and location, and purposefully moves a hand toward a painful stimulus to push it away. What is the client''s Glasgow Coma Scale (GCS) total?', '[{"id": "a", "text": "11"}, {"id": "b", "text": "13"}, {"id": "c", "text": "12"}, {"id": "d", "text": "10"}]'::jsonb, '["c"]', 'Eyes open to speech = E3, confused but with intact sentences = V4, and localizing pain = M5, so E3V4M5 = 12. A total of 13 would require a higher score in one component.'),
  ('gcs', 2, 'A client opens the eyes only to a sternal rub, makes moaning sounds with no recognizable words, and pulls away from nail bed pressure. Which action should the nurse take first?', '[{"id": "a", "text": "Document the score and reassess in 4 hours"}, {"id": "b", "text": "Ensure suction is at bedside and prepare for intubation"}, {"id": "c", "text": "Lay the client flat with the hips flexed for comfort"}, {"id": "d", "text": "Report only the total score at the next round"}]'::jsonb, '["b"]', 'E2 + V2 + M4 = 8, and a GCS of 8 or below means the client cannot protect the airway, so the nurse prepares intubation equipment and ensures suction is at the bedside. Delaying reassessment ignores an airway emergency.'),
  ('gcs', 3, 'A client opens the eyes spontaneously, correctly states person, place, time, and event, and follows commands. How should the nurse interpret the GCS?', '[{"id": "a", "text": "15; fully conscious"}, {"id": "b", "text": "14; mild impairment"}, {"id": "c", "text": "13; mild impairment"}, {"id": "d", "text": "12; moderate impairment"}]'::jsonb, '["a"]', 'Spontaneous eye opening (E4), oriented speech (V5), and obeying commands (M6) give the maximum score of 15, which means fully conscious. Lower totals would require a reduced component.'),
  ('gcs', 4, 'A client has no eye opening, makes no sounds, and has no movement in response to any stimulus, including painful stimuli. Which GCS total should the nurse document?', '[{"id": "a", "text": "0"}, {"id": "b", "text": "1"}, {"id": "c", "text": "4"}, {"id": "d", "text": "3"}]'::jsonb, '["d"]', 'Each component scores at least 1 (E1 + V1 + M1), so the minimum GCS is 3, indicating deep coma. The GCS cannot be scored as zero.'),
  ('gcs', 5, 'A client''s GCS has been recorded as 14 at 0800, 12 at 0900, and 10 at 1000. What is the nurse''s priority action?', '[{"id": "a", "text": "Continue reassessing the client every hour"}, {"id": "b", "text": "Notify the provider immediately"}, {"id": "c", "text": "Document only the most recent score"}, {"id": "d", "text": "Recheck the GCS at the next shift"}]'::jsonb, '["b"]', 'A GCS trending from 14 to 12 to 10 shows deterioration, and the provider must be notified immediately. Simply continuing hourly checks delays action on a declining trend.'),
  ('gcs', 6, 'In response to a painful stimulus, a client flexes the wrists and elbows and extends the legs. Which GCS motor score should the nurse assign?', '[{"id": "a", "text": "4"}, {"id": "b", "text": "2"}, {"id": "c", "text": "3"}, {"id": "d", "text": "5"}]'::jsonb, '["c"]', 'Wrist/elbow flexion with leg extension in response to pain is abnormal flexion (decorticate), scored M3. Extension of all extremities (decerebrate) is M2.'),
  ('gcs', 7, 'When a painful stimulus is applied, a client''s arms and legs extend and the arms rotate outward. The nurse recognizes that this posture indicates damage at which level?', '[{"id": "a", "text": "The cerebral cortex"}, {"id": "b", "text": "The internal capsule"}, {"id": "c", "text": "The cerebral hemispheres"}, {"id": "d", "text": "The brainstem"}]'::jsonb, '["d"]', 'Arms extending and rotating outward with leg extension is decerebrate posturing, which indicates damage at the brainstem level. Damage to the cortex, internal capsule, or cerebral hemispheres produces decorticate posturing.'),
  ('gcs', 8, 'A client with a head injury who previously showed decorticate posturing now shows decerebrate posturing. What should the nurse do?', '[{"id": "a", "text": "Report the change to the provider immediately"}, {"id": "b", "text": "Document the change as a sign of improvement"}, {"id": "c", "text": "Reassess in one hour before reporting the change"}, {"id": "d", "text": "Record the change in the end-of-shift note"}]'::jsonb, '["a"]', 'Progression from decorticate to decerebrate posturing signals neurological deterioration and is a medical emergency to report immediately. It is not improvement, and reporting should never be delayed.'),
  ('gcs', 9, 'A client is intubated and receiving mechanical ventilation. How should the nurse document the verbal component of the GCS?', '[{"id": "a", "text": "Score the verbal response as 0"}, {"id": "b", "text": "Omit the GCS until the client is extubated"}, {"id": "c", "text": "Record the verbal response as ''1T'' for tube"}, {"id": "d", "text": "Score the verbal response as 5"}]'::jsonb, '["c"]', 'Verbal response is not testable in intubated clients and is documented with ''T'' for tube, or ''1T''. A score of 0 is not possible, and the GCS should still be assessed.'),
  ('gcs', 10, 'A client has severe swelling around both eyes from facial trauma, and the eyes cannot be opened. How should the nurse document the eye-opening component?', '[{"id": "a", "text": "Score it as E1 for no eye opening"}, {"id": "b", "text": "Score it as E2 since pain is present"}, {"id": "c", "text": "Omit it and total only V and M scores"}, {"id": "d", "text": "Document NT and note the swelling as the reason"}]'::jsonb, '["d"]', 'When the eyes cannot be opened because of swelling or trauma, eye opening is documented as NT (not testable) with the reason noted. E1 means no response to any stimulus, which would misrepresent the client.'),
  ('gcs', 11, 'A client opens the eyes only to painful stimuli, uses recognizable but random words, and pulls away from painful stimuli. Which documentation entry is correct?', '[{"id": "a", "text": "GCS 9"}, {"id": "b", "text": "E2V3M4 = 9"}, {"id": "c", "text": "E2V3M4 = 10"}, {"id": "d", "text": "E3V3M4 = 10"}]'::jsonb, '["b"]', 'Eyes to pain = E2, inappropriate words = V3, withdraws = M4, so the total is 9, recorded in E_V_M format. Charting only ''GCS 9'' omits the individual component scores.'),
  ('gcs', 12, 'A nurse orienting to the neuro ICU makes several statements about GCS documentation. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will time-stamp every GCS assessment.\""}, {"id": "b", "text": "\"I will record each component score separately.\""}, {"id": "c", "text": "\"I will note the reason a component is not testable.\""}, {"id": "d", "text": "\"Charting only the total is fine if it is accurate.\""}]'::jsonb, '["d"]', 'Reporting only the total loses information about which component changed, so individual E, V, and M scores must be recorded. Time-stamping assessments and noting NT reasons are correct practices.'),
  ('gcs', 13, 'Which component of the Glasgow Coma Scale is the most prognostically significant?', '[{"id": "a", "text": "Eye opening"}, {"id": "b", "text": "Verbal response"}, {"id": "c", "text": "Motor response"}, {"id": "d", "text": "Pupil reactivity"}]'::jsonb, '["c"]', 'Motor response is the most prognostically significant GCS component. Pupils are checked with every GCS assessment but are not one of the three GCS components.'),
  ('gcs', 14, 'During a painful stimulus, a client''s right arm reaches toward the stimulus and pushes it away, while the left arm only pulls away from the stimulus. Which motor score should the nurse record?', '[{"id": "a", "text": "M5"}, {"id": "b", "text": "M4"}, {"id": "c", "text": "M3"}, {"id": "d", "text": "An average of M4 and M5"}]'::jsonb, '["a"]', 'The best response from any limb is scored, and moving purposefully toward the stimulus to push it away is localizing (M5). Withdrawal (M4) is the weaker limb''s response, and scores are not averaged.'),
  ('gcs', 15, 'A client responds to the nurse''s questions by shouting random, recognizable words and swearing, with no meaningful conversation. Which verbal score should the nurse assign?', '[{"id": "a", "text": "2"}, {"id": "b", "text": "4"}, {"id": "c", "text": "3"}, {"id": "d", "text": "1"}]'::jsonb, '["c"]', 'Recognizable but random words or swearing without meaningful conversation is ''inappropriate words,'' scored V3. A confused client (V4) still converses in intact sentences.'),
  ('gcs', 16, 'A client responds to the nurse only by groaning and moaning, with no recognizable words. Which verbal score is correct?', '[{"id": "a", "text": "1"}, {"id": "b", "text": "2"}, {"id": "c", "text": "3"}, {"id": "d", "text": "4"}]'::jsonb, '["b"]', 'Groaning or moaning without recognizable words is ''incomprehensible sounds,'' scored V2. V1 is reserved for a completely silent client.'),
  ('gcs', 17, 'A client speaks in complete sentences but believes it is a different year and that they are at home rather than in the hospital. Which verbal score should the nurse assign?', '[{"id": "a", "text": "5"}, {"id": "b", "text": "3"}, {"id": "c", "text": "2"}, {"id": "d", "text": "4"}]'::jsonb, '["d"]', 'A client who is conversational but disoriented to time or place with intact sentences is ''confused,'' scored V4. V5 requires orientation to person, place, time, and event.'),
  ('gcs', 18, 'A client is lying with the eyes closed and opens them when the nurse says, ''Good morning, can you hear me?'' Which eye-opening score is correct?', '[{"id": "a", "text": "3"}, {"id": "b", "text": "4"}, {"id": "c", "text": "2"}, {"id": "d", "text": "1"}]'::jsonb, '["a"]', 'Eyes opening in response to voice is scored E3 (to speech). E4 is reserved for eyes that open spontaneously without any stimulation.'),
  ('gcs', 19, 'The nurse needs to determine whether a client opens the eyes to pain. Which stimulus is appropriate?', '[{"id": "a", "text": "Calling the client''s name loudly"}, {"id": "b", "text": "Asking the client to open the eyes"}, {"id": "c", "text": "Applying nail bed pressure"}, {"id": "d", "text": "Observing without any stimulus"}]'::jsonb, '["c"]', 'Eye opening to pain is tested with a painful stimulus such as sternal rub or nail bed pressure. Calling the name or giving a command tests eye opening to speech.'),
  ('gcs', 20, 'A client has a GCS of 10 after a motor vehicle crash. Which plan of care should the nurse anticipate?', '[{"id": "a", "text": "Discharge with home monitoring"}, {"id": "b", "text": "Immediate intubation and neurosurgery consult"}, {"id": "c", "text": "CT scan only if risk factors are present"}, {"id": "d", "text": "Hospital admission, CT, and ICU evaluation"}]'::jsonb, '["d"]', 'A GCS of 9-12 is a moderate TBI, which calls for hospital admission, CT, and ICU evaluation. CT only if risk factors are present is the plan for a mild injury (13-14).'),
  ('gcs', 21, 'After a fall, a client has a GCS of 13. How should the nurse classify this score?', '[{"id": "a", "text": "Mild"}, {"id": "b", "text": "Moderate"}, {"id": "c", "text": "Severe"}, {"id": "d", "text": "Normal"}]'::jsonb, '["a"]', 'A GCS of 13-15 is classified as mild, with near-normal consciousness requiring close monitoring. Moderate is 9-12.'),
  ('gcs', 22, 'A nurse is reviewing GCS thresholds. At which GCS total should the nurse recognize the threshold for considering intubation?', '[{"id": "a", "text": "12 or below"}, {"id": "b", "text": "10 or below"}, {"id": "c", "text": "8 or below"}, {"id": "d", "text": "3 only"}]'::jsonb, '["c"]', 'A GCS of 8 or below means the client cannot protect the airway and is the threshold for considering intubation. Scores of 9-12 are moderate impairment.'),
  ('gcs', 23, 'A nurse is scoring a client''s motor response. What is the highest score possible for this component?', '[{"id": "a", "text": "5"}, {"id": "b", "text": "6"}, {"id": "c", "text": "4"}, {"id": "d", "text": "3"}]'::jsonb, '["b"]', 'The motor response has a maximum score of 6 (obeys commands). The verbal response maximum is 5 and eye opening is 4.'),
  ('gcs', 24, 'A client opens the eyes only when spoken to, is fully oriented to person, place, time, and event, and obeys commands. Which documentation is correct?', '[{"id": "a", "text": "E3V5M6 = 15"}, {"id": "b", "text": "E4V5M5 = 14"}, {"id": "c", "text": "E3V4M6 = 13"}, {"id": "d", "text": "E3V5M6 = 14"}]'::jsonb, '["d"]', 'Eyes to speech = E3, oriented = V5, obeys commands = M6, and 3 + 5 + 6 = 14. E3V5M6 = 15 has the wrong arithmetic.'),
  ('gcs', 25, 'Which action reflects correct technique when the nurse performs neuro checks that include the GCS?', '[{"id": "a", "text": "Omit pupil checks when the GCS is 15"}, {"id": "b", "text": "Assess pupil size, equality, and reactivity each time"}, {"id": "c", "text": "Time-stamp only assessments in which the score changes"}, {"id": "d", "text": "Record only the total score at each check"}]'::jsonb, '["b"]', 'Pupils (size, equality, reactivity) are included with every GCS assessment. Every assessment is time-stamped, and individual component scores are recorded rather than just the total.'),
  ('gcs', 26, 'A nurse is supervising care for a client with a head injury who is on ICP precautions. Which action by assistive personnel requires the nurse to intervene?', '[{"id": "a", "text": "Keeping the head of the bed at 30 degrees"}, {"id": "b", "text": "Keeping the head midline without neck rotation"}, {"id": "c", "text": "Positioning the client with the hips flexed"}, {"id": "d", "text": "Helping the client avoid straining"}]'::jsonb, '["c"]', 'ICP precautions include HOB 30 degrees, no hip flexion, no neck rotation, and avoiding Valsalva. Positioning the client with the hips flexed violates these precautions.'),
  ('gcs', 27, 'Which intervention should the nurse include in seizure precautions for a client with a decreased level of consciousness?', '[{"id": "a", "text": "Pad the side rails"}, {"id": "b", "text": "Place an object in the mouth during a seizure"}, {"id": "c", "text": "Store suction equipment outside the room"}, {"id": "d", "text": "Rub the gums to stop a seizure"}]'::jsonb, '["a"]', 'Seizure precautions include padded rails, suction at the bedside, and no oral stimulation during a seizure. Placing an object in the mouth or rubbing the gums is oral stimulation.'),
  ('gcs', 28, 'A client''s GCS is 9. Which statement by the nurse requires correction?', '[{"id": "a", "text": "\"This score falls in the moderate range.\""}, {"id": "b", "text": "\"This score confirms the client has a brain bleed.\""}, {"id": "c", "text": "\"I need to compare this with previous scores.\""}, {"id": "d", "text": "\"I should document each component separately.\""}]'::jsonb, '["b"]', 'The GCS is a measurement tool, not a diagnosis; the underlying cause (trauma, bleed, metabolic, toxin) must still be identified. A score of 9 is correctly classified as moderate.'),
  ('gcs', 29, 'The nurse is caring for two clients with head injuries: one shows decorticate posturing and the other shows decerebrate posturing. Which statement about prognosis is accurate?', '[{"id": "a", "text": "Decorticate posturing carries the worse prognosis."}, {"id": "b", "text": "Both postures carry the same prognosis."}, {"id": "c", "text": "Decerebrate posturing carries the worse prognosis."}, {"id": "d", "text": "Posturing is unrelated to prognosis."}]'::jsonb, '["c"]', 'Decerebrate posturing indicates deeper, brainstem-level injury and has a worse prognosis. Decorticate posturing has a better prognosis than decerebrate.'),
  ('gcs', 30, 'A client with a head injury shows decorticate posturing. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "It indicates damage at the brainstem level."}, {"id": "b", "text": "It indicates damage above the brainstem."}, {"id": "c", "text": "It is a normal withdrawal from pain."}, {"id": "d", "text": "It is scored as a motor response of 2."}]'::jsonb, '["b"]', 'Decorticate posturing indicates damage above the brainstem (cortex, internal capsule, or cerebral hemispheres) and is scored M3. Brainstem-level damage and a motor score of 2 describe decerebrate posturing.'),
  ('gcs', 31, 'During nail bed pressure on the client''s left hand, the client reaches across with the right hand and tries to push the nurse''s hand away. Which motor score is correct?', '[{"id": "a", "text": "6"}, {"id": "b", "text": "4"}, {"id": "c", "text": "5"}, {"id": "d", "text": "3"}]'::jsonb, '["c"]', 'Purposefully moving a hand toward the painful stimulus to push it away is localizing pain, scored M5. Simply pulling away from the stimulus would be withdrawal (M4).'),
  ('gcs', 32, 'When the nurse applies a painful stimulus, the client pulls the arm away from it but does not reach toward the stimulus. Which motor score should the nurse assign?', '[{"id": "a", "text": "4"}, {"id": "b", "text": "5"}, {"id": "c", "text": "3"}, {"id": "d", "text": "2"}]'::jsonb, '["a"]', 'Pulling away from a painful stimulus is withdrawal, scored M4. Reaching toward the stimulus to push it away would be localizing (M5).'),
  ('gcs', 33, 'A client opens the eyes spontaneously, speaks in complete sentences but is disoriented to time and place, and obeys commands. Which interpretation of the GCS is correct?', '[{"id": "a", "text": "13; mild"}, {"id": "b", "text": "14; moderate"}, {"id": "c", "text": "15; normal"}, {"id": "d", "text": "14; mild"}]'::jsonb, '["d"]', 'E4 + V4 (confused) + M6 = 14, which falls in the 13-15 mild range. A total of 14 is not moderate, which is 9-12.'),
  ('gcs', 34, 'A client opens the eyes when spoken to, makes only moaning sounds, and pulls away from painful stimuli. How should the nurse classify this client''s GCS?', '[{"id": "a", "text": "Mild"}, {"id": "b", "text": "Moderate"}, {"id": "c", "text": "Severe"}, {"id": "d", "text": "Normal"}]'::jsonb, '["b"]', 'E3 + V2 + M4 = 9, which falls in the 9-12 moderate range indicating significant impairment. A score of 8 or below would be severe.'),
  ('gcs', 35, 'A client opens the eyes only to painful stimuli, makes incomprehensible sounds, and shows decorticate posturing. How should the nurse classify this client''s GCS?', '[{"id": "a", "text": "Moderate"}, {"id": "b", "text": "Mild"}, {"id": "c", "text": "Severe"}, {"id": "d", "text": "Normal"}]'::jsonb, '["c"]', 'E2 + V2 + M3 = 7, which falls in the 3-8 severe/coma range where the airway is at risk. Moderate impairment is 9-12.'),
  ('gcs', 36, 'Which statement by a nurse reflects correct use of the Glasgow Coma Scale?', '[{"id": "a", "text": "\"The trend over time matters more than a single score.\""}, {"id": "b", "text": "\"A single low score tells me more than the trend.\""}, {"id": "c", "text": "\"I do not need prior scores to interpret today''s score.\""}, {"id": "d", "text": "\"The GCS identifies the cause of a decreased LOC.\""}]'::jsonb, '["a"]', 'A single GCS score is less meaningful than a trend, and GCS should never be documented without the context of previous scores. The GCS measures LOC but does not identify its cause.'),
  ('gcs', 37, 'A client with a head injury has a GCS of 6. Which interventions should the nurse anticipate?', '[{"id": "a", "text": "Discharge with written head-injury instructions"}, {"id": "b", "text": "Intubation, ICP monitoring, and neurosurgery consult"}, {"id": "c", "text": "A CT scan only if risk factors are present"}, {"id": "d", "text": "Admission to a general unit with routine checks"}]'::jsonb, '["b"]', 'A GCS of 3-8 is severe, with airway protection lost, requiring intubation, ICP monitoring, and a neurosurgery consult. CT only if risk factors are present applies to a mild injury.'),
  ('gcs', 38, 'A client fell at home and has a GCS of 14. Which plan of care should the nurse anticipate?', '[{"id": "a", "text": "Immediate intubation and mechanical ventilation"}, {"id": "b", "text": "ICP monitoring and a neurosurgery consult"}, {"id": "c", "text": "Admission to the ICU for evaluation"}, {"id": "d", "text": "Monitoring for deterioration; CT if risk factors"}]'::jsonb, '["d"]', 'A GCS of 13-14 is a minor TBI, managed with monitoring for deterioration and a CT if any risk factors are present. ICU evaluation is the plan for moderate injury (9-12).'),
  ('gcs', 39, 'A client''s GCS has decreased to 8. The family asks why the nurse is so concerned. The nurse explains that this score is concerning mainly because the client:', '[{"id": "a", "text": "may no longer be able to protect the airway."}, {"id": "b", "text": "has reached the lowest possible GCS score."}, {"id": "c", "text": "is now in the mild range of impairment."}, {"id": "d", "text": "has a confirmed bleed inside the brain."}]'::jsonb, '["a"]', 'A GCS of 8 or below indicates the client cannot protect their own airway. The lowest possible score is 3, not 8.'),
  ('gcs', 40, 'Which client response should the nurse score as a verbal response of 5?', '[{"id": "a", "text": "Correctly states name, location, date, and reason for admission"}, {"id": "b", "text": "Speaks in full sentences but gives the wrong date and location"}, {"id": "c", "text": "Says random words and swears without meaningful conversation"}, {"id": "d", "text": "Groans and moans without any recognizable words"}]'::jsonb, '["a"]', 'V5 (oriented) requires knowing person, place, time, and event (A&O x4). Full sentences with the wrong date and place are scored V4 (confused).'),
  ('gcs', 41, 'A client does not open the eyes or make any sound in response to a sternal rub, and the arms and legs extend and rotate. What is the client''s GCS total?', '[{"id": "a", "text": "3"}, {"id": "b", "text": "4"}, {"id": "c", "text": "5"}, {"id": "d", "text": "6"}]'::jsonb, '["b"]', 'No eye opening = E1, no verbal response = V1, and extension of arms and legs (decerebrate) = M2, so 1 + 1 + 2 = 4. A total of 3 would require no motor response at all.'),
  ('gcs', 42, 'A client opens the eyes when spoken to, shouts random words and swears without meaningful conversation, and pulls away from nail bed pressure. Which interpretation of the GCS is correct?', '[{"id": "a", "text": "9; moderate"}, {"id": "b", "text": "10; moderate"}, {"id": "c", "text": "10; mild"}, {"id": "d", "text": "11; moderate"}]'::jsonb, '["b"]', 'E3 + V3 (inappropriate words) + M4 (withdraws) = 10, which is in the 9-12 moderate range. A score of 10 is not mild, which is 13-15.'),
  ('gcs', 43, 'At 0800 a client''s GCS is documented as E3V4M5 = 12. At 0900 it is documented as E3V4M3 = 10. Which interpretation and action are correct?', '[{"id": "a", "text": "Verbal score declined; continue hourly checks"}, {"id": "b", "text": "Eye score declined; reassess in 4 hours"}, {"id": "c", "text": "Motor score declined; notify the provider urgently"}, {"id": "d", "text": "No significant change; document and continue"}]'::jsonb, '["c"]', 'The motor score fell from 5 to 3, a 2-point decrease in the total, and any decrease of 2 or more points is reported to the provider urgently. The eye and verbal scores are unchanged.'),
  ('gcs', 44, 'The nurse receives reports on four clients with head injuries. Which client should the nurse assess first?', '[{"id": "a", "text": "GCS increased from 9 to 12"}, {"id": "b", "text": "GCS stable at 15"}, {"id": "c", "text": "GCS stable at 14"}, {"id": "d", "text": "GCS decreased from 13 to 11"}]'::jsonb, '["d"]', 'A GCS trending down by 2 or more points requires immediate provider notification, so the client whose score fell from 13 to 11 is the priority. An increase from 9 to 12 reflects improvement.'),
  ('gcs', 45, 'The nurse observes that, in response to pain, a client''s arms flex toward the body''s core with the wrists curled inward while the legs extend. How should the nurse document this posture?', '[{"id": "a", "text": "Decorticate posturing"}, {"id": "b", "text": "Decerebrate posturing"}, {"id": "c", "text": "Localizing to pain"}, {"id": "d", "text": "Obeying commands"}]'::jsonb, '["a"]', 'Arms flexed toward the core with wrists curled inward and legs extended is decorticate posturing (''arms toward the CORe''). In decerebrate posturing, all extremities extend outward.'),
  ('gcs', 46, 'A nurse enters a client''s room and finds the client''s eyes already open before any stimulation is given. Which eye-opening score is appropriate?', '[{"id": "a", "text": "1"}, {"id": "b", "text": "2"}, {"id": "c", "text": "3"}, {"id": "d", "text": "4"}]'::jsonb, '["d"]', 'Eyes open without any stimulation is spontaneous eye opening, scored E4. E3 requires a voice or verbal command to open the eyes.'),
  ('gcs', 47, 'A client who speaks only a language the nurse does not speak is awake and talking, but an interpreter is not yet available. How should the nurse handle the verbal component of the GCS?', '[{"id": "a", "text": "Score it as V1 for no verbal response"}, {"id": "b", "text": "Score it as V4 because the client seems confused"}, {"id": "c", "text": "Score it as V3 for inappropriate words"}, {"id": "d", "text": "Document it as NT and note the reason"}]'::jsonb, '["d"]', 'A language barrier makes the verbal response not testable (NT), and the reason must be documented. Scoring V1 or V3 would misrepresent a client who is actually speaking.'),
  ('gcs', 48, 'Which statement best describes the primary purpose of the Glasgow Coma Scale?', '[{"id": "a", "text": "To assess and quantify level of consciousness"}, {"id": "b", "text": "To diagnose the cause of altered mental status"}, {"id": "c", "text": "To directly measure intracranial pressure"}, {"id": "d", "text": "To identify the location of a brain bleed"}]'::jsonb, '["a"]', 'The GCS is a standardized tool to assess and quantify level of consciousness. It is a measurement tool, not a diagnosis, so it does not identify the cause of altered mental status.'),
  ('gcs', 49, 'A family member asks why the nurse checks the client''s GCS every hour. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A single score shows exactly what caused the injury.\""}, {"id": "b", "text": "\"Changes in the score help guide imaging or surgery.\""}, {"id": "c", "text": "\"The score directly measures pressure inside the skull.\""}, {"id": "d", "text": "\"Hourly checks are needed only once the score is 15.\""}]'::jsonb, '["b"]', 'The GCS is trended over time and guides treatment decisions such as imaging, surgery, and intubation. It does not identify the cause of the injury.'),
  ('gcs', 50, 'A client with a head injury and a declining GCS requires ICP precautions. Which position should the nurse maintain?', '[{"id": "a", "text": "Head of bed flat with the head turned to one side"}, {"id": "b", "text": "Head of bed flat with the knees drawn to the chest"}, {"id": "c", "text": "Head of bed at 30 degrees with the head midline"}, {"id": "d", "text": "Head of bed at 30 degrees with the hips flexed"}]'::jsonb, '["c"]', 'ICP precautions call for HOB 30 degrees with no hip flexion and no neck rotation, so the head stays midline. Flexing the hips or turning the head violates these precautions.'),
  ('icp', 1, 'A client admitted after a fall has been alert and oriented. Which new finding should the nurse recognize as the earliest indicator of increased intracranial pressure (ICP)?', '[{"id": "a", "text": "A fixed, dilated right pupil"}, {"id": "b", "text": "Restlessness and new confusion"}, {"id": "c", "text": "Decerebrate posturing to pain"}, {"id": "d", "text": "Bradycardia with irregular breathing"}]'::jsonb, '["b"]', 'A change in level of consciousness, such as restlessness or confusion, is the earliest and most sensitive indicator of increased ICP. A fixed pupil, posturing, and bradycardia with irregular respirations are late signs of imminent herniation.'),
  ('icp', 2, 'A client with an ICP monitor after a craniotomy has an intracranial pressure (ICP) reading of 12 mmHg. How should the nurse interpret this value?', '[{"id": "a", "text": "It is within the normal range"}, {"id": "b", "text": "It is elevated and needs mannitol"}, {"id": "c", "text": "It is critically high and signals herniation"}, {"id": "d", "text": "It is sustained elevation needing a CT"}]'::jsonb, '["a"]', 'Normal ICP is 5–15 mmHg, so 12 mmHg is normal. Elevated ICP is defined as a sustained value greater than 20 mmHg.'),
  ('icp', 3, 'A client with a traumatic brain injury has an intracranial pressure (ICP) that has remained at 24 mmHg for the past hour. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "The ICP is within normal limits"}, {"id": "b", "text": "The ICP is elevated"}, {"id": "c", "text": "The ICP is lower than expected"}, {"id": "d", "text": "The ICP is at the treatment goal"}]'::jsonb, '["b"]', 'A sustained ICP greater than 20 mmHg is elevated; normal ICP is 5–15 mmHg. A value of 24 mmHg sustained over an hour therefore is not normal or at goal.'),
  ('icp', 4, 'A client with a head injury has a mean arterial pressure (MAP) of 80 mmHg and an intracranial pressure (ICP) of 25 mmHg. Which conclusion by the nurse is correct?', '[{"id": "a", "text": "The CPP is 105 mmHg, which is above goal"}, {"id": "b", "text": "The CPP is 55 mmHg, which is below goal"}, {"id": "c", "text": "The CPP is 55 mmHg, which meets the goal"}, {"id": "d", "text": "The CPP is 105 mmHg, which is below goal"}]'::jsonb, '["b"]', 'Cerebral perfusion pressure equals MAP minus ICP, so 80 − 25 = 55 mmHg. The goal is a CPP of 60 mmHg or higher, so 55 mmHg is below goal; adding the values (105) is the wrong formula.'),
  ('icp', 5, 'The nurse is reviewing hourly data for four clients with brain injuries. Which client''s values indicate that the cerebral perfusion pressure (CPP) goal is being met?', '[{"id": "a", "text": "MAP 70 mmHg and ICP 22 mmHg"}, {"id": "b", "text": "MAP 75 mmHg and ICP 20 mmHg"}, {"id": "c", "text": "MAP 65 mmHg and ICP 10 mmHg"}, {"id": "d", "text": "MAP 85 mmHg and ICP 15 mmHg"}]'::jsonb, '["d"]', 'CPP = MAP − ICP, with a goal of 60 mmHg or more; 85 − 15 = 70 mmHg meets the goal. The other clients have CPPs of 48, 55, and 55 mmHg, all below goal.'),
  ('icp', 6, 'The spouse of a client with a brain tumor asks why rising intracranial pressure is so dangerous. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It raises perfusion pressure, so too much blood floods the brain.\""}, {"id": "b", "text": "\"It speeds blood flow, so the brain receives extra oxygen.\""}, {"id": "c", "text": "\"It lowers perfusion pressure, so less blood reaches the brain.\""}, {"id": "d", "text": "\"It drains fluid from the brain, so the tissue shrinks.\""}]'::jsonb, '["c"]', 'Rising ICP decreases CPP, which decreases blood flow and leads to brain ischemia. It does not increase perfusion pressure or blood flow.'),
  ('icp', 7, 'Over 2 hours, a client''s vital signs change from BP 128/78, HR 84, and regular respirations of 16 to BP 172/64, HR 50, and an irregular breathing pattern. How should the nurse interpret these changes?', '[{"id": "a", "text": "An early sign of rising intracranial pressure"}, {"id": "b", "text": "An expected response to acute pain"}, {"id": "c", "text": "A stable pattern needing routine monitoring"}, {"id": "d", "text": "Cushing''s triad signaling impending herniation"}]'::jsonb, '["d"]', 'Rising systolic BP, bradycardia, and irregular respirations make up Cushing''s triad, a late sign of impending herniation. It is not an early sign; change in LOC is the earliest sign.'),
  ('icp', 8, 'A client with increased intracranial pressure develops a widening pulse pressure, a heart rate of 48, and Cheyne-Stokes respirations. What is the nurse''s priority action?', '[{"id": "a", "text": "Notify the provider immediately"}, {"id": "b", "text": "Recheck vital signs in 1 hour"}, {"id": "c", "text": "Lower the head of the bed flat"}, {"id": "d", "text": "Document the findings as expected"}]'::jsonb, '["a"]', 'These findings are Cushing''s triad, a pre-terminal sign of impending herniation, and the provider must be notified immediately. Lowering the bed flat increases ICP, and delaying reassessment wastes critical time.'),
  ('icp', 9, 'The nurse is performing hourly neurological checks on a client with a subdural bleed. Which finding indicates a late sign of increased intracranial pressure?', '[{"id": "a", "text": "A fixed, dilated pupil"}, {"id": "b", "text": "A headache that worsens with coughing"}, {"id": "c", "text": "Blurred vision when reading"}, {"id": "d", "text": "Restlessness and mild confusion"}]'::jsonb, '["a"]', 'A fixed, dilated ("blown") pupil is a late sign of imminent herniation. Headache worse with coughing, blurred vision, and restlessness are early signs.'),
  ('icp', 10, 'A client with a brain tumor suddenly vomits forcefully and states, "I did not even feel sick to my stomach." How should the nurse interpret this finding?', '[{"id": "a", "text": "An early sign of increased ICP"}, {"id": "b", "text": "A late sign of brain herniation"}, {"id": "c", "text": "A component of Cushing''s triad"}, {"id": "d", "text": "An unrelated finding needing no follow-up"}]'::jsonb, '["a"]', 'Vomiting that is often projectile and occurs without nausea is listed as an early sign of increased ICP. It is not one of the late signs, and it is not part of Cushing''s triad (↑ SBP, bradycardia, irregular respirations).'),
  ('icp', 11, 'A client with hydrocephalus reports a headache. Which description of the headache is most consistent with increased intracranial pressure?', '[{"id": "a", "text": "It eases when the client bends over"}, {"id": "b", "text": "It improves with straining at stool"}, {"id": "c", "text": "It worsens with coughing and straining"}, {"id": "d", "text": "It is relieved by a forceful cough"}]'::jsonb, '["c"]', 'Headache from increased ICP is worse with coughing, straining, and bending over. Each distractor describes relief from activities that actually worsen the headache.'),
  ('icp', 12, 'The nurse is positioning a client who has increased intracranial pressure after a head injury. Which position is most appropriate?', '[{"id": "a", "text": "Flat supine with a pillow under the knees"}, {"id": "b", "text": "Head of bed at 30° with the head midline"}, {"id": "c", "text": "Trendelenburg with the head midline"}, {"id": "d", "text": "Head of bed at 30° with the head rotated"}]'::jsonb, '["b"]', 'The head of the bed should be at 30° with the head kept midline and neutral. Flat and Trendelenburg positions both increase ICP, and rotating the head is to be avoided.'),
  ('icp', 13, 'A nursing student asks why the head of the bed is kept at 30° for a client with increased intracranial pressure. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It increases arterial blood flow into the brain.\""}, {"id": "b", "text": "\"It promotes venous drainage from the brain.\""}, {"id": "c", "text": "\"It raises carbon dioxide to dilate brain vessels.\""}, {"id": "d", "text": "\"It slows the heart rate to lower blood pressure.\""}]'::jsonb, '["b"]', 'Elevating the head of the bed to 30° promotes venous drainage from the brain. Raising CO₂ is harmful because it causes cerebral vasodilation and increases ICP.'),
  ('icp', 14, 'The nurse observes an assistive staff member caring for a client with increased intracranial pressure. Which action requires the nurse to intervene?', '[{"id": "a", "text": "Dimming the lights in the client''s room"}, {"id": "b", "text": "Lowering the bed flat to change the linens"}, {"id": "c", "text": "Keeping the client''s head in midline"}, {"id": "d", "text": "Speaking softly while providing care"}]'::jsonb, '["b"]', 'The bed must never be flat or in Trendelenburg because both increase ICP. Dim lights, a midline head, and a quiet environment are appropriate care.'),
  ('icp', 15, 'The nurse enters the room of a client with increased intracranial pressure. Which finding requires immediate correction?', '[{"id": "a", "text": "The head aligned midline on the pillow"}, {"id": "b", "text": "The head of the bed elevated to 30°"}, {"id": "c", "text": "The lights dimmed and the door closed"}, {"id": "d", "text": "A tight cervical collar compressing the neck"}]'::jsonb, '["d"]', 'Tight cervical collars and neck compression must be avoided in a client with increased ICP. The other findings reflect correct positioning and a low-stimulation environment.'),
  ('icp', 16, 'The nurse is supervising a student repositioning a client with increased intracranial pressure. Which action by the student requires correction?', '[{"id": "a", "text": "Keeping the client''s head neutral and midline"}, {"id": "b", "text": "Flexing the client''s neck forward on pillows"}, {"id": "c", "text": "Raising the head of the bed to 30 degrees"}, {"id": "d", "text": "Loosening a snug collar around the neck"}]'::jsonb, '["b"]', 'The head must stay midline and neutral with no flexion, rotation, or hyperextension. Elevating the head of the bed to 30° and avoiding neck compression are correct.'),
  ('icp', 17, 'A client with increased intracranial pressure has an arterial blood gas showing a PaCO₂ of 48 mmHg. How should the nurse interpret this result?', '[{"id": "a", "text": "The high CO₂ will dilate cerebral vessels and raise ICP"}, {"id": "b", "text": "The high CO₂ will constrict cerebral vessels and lower ICP"}, {"id": "c", "text": "The CO₂ is within the target range for this client"}, {"id": "d", "text": "The CO₂ level has no effect on intracranial pressure"}]'::jsonb, '["a"]', 'The PaCO₂ target is 35–38 mmHg, and elevated CO₂ causes cerebral vasodilation that increases ICP. It does not constrict vessels or lower ICP.'),
  ('icp', 18, 'The nurse is managing ventilation for an intubated client with increased intracranial pressure. Which PaCO₂ value indicates the respiratory target is being met?', '[{"id": "a", "text": "30 mmHg"}, {"id": "b", "text": "44 mmHg"}, {"id": "c", "text": "50 mmHg"}, {"id": "d", "text": "36 mmHg"}]'::jsonb, '["d"]', 'PaCO₂ should be maintained at 35–38 mmHg, so 36 mmHg is on target. Values of 44 and 50 mmHg are high and raise ICP through cerebral vasodilation, and 30 mmHg is below the target range.'),
  ('icp', 19, 'A client with increased intracranial pressure has an oxygen saturation of 90%. Why is the nurse concerned about this finding?', '[{"id": "a", "text": "Hypoxia causes cerebral vasoconstriction, lowering ICP"}, {"id": "b", "text": "The saturation is within the goal for this client"}, {"id": "c", "text": "Hypoxia causes cerebral vasodilation, raising ICP"}, {"id": "d", "text": "Hypoxia slows cerebral metabolism, lowering ICP"}]'::jsonb, '["c"]', 'Low oxygen causes cerebral vasodilation, which raises ICP, and oxygen saturation should be kept above 94%. A saturation of 90% is therefore below goal.'),
  ('icp', 20, 'An intubated client with increased intracranial pressure needs endotracheal suctioning. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Suction cautiously and keep each pass brief"}, {"id": "b", "text": "Suction for an extended time to clear secretions"}, {"id": "c", "text": "Suction routinely every 15 minutes"}, {"id": "d", "text": "Lower the bed flat before suctioning"}]'::jsonb, '["a"]', 'Suctioning spikes ICP, so it must be done cautiously and briefly. Prolonged or frequent suctioning raises ICP, and lying flat also increases ICP.'),
  ('icp', 21, 'The nurse is planning care for a client with increased intracranial pressure. Which approach to the environment is most appropriate?', '[{"id": "a", "text": "Space care hourly with lights kept bright"}, {"id": "b", "text": "Encourage frequent visitors for stimulation"}, {"id": "c", "text": "Keep the television on for orientation"}, {"id": "d", "text": "Cluster care and keep the lights dim"}]'::jsonb, '["d"]', 'A quiet, low-stimulation environment with clustered care and dim lights helps prevent rises in ICP. Bright lights, frequent visitors, and television add stimulation.'),
  ('icp', 22, 'A client with increased intracranial pressure has a temperature of 39.2°C (102.6°F). The family asks why the fever matters. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Fever lowers the brain''s metabolic demand and protects it.\""}, {"id": "b", "text": "\"Fever raises the brain''s metabolic demand and worsens pressure.\""}, {"id": "c", "text": "\"Fever is expected and should be allowed to run its course.\""}, {"id": "d", "text": "\"Fever reduces swelling by pulling fluid out of the brain.\""}]'::jsonb, '["b"]', 'Fever increases metabolic demand, which increases ICP, so it should be prevented and treated with antipyretics. Fever does not lower demand or reduce swelling.'),
  ('icp', 23, 'A client with increased intracranial pressure after a head injury has a fever. Which prescription should the nurse question?', '[{"id": "a", "text": "Aspirin for a temperature above 38°C"}, {"id": "b", "text": "Acetaminophen for a temperature above 38°C"}, {"id": "c", "text": "Cooling blanket for persistent fever"}, {"id": "d", "text": "Phenytoin for seizure prevention"}]'::jsonb, '["a"]', 'Acetaminophen and cooling blankets are used to control fever, and phenytoin prevents seizures after neuro injury. Aspirin should be avoided because of bleeding risk.'),
  ('icp', 24, 'The nurse is caring for a client with increased intracranial pressure after a brain injury. What is the main reason for strict intake and output monitoring?', '[{"id": "a", "text": "To calculate cerebral perfusion pressure"}, {"id": "b", "text": "To detect early meningitis"}, {"id": "c", "text": "To detect SIADH or diabetes insipidus"}, {"id": "d", "text": "To detect a CSF leak from the brain"}]'::jsonb, '["c"]', 'Strict I&O is used to monitor for SIADH or diabetes insipidus, both of which occur after neuro injury. CPP is calculated from MAP and ICP, not from intake and output.'),
  ('icp', 25, 'A client with increased intracranial pressure has not had a bowel movement in 3 days and is straining to defecate. Which action should the nurse take?', '[{"id": "a", "text": "Encourage the client to bear down"}, {"id": "b", "text": "Teach vigorous coughing exercises"}, {"id": "c", "text": "Give the prescribed stool softener"}, {"id": "d", "text": "Place the client flat on a bedpan"}]'::jsonb, '["c"]', 'The Valsalva maneuver, including straining, coughing, and bearing down, must be avoided, and stool softeners are used to prevent it. Lying flat also increases ICP.'),
  ('icp', 26, 'The nurse teaches the family of a client with increased intracranial pressure how to help at the bedside. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"We''ll keep the room quiet and the lights low.\""}, {"id": "b", "text": "\"We''ll keep his head straight on the pillow.\""}, {"id": "c", "text": "\"We''ll encourage him to cough hard and often.\""}, {"id": "d", "text": "\"We''ll keep our visits short and calm.\""}]'::jsonb, '["c"]', 'Coughing is part of the Valsalva maneuver, which raises ICP and should be avoided. A quiet, dim room, a midline head, and low stimulation are correct.'),
  ('icp', 27, 'The nurse is developing a care plan for a client with increased intracranial pressure. How often should the nurse plan neurological checks unless the protocol states otherwise?', '[{"id": "a", "text": "Every 4 to 6 hours"}, {"id": "b", "text": "Every 8 to 12 hours"}, {"id": "c", "text": "Once each shift"}, {"id": "d", "text": "Every 1 to 2 hours"}]'::jsonb, '["d"]', 'Neuro checks are performed every 1–2 hours or per protocol. Longer intervals could miss an early change in LOC.'),
  ('icp', 28, 'A client with increased intracranial pressure is at risk for seizures. Which intervention should the nurse include in the plan of care?', '[{"id": "a", "text": "Remove the suction setup from the room"}, {"id": "b", "text": "Pad the side rails and keep suction ready"}, {"id": "c", "text": "Keep the bed flat to prevent falls"}, {"id": "d", "text": "Lower all the side rails at night"}]'::jsonb, '["b"]', 'Seizure precautions include padded rails, suction, and anticonvulsants. A flat bed raises ICP, and removing suction or rails removes safety measures.'),
  ('icp', 29, 'A client with cerebral edema is prescribed mannitol. The client''s daughter asks how the drug works. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"It lowers the fever that is worsening the swelling.\""}, {"id": "b", "text": "\"It pulls fluid out of the brain into the bloodstream.\""}, {"id": "c", "text": "\"It prevents seizures caused by the brain injury.\""}, {"id": "d", "text": "\"It treats swelling caused only by brain tumors.\""}]'::jsonb, '["b"]', 'Mannitol is an osmotic diuretic that pulls fluid out of the brain into the bloodstream to reduce edema. Fever control is the role of acetaminophen, and tumor-only edema is treated with dexamethasone.'),
  ('icp', 30, 'A client with increased intracranial pressure is receiving IV mannitol. Which laboratory value is most important for the nurse to monitor?', '[{"id": "a", "text": "Serum drug level"}, {"id": "b", "text": "Serum osmolality"}, {"id": "c", "text": "Platelet count"}, {"id": "d", "text": "Liver enzymes"}]'::jsonb, '["b"]', 'Mannitol therapy requires monitoring of serum osmolality, kidney function, and urine output. Drug levels are monitored for phenytoin, not mannitol.'),
  ('icp', 31, 'The nurse is creating a monitoring plan for a client receiving mannitol for cerebral edema. Which assessments should be included?', '[{"id": "a", "text": "Phenytoin levels and seizure activity"}, {"id": "b", "text": "Bleeding time and stool for blood"}, {"id": "c", "text": "Electrocardiogram and liver enzymes"}, {"id": "d", "text": "Kidney function and urine output"}]'::jsonb, '["d"]', 'Mannitol is an osmotic diuretic, so kidney function and osmolality must be monitored. Phenytoin levels relate to anticonvulsant therapy, and bleeding risk relates to aspirin.'),
  ('icp', 32, 'A client with a traumatic brain injury is receiving 3% hypertonic saline. Which laboratory results should the nurse monitor most closely?', '[{"id": "a", "text": "Serum phenytoin levels"}, {"id": "b", "text": "Serum electrolytes"}, {"id": "c", "text": "Bleeding time"}, {"id": "d", "text": "Blood cultures"}]'::jsonb, '["b"]', 'Hypertonic saline 3% reduces brain swelling, and electrolytes must be monitored. Drug levels are monitored for phenytoin.'),
  ('icp', 33, 'A client with cerebral edema from a traumatic brain injury has a new prescription for dexamethasone to reduce swelling. What is the nurse''s best action?', '[{"id": "a", "text": "Clarify the order, because it is not used for head trauma"}, {"id": "b", "text": "Give it, because it is first-line for traumatic edema"}, {"id": "c", "text": "Give it with mannitol to increase fluid removal"}, {"id": "d", "text": "Hold the mannitol until the steroid takes effect"}]'::jsonb, '["a"]', 'Dexamethasone is used only for tumor-related edema and is not indicated for traumatic brain injury, so the order should be clarified. It is not first-line therapy for traumatic edema.'),
  ('icp', 34, 'The nurse is caring for four clients with cerebral edema. For which client is dexamethasone an appropriate therapy?', '[{"id": "a", "text": "A client with edema around a brain tumor"}, {"id": "b", "text": "A client with edema after a car crash"}, {"id": "c", "text": "A client with edema after a fall from a ladder"}, {"id": "d", "text": "A client with edema after an assault"}]'::jsonb, '["a"]', 'Dexamethasone is used for tumor-related edema only. The other clients have traumatic brain injuries, for which dexamethasone is not indicated.'),
  ('icp', 35, 'A client receives phenytoin after a severe head injury. Which assessment is most specific to this medication?', '[{"id": "a", "text": "Serum drug levels"}, {"id": "b", "text": "Serum osmolality"}, {"id": "c", "text": "Bleeding precautions"}, {"id": "d", "text": "Serum electrolytes"}]'::jsonb, '["a"]', 'Phenytoin prevents and treats seizures after neuro injury, and its drug levels must be monitored. Serum osmolality is monitored with mannitol, and electrolytes with hypertonic saline.'),
  ('icp', 36, 'An intubated client with increased intracranial pressure is agitated, and propofol is prescribed. The nurse understands the purpose of this medication is to:', '[{"id": "a", "text": "Lower body temperature during fever"}, {"id": "b", "text": "Reduce agitation and metabolic demand"}, {"id": "c", "text": "Pull fluid out of the brain tissue"}, {"id": "d", "text": "Reduce swelling around a brain tumor"}]'::jsonb, '["b"]', 'Sedatives such as propofol and midazolam are CNS depressants used to reduce agitation and metabolic demand. Fluid removal is the role of mannitol, and tumor edema is treated with dexamethasone.'),
  ('icp', 37, 'A client with increased intracranial pressure has a Glasgow Coma Scale score that has dropped to 7. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "A lumbar puncture to relieve pressure"}, {"id": "b", "text": "Lowering the bed flat to improve flow"}, {"id": "c", "text": "Dexamethasone for the head trauma"}, {"id": "d", "text": "Intubation to protect the airway"}]'::jsonb, '["d"]', 'For the unconscious client, airway protection includes intubation if the GCS is 8 or less. Lumbar puncture is contraindicated with increased ICP, and the bed should never be flat.'),
  ('icp', 38, 'A client with suspected increased intracranial pressure is scheduled for a lumbar puncture to obtain CSF. Which action should the nurse take?', '[{"id": "a", "text": "Confirm that a CT is done first, as LP is contraindicated"}, {"id": "b", "text": "Place the client flat and assist with the procedure"}, {"id": "c", "text": "Proceed, since removing CSF will lower the pressure"}, {"id": "d", "text": "Give mannitol so the procedure can proceed safely"}]'::jsonb, '["a"]', 'Lumbar puncture is contraindicated with increased ICP because sudden CSF release can cause fatal brain herniation; a CT is always obtained first. Removing CSF is not a safe way to lower the pressure.'),
  ('icp', 39, 'The nurse is reviewing causes of increased intracranial pressure. Which cause raises ICP by producing cerebral vasodilation?', '[{"id": "a", "text": "Hydrocephalus"}, {"id": "b", "text": "Brain tumor"}, {"id": "c", "text": "Brain contusion"}, {"id": "d", "text": "Hypercapnia"}]'::jsonb, '["d"]', 'Hypercapnia (high CO₂) causes cerebral vasodilation, which raises ICP. Hydrocephalus, tumor, and contusion are structural causes, not vasodilation.'),
  ('icp', 40, 'The nurse is teaching about causes of increased intracranial pressure. Which condition is a structural cause rather than a physiological one?', '[{"id": "a", "text": "Meningitis"}, {"id": "b", "text": "Hypoxia"}, {"id": "c", "text": "Hypercapnia"}, {"id": "d", "text": "Hydrocephalus"}]'::jsonb, '["d"]', 'Hydrocephalus, a fluid buildup in the ventricles, is a structural cause. Meningitis, hypoxia, and hypercapnia are physiological causes.'),
  ('icp', 41, 'The family of a client with a brain bleed asks what "increased intracranial pressure" means. Which explanation by the nurse is most accurate?', '[{"id": "a", "text": "\"The skull expands outward to make room for the swelling.\""}, {"id": "b", "text": "\"Fluid collects in the lower spine and blocks the nerves.\""}, {"id": "c", "text": "\"Pressure rises inside the rigid skull and squeezes the brain.\""}, {"id": "d", "text": "\"Blood pressure in the arms rises above the normal range.\""}]'::jsonb, '["c"]', 'Increased ICP occurs when pressure inside the rigid skull rises, compressing brain tissue and impairing blood flow. The skull is rigid and does not expand.'),
  ('icp', 42, 'A nurse explains to a new graduate why increased intracranial pressure is treated as a neurological emergency. Which outcome of untreated increased ICP should the nurse identify?', '[{"id": "a", "text": "Spontaneous resolution"}, {"id": "b", "text": "Isolated peripheral weakness"}, {"id": "c", "text": "Gradual skull enlargement"}, {"id": "d", "text": "Herniation and death"}]'::jsonb, '["d"]', 'Increased ICP is a neurological emergency; untreated, it leads to herniation and death. It does not resolve on its own.'),
  ('icp', 43, 'A client with a head injury is being monitored for increased intracranial pressure. Which pupil finding is consistent with an early stage of increased ICP?', '[{"id": "a", "text": "Sluggish or unequal pupil reaction"}, {"id": "b", "text": "A fixed, dilated pupil on one side"}, {"id": "c", "text": "Fixed, dilated pupils on both sides"}, {"id": "d", "text": "Nonreactive pupils in a comatose client"}]'::jsonb, '["a"]', 'Sluggish or unequal pupils are an early sign. Fixed, dilated ("blown") pupils and coma are late signs of imminent herniation.'),
  ('icp', 44, 'A client recovering from a hemorrhagic stroke tells the nurse, "I''m seeing double." How should the nurse interpret this finding?', '[{"id": "a", "text": "An early sign of increased ICP"}, {"id": "b", "text": "A late sign of brain herniation"}, {"id": "c", "text": "A component of Cushing''s triad"}, {"id": "d", "text": "An expected finding needing no follow-up"}]'::jsonb, '["a"]', 'Blurred or double vision (diplopia) is an early sign of increased ICP and needs follow-up. It is not a late sign or part of Cushing''s triad.'),
  ('icp', 45, 'The nurse is assessing a client with suspected brainstem compression from increased intracranial pressure. Which respiratory pattern is consistent with this finding?', '[{"id": "a", "text": "Regular, unlabored breathing"}, {"id": "b", "text": "Slow, even, regular breathing"}, {"id": "c", "text": "Cheyne-Stokes breathing"}, {"id": "d", "text": "Quiet breathing at 16 per minute"}]'::jsonb, '["c"]', 'Irregular respirations such as Cheyne-Stokes breathing or apnea reflect brainstem compression in Cushing''s triad. Regular, even breathing does not.'),
  ('icp', 46, 'The nurse is monitoring blood pressure trends in a client with worsening intracranial pressure. Which blood pressure pattern reflects Cushing''s triad?', '[{"id": "a", "text": "Falling systolic pressure with a narrow pulse pressure"}, {"id": "b", "text": "Falling systolic pressure with a rapid heart rate"}, {"id": "c", "text": "Rising systolic pressure with a widened pulse pressure"}, {"id": "d", "text": "Equal drops in both systolic and diastolic pressure"}]'::jsonb, '["c"]', 'In Cushing''s triad, systolic BP rises with a widened pulse pressure as the brain tries to force blood in against the pressure. Falling pressures do not fit the triad.'),
  ('icp', 47, 'A client with increased intracranial pressure develops a rising systolic blood pressure. Which heart rate change should the nurse expect if Cushing''s triad is developing?', '[{"id": "a", "text": "Tachycardia"}, {"id": "b", "text": "No change in rate"}, {"id": "c", "text": "Irregular tachycardia"}, {"id": "d", "text": "Bradycardia"}]'::jsonb, '["d"]', 'In Cushing''s triad, the heart rate slows as a reflex response to hypertension. Tachycardia is not part of the triad.'),
  ('icp', 48, 'The nurse receives report on four clients on a neuro unit. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with a headache when bending over"}, {"id": "b", "text": "A client with an ICP of 10 mmHg"}, {"id": "c", "text": "A client with new decerebrate posturing"}, {"id": "d", "text": "A client with a CPP of 72 mmHg"}]'::jsonb, '["c"]', 'Decorticate or decerebrate posturing is a late sign of imminent herniation. A headache with bending is an early sign, an ICP of 10 mmHg is normal, and a CPP of 72 mmHg meets the goal of 60 mmHg or more.'),
  ('icp', 49, 'A client with a head injury who was calm and oriented an hour ago is now restless and keeps asking where he is. What should the nurse do first?', '[{"id": "a", "text": "Document it as anxiety from hospitalization"}, {"id": "b", "text": "Lower the head of the bed to promote rest"}, {"id": "c", "text": "Perform a focused neurological assessment"}, {"id": "d", "text": "Plan to reassess at the end of the shift"}]'::jsonb, '["c"]', 'Any new restlessness, confusion, or decreased responsiveness should trigger an immediate neurological assessment because change in LOC is the earliest sign of increased ICP. Lowering the bed raises ICP, and delaying assessment misses the change.'),
  ('icp', 50, 'A client with increased intracranial pressure develops bradycardia, rising systolic pressure, and irregular respirations. After notifying the provider, which intervention should the nurse prepare for?', '[{"id": "a", "text": "A lumbar puncture to drain spinal fluid"}, {"id": "b", "text": "Dexamethasone for traumatic swelling"}, {"id": "c", "text": "Osmotic diuretics and possible surgical decompression"}, {"id": "d", "text": "Trendelenburg positioning to raise BP"}]'::jsonb, '["c"]', 'Cushing''s triad signals impending herniation; the nurse prepares for emergency interventions including osmotic diuretics and possible surgical decompression. Lumbar puncture is contraindicated with increased ICP, and Trendelenburg increases ICP.'),
  ('ms', 1, 'A client newly diagnosed with relapsing-remitting multiple sclerosis (MS) is being admitted to a medical unit. Which symptom does the nurse anticipate the client will describe as the most common and debilitating?', '[{"id": "a", "text": "Fatigue"}, {"id": "b", "text": "Hearing loss"}, {"id": "c", "text": "Severe headache"}, {"id": "d", "text": "Resting tremor"}]'::jsonb, '["a"]', 'Fatigue is the #1 most common and debilitating symptom of MS. The other complaints are not identified as hallmark MS symptoms, which center on fatigue, weakness, sensory changes, and vision changes.'),
  ('ms', 2, 'A client with MS reports that her legs feel much weaker after taking a long hot bath. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Hot water causes new plaques to form on your peripheral nerves.\""}, {"id": "b", "text": "\"Increased body temperature can make your MS symptoms worse.\""}, {"id": "c", "text": "\"Weakness after warmth shows your medication is working well.\""}, {"id": "d", "text": "\"This change means your MS has become primary progressive.\""}]'::jsonb, '["b"]', 'Uhthoff''s phenomenon is the worsening of MS symptoms with increased body temperature, including hot showers. MS does not affect peripheral nerves, and heat-related worsening does not indicate a change in MS type.'),
  ('ms', 3, 'A nursing student is explaining which parts of the nervous system are affected by MS. Which statement by the student is accurate?', '[{"id": "a", "text": "\"MS damages the peripheral nerves but spares the brain.\""}, {"id": "b", "text": "\"MS affects the central and peripheral systems equally.\""}, {"id": "c", "text": "\"MS affects the brain and spinal cord but spares the PNS.\""}, {"id": "d", "text": "\"MS affects the spinal cord but always spares the brain.\""}]'::jsonb, '["c"]', 'MS affects the CNS only (brain and spinal cord); the peripheral nervous system is spared. It does not spare the brain or involve peripheral nerves.'),
  ('ms', 4, 'A client asks the nurse what is happening inside the body to cause MS. Which explanation is accurate?', '[{"id": "a", "text": "\"A bacterial infection forms abscesses in the spinal cord.\""}, {"id": "b", "text": "\"Nerve cells produce excess myelin that blocks impulses.\""}, {"id": "c", "text": "\"Antibodies attack the muscle fibers of the arms and legs.\""}, {"id": "d", "text": "\"Immune cells attack myelin, slowing or blocking impulses.\""}]'::jsonb, '["d"]', 'In MS the immune system attacks the myelin sheath, which slows or blocks nerve impulses and leads to plaques. The disorder is autoimmune and targets myelin, not muscle fibers, and does not involve excess myelin.'),
  ('ms', 5, 'A client recently diagnosed with MS asks which type of the disease most people have when they are first diagnosed. Which type should the nurse identify?', '[{"id": "a", "text": "Relapsing-remitting MS"}, {"id": "b", "text": "Primary progressive MS"}, {"id": "c", "text": "Secondary progressive MS"}, {"id": "d", "text": "Progressive-relapsing MS"}]'::jsonb, '["a"]', 'Relapsing-remitting MS is the most common type, and most patients start here. Secondary progressive MS develops later from RRMS, and primary progressive MS has steady worsening from onset.'),
  ('ms', 6, 'A client''s MS has worsened steadily since the first symptoms appeared, and the client has never had a clear relapse or a period of remission. The nurse recognizes this pattern as which type of MS?', '[{"id": "a", "text": "Relapsing-remitting"}, {"id": "b", "text": "Primary progressive"}, {"id": "c", "text": "Secondary progressive"}, {"id": "d", "text": "Progressive-relapsing"}]'::jsonb, '["b"]', 'Primary progressive MS shows steady worsening from onset with no clear relapses and no remission periods. Secondary progressive MS begins as RRMS first, and relapsing-remitting MS has clear relapses and remissions.'),
  ('ms', 7, 'A client had relapsing-remitting MS for many years with clear flare-ups and recoveries. Over the past year the client''s function has declined steadily without recovery periods. The nurse recognizes this as which type of MS?', '[{"id": "a", "text": "Primary progressive"}, {"id": "b", "text": "Relapsing-remitting"}, {"id": "c", "text": "Secondary progressive"}, {"id": "d", "text": "Remission phase"}]'::jsonb, '["c"]', 'Secondary progressive MS begins as RRMS and then transitions to a steady decline. Primary progressive MS worsens steadily from onset rather than after a relapsing-remitting course.'),
  ('ms', 8, 'A client with relapsing-remitting MS asks what the provider meant by saying the disease is "in remission." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Your symptoms have flared up and are getting worse.\""}, {"id": "b", "text": "\"Your disease is cured and will not come back again.\""}, {"id": "c", "text": "\"Your disease is declining steadily without any breaks.\""}, {"id": "d", "text": "\"Your symptoms have improved or have gone away for now.\""}]'::jsonb, '["d"]', 'Remission means symptoms improve or disappear, whereas an exacerbation is a flare-up of symptoms. MS is chronic and progressive, so remission is not a cure.'),
  ('ms', 9, 'A client with relapsing-remitting MS asks what could set off a flare-up. Which factor should the nurse identify as a trigger for an exacerbation?', '[{"id": "a", "text": "Developing an infection such as the flu"}, {"id": "b", "text": "Taking scheduled rest periods each day"}, {"id": "c", "text": "Keeping the home air-conditioned"}, {"id": "d", "text": "Eating a high-fiber diet with fluids"}]'::jsonb, '["a"]', 'MS relapses are triggered by heat, stress, illness, and infection. Rest periods, a cool environment, and a high-fiber diet with fluids are recommended nursing measures, not triggers.'),
  ('ms', 10, 'The nurse is teaching a client with MS how to reduce the risk of exacerbations. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will try to stay away from people who are sick.\""}, {"id": "b", "text": "\"Stress has no effect on my MS, so I won''t worry about it.\""}, {"id": "c", "text": "\"I will keep my house cool during the summer months.\""}, {"id": "d", "text": "\"I will plan rest periods so I don''t overexert myself.\""}]'::jsonb, '["b"]', 'Stress is a trigger for MS relapses, and clients should avoid stress, illness, and overheating. Avoiding sick contacts, staying cool, and planning rest are correct measures.'),
  ('ms', 11, 'A client with MS plans to garden outdoors during the summer. Which instruction by the nurse best addresses the client''s heat sensitivity?', '[{"id": "a", "text": "\"Take a hot shower afterward to relax your muscles.\""}, {"id": "b", "text": "\"Work outside during the warmest part of the afternoon.\""}, {"id": "c", "text": "\"Wear a cooling vest while you are working outdoors.\""}, {"id": "d", "text": "\"Use a heating pad on any areas that feel numb.\""}]'::jsonb, '["c"]', 'Teaching for Uhthoff''s phenomenon includes cool environments, air conditioning, and cooling vests. Hot showers and other heat exposure worsen MS symptoms.'),
  ('ms', 12, 'A client with MS develops a fever from a respiratory infection and reports that leg weakness and blurred vision have become worse. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "The worsening shows the MS has become primary progressive."}, {"id": "b", "text": "The fever is directly damaging the client''s peripheral nerves."}, {"id": "c", "text": "The new symptoms are unrelated to the client''s MS diagnosis."}, {"id": "d", "text": "Fever and infection can worsen MS symptoms and trigger a relapse."}]'::jsonb, '["d"]', 'Increased body temperature, including fever, worsens MS symptoms, and infection is a relapse trigger. MS spares the peripheral nervous system, so the fever is not damaging peripheral nerves.'),
  ('ms', 13, 'A client with MS coughs and clears the throat repeatedly while drinking water at lunch. The nurse identifies which complication as the priority concern?', '[{"id": "a", "text": "Aspiration related to dysphagia"}, {"id": "b", "text": "Urinary retention from bladder dysfunction"}, {"id": "c", "text": "Diplopia from optic nerve inflammation"}, {"id": "d", "text": "Fatigue related to overexertion"}]'::jsonb, '["a"]', 'Dysphagia in MS creates an aspiration risk, and aspiration is one of the listed safety priorities. Coughing while drinking points to swallowing difficulty rather than bladder, vision, or fatigue problems.'),
  ('ms', 14, 'The nurse is developing a plan of care for a hospitalized client with advanced MS. Which group of safety risks should the nurse prioritize?', '[{"id": "a", "text": "Burns, hypoglycemia, and bleeding"}, {"id": "b", "text": "Falls, aspiration, and urinary tract infection"}, {"id": "c", "text": "Seizures, dehydration, and hypothermia"}, {"id": "d", "text": "Pressure injury, bleeding, and hearing loss"}]'::jsonb, '["b"]', 'The safety priorities in MS are falls, aspiration from dysphagia, and UTI from bladder dysfunction. The other groupings do not reflect the major MS risks of mobility impairment, swallowing difficulty, and bladder dysfunction.'),
  ('ms', 15, 'A client with MS has bladder dysfunction. The client''s family asks why the nurse is closely watching for a urinary tract infection. Which explanation is accurate?', '[{"id": "a", "text": "\"Steroid flares cause infection directly in the bladder.\""}, {"id": "b", "text": "\"Heat sensitivity raises the risk of bladder infection.\""}, {"id": "c", "text": "\"Bladder dysfunction in MS increases the risk of UTI.\""}, {"id": "d", "text": "\"Optic neuritis spreads infection to the urinary tract.\""}]'::jsonb, '["c"]', 'UTI is a safety priority in MS because of bladder dysfunction. Heat sensitivity worsens symptoms but is not described as the cause of UTI risk.'),
  ('ms', 16, 'A client with MS reports frequent, sudden urges to urinate and difficulty reaching the bathroom in time. Which medication does the nurse anticipate the provider will prescribe?', '[{"id": "a", "text": "Bethanechol"}, {"id": "b", "text": "Baclofen"}, {"id": "c", "text": "Fingolimod"}, {"id": "d", "text": "Oxybutynin"}]'::jsonb, '["d"]', 'Oxybutynin targets bladder urgency/overactive bladder. Bethanechol is used for urinary retention because it stimulates bladder contraction, which would not help urgency.'),
  ('ms', 17, 'A client with MS has urinary retention and is prescribed bethanechol. The nurse explains that this medication will have which effect?', '[{"id": "a", "text": "Stimulate the bladder to contract"}, {"id": "b", "text": "Relax the bladder to reduce urgency"}, {"id": "c", "text": "Reduce stiffness in the leg muscles"}, {"id": "d", "text": "Shorten the duration of a relapse"}]'::jsonb, '["a"]', 'Bethanechol treats urinary retention by stimulating bladder contraction. Reducing bladder urgency is the target of oxybutynin, not bethanechol.'),
  ('ms', 18, 'A client with MS has been taking baclofen for several weeks. Which finding best indicates that the medication is effective?', '[{"id": "a", "text": "Fewer episodes of bladder urgency"}, {"id": "b", "text": "Decreased stiffness in the leg muscles"}, {"id": "c", "text": "More energy throughout the day"}, {"id": "d", "text": "Less burning pain in the feet"}]'::jsonb, '["b"]', 'Baclofen targets muscle spasticity (stiffness), so decreased stiffness shows effectiveness. Bladder urgency, fatigue, and neuropathic pain are targeted by oxybutynin, amantadine/modafinil, and gabapentin/pregabalin.'),
  ('ms', 19, 'A client with MS asks why amantadine has been added to the treatment plan. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It will help relax the stiffness in your legs.\""}, {"id": "b", "text": "\"It will help your bladder empty more completely.\""}, {"id": "c", "text": "\"It will help you manage your MS-related fatigue.\""}, {"id": "d", "text": "\"It will help correct the double vision you have.\""}]'::jsonb, '["c"]', 'Amantadine and modafinil are used for fatigue management in MS. Spasticity is treated with baclofen or tizanidine, and urinary retention with bethanechol.'),
  ('ms', 20, 'A client with MS describes burning, tingling pain in both feet that disrupts sleep. Which medication does the nurse anticipate for this symptom?', '[{"id": "a", "text": "Oxybutynin"}, {"id": "b", "text": "Bethanechol"}, {"id": "c", "text": "Modafinil"}, {"id": "d", "text": "Gabapentin"}]'::jsonb, '["d"]', 'Gabapentin and pregabalin target neuropathic pain and paresthesias. Modafinil is used for fatigue, and oxybutynin and bethanechol treat bladder problems.'),
  ('ms', 21, 'A client with relapsing-remitting MS is admitted with an acute exacerbation involving new weakness and visual changes. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "IV methylprednisolone"}, {"id": "b", "text": "Oral oxybutynin"}, {"id": "c", "text": "Oral tizanidine"}, {"id": "d", "text": "Oral bethanechol"}]'::jsonb, '["a"]', 'IV corticosteroids such as methylprednisolone are the treatment for an acute MS flare. Tizanidine treats spasticity and oxybutynin and bethanechol treat bladder problems, not the flare itself.'),
  ('ms', 22, 'A client receiving IV methylprednisolone for an MS flare asks how the medication will help. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It rebuilds the myelin that has already been lost.\""}, {"id": "b", "text": "\"It reduces inflammation and shortens the relapse.\""}, {"id": "c", "text": "\"It blocks immune cells from crossing into the brain.\""}, {"id": "d", "text": "\"It traps immune cells inside your lymph nodes.\""}]'::jsonb, '["b"]', 'Corticosteroids reduce inflammation during acute flares and shorten relapse duration. Blocking immune cells from crossing the blood-brain barrier describes natalizumab, and trapping them in lymph nodes describes fingolimod.'),
  ('ms', 23, 'A client with relapsing-remitting MS begins interferon beta-1a. Which outcome indicates the medication is achieving its intended effect?', '[{"id": "a", "text": "Immediate disappearance of existing plaques"}, {"id": "b", "text": "Rapid relief of bladder urgency symptoms"}, {"id": "c", "text": "Fewer relapses occurring over time"}, {"id": "d", "text": "Relief of leg stiffness within hours"}]'::jsonb, '["c"]', 'Interferon beta is a disease-modifying drug that reduces the frequency of relapses. It slows progression rather than removing existing plaques or treating bladder urgency or spasticity.'),
  ('ms', 24, 'A client with MS is starting glatiramer acetate (Copaxone). Which explanation of how this medication works is accurate?', '[{"id": "a", "text": "It keeps immune cells trapped in the lymph nodes."}, {"id": "b", "text": "It stops immune cells crossing the blood-brain barrier."}, {"id": "c", "text": "It stimulates the bladder muscle to contract fully."}, {"id": "d", "text": "It mimics myelin to divert the immune attack from it."}]'::jsonb, '["d"]', 'Glatiramer acetate mimics myelin and diverts the immune attack away from myelin. Trapping immune cells in lymph nodes describes fingolimod, and blocking passage across the blood-brain barrier describes natalizumab.'),
  ('ms', 25, 'A client with MS is scheduled to begin natalizumab. The nurse explains that this medication slows the disease by which action?', '[{"id": "a", "text": "Preventing immune cells from crossing the blood-brain barrier"}, {"id": "b", "text": "Trapping immune cells inside the lymph nodes of the body"}, {"id": "c", "text": "Mimicking myelin so the immune attack is directed elsewhere"}, {"id": "d", "text": "Reducing inflammation to shorten an acute relapse episode"}]'::jsonb, '["a"]', 'Natalizumab prevents immune cells from crossing the blood-brain barrier. Trapping immune cells in lymph nodes is the action of fingolimod, and mimicking myelin is the action of glatiramer.'),
  ('ms', 26, 'A client with MS prefers a disease-modifying medication that can be taken by mouth. Which medication does the nurse expect the provider to discuss?', '[{"id": "a", "text": "Natalizumab"}, {"id": "b", "text": "Fingolimod"}, {"id": "c", "text": "Methylprednisolone IV"}, {"id": "d", "text": "Glatiramer acetate"}]'::jsonb, '["b"]', 'Fingolimod is an oral disease-modifying drug. IV methylprednisolone is a corticosteroid for acute flares, not a disease-modifying drug.'),
  ('ms', 27, 'A nurse is reviewing a client''s new prescription for fingolimod. Which mechanism of action does the nurse recognize for this drug?', '[{"id": "a", "text": "Mimics myelin to divert the immune attack"}, {"id": "b", "text": "Stimulates contraction of the bladder"}, {"id": "c", "text": "Traps immune cells in the lymph nodes"}, {"id": "d", "text": "Converts to dopamine within the brain"}]'::jsonb, '["c"]', 'Fingolimod traps immune cells in lymph nodes and is taken orally. Mimicking myelin describes glatiramer acetate, and stimulating bladder contraction describes bethanechol.'),
  ('ms', 28, 'A client starting a disease-modifying drug for MS asks what the medication is expected to do. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It will cure the disease after several months.\""}, {"id": "b", "text": "\"It will repair the plaques that have already formed.\""}, {"id": "c", "text": "\"It is used only to treat symptoms during a flare.\""}, {"id": "d", "text": "\"It is intended to slow the progression of the disease.\""}]'::jsonb, '["d"]', 'Disease-modifying drugs are used to slow progression. Acute flares are treated with corticosteroids, and MS is chronic and progressive with permanent damage over time, so these drugs do not cure it or repair plaques.'),
  ('ms', 29, 'A provider suspects MS in a client with intermittent numbness and blurred vision. Which diagnostic test does the nurse anticipate will be most useful?', '[{"id": "a", "text": "MRI of the brain and spinal cord"}, {"id": "b", "text": "Lumbar puncture for CSF analysis"}, {"id": "c", "text": "Evoked potential testing"}, {"id": "d", "text": "Serum dopamine level"}]'::jsonb, '["a"]', 'MRI is the most useful test, showing brain and spinal cord lesions (plaques). CSF oligoclonal bands indicate CNS inflammation but are not diagnostic alone.'),
  ('ms', 30, 'A client is undergoing an MRI to evaluate for MS. Which finding would the nurse expect to be reported if the diagnosis is MS?', '[{"id": "a", "text": "Plaques confined to the peripheral nerves"}, {"id": "b", "text": "White matter plaques in the brain and spinal cord"}, {"id": "c", "text": "Bleeding within the brainstem tissue"}, {"id": "d", "text": "Normal brain and spinal cord tissue"}]'::jsonb, '["b"]', 'The MRI finding in MS is white matter plaques (lesions in the brain and spinal cord). MS affects the CNS only, so plaques would not be confined to peripheral nerves.'),
  ('ms', 31, 'A client with suspected MS has a lumbar puncture. Which cerebrospinal fluid finding is consistent with MS?', '[{"id": "a", "text": "Decreased oligoclonal bands (IgG)"}, {"id": "b", "text": "Absent IgG within the spinal fluid"}, {"id": "c", "text": "Increased oligoclonal bands (IgG)"}, {"id": "d", "text": "Unchanged oligoclonal bands (IgG)"}]'::jsonb, '["c"]', 'The CSF finding in MS is increased oligoclonal bands (IgG), which indicates CNS inflammation. A decreased or absent finding reverses the expected direction.'),
  ('ms', 32, 'After a lumbar puncture shows increased oligoclonal bands, the nurse reviews the results with a client being evaluated for MS. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"The bands suggest there is inflammation in my CNS.\""}, {"id": "b", "text": "\"An MRI can show whether I have plaques on my nerves.\""}, {"id": "c", "text": "\"The bands are found in the fluid around my spinal cord.\""}, {"id": "d", "text": "\"The spinal tap result alone proves that I have MS.\""}]'::jsonb, '["d"]', 'Increased oligoclonal bands indicate CNS inflammation but are not diagnostic alone. MRI showing brain and spinal cord plaques is the most useful test.'),
  ('ms', 33, 'A client being evaluated for MS asks why evoked potential testing has been ordered. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It measures slowed nerve conduction to find hidden lesions.\""}, {"id": "b", "text": "\"It shows white matter plaques in images of the brain.\""}, {"id": "c", "text": "\"It measures oligoclonal bands in the spinal fluid.\""}, {"id": "d", "text": "\"It confirms MS by testing for dopamine response.\""}]'::jsonb, '["a"]', 'Evoked potentials test for slowed nerve conduction and help detect subclinical lesions. Imaging plaques is the role of MRI, and oligoclonal bands are measured by lumbar puncture.'),
  ('ms', 34, 'A client with MS reports seeing two images of every object since yesterday. Which intervention should the nurse include in the plan of care?', '[{"id": "a", "text": "Apply warm compresses to both eyes"}, {"id": "b", "text": "Provide an eye patch for the diplopia"}, {"id": "c", "text": "Dim all lights and limit activity"}, {"id": "d", "text": "Instill thickened artificial tears"}]'::jsonb, '["b"]', 'Double vision (diplopia) is a common MS vision change, and an eye patch is the listed nursing intervention. Warm compresses add heat, which worsens MS symptoms.'),
  ('ms', 35, 'A client with MS is diagnosed with optic neuritis. The client asks what this term means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is a loss of myelin in the nerves of the hands.\""}, {"id": "b", "text": "\"It is a weakness of the muscles that close the eyelid.\""}, {"id": "c", "text": "\"It is inflammation of the nerve that serves the eye.\""}, {"id": "d", "text": "\"It is an infection of the outer surface of the eye.\""}]'::jsonb, '["c"]', 'Optic neuritis is inflammation of the optic nerve and is one of the sight issues seen in MS. MS spares peripheral nerves, so it is not a loss of myelin in the hands.'),
  ('ms', 36, 'During an admission assessment, the nurse observes that a client with MS walks with an unsteady, uncoordinated gait. How should the nurse document this finding?', '[{"id": "a", "text": "Dysarthria"}, {"id": "b", "text": "Paresthesia"}, {"id": "c", "text": "Dysphagia"}, {"id": "d", "text": "Ataxia"}]'::jsonb, '["d"]', 'Ataxia is an unsteady, uncoordinated gait. Dysarthria is slurred speech, paresthesia is numbness/tingling, and dysphagia is difficulty swallowing.'),
  ('ms', 37, 'A client being evaluated for MS reports numbness and a pins-and-needles feeling in both hands. The nurse recognizes this finding as which symptom?', '[{"id": "a", "text": "Paresthesia"}, {"id": "b", "text": "Spasticity"}, {"id": "c", "text": "Ataxia"}, {"id": "d", "text": "Diplopia"}]'::jsonb, '["a"]', 'Numbness/tingling is paresthesia, a motor and sensory symptom of MS. Spasticity is muscle stiffness, ataxia is an uncoordinated gait, and diplopia is double vision.'),
  ('ms', 38, 'The nurse notes that a client with MS speaks with slurred words that are difficult to understand. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Dysphagia"}, {"id": "b", "text": "Dysarthria"}, {"id": "c", "text": "Diplopia"}, {"id": "d", "text": "Ataxia"}]'::jsonb, '["b"]', 'Dysarthria is slurred speech. Dysphagia is difficulty swallowing, diplopia is double vision, and ataxia is an unsteady gait.'),
  ('ms', 39, 'The spouse of a client with MS reports that the client has become forgetful and has trouble concentrating while reading. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"These changes are unrelated to MS and need a separate workup.\""}, {"id": "b", "text": "\"These changes mean the MS has spread to peripheral nerves.\""}, {"id": "c", "text": "\"Memory and concentration changes can occur as part of MS.\""}, {"id": "d", "text": "\"These changes happen only when the MS is in remission.\""}]'::jsonb, '["c"]', 'Cognitive changes involving memory and concentration are listed symptoms of MS. MS affects the CNS only, so the changes do not reflect peripheral nerve spread.'),
  ('ms', 40, 'A client with MS who has muscle weakness and ataxia is preparing for discharge home. Which instruction best reduces the client''s risk of falls?', '[{"id": "a", "text": "\"Avoid using a walker so your leg muscles get stronger.\""}, {"id": "b", "text": "\"Walk quickly between rooms to limit time on your feet.\""}, {"id": "c", "text": "\"Keep throw rugs near the bed to cushion any falls.\""}, {"id": "d", "text": "\"Use your assistive device and clear hazards from walkways.\""}]'::jsonb, '["d"]', 'Fall prevention in MS includes assistive devices and removing hazards. Avoiding the walker or leaving rugs in place increases fall risk.'),
  ('ms', 41, 'A client with MS has muscle weakness and spasticity in the legs. Which intervention should the nurse encourage to support the client''s mobility?', '[{"id": "a", "text": "Participation in physical therapy and ROM exercises"}, {"id": "b", "text": "Strict bed rest until the spasticity has resolved"}, {"id": "c", "text": "Long walks in warm weather to build endurance"}, {"id": "d", "text": "Avoiding all exercise to prevent fatigue"}]'::jsonb, '["a"]', 'The nurse should encourage PT and ROM exercises for safety and mobility. Exercising in heat worsens symptoms, and the plan calls for balancing activity with rest rather than eliminating activity.'),
  ('ms', 42, 'A nursing assistant reports that a client with MS takes a very long time to dress each morning. Which instruction by the nurse is most appropriate?', '[{"id": "a", "text": "\"Dress the client yourself to save the client''s energy.\""}, {"id": "b", "text": "\"Allow the client extra time to complete the activity.\""}, {"id": "c", "text": "\"Encourage the client to dress quickly to stay on schedule.\""}, {"id": "d", "text": "\"Have the client dress after a hot shower to loosen muscles.\""}]'::jsonb, '["b"]', 'Nursing priorities for safety and mobility include allowing extra time for activities. A hot shower raises body temperature and worsens MS symptoms.'),
  ('ms', 43, 'A client with MS who reports severe fatigue plans to clean the entire house in one morning before guests arrive. Which advice by the nurse is most appropriate?', '[{"id": "a", "text": "\"Finish all the cleaning at once so you can rest later.\""}, {"id": "b", "text": "\"Clean during the hottest part of the day to stay loose.\""}, {"id": "c", "text": "\"Spread tasks out and take rest periods between them.\""}, {"id": "d", "text": "\"Push through the tiredness so your stamina improves.\""}]'::jsonb, '["c"]', 'Energy conservation for MS fatigue includes rest periods and avoiding overexertion. Pushing through fatigue is overexertion, and heat worsens symptoms.'),
  ('ms', 44, 'The nurse has taught a client with MS about managing fatigue. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will build rest periods into my daily schedule.\""}, {"id": "b", "text": "\"I will keep my home cool with air conditioning.\""}, {"id": "c", "text": "\"I will ask my provider about medication for fatigue.\""}, {"id": "d", "text": "\"I will exercise until I am exhausted to build energy.\""}]'::jsonb, '["d"]', 'Clients with MS should conserve energy with rest periods and avoid overexertion, so exercising to exhaustion needs correction. Cool environments and fatigue medications such as amantadine or modafinil are appropriate.'),
  ('ms', 45, 'A client with MS has episodes of urinary incontinence related to bladder dysfunction. Which nursing intervention is most appropriate to include in the plan of care?', '[{"id": "a", "text": "Timed voiding with a bladder training program"}, {"id": "b", "text": "Restricting fluids throughout the entire day"}, {"id": "c", "text": "Inserting an indwelling catheter for comfort"}, {"id": "d", "text": "Limiting toileting to twice during each shift"}]'::jsonb, '["a"]', 'Timed voiding and bladder training are listed interventions for bladder dysfunction in MS. Restricting fluids conflicts with the recommended fluid intake for the bowel program.'),
  ('ms', 46, 'A client with MS reports bowel dysfunction with infrequent stools. Which dietary instruction is most appropriate as part of a bowel program?', '[{"id": "a", "text": "\"Limit fluids so that your bladder stays under control.\""}, {"id": "b", "text": "\"Eat high-fiber foods and maintain a good fluid intake.\""}, {"id": "c", "text": "\"Choose low-fiber foods to make swallowing easier.\""}, {"id": "d", "text": "\"Eat only one large meal each day to rest the bowel.\""}]'::jsonb, '["b"]', 'A bowel program for MS includes high fiber and fluid intake. Limiting fluids or fiber works against the bowel program.'),
  ('ms', 47, 'A client with MS has new slurred speech and coughs while eating breakfast. Which action should the nurse take first?', '[{"id": "a", "text": "Encourage the client to finish the meal quickly"}, {"id": "b", "text": "Leave the tray so the client can eat privately"}, {"id": "c", "text": "Stop the meal and assess the client''s swallowing"}, {"id": "d", "text": "Offer a cup of hot tea to soothe the throat"}]'::jsonb, '["c"]', 'Coughing during meals suggests dysphagia, which creates an aspiration risk, so monitoring swallowing comes first. Leaving the client to eat alone or hurrying the meal ignores the aspiration risk.'),
  ('ms', 48, 'A client newly diagnosed with MS asks what to expect from the disease over the long term. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"MS goes away completely after the first remission.\""}, {"id": "b", "text": "\"MS affects only the nerves in your arms and legs.\""}, {"id": "c", "text": "\"MS does not cause any lasting damage to the nerves.\""}, {"id": "d", "text": "\"MS is chronic and can cause permanent damage over time.\""}]'::jsonb, '["d"]', 'MS is a chronic, progressive autoimmune disorder in which plaques form and cause permanent damage over time. It affects the CNS only, and remission does not mean the disease is gone.'),
  ('ms', 49, 'The nurse is reviewing the health history of a client being evaluated for MS. Which pair of findings is most consistent with MS?', '[{"id": "a", "text": "Muscle weakness and double vision"}, {"id": "b", "text": "Pill-rolling tremor and drooling"}, {"id": "c", "text": "Hearing loss and ringing in the ears"}, {"id": "d", "text": "Chest pain and shortness of breath"}]'::jsonb, '["a"]', 'The MS memory aid highlights muscle weakness/mobility impairment and sight issues such as diplopia. The other pairs are not listed MS manifestations.'),
  ('ms', 50, 'A client with relapsing-remitting MS reports that numbness and leg weakness have suddenly worsened over the past three days after a stable period. The nurse recognizes this change as which phase of the disease?', '[{"id": "a", "text": "Remission"}, {"id": "b", "text": "Exacerbation"}, {"id": "c", "text": "Primary progression"}, {"id": "d", "text": "Secondary progression"}]'::jsonb, '["b"]', 'An exacerbation is a flare-up of symptoms, which fits a sudden worsening after a stable period in RRMS. Remission is when symptoms improve or disappear, and progressive types involve steady decline rather than a distinct flare.'),
  ('imaging', 1, 'A client arrives in the emergency department 45 minutes after the sudden onset of slurred speech and right-sided weakness. The provider is considering tPA. Which test should the nurse anticipate first?', '[{"id": "a", "text": "MRI of the brain"}, {"id": "b", "text": "Electroencephalogram"}, {"id": "c", "text": "CT scan of the head"}, {"id": "d", "text": "Lumbar puncture"}]'::jsonb, '["c"]', 'A CT scan must always be done first in suspected stroke to rule out hemorrhage before tPA is given. MRI takes 30–60 minutes and is not for acute emergencies.'),
  ('imaging', 2, 'A nursing student asks why a client with a suspected stroke must have a CT scan before receiving tPA. Which response by the nurse is correct?', '[{"id": "a", "text": "\"The CT rules out a bleed in the brain.\""}, {"id": "b", "text": "\"The CT shows the plaques of multiple sclerosis.\""}, {"id": "c", "text": "\"The CT measures the electrical activity of the brain.\""}, {"id": "d", "text": "\"The CT obtains spinal fluid for laboratory analysis.\""}]'::jsonb, '["a"]', 'CT is done first in stroke to rule out hemorrhage before tPA, because giving tPA to a hemorrhagic stroke patient is fatal. Electrical activity is measured by EEG, and spinal fluid is obtained by lumbar puncture.'),
  ('imaging', 3, 'A client is brought to the emergency department after being struck on the head and is suspected of having a skull fracture. Which diagnostic test should the nurse anticipate first?', '[{"id": "a", "text": "MRI scan"}, {"id": "b", "text": "Electroencephalogram"}, {"id": "c", "text": "CT scan"}, {"id": "d", "text": "Lumbar puncture"}]'::jsonb, '["c"]', 'CT is first-line in emergencies such as trauma and best detects skull fractures. MRI is not used for acute emergencies.'),
  ('imaging', 4, 'The CT report for a client with a sudden severe headache describes a bright white area within the brain. How should the nurse interpret this finding?', '[{"id": "a", "text": "A multiple sclerosis plaque"}, {"id": "b", "text": "Normal cerebrospinal fluid"}, {"id": "c", "text": "Abnormal brain wave activity"}, {"id": "d", "text": "Bleeding in the brain"}]'::jsonb, '["d"]', 'On CT, hemorrhage appears bright white. MS plaques are best seen on MRI, and brain wave activity is measured by EEG.'),
  ('imaging', 5, 'A client with a head injury asks why a CT scan is being done instead of an MRI. Which response by the nurse explains why CT is preferred in an emergency?', '[{"id": "a", "text": "\"A CT is fast, with results in minutes.\""}, {"id": "b", "text": "\"A CT uses magnets instead of radiation.\""}, {"id": "c", "text": "\"A CT shows more soft tissue detail.\""}, {"id": "d", "text": "\"A CT records your brain wave activity.\""}]'::jsonb, '["a"]', 'CT is fast, gives results in minutes, and is first-line in emergencies. Magnets without radiation and greater soft tissue detail describe MRI.'),
  ('imaging', 6, 'A client scheduled for a head CT asks how the scan works. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It uses X-rays to make cross-sectional images.\""}, {"id": "b", "text": "\"It uses strong magnets and radio waves.\""}, {"id": "c", "text": "\"It records signals from scalp electrodes.\""}, {"id": "d", "text": "\"It analyzes fluid taken from your spine.\""}]'::jsonb, '["a"]', 'CT uses X-rays to create cross-sectional brain images. Magnets and radio waves describe MRI, and scalp electrodes describe EEG.'),
  ('imaging', 7, 'A client is scheduled for a CT scan with contrast. Which question is most important for the nurse to ask before the scan?', '[{"id": "a", "text": "\"Did you wash your hair free of products?\""}, {"id": "b", "text": "\"Have you had any coffee this morning?\""}, {"id": "c", "text": "\"Have you ever had an allergy to iodine?\""}, {"id": "d", "text": "\"Can you curl up with your knees to chest?\""}]'::jsonb, '["c"]', 'Before contrast CT, the nurse asks about allergies to iodine because the contrast contains iodine. Clean hair and holding caffeine are EEG preparation, and the fetal position is for lumbar puncture.'),
  ('imaging', 8, 'The nurse is preparing a client for a CT scan with contrast. Which laboratory results should the nurse review before the procedure?', '[{"id": "a", "text": "Serum glucose level"}, {"id": "b", "text": "CSF oligoclonal bands"}, {"id": "c", "text": "Serum sodium level"}, {"id": "d", "text": "BUN and creatinine"}]'::jsonb, '["d"]', 'Kidney function (BUN, creatinine) must be checked before contrast because contrast is nephrotoxic. Oligoclonal bands are a CSF finding from lumbar puncture in MS.'),
  ('imaging', 9, 'A client scheduled for a contrast CT asks why a kidney blood test was drawn first. Which response by the nurse is correct?', '[{"id": "a", "text": "\"The magnet can affect kidney function.\""}, {"id": "b", "text": "\"Low blood sugar can alter your results.\""}, {"id": "c", "text": "\"The contrast dye can harm the kidneys.\""}, {"id": "d", "text": "\"Kidney labs help diagnose meningitis.\""}]'::jsonb, '["c"]', 'Contrast is nephrotoxic, so kidney function is checked before a contrast CT. Magnets are used in MRI, and low blood sugar is a concern for EEG.'),
  ('imaging', 10, 'A client asks why the provider ordered contrast for a CT scan of the brain. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It helps highlight blood vessels and tumors.\""}, {"id": "b", "text": "\"It removes the need for any X-ray exposure.\""}, {"id": "c", "text": "\"It records the brain''s electrical activity.\""}, {"id": "d", "text": "\"It replaces the need for a kidney lab check.\""}]'::jsonb, '["a"]', 'Contrast helps highlight blood vessels and tumors on CT. CT still uses X-rays, and kidney function must be checked because contrast is nephrotoxic.'),
  ('imaging', 11, 'A client with visual changes and numbness is suspected of having multiple sclerosis. Which test should the nurse anticipate to visualize MS plaques?', '[{"id": "a", "text": "CT scan of the head"}, {"id": "b", "text": "Electroencephalogram"}, {"id": "c", "text": "Lumbar puncture"}, {"id": "d", "text": "MRI of the brain"}]'::jsonb, '["d"]', 'MRI is best for brain tumors and MS plaques. A lumbar puncture can show oligoclonal bands in MS but does not image plaques, and EEG measures electrical activity.'),
  ('imaging', 12, 'During screening for an MRI, a client reports having a pacemaker. What is the nurse''s best action?', '[{"id": "a", "text": "Proceed because MRI uses no radiation"}, {"id": "b", "text": "Proceed after giving the contrast dye"}, {"id": "c", "text": "Proceed if the client can lie still"}, {"id": "d", "text": "Notify the provider before the scan"}]'::jsonb, '["d"]', 'Pacemakers are an absolute contraindication to MRI, so the provider must be notified before the scan. The lack of radiation does not make the magnetic field safe for ferromagnetic devices.'),
  ('imaging', 13, 'The nurse is screening four clients scheduled for an MRI. Which client history is a contraindication to the procedure?', '[{"id": "a", "text": "Shrapnel fragments from a past injury"}, {"id": "b", "text": "An allergy to iodine-based dye"}, {"id": "c", "text": "A history of a seizure disorder"}, {"id": "d", "text": "Coffee consumed earlier today"}]'::jsonb, '["a"]', 'Metal implants and clips, including shrapnel, are absolute contraindications to MRI. Iodine allergy is a concern for CT contrast, and caffeine is held before EEG.'),
  ('imaging', 14, 'A client is waiting outside the MRI room. Which client statement requires immediate follow-up by the nurse?', '[{"id": "a", "text": "\"I washed my hair and left it dry last night.\""}, {"id": "b", "text": "\"I had metal clips placed on a brain aneurysm.\""}, {"id": "c", "text": "\"I had a CT scan of my head two years ago.\""}, {"id": "d", "text": "\"I ate a normal breakfast this morning.\""}]'::jsonb, '["b"]', 'All patients must be screened before entering the MRI room because the magnetic field can be lethal with ferromagnetic devices such as surgical clips. Hair care and eating are not MRI concerns listed.'),
  ('imaging', 15, 'A client scheduled for a brain MRI asks how long the test will take. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"About 2 to 5 minutes.\""}, {"id": "b", "text": "\"About 3 to 4 hours.\""}, {"id": "c", "text": "\"Less than 1 minute.\""}, {"id": "d", "text": "\"About 30 to 60 minutes.\""}]'::jsonb, '["d"]', 'An MRI takes 30–60 minutes, which is why it is not used for acute emergencies. Results in minutes describe CT.'),
  ('imaging', 16, 'A client scheduled for an MRI says, "I''m worried about all the radiation from this scan." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"MRI uses a low dose of X-rays to make images.\""}, {"id": "b", "text": "\"MRI uses iodine dye that blocks the radiation.\""}, {"id": "c", "text": "\"MRI uses scalp electrodes rather than X-rays.\""}, {"id": "d", "text": "\"MRI uses magnets and radio waves, not radiation.\""}]'::jsonb, '["d"]', 'MRI uses strong magnets and radio waves with no radiation. X-rays are used by CT, and scalp electrodes are used by EEG.'),
  ('imaging', 17, 'A nursing student asks why a client with acute stroke symptoms is going to CT rather than MRI, which gives more detail. Which response by the nurse is correct?', '[{"id": "a", "text": "\"MRI cannot show soft tissue as well as CT can.\""}, {"id": "b", "text": "\"MRI exposes the client to more radiation than CT.\""}, {"id": "c", "text": "\"MRI requires a lumbar puncture to be done first.\""}, {"id": "d", "text": "\"MRI takes longer and is not used for emergencies.\""}]'::jsonb, '["d"]', 'MRI gives the best detail but is not for emergencies; CT is first in stroke to rule out hemorrhage. MRI is best for soft tissue detail and uses no radiation.'),
  ('imaging', 18, 'A stable client is suspected of having a lesion in the brain stem. Which diagnostic test is best suited to evaluate this area?', '[{"id": "a", "text": "Electroencephalogram"}, {"id": "b", "text": "MRI"}, {"id": "c", "text": "Lumbar puncture"}, {"id": "d", "text": "CT without contrast"}]'::jsonb, '["b"]', 'MRI is best for brain stem and spinal cord lesions because of its soft tissue detail. EEG measures electrical activity, and lumbar puncture collects CSF.'),
  ('imaging', 19, 'A stable client is suspected of having a mass in the posterior fossa. Which test should the nurse expect the provider to order for the best image of this area?', '[{"id": "a", "text": "Electroencephalogram"}, {"id": "b", "text": "Lumbar puncture"}, {"id": "c", "text": "Plain CT"}, {"id": "d", "text": "MRI"}]'::jsonb, '["d"]', 'MRI is best for posterior fossa pathology and gives more detail than CT. EEG and lumbar puncture do not provide images.'),
  ('imaging', 20, 'A nursing student makes several statements about MRI. Which statement is correct?', '[{"id": "a", "text": "\"It is the first test for acute head trauma.\""}, {"id": "b", "text": "\"It is the fastest of the brain imaging tests.\""}, {"id": "c", "text": "\"It provides more detail than a CT scan.\""}, {"id": "d", "text": "\"It uses X-rays to create brain images.\""}]'::jsonb, '["c"]', 'MRI gives more detail than CT but is not emergent and takes 30–60 minutes. CT is first in emergencies, is fast, and uses X-rays.'),
  ('imaging', 21, 'A client scheduled for an electroencephalogram (EEG) asks what the test measures. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It measures blood flow through brain vessels.\""}, {"id": "b", "text": "\"It measures the pressure of your spinal fluid.\""}, {"id": "c", "text": "\"It measures your brain''s electrical activity.\""}, {"id": "d", "text": "\"It measures the structure of brain soft tissue.\""}]'::jsonb, '["c"]', 'An EEG measures the electrical activity of the brain (brain waves). Soft tissue structure is best seen with MRI.'),
  ('imaging', 22, 'A client scheduled for an EEG asks, "Will they have to put a needle in me?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"No, electrodes are placed on your scalp.\""}, {"id": "b", "text": "\"Yes, a needle goes into your lower back.\""}, {"id": "c", "text": "\"Yes, dye is injected into a vein first.\""}, {"id": "d", "text": "\"No, you will lie inside a strong magnet.\""}]'::jsonb, '["a"]', 'EEG is non-invasive, with electrodes placed on the scalp. A needle in the lower back describes lumbar puncture, and a strong magnet describes MRI.'),
  ('imaging', 23, 'The nurse is teaching a client how to prepare hair for an EEG. Which instruction is correct?', '[{"id": "a", "text": "Apply conditioner so the hair is soft and moist"}, {"id": "b", "text": "Apply hair gel so the electrodes stay in place"}, {"id": "c", "text": "Leave hair oil in overnight before the test"}, {"id": "d", "text": "Wash hair so it is clean, dry, and product-free"}]'::jsonb, '["d"]', 'For an EEG, hair must be clean, dry, and free of oils and products. Gel, conditioner, and oil leave products on the hair.'),
  ('imaging', 24, 'The nurse is evaluating a client''s understanding of EEG preparation. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll wash my hair and leave it dry.\""}, {"id": "b", "text": "\"I won''t eat anything after midnight.\""}, {"id": "c", "text": "\"I''ll skip my coffee that morning.\""}, {"id": "d", "text": "\"I can eat breakfast before the test.\""}]'::jsonb, '["b"]', 'Clients should not fast before an EEG because hypoglycemia alters brain waves. Washing hair and avoiding caffeine are correct preparation.'),
  ('imaging', 25, 'A client asks why it is important to eat before an EEG. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"Food helps the contrast dye reach your brain.\""}, {"id": "b", "text": "\"Low blood sugar can change your brain waves.\""}, {"id": "c", "text": "\"Fasting can damage your kidneys during the test.\""}, {"id": "d", "text": "\"Food keeps the scalp electrodes from slipping.\""}]'::jsonb, '["b"]', 'The client should not fast because hypoglycemia alters brain waves. EEG does not use contrast dye; kidney concerns relate to CT contrast.'),
  ('imaging', 26, 'A client is scheduled for an EEG tomorrow morning. Which instruction should the nurse give about beverages?', '[{"id": "a", "text": "\"Drink extra coffee so you stay alert.\""}, {"id": "b", "text": "\"Avoid coffee before the test as instructed.\""}, {"id": "c", "text": "\"Drink nothing at all after midnight.\""}, {"id": "d", "text": "\"Have a soda to keep your energy up.\""}]'::jsonb, '["b"]', 'Stimulants such as caffeine are held before an EEG as ordered. The client should not fast before an EEG.'),
  ('imaging', 27, 'A client who takes a nightly sedative is scheduled for an EEG. Which instruction about this medication should the nurse anticipate?', '[{"id": "a", "text": "Take a double dose to stay still during the test"}, {"id": "b", "text": "Take it with coffee the morning of the test"}, {"id": "c", "text": "Hold the sedative before the test as ordered"}, {"id": "d", "text": "Take it in place of eating breakfast that day"}]'::jsonb, '["c"]', 'Sedatives and stimulants are held before an EEG as ordered. Coffee is a stimulant to avoid, and the client should eat rather than fast.'),
  ('imaging', 28, 'A client with a seizure disorder asks why the provider said to hold the antiseizure medication before an EEG. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It prevents a reaction with the contrast dye.\""}, {"id": "b", "text": "\"It helps the test capture seizure activity.\""}, {"id": "c", "text": "\"It keeps the electrodes from overheating.\""}, {"id": "d", "text": "\"It keeps your blood sugar from dropping.\""}]'::jsonb, '["b"]', 'Seizure medications may be held if ordered so the EEG can capture seizure activity. EEG does not use contrast dye.'),
  ('imaging', 29, 'A comatose client on a ventilator is being evaluated for possible brain death. Which diagnostic test should the nurse anticipate for this purpose?', '[{"id": "a", "text": "Magnetic resonance imaging"}, {"id": "b", "text": "Electroencephalogram"}, {"id": "c", "text": "Lumbar puncture"}, {"id": "d", "text": "Contrast-enhanced CT scan"}]'::jsonb, '["b"]', 'EEG is used for brain death determination. Lumbar puncture is used for meningitis, MS, and SAH.'),
  ('imaging', 30, 'A client reports frequent nighttime awakenings, and the provider wants to monitor the client''s sleep stages. Which test should the nurse anticipate?', '[{"id": "a", "text": "Lumbar puncture"}, {"id": "b", "text": "Magnetic resonance imaging"}, {"id": "c", "text": "Computed tomography scan"}, {"id": "d", "text": "Electroencephalogram"}]'::jsonb, '["d"]', 'EEG is used for sleep disorders by monitoring sleep stages. CT and MRI provide structural images rather than brain wave monitoring.'),
  ('imaging', 31, 'A client had a first-time seizure, and the provider wants to diagnose and classify the seizure type. Which test should the nurse anticipate?', '[{"id": "a", "text": "Electroencephalogram"}, {"id": "b", "text": "Lumbar puncture"}, {"id": "c", "text": "Magnetic resonance imaging"}, {"id": "d", "text": "CT scan with contrast dye"}]'::jsonb, '["a"]', 'EEG is used for seizure diagnosis and classification. Lumbar puncture is used for meningitis, MS, and SAH.'),
  ('imaging', 32, 'A client scheduled for a lumbar puncture asks what the procedure is for. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It collects spinal fluid for testing.\""}, {"id": "b", "text": "\"It records the brain''s electrical activity.\""}, {"id": "c", "text": "\"It takes X-ray images of the spine.\""}, {"id": "d", "text": "\"It relieves high pressure in the skull.\""}]'::jsonb, '["a"]', 'A lumbar puncture collects cerebrospinal fluid for analysis. It is contraindicated when ICP is elevated, so it is not used to relieve skull pressure.'),
  ('imaging', 33, 'A client is suspected of having meningitis, and a CT scan shows no evidence of increased intracranial pressure. Which diagnostic procedure should the nurse prepare the client for next?', '[{"id": "a", "text": "Electroencephalogram"}, {"id": "b", "text": "MRI of the brain"}, {"id": "c", "text": "Repeat CT scan"}, {"id": "d", "text": "Lumbar puncture"}]'::jsonb, '["d"]', 'A lumbar puncture diagnoses meningitis by collecting CSF, and it may proceed once a CT confirms no increased ICP. EEG is used for seizures and brain activity.'),
  ('imaging', 34, 'A client''s cerebrospinal fluid results show increased oligoclonal bands. The nurse recognizes this finding is consistent with which condition?', '[{"id": "a", "text": "Skull fracture"}, {"id": "b", "text": "Hydrocephalus"}, {"id": "c", "text": "Multiple sclerosis"}, {"id": "d", "text": "Sleep disorder"}]'::jsonb, '["c"]', 'Increased oligoclonal bands in CSF are the MS finding, indicating CNS inflammation and demyelination. Skull fracture and hydrocephalus are detected by CT.'),
  ('imaging', 35, 'The nurse is positioning a client for a lumbar puncture. Which position is most commonly used?', '[{"id": "a", "text": "Prone with arms raised above the head"}, {"id": "b", "text": "Side-lying with knees to chest and chin down"}, {"id": "c", "text": "Supine with the head of bed at 30 degrees"}, {"id": "d", "text": "Side-lying with legs straight and neck extended"}]'::jsonb, '["b"]', 'The most common LP position is lateral side-lying fetal position with knees to chest and chin down. Knees to chest and chin down open the intervertebral space, so straight legs and an extended neck are incorrect.'),
  ('imaging', 36, 'A client cannot tolerate lying on the side for a lumbar puncture. Which alternative position should the nurse use?', '[{"id": "a", "text": "Sitting upright and leaning forward over a table"}, {"id": "b", "text": "Sitting upright and leaning back on pillows"}, {"id": "c", "text": "Lying flat on the back with legs straight"}, {"id": "d", "text": "Lying prone with the head turned to the side"}]'::jsonb, '["a"]', 'The alternative LP position is sitting upright, leaning forward over a table. Leaning back is not a described LP position; leaning forward opens the intervertebral space.'),
  ('imaging', 37, 'A client being prepared for a lumbar puncture asks why it is necessary to curl up so tightly. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It prevents a headache after the procedure.\""}, {"id": "b", "text": "\"It increases the amount of spinal fluid made.\""}, {"id": "c", "text": "\"It opens the spaces between your vertebrae.\""}, {"id": "d", "text": "\"It keeps the contrast dye from spreading.\""}]'::jsonb, '["c"]', 'The goal of LP positioning is to open the intervertebral space for needle insertion. Post-LP headache is prevented by keeping the client flat afterward.'),
  ('imaging', 38, 'A client with suspected increased intracranial pressure is scheduled for a lumbar puncture. What is the nurse''s priority before the procedure?', '[{"id": "a", "text": "Place the client in a fetal position"}, {"id": "b", "text": "Confirm that a CT scan is normal"}, {"id": "c", "text": "Encourage the client to drink fluids"}, {"id": "d", "text": "Hold the client''s morning sedative"}]'::jsonb, '["b"]', 'Lumbar puncture is contraindicated with elevated ICP, so the nurse must confirm a normal CT scan first when ICP is suspected. Positioning comes only after it is safe to proceed.'),
  ('imaging', 39, 'A nursing student asks why a lumbar puncture is contraindicated in a client with elevated intracranial pressure. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Sudden CSF release can cause brain herniation.\""}, {"id": "b", "text": "\"Spinal fluid loss can cause kidney damage.\""}, {"id": "c", "text": "\"The needle will block the flow of contrast.\""}, {"id": "d", "text": "\"Curling up will cause the heart rate to rise.\""}]'::jsonb, '["a"]', 'With elevated ICP, sudden release of CSF pressure from below can cause brain herniation, a rapidly fatal complication. Kidney damage relates to CT contrast.'),
  ('imaging', 40, 'A client has just returned to the unit after a lumbar puncture. Which position should the nurse maintain?', '[{"id": "a", "text": "Flat, prone or supine, for 1 to 4 hours"}, {"id": "b", "text": "Head of bed at 45 degrees for 4 hours"}, {"id": "c", "text": "Sitting upright in a chair right away"}, {"id": "d", "text": "Walking in the hall within 15 minutes"}]'::jsonb, '["a"]', 'After an LP, the client is kept flat (prone or supine) for 1–4 hours to prevent post-LP headache from CSF leak. Sitting up or walking right away does not follow this.'),
  ('imaging', 41, 'A client who had a lumbar puncture asks why lying flat afterward is necessary. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It helps prevent kidney damage from the dye.\""}, {"id": "b", "text": "\"It helps prevent a headache from a fluid leak.\""}, {"id": "c", "text": "\"It helps keep the scalp electrodes in place.\""}, {"id": "d", "text": "\"It helps prevent low blood sugar afterward.\""}]'::jsonb, '["b"]', 'Lying flat for 1–4 hours after LP prevents post-LP headache caused by CSF leak. Kidney damage relates to CT contrast, and electrodes relate to EEG.'),
  ('imaging', 42, 'The nurse is planning care for a client after a lumbar puncture. Which intervention regarding fluids is appropriate?', '[{"id": "a", "text": "Restrict oral fluids for the first 4 hours"}, {"id": "b", "text": "Keep the client NPO until the next morning"}, {"id": "c", "text": "Encourage the client to drink oral fluids"}, {"id": "d", "text": "Limit the client to small sips of water"}]'::jsonb, '["c"]', 'Oral fluids are encouraged after LP to replenish CSF volume. Restricting fluids would not help replace CSF.'),
  ('imaging', 43, 'Two hours after a lumbar puncture, the nurse assesses a client. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "A dry, intact dressing at the site"}, {"id": "b", "text": "New numbness and tingling in the legs"}, {"id": "c", "text": "The client resting flat in bed"}, {"id": "d", "text": "The client drinking fluids well"}]'::jsonb, '["b"]', 'After LP, the nurse monitors for headache, numbness, tingling, or bladder dysfunction. A dry site, lying flat, and drinking fluids are expected findings.'),
  ('imaging', 44, 'The nurse is assessing the puncture site of a client after a lumbar puncture. Which finding requires further action?', '[{"id": "a", "text": "A clean, dry dressing over the site"}, {"id": "b", "text": "No visible bleeding at the site"}, {"id": "c", "text": "Fluid leaking from the puncture site"}, {"id": "d", "text": "Skin around the site that is intact"}]'::jsonb, '["c"]', 'The nurse assesses the puncture site for bleeding or leakage after LP. A clean, dry, intact site without bleeding is expected.'),
  ('imaging', 45, 'The nurse observes an assistive staff member caring for a client 30 minutes after a lumbar puncture. Which action requires the nurse to intervene?', '[{"id": "a", "text": "Offering the client a glass of water"}, {"id": "b", "text": "Helping the client sit up to walk"}, {"id": "c", "text": "Keeping the client lying supine"}, {"id": "d", "text": "Reporting the client''s headache"}]'::jsonb, '["b"]', 'The client should remain flat for 1–4 hours after LP. Offering fluids, keeping the client flat, and reporting headache are appropriate.'),
  ('imaging', 46, 'A client with a head injury is having a CT scan in the emergency department. Which finding is CT able to detect?', '[{"id": "a", "text": "Abnormal brain wave patterns"}, {"id": "b", "text": "Oligoclonal bands in the CSF"}, {"id": "c", "text": "Mass effect from brain swelling"}, {"id": "d", "text": "Changes in sleep stages"}]'::jsonb, '["c"]', 'CT best detects hemorrhage, skull fractures, mass effect from tumor or swelling, and hydrocephalus. Brain waves and sleep stages are measured by EEG, and oligoclonal bands are found by LP.'),
  ('imaging', 47, 'The nurse is reviewing diagnostic orders for several neurology clients. Which pairing of test and purpose is correct?', '[{"id": "a", "text": "EEG to classify a seizure disorder"}, {"id": "b", "text": "MRI as the first test after acute trauma"}, {"id": "c", "text": "LP for a client with elevated ICP"}, {"id": "d", "text": "CT to measure the brain''s electrical waves"}]'::jsonb, '["a"]', 'EEG is used for seizures, brain activity, and brain death. MRI is not emergent, LP is contraindicated with increased ICP, and CT produces X-ray images rather than measuring brain waves.'),
  ('imaging', 48, 'The nurse is reviewing four clients scheduled for diagnostic tests. Which situation requires the nurse to contact the provider before the test proceeds?', '[{"id": "a", "text": "A client with suspected high ICP scheduled for LP"}, {"id": "b", "text": "A client who ate breakfast before an EEG"}, {"id": "c", "text": "A client with clean, dry hair before an EEG"}, {"id": "d", "text": "A client with normal kidney labs before contrast CT"}]'::jsonb, '["a"]', 'Lumbar puncture is never done when ICP is elevated. Eating before an EEG, clean dry hair, and normal kidney function before contrast are all appropriate.'),
  ('imaging', 49, 'A client scheduled for a CT scan with contrast has elevated BUN and creatinine on the morning laboratory results. What is the nurse''s best action?', '[{"id": "a", "text": "Proceed with the scan as it is scheduled"}, {"id": "b", "text": "Notify the provider before contrast is given"}, {"id": "c", "text": "Have the client fast before the scan"}, {"id": "d", "text": "Hold the client''s coffee before the scan"}]'::jsonb, '["b"]', 'Kidney function must be checked before contrast because contrast is nephrotoxic, so abnormal results should be reported first. Holding caffeine is EEG preparation.'),
  ('imaging', 50, 'A client is being evaluated for several neurologic conditions. For which condition is a lumbar puncture used as a diagnostic test?', '[{"id": "a", "text": "Fracture of the skull"}, {"id": "b", "text": "Sleep stage disorder"}, {"id": "c", "text": "Brain death"}, {"id": "d", "text": "Subarachnoid hemorrhage"}]'::jsonb, '["d"]', 'Lumbar puncture is used for meningitis, MS, and SAH. Skull fractures are detected by CT, and sleep disorders and brain death are evaluated by EEG.'),
  ('orientation', 1, 'A nurse is performing a focused neurological assessment on a newly admitted client. Which question should the nurse ask to assess the client''s orientation to place?', '[{"id": "a", "text": "''Can you tell me your name?''"}, {"id": "b", "text": "''Can you tell me where you are right now?''"}, {"id": "c", "text": "''What year is it?''"}, {"id": "d", "text": "''Do you know why you''re in the hospital?''"}]'::jsonb, '["b"]', 'Orientation to place tests whether the client knows where they are, which is assessed by asking where the client is right now. Asking the client''s name tests person, and asking the year tests time.'),
  ('orientation', 2, 'During an admission assessment, the nurse asks a client, ''Do you know why you''re in the hospital?'' Which orientation domain is the nurse assessing?', '[{"id": "a", "text": "Person"}, {"id": "b", "text": "Place"}, {"id": "c", "text": "Time"}, {"id": "d", "text": "Situation"}]'::jsonb, '["d"]', 'The situation domain tests whether the client knows why they are here, and it is the domain added for A&O × 4. Place tests whether the client knows where they are, not why they are there.'),
  ('orientation', 3, 'A client correctly states her name, the name of the hospital, and today''s date but cannot say why she was admitted. How should the nurse document the client''s orientation?', '[{"id": "a", "text": "Alert and oriented × 3"}, {"id": "b", "text": "Alert and oriented × 4"}, {"id": "c", "text": "Alert and oriented × 2"}, {"id": "d", "text": "Disoriented × 3"}]'::jsonb, '["a"]', 'A&O × 3 means the client correctly knows person, place, and time. A&O × 4 requires the client to also know the situation, which this client could not identify.'),
  ('orientation', 4, 'A client correctly identifies himself, his location, and the date, and explains that he was admitted for treatment of his current diagnosis. Which documentation entry is most accurate?', '[{"id": "a", "text": "A&O × 3; oriented to person, place, and time"}, {"id": "b", "text": "A&O × 2; oriented to person and place only"}, {"id": "c", "text": "A&O × 4; aware of diagnosis and reason for admission"}, {"id": "d", "text": "A&O × 1; oriented to person only"}]'::jsonb, '["c"]', 'A client who knows person, place, time, and situation is documented as A&O × 4, the highest level documented. A&O × 3 under-describes this client because it omits awareness of the situation.'),
  ('orientation', 5, 'A nurse is monitoring a client whose neurological status is slowly deteriorating. Which orientation domain does the nurse expect the client to lose first?', '[{"id": "a", "text": "Person"}, {"id": "b", "text": "Place"}, {"id": "c", "text": "Time"}, {"id": "d", "text": "Person and place at the same time"}]'::jsonb, '["c"]', 'Orientation is lost in a predictable order: time first, place second, and person last. Loss of person is the last and most severe change, not the first.'),
  ('orientation', 6, 'A client with a head injury who was previously oriented can no longer state his own name. How should the nurse interpret this finding?', '[{"id": "a", "text": "Severe neurological compromise requiring immediate priority action"}, {"id": "b", "text": "Early, mild disorientation requiring close monitoring only"}, {"id": "c", "text": "Moderate deterioration consistent with loss of place"}, {"id": "d", "text": "An expected finding that requires no change in care"}]'::jsonb, '["a"]', 'Person is the last domain lost, so a client who does not know their own name has severe neurological compromise requiring immediate priority action. Early, mild disorientation describes confusion about time only.'),
  ('orientation', 7, 'A client knows her name and that she is in the hospital but states the wrong year. How should the nurse interpret this finding?', '[{"id": "a", "text": "Severe neurological compromise"}, {"id": "b", "text": "Moderate deterioration with loss of place"}, {"id": "c", "text": "An obtunded level of consciousness"}, {"id": "d", "text": "Early, mild disorientation; monitor closely"}]'::jsonb, '["d"]', 'Confusion about time only is early, mild disorientation, and the client should be monitored closely. Severe compromise is indicated when the client no longer knows their own name.'),
  ('orientation', 8, 'A client is oriented to person and place but is unable to correctly identify the date or year. Which documentation entry is correct?', '[{"id": "a", "text": "Alert and oriented × 3"}, {"id": "b", "text": "Alert and oriented × 2"}, {"id": "c", "text": "Alert and oriented × 1"}, {"id": "d", "text": "Alert and oriented × 4"}]'::jsonb, '["b"]', 'A client who knows person and place but cannot identify the date or year is documented as A&O × 2. Documenting A&O × 3 would be over-documentation because the time domain was missed.'),
  ('orientation', 9, 'A client responds to his name but cannot identify where he is or what the date is. Which documentation entry is correct?', '[{"id": "a", "text": "Alert and oriented × 1"}, {"id": "b", "text": "Alert and oriented × 2"}, {"id": "c", "text": "Alert and oriented × 3"}, {"id": "d", "text": "Disoriented × 3"}]'::jsonb, '["a"]', 'Responding to name with inability to identify location or date is documented as A&O × 1. Disoriented × 3 is used when the client cannot identify self, location, or date.'),
  ('orientation', 10, 'A confused client is unable to identify himself, his location, or the date. Which documentation entry is correct?', '[{"id": "a", "text": "Alert and oriented × 1"}, {"id": "b", "text": "Alert and oriented × 2"}, {"id": "c", "text": "Disoriented × 3"}, {"id": "d", "text": "Disoriented to time only"}]'::jsonb, '["c"]', 'A confused client who cannot identify self, location, or date is documented as disoriented × 3. A&O × 1 applies only when the client still responds to their name.'),
  ('orientation', 11, 'A hospitalized client correctly states her name and today''s date but insists that she is at home. Which orientation domain is impaired?', '[{"id": "a", "text": "Person"}, {"id": "b", "text": "Place"}, {"id": "c", "text": "Time"}, {"id": "d", "text": "None; she is fully oriented"}]'::jsonb, '["b"]', 'Loss of place means the client is unsure of their location, such as thinking they are at home when in the hospital. The client correctly identified person and time, so those domains are intact.'),
  ('orientation', 12, 'Which client finding supports documenting the client''s level of consciousness as alert?', '[{"id": "a", "text": "Drowsy but opens eyes when spoken to"}, {"id": "b", "text": "Rouses only after repeated, loud stimuli"}, {"id": "c", "text": "Arousable only with a painful stimulus"}, {"id": "d", "text": "Awake and responds to a normal speaking voice"}]'::jsonb, '["d"]', 'Alert means the client is awake and responds to normal verbal stimuli. A client who is drowsy but arousable with verbal stimuli is lethargic, not alert.'),
  ('orientation', 13, 'A client is drowsy but wakes when the nurse speaks to her in a normal voice, answers some questions incorrectly, and then dozes off. Which level of consciousness should the nurse document?', '[{"id": "a", "text": "Alert"}, {"id": "b", "text": "Lethargic"}, {"id": "c", "text": "Obtunded"}, {"id": "d", "text": "Stuporous"}]'::jsonb, '["b"]', 'A lethargic client is drowsy but arousable with verbal stimuli and may be partially oriented or confused. An obtunded client requires repeated or loud stimuli to rouse.'),
  ('orientation', 14, 'The nurse must call a client''s name loudly several times before the client rouses, and the client then gives only a minimal verbal response. Which level of consciousness is this?', '[{"id": "a", "text": "Lethargic"}, {"id": "b", "text": "Stuporous"}, {"id": "c", "text": "Comatose"}, {"id": "d", "text": "Obtunded"}]'::jsonb, '["d"]', 'Obtunded describes a client who requires repeated or loud stimuli to rouse and gives a minimal verbal response. A stuporous client is arousable only with painful stimuli.'),
  ('orientation', 15, 'A client does not respond to the nurse''s voice but briefly arouses when the nurse applies a painful stimulus. Which level of consciousness should the nurse document?', '[{"id": "a", "text": "Obtunded"}, {"id": "b", "text": "Lethargic"}, {"id": "c", "text": "Stuporous"}, {"id": "d", "text": "Comatose"}]'::jsonb, '["c"]', 'Stuporous clients are arousable only with painful stimuli. A comatose client is completely unarousable with no response.'),
  ('orientation', 16, 'A client is completely unarousable and shows no response to any stimulus. What should the nurse conclude about assessing this client''s orientation?', '[{"id": "a", "text": "Orientation is not testable at this level"}, {"id": "b", "text": "Orientation can be fully tested and documented"}, {"id": "c", "text": "The client is likely partially oriented"}, {"id": "d", "text": "The client should be documented as A&O × 1"}]'::jsonb, '["a"]', 'A comatose client is completely unarousable, and orientation is not testable at this level because orientation testing requires the client to be alert. Partial orientation may be seen in a lethargic client, not a comatose one.'),
  ('orientation', 17, 'A nursing student is reviewing the level of consciousness continuum. Which sequence correctly lists the levels from least to most impaired?', '[{"id": "a", "text": "Alert, obtunded, lethargic, stuporous, comatose"}, {"id": "b", "text": "Alert, lethargic, obtunded, stuporous, comatose"}, {"id": "c", "text": "Alert, lethargic, stuporous, obtunded, comatose"}, {"id": "d", "text": "Lethargic, alert, obtunded, comatose, stuporous"}]'::jsonb, '["b"]', 'The continuum moves from alert (normal voice) to lethargic (verbal stimuli), obtunded (repeated or loud stimuli), stuporous (painful stimuli only), and comatose (completely unarousable). Obtunded follows lethargic because it requires stronger stimuli to rouse.'),
  ('orientation', 18, 'A client who was alert and oriented × 4 at the start of the shift is now confused and cannot state where he is. What is the nurse''s first action?', '[{"id": "a", "text": "Assess airway, breathing, and circulation"}, {"id": "b", "text": "Notify the provider of the change"}, {"id": "c", "text": "Place a large-print calendar in the room"}, {"id": "d", "text": "Review the medication administration record"}]'::jsonb, '["a"]', 'ABCs come first: airway, breathing, and circulation are assessed before any other action. Notifying the provider and reviewing medications are important but follow the initial assessment.'),
  ('orientation', 19, 'A client has become acutely disoriented. The nurse confirms that the airway is patent and breathing is unlabored. Which action should the nurse take next?', '[{"id": "a", "text": "Reorient the client using a large-print clock"}, {"id": "b", "text": "Notify the provider of the change"}, {"id": "c", "text": "Check the oxygen saturation and blood glucose"}, {"id": "d", "text": "Turn on the bed alarm and leave the room"}]'::jsonb, '["c"]', 'After the ABCs, the nurse checks SpO₂, glucose, and vital signs to rule out hypoxia and hypoglycemia first. Reorientation and provider notification come after these causes are assessed.'),
  ('orientation', 20, 'A nurse finds a client with new acute confusion. Which sequence of actions reflects the correct priority?', '[{"id": "a", "text": "Notify provider, assess ABCs, check SpO₂ and glucose, review medications"}, {"id": "b", "text": "Check SpO₂ and glucose, notify provider, assess ABCs, review medications"}, {"id": "c", "text": "Review medications, assess ABCs, notify provider, check SpO₂ and glucose"}, {"id": "d", "text": "Assess ABCs, check SpO₂ and glucose, review medications, notify provider"}]'::jsonb, '["d"]', 'ABCs come first, followed by checking SpO₂, glucose, and vitals, then reviewing medications and notifying the provider. Notifying the provider before assessing the ABCs delays the priority assessment.'),
  ('orientation', 21, 'An older adult client becomes newly disoriented. Which finding in the client''s history represents a medication-related cause of disorientation?', '[{"id": "a", "text": "A recently started anticholinergic medication"}, {"id": "b", "text": "A low serum sodium level"}, {"id": "c", "text": "Several nights of sleep deprivation"}, {"id": "d", "text": "A recent traumatic brain injury"}]'::jsonb, '["a"]', 'Anticholinergics are a medication cause of disorientation, especially in the elderly. Hyponatremia is a systemic/metabolic cause, sleep deprivation is environmental/situational, and TBI is neurological.'),
  ('orientation', 22, 'Ten minutes after a generalized seizure, a client is disoriented to time and place. Under which category of causes does the nurse classify this disorientation?', '[{"id": "a", "text": "Systemic/metabolic"}, {"id": "b", "text": "Neurological"}, {"id": "c", "text": "Medications and substances"}, {"id": "d", "text": "Environmental/situational"}]'::jsonb, '["b"]', 'The post-ictal state after a seizure is a neurological cause of disorientation. Systemic/metabolic causes include problems such as hypoxia, hypoglycemia, and electrolyte imbalance.'),
  ('orientation', 23, 'A client with renal failure who has missed several dialysis treatments becomes newly disoriented. Which cause of disorientation should the nurse suspect?', '[{"id": "a", "text": "ICU psychosis"}, {"id": "b", "text": "Alcohol withdrawal"}, {"id": "c", "text": "Uremia"}, {"id": "d", "text": "Postoperative confusion"}]'::jsonb, '["c"]', 'Uremia from renal failure is a systemic/metabolic cause of disorientation and fits this client''s history. Nothing in the history suggests an ICU stay, alcohol use, or recent surgery.'),
  ('orientation', 24, 'A client has been in the ICU for six days with constant alarms and little sleep. The client is now disoriented, and the workup for neurological and metabolic causes is negative. Which cause is most likely?', '[{"id": "a", "text": "Increased ICP"}, {"id": "b", "text": "Hepatic encephalopathy"}, {"id": "c", "text": "Meningitis"}, {"id": "d", "text": "ICU psychosis"}]'::jsonb, '["d"]', 'ICU psychosis/hospital delirium is an environmental/situational cause, along with sleep deprivation and sensory overload. Increased ICP and meningitis are neurological causes, which the negative workup makes less likely.'),
  ('orientation', 25, 'A nurse explains to a student why orientation is assessed on every client contact. Which statement by the student indicates understanding?', '[{"id": "a", "text": "''Orientation changes can signal deterioration, often before vital signs change.''"}, {"id": "b", "text": "''Orientation needs to be assessed only once, at the time of admission.''"}, {"id": "c", "text": "''Vital signs always change before a client''s orientation changes.''"}, {"id": "d", "text": "''Orientation is assessed only in clients with a neurological diagnosis.''"}]'::jsonb, '["a"]', 'Changes in orientation can signal neurological deterioration, hypoxia, hypoglycemia, and other problems, often before vital signs change. Orientation is assessed on every patient contact, not only on admission.'),
  ('orientation', 26, 'A nurse manager is reviewing documentation practices with new graduate nurses. Which statement by a new graduate indicates a need for further teaching?', '[{"id": "a", "text": "''If the client misses one domain, I will not chart A&O × 3.''"}, {"id": "b", "text": "''I will document exactly what I assessed for each domain.''"}, {"id": "c", "text": "''If the client misses only the date, I can still chart A&O × 3.''"}, {"id": "d", "text": "''Inaccurate orientation charting is a patient safety risk.''"}]'::jsonb, '["c"]', 'A&O × 3 must not be charted if the client missed even one domain, including time. Documenting exactly what was assessed is correct practice.'),
  ('orientation', 27, 'A charge nurse reads an entry stating ''A&O × 3'' for a client who correctly gave her name and location but stated the wrong year. What is the charge nurse''s best response to the nurse who wrote the entry?', '[{"id": "a", "text": "''This is acceptable because the year is a minor detail.''"}, {"id": "b", "text": "''This needs correction because one domain was missed.''"}, {"id": "c", "text": "''This is acceptable because the client is awake and alert.''"}, {"id": "d", "text": "''This needs correction to read disoriented × 3.''"}]'::jsonb, '["b"]', 'One wrong domain means the client is not fully oriented, so the entry must reflect exactly what was assessed. Disoriented × 3 is incorrect because the client knew person and place.'),
  ('orientation', 28, 'A client is mildly disoriented to time. Which nursing intervention is most appropriate for reorienting the client?', '[{"id": "a", "text": "Speak loudly and quickly to keep the client''s attention"}, {"id": "b", "text": "Remove family photos to reduce clutter in the room"}, {"id": "c", "text": "Avoid using the client''s name to prevent agitation"}, {"id": "d", "text": "Provide a large-print clock and calendar in the room"}]'::jsonb, '["d"]', 'Reorientation includes using the client''s name, speaking calmly, and providing a large-print clock or calendar and familiar items. Removing familiar items and avoiding the client''s name work against reorientation.'),
  ('orientation', 29, 'A nurse observes an unlicensed assistive personnel (UAP) caring for a disoriented client. Which action by the UAP requires correction?', '[{"id": "a", "text": "Placing the call light within the client''s reach"}, {"id": "b", "text": "Turning on the bed alarm before leaving the room"}, {"id": "c", "text": "Removing familiar items from the bedside table"}, {"id": "d", "text": "Calling the client by name when speaking to him"}]'::jsonb, '["c"]', 'Familiar items support reorientation and should remain with the client. Placing the call light within reach and turning on the bed alarm are fall precautions, and using the client''s name supports reorientation.'),
  ('orientation', 30, 'A newly disoriented client has been trying to get out of bed without help. Which intervention should the nurse implement?', '[{"id": "a", "text": "Turn on the bed alarm and keep the call light within reach"}, {"id": "b", "text": "Delay reorientation until the confusion has fully resolved"}, {"id": "c", "text": "Wait until morning rounds to notify the provider of the change"}, {"id": "d", "text": "Document the client as A&O × 3 because the client is awake"}]'::jsonb, '["a"]', 'Fall precautions for a client with changed orientation include keeping the call light within reach and the bed alarm on. Reorientation should begin now, and an acute decline should be reported to the provider rather than delayed.'),
  ('orientation', 31, 'After confirming that a newly confused client''s SpO₂ and blood glucose are within normal limits, the nurse notes an acute decline in orientation from baseline. Which action is appropriate?', '[{"id": "a", "text": "Recheck orientation at the end of the shift before reporting"}, {"id": "b", "text": "Notify the provider and document the change from baseline"}, {"id": "c", "text": "Chart the client''s previous orientation status from admission"}, {"id": "d", "text": "Postpone reporting until the vital signs become abnormal"}]'::jsonb, '["b"]', 'The nurse should notify the provider, document the change from baseline, and report any acute decline. Waiting for vital sign changes is inappropriate because orientation often changes before vital signs do.'),
  ('orientation', 32, 'During hourly rounds, the nurse finds that a client who was oriented × 4 an hour ago now cannot state the day. How should the nurse classify this finding?', '[{"id": "a", "text": "A priority finding that requires immediate assessment"}, {"id": "b", "text": "An expected finding in most hospitalized clients"}, {"id": "c", "text": "A routine finding to report at the end of the shift"}, {"id": "d", "text": "A finding that matters only if vital signs are abnormal"}]'::jsonb, '["a"]', 'An acute change in orientation is a priority assessment finding that requires immediate assessment. It should not wait for the end of the shift or for vital signs to change.'),
  ('orientation', 33, 'Before testing a client''s orientation, which condition must the nurse first confirm?', '[{"id": "a", "text": "The client has been fasting"}, {"id": "b", "text": "The client is sitting upright"}, {"id": "c", "text": "The client is lethargic"}, {"id": "d", "text": "The client is alert"}]'::jsonb, '["d"]', 'Orientation testing requires the client to be alert, meaning awake and responsive to normal verbal stimuli. A lethargic client may be only partially oriented and confused.'),
  ('orientation', 34, 'A nursing student asks which examination orientation is part of. What is the nurse''s best response?', '[{"id": "a", "text": "The cranial nerve examination"}, {"id": "b", "text": "The motor strength examination"}, {"id": "c", "text": "The mental status examination"}, {"id": "d", "text": "The sensory examination"}]'::jsonb, '["c"]', 'Orientation is a component of the mental status exam (MSE) used in every neurological and focused assessment. It measures whether the client knows who and where they are, the time, and why they are present.'),
  ('orientation', 35, 'A preceptor asks a new nurse to describe the role of orientation in client assessment. Which statement by the new nurse is accurate?', '[{"id": "a", "text": "''It is assessed only when the client is admitted.''"}, {"id": "b", "text": "''It is the most rapid, accessible indicator of LOC.''"}, {"id": "c", "text": "''It replaces the need to check vital signs.''"}, {"id": "d", "text": "''It can be tested in clients who are comatose.''"}]'::jsonb, '["b"]', 'Orientation is the most rapid, accessible indicator of level of consciousness and is assessed on every patient contact. It is not testable in a comatose client.'),
  ('orientation', 36, 'The nurse asks a client several questions. Which client response demonstrates orientation to time?', '[{"id": "a", "text": "''I came in because I fell and broke my hip.''"}, {"id": "b", "text": "''I am at the hospital on Main Street.''"}, {"id": "c", "text": "''Today is Tuesday, the third of the month.''"}, {"id": "d", "text": "''I can tell you my full name and birthday.''"}]'::jsonb, '["c"]', 'The time domain tests whether the client knows the date, day, or year. Stating the reason for admission reflects situation, and identifying the hospital reflects place.'),
  ('orientation', 37, 'A nurse reviews a chart entry stating that a client is ''A&O × 4.'' What does this documentation indicate?', '[{"id": "a", "text": "The client knows person, place, and time only"}, {"id": "b", "text": "The client has moderate cognitive deterioration"}, {"id": "c", "text": "The client is drowsy but arousable to voice"}, {"id": "d", "text": "The client has full situational awareness"}]'::jsonb, '["d"]', 'A&O × 4 means the client knows person, place, time, and situation, which is full situational awareness and the highest level documented. Knowing only person, place, and time is A&O × 3.'),
  ('orientation', 38, 'A nurse new to a medical-surgical unit asks which orientation documentation is considered the standard baseline. What is the preceptor''s best response?', '[{"id": "a", "text": "A&O × 3"}, {"id": "b", "text": "A&O × 1"}, {"id": "c", "text": "A&O × 2"}, {"id": "d", "text": "Disoriented × 3"}]'::jsonb, '["a"]', 'A&O × 3 (person, place, and time) is the standard baseline and the most common documentation. A&O × 1 and A&O × 2 indicate that one or more domains were missed.'),
  ('orientation', 39, 'A client with a progressing neurological illness knows his own name but can no longer identify the date or where he is. How should the nurse interpret this pattern?', '[{"id": "a", "text": "Early, mild disorientation involving time only"}, {"id": "b", "text": "Moderate deterioration with loss of time and place"}, {"id": "c", "text": "Severe compromise with loss of person"}, {"id": "d", "text": "Full orientation with situational confusion"}]'::jsonb, '["b"]', 'Time is lost first and place second, and loss of place reflects moderate deterioration. Severe compromise is signaled when person, the last domain, is lost.'),
  ('orientation', 40, 'A nurse reviews the histories of four clients with new disorientation. Which client''s disorientation has a systemic/metabolic cause?', '[{"id": "a", "text": "A client who recently had a stroke"}, {"id": "b", "text": "A client taking a benzodiazepine for sleep"}, {"id": "c", "text": "A client with prolonged sleep deprivation"}, {"id": "d", "text": "A client with hepatic encephalopathy"}]'::jsonb, '["d"]', 'Hepatic encephalopathy is a systemic/metabolic cause of disorientation. Stroke is neurological, benzodiazepines are a medication cause, and sleep deprivation is environmental/situational.'),
  ('orientation', 41, 'An older adult client who takes many different prescribed medications each day becomes newly disoriented. Oxygen saturation and blood glucose are normal, and the client has had no recent surgery or injury. Which contributing cause should the nurse identify?', '[{"id": "a", "text": "Traumatic brain injury"}, {"id": "b", "text": "Postoperative confusion"}, {"id": "c", "text": "Polypharmacy"}, {"id": "d", "text": "Hepatic encephalopathy"}]'::jsonb, '["c"]', 'Polypharmacy is a medication-related cause of disorientation and fits a client taking many medications. The client has had no injury or surgery, so TBI and postoperative confusion do not fit.'),
  ('orientation', 42, 'A client admitted two days ago reports drinking large amounts of alcohol daily before admission and is now newly disoriented. Which cause should the nurse suspect?', '[{"id": "a", "text": "Alcohol withdrawal"}, {"id": "b", "text": "Uremia"}, {"id": "c", "text": "Postoperative confusion"}, {"id": "d", "text": "Increased ICP"}]'::jsonb, '["a"]', 'Alcohol intoxication or withdrawal is a substance-related cause of disorientation and fits this client''s history. Nothing in the history suggests renal failure, surgery, or increased ICP.'),
  ('orientation', 43, 'A nurse is caring for two clients. Client 1 is drowsy but wakes when spoken to in a normal voice; Client 2 rouses only after repeated, loud stimuli. Which statement is correct?', '[{"id": "a", "text": "Client 1 is obtunded, and Client 2 is lethargic."}, {"id": "b", "text": "Client 1 is lethargic, and Client 2 is obtunded."}, {"id": "c", "text": "Client 1 is alert, and Client 2 is stuporous."}, {"id": "d", "text": "Client 1 is stuporous, and Client 2 is comatose."}]'::jsonb, '["b"]', 'A lethargic client is drowsy but arousable with verbal stimuli, while an obtunded client requires repeated or loud stimuli to rouse. A stuporous client is arousable only with painful stimuli.'),
  ('orientation', 44, 'A lethargic client opens her eyes when spoken to and answers some orientation questions incorrectly. How should the nurse interpret the incorrect answers?', '[{"id": "a", "text": "Lethargic clients cannot have orientation tested"}, {"id": "b", "text": "The client should be documented as comatose"}, {"id": "c", "text": "The client should still be charted as A&O × 4"}, {"id": "d", "text": "Lethargic clients may be partially oriented and confused"}]'::jsonb, '["d"]', 'A lethargic client may be partially oriented and confused. A comatose client is completely unarousable, which does not describe a client who opens her eyes to voice.'),
  ('orientation', 45, 'A nurse asks a client, ''Can you tell me where you are?'' The client, who is awake, answers immediately, ''I''m at home.'' Why should the nurse NOT document this client as obtunded?', '[{"id": "a", "text": "The client knew the correct date"}, {"id": "b", "text": "The client has full situational awareness"}, {"id": "c", "text": "The client responded appropriately to the question"}, {"id": "d", "text": "The client needed a painful stimulus to answer"}]'::jsonb, '["c"]', 'The client is not obtunded because they responded appropriately to the verbal question; an obtunded client needs repeated or loud stimuli to rouse. The client is alert but disoriented to place.'),
  ('orientation', 46, 'The daughter of an older client asks why the nurse keeps asking her father what day it is. Which response by the nurse is best?', '[{"id": "a", "text": "''Time is usually the first area of orientation to be lost.''"}, {"id": "b", "text": "''Asking the day checks whether he knows where he is.''"}, {"id": "c", "text": "''Knowing his own name is usually the first area lost.''"}, {"id": "d", "text": "''Asking the day is only needed for paperwork purposes.''"}]'::jsonb, '["a"]', 'Time is lost first and is the earliest cognitive sign of deterioration, so checking the day detects early change. Knowing one''s own name (person) is lost last, not first.'),
  ('orientation', 47, 'Which question should the nurse ask to assess a client''s orientation to person?', '[{"id": "a", "text": "''What day is it today?''"}, {"id": "b", "text": "''Can you tell me your name?''"}, {"id": "c", "text": "''Can you tell me where you are right now?''"}, {"id": "d", "text": "''Do you know why you''re in the hospital?''"}]'::jsonb, '["b"]', 'The person domain tests whether the client knows who they are, assessed by asking the client''s name. Asking where the client is tests place, and asking the day tests time.'),
  ('orientation', 48, 'A nurse reviews four orientation entries written by a student. Which entry is documented correctly?', '[{"id": "a", "text": "Patient oriented to person and place; unable to identify date — A&O × 3."}, {"id": "b", "text": "Patient responds to name but unable to identify location or date — A&O × 2."}, {"id": "c", "text": "Patient unable to identify self, location, or date — A&O × 1."}, {"id": "d", "text": "Patient alert and oriented to person, place, and time — A&O × 3."}]'::jsonb, '["d"]', 'Oriented to person, place, and time is correctly documented as A&O × 3. Responding to name only is A&O × 1, and inability to identify date with intact person and place is A&O × 2.'),
  ('orientation', 49, 'A hospitalized client knows his name and the correct date but states that he is at his daughter''s house. How should the nurse document this finding?', '[{"id": "a", "text": "A&O × 2; disoriented to place"}, {"id": "b", "text": "A&O × 3; fully oriented"}, {"id": "c", "text": "A&O × 2; disoriented to time"}, {"id": "d", "text": "Obtunded; unable to respond"}]'::jsonb, '["a"]', 'The client incorrectly identified his location, so he is A&O × 2, oriented to person and time but disoriented to place. Without place, the client cannot be A&O × 3.'),
  ('orientation', 50, 'A nurse is caring for a client documented as stuporous. What should the nurse expect when attempting to assess orientation?', '[{"id": "a", "text": "Orientation will be fully testable"}, {"id": "b", "text": "The client will be partially oriented"}, {"id": "c", "text": "No meaningful orientation will be possible"}, {"id": "d", "text": "The client will be oriented to person only"}]'::jsonb, '["c"]', 'A stuporous client is arousable only with painful stimuli, and no meaningful orientation is possible. Partial orientation may be seen in a lethargic client.'),
  ('parkinsons', 1, 'A client newly diagnosed with Parkinson''s disease asks what causes the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Immune cells attack the myelin around the nerves.\""}, {"id": "b", "text": "\"Dopamine-producing neurons in the brain are lost.\""}, {"id": "c", "text": "\"The brain produces too much dopamine over time.\""}, {"id": "d", "text": "\"Peripheral nerves in the arms and legs degenerate.\""}]'::jsonb, '["b"]', 'Parkinson''s disease results from the loss of dopamine-producing neurons in the substantia nigra. Excess dopamine reverses the direction; the problem is decreased dopamine.'),
  ('parkinsons', 2, 'A nursing student is describing the neurotransmitter imbalance in Parkinson''s disease. Which statement by the student is accurate?', '[{"id": "a", "text": "\"Dopamine rises while the acetylcholine effect falls.\""}, {"id": "b", "text": "\"Dopamine and acetylcholine both decrease equally.\""}, {"id": "c", "text": "\"Dopamine falls and the acetylcholine effect increases.\""}, {"id": "d", "text": "\"Acetylcholine is lost while dopamine stays normal.\""}]'::jsonb, '["c"]', 'In Parkinson''s disease, decreased dopamine leads to an increased acetylcholine effect, causing abnormal motor activity. The first option reverses both directions.'),
  ('parkinsons', 3, 'While a client with Parkinson''s disease sits quietly with hands resting in the lap, the nurse notes a rhythmic rubbing movement of the thumb against the fingers. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is a pill-rolling tremor occurring at rest."}, {"id": "b", "text": "It is cogwheel rigidity of the hand muscles."}, {"id": "c", "text": "It is a dyskinesia from early levodopa use."}, {"id": "d", "text": "It is festination affecting the upper limbs."}]'::jsonb, '["a"]', 'The tremor of Parkinson''s disease occurs at rest as a pill-rolling motion of the thumb and fingers. Cogwheel rigidity is jerky resistance to passive movement, not a spontaneous movement.'),
  ('parkinsons', 4, 'While performing passive range of motion on the elbow of a client with Parkinson''s disease, the nurse feels jerky, ratchet-like resistance. The nurse documents this finding as which sign?', '[{"id": "a", "text": "Resting tremor"}, {"id": "b", "text": "Festination"}, {"id": "c", "text": "Akinesia"}, {"id": "d", "text": "Cogwheel rigidity"}]'::jsonb, '["d"]', 'Cogwheel rigidity is jerky resistance to passive movement. Akinesia is absence or slowing of voluntary movement, and festination is a shuffling gait.'),
  ('parkinsons', 5, 'A client with Parkinson''s disease sits for a long time before managing to stand and begin walking, and the movements are very slow. The nurse recognizes this finding as which manifestation?', '[{"id": "a", "text": "Cogwheel rigidity"}, {"id": "b", "text": "Bradykinesia"}, {"id": "c", "text": "Dyskinesia"}, {"id": "d", "text": "Pill-rolling tremor"}]'::jsonb, '["b"]', 'Bradykinesia is slow movement with difficulty initiating movement. Dyskinesias are involuntary movements associated with long-term levodopa use, not slowness.'),
  ('parkinsons', 6, 'The nurse observes the gait of a client with Parkinson''s disease. Which gait pattern does the nurse expect to find?', '[{"id": "a", "text": "Wide, high-stepping gait with long strides"}, {"id": "b", "text": "Steady gait with normal arm swing"}, {"id": "c", "text": "Shuffling gait with short steps"}, {"id": "d", "text": "Scissoring gait with crossed knees"}]'::jsonb, '["c"]', 'Parkinson''s disease produces a shuffling gait with short steps (festination). A steady gait would not fit the postural instability seen in the disease.'),
  ('parkinsons', 7, 'During a physical assessment of a client with Parkinson''s disease, which posture would the nurse expect to observe?', '[{"id": "a", "text": "Stooped and flexed, with the head forward"}, {"id": "b", "text": "Rigidly upright, with the head tilted back"}, {"id": "c", "text": "Arched backward, with the arms extended"}, {"id": "d", "text": "Leaning to one side, with the head tilted"}]'::jsonb, '["a"]', 'Parkinson''s disease causes a stooped, flexed, forward-leaning posture with the head drooping forward and the chin toward the chest. An upright or backward-leaning posture is the reverse of the expected finding.'),
  ('parkinsons', 8, 'The daughter of a client with Parkinson''s disease says, "Dad always looks angry or bored now, even when he says he''s happy." Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"He is likely hiding feelings of anger from the family.\""}, {"id": "b", "text": "\"This is a side effect of his levodopa that will pass.\""}, {"id": "c", "text": "\"This shows the disease has reached its late stage.\""}, {"id": "d", "text": "\"Parkinson''s reduces facial expression and blinking.\""}]'::jsonb, '["d"]', 'Facial masking (hypomimia) produces a blank, expressionless face with reduced blinking. It is a motor sign of the disease, not a sign of hidden emotion or a levodopa effect.'),
  ('parkinsons', 9, 'The nurse notes that a client with Parkinson''s disease drools frequently and has a soft voice. The nurse recognizes that these findings place the client at highest risk for which complication?', '[{"id": "a", "text": "Orthostatic hypotension"}, {"id": "b", "text": "Aspiration"}, {"id": "c", "text": "Urinary retention"}, {"id": "d", "text": "Dyskinesia"}]'::jsonb, '["b"]', 'Excess drooling, dysphagia, and a soft voice indicate aspiration risk. Orthostatic hypotension relates to falls on standing, not to drooling.'),
  ('parkinsons', 10, 'A client with Parkinson''s disease speaks in a soft, slurred voice that family members struggle to understand. Which referral is most appropriate?', '[{"id": "a", "text": "Physical therapy"}, {"id": "b", "text": "Occupational therapy"}, {"id": "c", "text": "Speech therapy"}, {"id": "d", "text": "Respiratory therapy"}]'::jsonb, '["c"]', 'Speech therapy addresses dysarthria (soft, slurred speech). Occupational therapy addresses ADLs, and physical therapy addresses mobility and ROM.'),
  ('parkinsons', 11, 'A client with Parkinson''s disease coughs and chokes when drinking thin liquids. Which intervention should the nurse implement?', '[{"id": "a", "text": "Provide thin liquids through a straw"}, {"id": "b", "text": "Have the client lie flat while drinking"}, {"id": "c", "text": "Withhold all fluids until further notice"}, {"id": "d", "text": "Provide thickened liquids with meals"}]'::jsonb, '["d"]', 'Thickened liquids are used for dysphagia in Parkinson''s disease to reduce aspiration risk. Lying flat while drinking conflicts with elevating the HOB during eating.'),
  ('parkinsons', 12, 'The nurse is preparing to assist a client with Parkinson''s disease and dysphagia with lunch. Which action should the nurse take first?', '[{"id": "a", "text": "Elevate the head of the bed"}, {"id": "b", "text": "Cut food into large bites"}, {"id": "c", "text": "Offer thin liquids first"}, {"id": "d", "text": "Lower the head of the bed"}]'::jsonb, '["a"]', 'The HOB should be elevated during eating because dysphagia creates aspiration risk. Lowering the HOB or offering thin liquids increases that risk.'),
  ('parkinsons', 13, 'A client with advanced Parkinson''s disease has dysphagia and frequent drooling. Which equipment is most important for the nurse to keep at the bedside?', '[{"id": "a", "text": "A cane and a raised toilet seat"}, {"id": "b", "text": "A heating pad for rigid muscles"}, {"id": "c", "text": "Suction equipment"}, {"id": "d", "text": "An eye patch"}]'::jsonb, '["c"]', 'Suction at the bedside is indicated because of aspiration risk from dysphagia. A cane and raised toilet seat address falls rather than aspiration.'),
  ('parkinsons', 14, 'A client with Parkinson''s disease has difficulty chewing and swallowing and tires during meals. Which meal plan is most appropriate?', '[{"id": "a", "text": "Two large meals of firm, chewy foods"}, {"id": "b", "text": "One large meal eaten late in the evening"}, {"id": "c", "text": "Three large meals with thin liquids"}, {"id": "d", "text": "Small, frequent, easy-to-chew meals"}]'::jsonb, '["d"]', 'Small, frequent, easy-to-chew meals support nutrition and swallowing safety in Parkinson''s disease. Large meals with firm foods or thin liquids increase difficulty and aspiration risk.'),
  ('parkinsons', 15, 'The nurse is assessing a client with Parkinson''s disease for non-motor symptoms. Which finding would the nurse expect?', '[{"id": "a", "text": "Constipation"}, {"id": "b", "text": "Diarrhea"}, {"id": "c", "text": "Hypertension on standing"}, {"id": "d", "text": "Increased facial expression"}]'::jsonb, '["a"]', 'Constipation is a listed non-motor symptom of Parkinson''s disease. Blood pressure drops on standing (orthostatic hypotension) rather than rising, and facial expression is reduced.'),
  ('parkinsons', 16, 'A client with Parkinson''s disease reports feeling dizzy and lightheaded when getting out of bed in the morning. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Stand up quickly so the dizzy feeling passes.\""}, {"id": "b", "text": "\"Rise slowly, sitting at the edge of the bed first.\""}, {"id": "c", "text": "\"Stay in bed until the dizziness goes away completely.\""}, {"id": "d", "text": "\"Skip your levodopa dose on mornings when you''re dizzy.\""}]'::jsonb, '["b"]', 'Orthostatic hypotension in Parkinson''s disease and with levodopa use creates a fall risk on standing, so clients are taught to rise slowly. Standing quickly increases the risk of falling.'),
  ('parkinsons', 17, 'The nurse is prioritizing care for a client with Parkinson''s disease who has a shuffling gait and orthostatic hypotension. Which concern is the priority?', '[{"id": "a", "text": "Depression"}, {"id": "b", "text": "Constipation"}, {"id": "c", "text": "Falls"}, {"id": "d", "text": "Sleep disturbance"}]'::jsonb, '["c"]', 'Falls are the priority safety concern because of the shuffling gait plus orthostatic hypotension. Depression, constipation, and sleep disturbances are non-motor symptoms but are not the priority safety risk.'),
  ('parkinsons', 18, 'A client with Parkinson''s disease has become withdrawn, has lost interest in hobbies, and reports poor sleep. Which nursing action is most appropriate?', '[{"id": "a", "text": "Reassure the family that this is a normal part of aging"}, {"id": "b", "text": "Explain that the levodopa dose is too high"}, {"id": "c", "text": "Increase the client''s daily activity to exhaustion"}, {"id": "d", "text": "Assess the client for depression and report findings"}]'::jsonb, '["d"]', 'Depression and sleep disturbances are non-motor symptoms of Parkinson''s disease, and monitoring for depression is a nursing intervention. Dismissing the changes as normal aging misses this symptom.'),
  ('parkinsons', 19, 'The family of a client with early Parkinson''s disease asks whether memory loss and confusion are expected right away. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Dementia can develop, usually in the late stage.\""}, {"id": "b", "text": "\"Dementia is the first sign of Parkinson''s disease.\""}, {"id": "c", "text": "\"Dementia never occurs with Parkinson''s disease.\""}, {"id": "d", "text": "\"Dementia occurs only when levodopa is stopped.\""}]'::jsonb, '["a"]', 'Dementia is a non-motor symptom that occurs in late-stage Parkinson''s disease. It is not the first sign, and it is not absent from the disease.'),
  ('parkinsons', 20, 'A client with suspected Parkinson''s disease asks which test will confirm the diagnosis. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"A blood test that measures dopamine confirms it.\""}, {"id": "b", "text": "\"A brain MRI will show the disease very clearly.\""}, {"id": "c", "text": "\"It is mainly based on your symptoms and exam.\""}, {"id": "d", "text": "\"A lumbar puncture showing IgG bands confirms it.\""}]'::jsonb, '["c"]', 'Diagnosis is primarily clinical, based on the TRAP symptom triad. MRI/CT may be used to rule out other causes rather than to confirm Parkinson''s disease.'),
  ('parkinsons', 21, 'A client with suspected Parkinson''s disease is started on levodopa/carbidopa. Which finding would most help support the diagnosis?', '[{"id": "a", "text": "New involuntary movements in the first week"}, {"id": "b", "text": "No change in tremor or rigidity"}, {"id": "c", "text": "A drop in blood pressure on standing"}, {"id": "d", "text": "Improvement in symptoms on levodopa"}]'::jsonb, '["d"]', 'A positive response to levodopa therapy helps confirm the diagnosis. Orthostatic hypotension is a medication concern to monitor, not a confirming response.'),
  ('parkinsons', 22, 'A client being evaluated for Parkinson''s disease is scheduled for an MRI. The client asks why it is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It shows white matter plaques that confirm Parkinson''s.\""}, {"id": "b", "text": "\"It can help rule out other causes of your symptoms.\""}, {"id": "c", "text": "\"It measures how much dopamine your brain produces.\""}, {"id": "d", "text": "\"It is the main test used to diagnose Parkinson''s.\""}]'::jsonb, '["b"]', 'MRI/CT may rule out other causes, while diagnosis is primarily clinical. MRI is not the main diagnostic test for Parkinson''s disease.'),
  ('parkinsons', 23, 'A client asks why carbidopa is combined with levodopa in Sinemet. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Carbidopa converts directly into dopamine in the brain.\""}, {"id": "b", "text": "\"Carbidopa blocks acetylcholine to lessen your tremors.\""}, {"id": "c", "text": "\"Carbidopa stops levodopa breakdown so more reaches the brain.\""}, {"id": "d", "text": "\"Carbidopa mimics dopamine in the brain on its own.\""}]'::jsonb, '["c"]', 'Carbidopa prevents breakdown of levodopa in the bloodstream, letting more reach the brain. Levodopa, not carbidopa, is the component that converts to dopamine in the brain.'),
  ('parkinsons', 24, 'The nurse is teaching a client how to take levodopa/carbidopa. Which instruction about timing is correct?', '[{"id": "a", "text": "\"Take it with a large meal to protect your stomach.\""}, {"id": "b", "text": "\"Take it right after a high-protein snack each day.\""}, {"id": "c", "text": "\"Take it at bedtime with a full glass of milk.\""}, {"id": "d", "text": "\"Take it before meals or on an empty stomach.\""}]'::jsonb, '["d"]', 'Levodopa/carbidopa should be taken before meals or on an empty stomach because food reduces absorption. Taking it with a high-protein snack should be avoided.'),
  ('parkinsons', 25, 'The nurse has taught a client about levodopa/carbidopa. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll take my dose with my big steak dinner.\""}, {"id": "b", "text": "\"I''ll take my dose before I eat my breakfast.\""}, {"id": "c", "text": "\"I''ll sit up slowly before I get out of bed.\""}, {"id": "d", "text": "\"I''ll report any new involuntary movements.\""}]'::jsonb, '["a"]', 'Clients should avoid high-protein meals and take the drug on an empty stomach, so taking it with a steak dinner needs correction. Rising slowly and reporting dyskinesias are correct.'),
  ('parkinsons', 26, 'A client taking levodopa/carbidopa asks why the nurse brings the medication before breakfast instead of with the meal. Which response is accurate?', '[{"id": "a", "text": "\"Food makes the drug act too strongly.\""}, {"id": "b", "text": "\"Food reduces how well the drug is absorbed.\""}, {"id": "c", "text": "\"Food causes the drug to raise your blood pressure.\""}, {"id": "d", "text": "\"Food turns the drug into acetylcholine.\""}]'::jsonb, '["b"]', 'Levodopa/carbidopa is taken on an empty stomach because food reduces absorption. Food does not intensify the drug''s action; it lessens absorption.'),
  ('parkinsons', 27, 'A client who has taken levodopa/carbidopa for many years develops involuntary writhing movements of the arms and face. Which action should the nurse take?', '[{"id": "a", "text": "Document the movements as an expected resting tremor"}, {"id": "b", "text": "Encourage the client to double the next dose"}, {"id": "c", "text": "Report the involuntary movements to the provider"}, {"id": "d", "text": "Teach the client to take the drug with protein"}]'::jsonb, '["c"]', 'Dyskinesias are involuntary movements with long-term levodopa use and should be reported to the provider. The resting tremor of Parkinson''s is a pill-rolling motion, not drug-related involuntary movements.'),
  ('parkinsons', 28, 'A client on long-term levodopa/carbidopa therapy says, "Some hours I move fairly well, then suddenly I can hardly move at all." The nurse recognizes this description as which effect?', '[{"id": "a", "text": "Cogwheel rigidity"}, {"id": "b", "text": "Festination"}, {"id": "c", "text": "Hypomimia"}, {"id": "d", "text": "On-off effect"}]'::jsonb, '["d"]', 'The on-off effect is periods of adequate control alternating with loss of control during long-term levodopa use. Festination is a shuffling gait, and hypomimia is facial masking.'),
  ('parkinsons', 29, 'A nursing student asks what the on-off effect refers to in a client with Parkinson''s disease. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It is fluctuation in levodopa''s effectiveness with long-term use.\""}, {"id": "b", "text": "\"It is a tremor that appears only when the hands are at rest.\""}, {"id": "c", "text": "\"It is a drop in blood pressure when the client stands up.\""}, {"id": "d", "text": "\"It is the stiffness felt when moving the client''s joints.\""}]'::jsonb, '["a"]', 'The on-off effect is fluctuation in drug effectiveness with long-term levodopa use. A drop in blood pressure on standing is orthostatic hypotension, a separate concern.'),
  ('parkinsons', 30, 'A client with Parkinson''s disease is prescribed ropinirole. The client asks how the drug works. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It blocks acetylcholine to reduce tremors.\""}, {"id": "b", "text": "\"It mimics the action of dopamine in the brain.\""}, {"id": "c", "text": "\"It prevents levodopa from breaking down in the blood.\""}, {"id": "d", "text": "\"It converts into dopamine once it reaches the brain.\""}]'::jsonb, '["b"]', 'Ropinirole is a dopamine agonist that mimics dopamine in the brain. Levodopa is the drug that converts to dopamine, and blocking acetylcholine describes the anticholinergic benztropine.'),
  ('parkinsons', 31, 'A client with Parkinson''s disease is prescribed pramipexole and asks whether it must always be taken together with levodopa. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It works only when combined with levodopa.\""}, {"id": "b", "text": "\"It must never be taken along with levodopa.\""}, {"id": "c", "text": "\"It can be used alone or along with levodopa.\""}, {"id": "d", "text": "\"It replaces levodopa as the cornerstone drug.\""}]'::jsonb, '["c"]', 'Dopamine agonists such as pramipexole are used alone or with levodopa. Levodopa/carbidopa remains the cornerstone therapy.'),
  ('parkinsons', 32, 'A client with Parkinson''s disease is started on selegiline. The nurse explains that this medication improves symptoms by which action?', '[{"id": "a", "text": "Mimicking dopamine at brain receptors"}, {"id": "b", "text": "Blocking the effects of acetylcholine"}, {"id": "c", "text": "Converting directly into dopamine"}, {"id": "d", "text": "Slowing the breakdown of dopamine"}]'::jsonb, '["d"]', 'Selegiline and rasagiline are MAO-B inhibitors that slow dopamine breakdown. Mimicking dopamine describes dopamine agonists such as ropinirole.'),
  ('parkinsons', 33, 'A client taking levodopa/carbidopa is prescribed entacapone. Which outcome does the nurse expect from adding this medication?', '[{"id": "a", "text": "A longer and stronger levodopa effect"}, {"id": "b", "text": "Elimination of the need for levodopa"}, {"id": "c", "text": "Reversal of the loss of dopamine neurons"}, {"id": "d", "text": "Prevention of all orthostatic hypotension"}]'::jsonb, '["a"]', 'Entacapone, a COMT inhibitor, boosts the effect of levodopa and extends its duration. It works with levodopa rather than replacing it.'),
  ('parkinsons', 34, 'A client on levodopa/carbidopa notices that each dose seems to wear off too soon. Which medication does the nurse anticipate the provider may add to extend the duration of levodopa?', '[{"id": "a", "text": "Benztropine"}, {"id": "b", "text": "Entacapone"}, {"id": "c", "text": "Ropinirole"}, {"id": "d", "text": "Bethanechol"}]'::jsonb, '["b"]', 'Entacapone is a COMT inhibitor that boosts and extends the duration of levodopa. Benztropine is an anticholinergic that reduces tremors and rigidity but does not extend levodopa.'),
  ('parkinsons', 35, 'A client with Parkinson''s disease is prescribed benztropine. Which outcome indicates the medication is effective?', '[{"id": "a", "text": "Improved swallowing of thin liquids"}, {"id": "b", "text": "Higher blood pressure when standing"}, {"id": "c", "text": "Reduced tremors and muscle rigidity"}, {"id": "d", "text": "Fewer episodes of constipation"}]'::jsonb, '["c"]', 'Benztropine, an anticholinergic, reduces tremors and rigidity. Constipation is listed as an adverse effect of benztropine, not a symptom it improves.'),
  ('parkinsons', 36, 'An 82-year-old client with Parkinson''s disease was started on benztropine 3 days ago. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Slightly reduced hand tremor"}, {"id": "b", "text": "Less stiffness during range of motion"}, {"id": "c", "text": "Continued soft, quiet speech"}, {"id": "d", "text": "New confusion and disorientation"}]'::jsonb, '["d"]', 'Benztropine should be avoided in the elderly because of confusion, urinary retention, and constipation, so new confusion should be reported. Reduced tremor and stiffness are expected therapeutic effects.'),
  ('parkinsons', 37, 'An older adult with Parkinson''s disease is taking benztropine. Which assessment finding is most important for the nurse to monitor as an adverse effect?', '[{"id": "a", "text": "Urinary retention"}, {"id": "b", "text": "Excess tearing"}, {"id": "c", "text": "Frequent diarrhea"}, {"id": "d", "text": "Increased facial expression"}]'::jsonb, '["a"]', 'Benztropine''s cautions in the elderly include confusion, urinary retention, and constipation. Diarrhea is the reverse of the listed constipation effect.'),
  ('parkinsons', 38, 'A client with Parkinson''s disease has postural instability and a shuffling gait. Which item should the nurse recommend to promote safe ambulation?', '[{"id": "a", "text": "Soft slippers without backs"}, {"id": "b", "text": "A walker or a cane"}, {"id": "c", "text": "A wheeled office chair"}, {"id": "d", "text": "Thick throw rugs"}]'::jsonb, '["b"]', 'Assistive devices such as a cane or walker are fall-prevention measures for Parkinson''s disease. Throw rugs are trip hazards that should be removed.'),
  ('parkinsons', 39, 'A home health nurse is evaluating the bathroom of a client with Parkinson''s disease. Which modification should the nurse recommend?', '[{"id": "a", "text": "A low toilet seat and a bath rug"}, {"id": "b", "text": "A rug in front of the sink"}, {"id": "c", "text": "Raised toilet seat and grab bars"}, {"id": "d", "text": "Removal of the existing grab bars"}]'::jsonb, '["c"]', 'Raised toilet seats and grab bars are listed fall-prevention measures. Rugs are trip hazards that should be removed.'),
  ('parkinsons', 40, 'A home health nurse is visiting a client with Parkinson''s disease. Which finding in the home requires the nurse''s intervention?', '[{"id": "a", "text": "Grab bars installed next to the toilet"}, {"id": "b", "text": "A walker placed beside the client''s chair"}, {"id": "c", "text": "A raised toilet seat in the bathroom"}, {"id": "d", "text": "Loose area rugs in the client''s hallway"}]'::jsonb, '["d"]', 'Rugs and trip hazards should be removed to prevent falls. Grab bars, a walker, and a raised toilet seat are appropriate safety measures.'),
  ('parkinsons', 41, 'A nursing assistant is helping a client with Parkinson''s disease get dressed and becomes frustrated by how slowly the client moves. Which instruction by the nurse is most appropriate?', '[{"id": "a", "text": "\"Allow extra time and let the client do what they can.\""}, {"id": "b", "text": "\"Hurry the client so morning care stays on schedule.\""}, {"id": "c", "text": "\"Dress the client quickly to prevent fatigue.\""}, {"id": "d", "text": "\"Skip dressing until the client can move faster.\""}]'::jsonb, '["a"]', 'Nursing interventions for Parkinson''s disease include allowing extra time for ADLs because of bradykinesia. Rushing the client increases fall risk and does not support independence.'),
  ('parkinsons', 42, 'A client with Parkinson''s disease has increasing difficulty buttoning clothes and using utensils. Which referral is most appropriate?', '[{"id": "a", "text": "Speech therapy"}, {"id": "b", "text": "Respiratory therapy"}, {"id": "c", "text": "Occupational therapy"}, {"id": "d", "text": "Dietary counseling"}]'::jsonb, '["c"]', 'Occupational therapy addresses ADLs such as dressing and eating. Speech therapy addresses dysarthria.'),
  ('parkinsons', 43, 'A client with Parkinson''s disease has progressive rigidity and reduced mobility. Which intervention should the nurse include in the plan of care?', '[{"id": "a", "text": "\"It is a short-term illness that usually resolves.\""}, {"id": "b", "text": "\"It is a chronic, progressive movement disorder.\""}, {"id": "c", "text": "\"It mainly affects sensation rather than movement.\""}, {"id": "d", "text": "\"It stays stable once your medication is started.\""}]'::jsonb, '["d"]', 'Physical therapy and ROM exercises are listed rehab interventions for Parkinson''s disease. Bed rest and avoiding movement do not appear among the interventions and work against mobility.'),
  ('parkinsons', 44, 'A client newly diagnosed with Parkinson''s disease asks what to expect over time. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is a short illness that usually resolves.\""}, {"id": "b", "text": "\"It is a chronic, progressive movement disorder.\""}, {"id": "c", "text": "\"It mainly affects sensation, not movement.\""}, {"id": "d", "text": "\"It stays stable once medication is started.\""}]'::jsonb, '["b"]', 'Parkinson''s disease is a chronic, progressive neurodegenerative disorder affecting movement. It does not resolve, and long-term levodopa use can bring on-off effects and dyskinesias.'),
  ('parkinsons', 45, 'The spouse of a client with Parkinson''s disease asks why the client falls so often. Which explanation by the nurse is most accurate?', '[{"id": "a", "text": "\"Falls occur from rigidity, instability, and low blood pressure on standing.\""}, {"id": "b", "text": "\"Falls occur because levodopa raises blood pressure too much on standing.\""}, {"id": "c", "text": "\"Falls occur mainly because of excess facial movement and blinking.\""}, {"id": "d", "text": "\"Falls occur because the disease causes loss of feeling in the feet.\""}]'::jsonb, '["a"]', 'Falls are common due to rigidity, postural instability, and orthostatic hypotension. Levodopa is associated with orthostatic hypotension, not a rise in blood pressure.'),
  ('parkinsons', 46, 'A nursing student is reviewing the classic TRAP signs of Parkinson''s disease. Which set correctly lists these signs?', '[{"id": "a", "text": "Tremor, reflex loss, ataxia, and paralysis"}, {"id": "b", "text": "Tremor, rigidity, akinesia, postural instability"}, {"id": "c", "text": "Tingling, rigidity, aphasia, and paresthesia"}, {"id": "d", "text": "Twitching, rash, akinesia, and muscle pain"}]'::jsonb, '["b"]', 'TRAP stands for tremor at rest, cogwheel rigidity, akinesia, and postural instability. The other sets substitute findings that are not part of the triad.'),
  ('parkinsons', 47, 'The nurse is documenting akinesia in a client with Parkinson''s disease. Which description best matches this finding?', '[{"id": "a", "text": "Jerky resistance when a joint is moved passively"}, {"id": "b", "text": "Rhythmic rubbing of the thumb and fingers at rest"}, {"id": "c", "text": "Absence or slowing of voluntary movement"}, {"id": "d", "text": "Involuntary writhing movements of the face"}]'::jsonb, '["c"]', 'Akinesia is absence or slowing of voluntary movement (bradykinesia). Jerky resistance to passive movement is cogwheel rigidity, and rhythmic thumb-finger rubbing is the resting tremor.'),
  ('parkinsons', 48, 'A client with Parkinson''s disease is receiving levodopa/carbidopa. Which assessment should the nurse perform to monitor for a common adverse effect of this medication?', '[{"id": "a", "text": "Blood pressure lying and then standing"}, {"id": "b", "text": "Daily weight before breakfast"}, {"id": "c", "text": "Pupil size and reaction to light"}, {"id": "d", "text": "Hearing acuity in both ears"}]'::jsonb, '["a"]', 'Clients taking levodopa/carbidopa should be monitored for orthostatic hypotension, a drop in blood pressure on standing. The other assessments do not address the listed adverse effects.'),
  ('parkinsons', 49, 'The nurse is reviewing the medication list of a client with Parkinson''s disease and notes rasagiline. The nurse identifies this drug as belonging to which class?', '[{"id": "a", "text": "Dopamine agonist"}, {"id": "b", "text": "COMT inhibitor"}, {"id": "c", "text": "Anticholinergic"}, {"id": "d", "text": "MAO-B inhibitor"}]'::jsonb, '["d"]', 'Rasagiline, like selegiline, is an MAO-B inhibitor that slows dopamine breakdown. Dopamine agonists are ropinirole and pramipexole, and the COMT inhibitor is entacapone.'),
  ('parkinsons', 50, 'A client newly diagnosed with Parkinson''s disease asks which medication is the main treatment for the condition. Which medication should the nurse identify?', '[{"id": "a", "text": "Benztropine"}, {"id": "b", "text": "Entacapone"}, {"id": "c", "text": "Selegiline"}, {"id": "d", "text": "Levodopa/carbidopa"}]'::jsonb, '["d"]', 'Levodopa/carbidopa (Sinemet) is the cornerstone therapy for Parkinson''s disease. Entacapone boosts and extends levodopa rather than serving as the main treatment.'),
  ('seizures', 1, 'A nursing student asks what causes a seizure. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Too much GABA activity that overstimulates the neurons"}, {"id": "b", "text": "Overactive glutamate or too little GABA, causing uncontrolled firing"}, {"id": "c", "text": "Too little glutamate activity that blocks neuronal firing"}, {"id": "d", "text": "Equal increases in glutamate and GABA that cancel each other out"}]'::jsonb, '["b"]', 'Seizures result from a disruption between excitatory glutamate and inhibitory GABA: glutamate overactivation causes uncontrolled firing, and insufficient GABA means firing can''t be stopped. GABA calms brain activity rather than stimulating it.'),
  ('seizures', 2, 'A client suddenly loses consciousness. The nurse observes that the client''s body is stiff, the client is not breathing, and the lips are cyanotic. Which seizure phase is the nurse observing?', '[{"id": "a", "text": "Clonic phase"}, {"id": "b", "text": "Postictal phase"}, {"id": "c", "text": "Prodromal phase"}, {"id": "d", "text": "Tonic phase"}]'::jsonb, '["d"]', 'The tonic phase of a tonic-clonic seizure involves body stiffening, apnea, cyanosis, and tongue biting. The clonic phase involves jerking movements.'),
  ('seizures', 3, 'During a generalized seizure, a client''s stiffened body begins to jerk rhythmically, and the client is incontinent of urine. Which phase is occurring?', '[{"id": "a", "text": "Clonic phase"}, {"id": "b", "text": "Tonic phase"}, {"id": "c", "text": "Postictal phase"}, {"id": "d", "text": "Aura phase"}]'::jsonb, '["a"]', 'The clonic phase involves jerking movements and possible incontinence. The tonic phase is the stiffening phase that comes before the jerking.'),
  ('seizures', 4, 'An hour after a tonic-clonic seizure, a client is confused, tired, and reports sore muscles. How should the nurse interpret these findings?', '[{"id": "a", "text": "Signs of an approaching absence seizure"}, {"id": "b", "text": "An aura warning of another seizure"}, {"id": "c", "text": "Expected findings of the postictal phase"}, {"id": "d", "text": "Findings of the prodromal phase"}]'::jsonb, '["c"]', 'Confusion, fatigue, and soreness are expected in the postictal phase after a tonic-clonic seizure. The prodromal phase occurs days before a seizure, not after it.'),
  ('seizures', 5, 'A nurse is caring for four clients with seizure disorders. Which client''s seizure type carries a high risk for status epilepticus?', '[{"id": "a", "text": "A child with absence seizures"}, {"id": "b", "text": "A client with atonic seizures"}, {"id": "c", "text": "A client with tonic-clonic seizures"}, {"id": "d", "text": "A client with focal onset aware seizures"}]'::jsonb, '["c"]', 'Tonic-clonic (grand mal) seizures are the most severe type and carry a high risk for status epilepticus. Absence seizures are very brief with immediate recovery.'),
  ('seizures', 6, 'A parent reports that a 7-year-old has several episodes a day of sudden staring that last only seconds, after which the child resumes activity normally. Which seizure type does the nurse suspect?', '[{"id": "a", "text": "Absence"}, {"id": "b", "text": "Atonic"}, {"id": "c", "text": "Focal impaired awareness"}, {"id": "d", "text": "Tonic-clonic"}]'::jsonb, '["a"]', 'Absence seizures are common in children and cause sudden, very brief staring episodes with immediate recovery. Focal impaired awareness seizures involve automatisms such as lip-smacking, which this child does not show.'),
  ('seizures', 7, 'A nurse observes a child having an absence seizure. Which finding does the nurse expect immediately after the episode?', '[{"id": "a", "text": "Prolonged confusion and drowsiness"}, {"id": "b", "text": "Muscle soreness and headache"}, {"id": "c", "text": "Amnesia and deep sleep"}, {"id": "d", "text": "Immediate return to normal awareness"}]'::jsonb, '["d"]', 'Absence seizures have immediate postictal recovery with no confusion afterward. Confusion, fatigue, and soreness follow a tonic-clonic seizure.'),
  ('seizures', 8, 'The nurse teaches the parents of a child newly diagnosed with absence seizures. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "''The episodes may be so brief that her teacher does not notice them.''"}, {"id": "b", "text": "''My child will feel an aura that warns her before each episode.''"}, {"id": "c", "text": "''My child may look like she is just blanking out for a moment.''"}, {"id": "d", "text": "''Absence seizures are a common type of seizure in children.''"}]'::jsonb, '["b"]', 'Absence seizures occur with no aura and no confusion afterward. They are common in children and may go unnoticed because the child appears to blank out.'),
  ('seizures', 9, 'A client has repeated episodes of sudden loss of muscle tone that cause falls, followed by immediate recovery. Which protective item should the nurse anticipate for this client?', '[{"id": "a", "text": "A protective helmet"}, {"id": "b", "text": "Wrist restraints"}, {"id": "c", "text": "A padded bite block"}, {"id": "d", "text": "A cervical collar"}]'::jsonb, '["a"]', 'Atonic seizures (drop attacks) cause sudden falls and a high injury risk, so clients often require a helmet. Restraints and objects in the mouth are not used during seizures.'),
  ('seizures', 10, 'During a seizure, a client reports seeing flashing lights and remains fully aware and able to answer the nurse''s questions. Which seizure type is this?', '[{"id": "a", "text": "Focal impaired awareness"}, {"id": "b", "text": "Absence"}, {"id": "c", "text": "Focal onset aware"}, {"id": "d", "text": "Atonic"}]'::jsonb, '["c"]', 'In a focal onset aware (simple partial) seizure, the client remains aware, and symptoms vary by location, such as visual changes. In a focal impaired awareness seizure, the client is unaware.'),
  ('seizures', 11, 'A client''s focal onset aware seizures cause visual changes. The nurse recognizes that the seizures most likely originate in which lobe?', '[{"id": "a", "text": "Temporal lobe"}, {"id": "b", "text": "Occipital lobe"}, {"id": "c", "text": "Frontal lobe"}, {"id": "d", "text": "Parietal lobe"}]'::jsonb, '["b"]', 'Focal aware seizure symptoms vary by location, and occipital involvement produces visual changes. The temporal lobe is the most common site of focal impaired awareness seizures with automatisms.'),
  ('seizures', 12, 'A client with tonic-clonic seizures states, ''I always smell burning rubber and know what is happening, and then I black out and start shaking.'' How should the nurse interpret the first part of this experience?', '[{"id": "a", "text": "A postictal phase preceding the convulsion"}, {"id": "b", "text": "An absence seizure before the convulsion"}, {"id": "c", "text": "The onset of status epilepticus"}, {"id": "d", "text": "A focal aware seizure serving as an aura"}]'::jsonb, '["d"]', 'A focal onset aware seizure, in which the client stays aware, often serves as the aura before a bigger seizure. The postictal phase occurs after a seizure, not before it.'),
  ('seizures', 13, 'A client stares blankly, smacks her lips, and repeatedly picks at her gown. She does not respond to the nurse during the episode. Which seizure type is the nurse observing?', '[{"id": "a", "text": "Absence"}, {"id": "b", "text": "Focal impaired awareness (complex partial)"}, {"id": "c", "text": "Focal onset aware (simple partial)"}, {"id": "d", "text": "Atonic (drop attack)"}]'::jsonb, '["b"]', 'Focal impaired awareness seizures cause unawareness with automatisms such as lip-smacking and repetitive hand movements. In a focal onset aware seizure, the client remains aware.'),
  ('seizures', 14, 'A client is diagnosed with focal impaired awareness (complex partial) seizures. The nurse knows these seizures most commonly arise from which lobe?', '[{"id": "a", "text": "Occipital lobe"}, {"id": "b", "text": "Frontal lobe"}, {"id": "c", "text": "Parietal lobe"}, {"id": "d", "text": "Temporal lobe"}]'::jsonb, '["d"]', 'Focal impaired awareness (complex partial) seizures are most common in the temporal lobe. Occipital involvement is associated with visual changes in focal aware seizures.'),
  ('seizures', 15, 'Which finding distinguishes a focal impaired awareness seizure from a focal onset aware seizure?', '[{"id": "a", "text": "The seizure begins in one area of the brain"}, {"id": "b", "text": "Both brain hemispheres are involved"}, {"id": "c", "text": "The client is unaware during the seizure"}, {"id": "d", "text": "The client remains aware during the seizure"}]'::jsonb, '["c"]', 'In a focal impaired awareness seizure, the client is unaware during the seizure, whereas in a focal onset aware seizure the client remains aware. Both are focal seizures arising in one brain area.'),
  ('seizures', 16, 'A nursing student asks how generalized seizures differ from focal seizures. Which response by the nurse is accurate?', '[{"id": "a", "text": "''Generalized seizures involve both hemispheres; focal seizures involve one area.''"}, {"id": "b", "text": "''Generalized seizures involve one area; focal seizures involve both hemispheres.''"}, {"id": "c", "text": "''Generalized seizures occur only in children; focal seizures occur only in adults.''"}, {"id": "d", "text": "''Generalized seizures always begin with an aura; focal seizures never do.''"}]'::jsonb, '["a"]', 'Generalized seizures involve both brain hemispheres, while focal (partial) seizures involve one brain area. An aura may precede a tonic-clonic seizure, but absence seizures have no aura.'),
  ('seizures', 17, 'A nurse is teaching a client about the stages of a seizure. Which sequence is correct?', '[{"id": "a", "text": "Aura, prodromal, ictus, postictal"}, {"id": "b", "text": "Prodromal, aura, ictus, postictal"}, {"id": "c", "text": "Prodromal, ictus, aura, postictal"}, {"id": "d", "text": "Ictus, aura, prodromal, postictal"}]'::jsonb, '["b"]', 'The prodromal phase occurs days before, the aura seconds to minutes before, the ictus is the seizure itself, and the postictal phase is recovery. The aura comes after the prodromal phase because it occurs closest to the seizure.'),
  ('seizures', 18, 'A client with epilepsy reports feeling anxious, depressed, and having GI upset for a couple of days before her seizures. Which seizure stage does this describe?', '[{"id": "a", "text": "Prodromal"}, {"id": "b", "text": "Aura"}, {"id": "c", "text": "Ictus"}, {"id": "d", "text": "Postictal"}]'::jsonb, '["a"]', 'The prodromal phase occurs days before the seizure and can include depression, anxiety, and GI changes. The aura occurs only seconds to minutes before.'),
  ('seizures', 19, 'A client reports that seconds before his seizures he notices a strange smell and a feeling of déjà vu. Which seizure stage is this?', '[{"id": "a", "text": "Prodromal"}, {"id": "b", "text": "Postictal"}, {"id": "c", "text": "Aura"}, {"id": "d", "text": "Ictus"}]'::jsonb, '["c"]', 'The aura occurs seconds to minutes before the seizure and can include smells, déjà vu, and dizziness. The prodromal phase occurs days before.'),
  ('seizures', 20, 'A client begins having a seizure in the dayroom. Which nursing action is most important for determining whether the seizure becomes an emergency?', '[{"id": "a", "text": "Asking the client to state his name"}, {"id": "b", "text": "Checking the client''s pupil size"}, {"id": "c", "text": "Obtaining a blood glucose level"}, {"id": "d", "text": "Timing the seizure from its onset"}]'::jsonb, '["d"]', 'The ictus must be timed because a seizure lasting more than 5 minutes is an emergency. Asking orientation questions during the seizure does not determine whether status epilepticus is developing.'),
  ('seizures', 21, 'A nurse has timed a client''s tonic-clonic seizure at 6 minutes, and the seizure is continuing. Which action should the nurse take?', '[{"id": "a", "text": "Activate the emergency response immediately"}, {"id": "b", "text": "Wait for the seizure to stop on its own"}, {"id": "c", "text": "Insert an oral airway between the teeth"}, {"id": "d", "text": "Restrain the client''s arms and legs"}]'::jsonb, '["a"]', 'A seizure lasting more than 5 minutes is status epilepticus, an emergency requiring immediate activation of the emergency response. Nothing should be inserted in the mouth, and the client should not be restrained.'),
  ('seizures', 22, 'A client has two tonic-clonic seizures, each lasting about 3 minutes, and does not regain consciousness between them. How should the nurse interpret this?', '[{"id": "a", "text": "An expected postictal phase"}, {"id": "b", "text": "Status epilepticus"}, {"id": "c", "text": "A series of absence seizures"}, {"id": "d", "text": "A prolonged prodromal phase"}]'::jsonb, '["b"]', 'Status epilepticus includes repeated seizures without regaining consciousness, even if each seizure is shorter than 5 minutes. It is an emergency, not an expected postictal recovery.'),
  ('seizures', 23, 'A client is in status epilepticus. Which medication should the nurse anticipate administering first?', '[{"id": "a", "text": "Oral valproic acid"}, {"id": "b", "text": "Oral phenytoin"}, {"id": "c", "text": "IV lorazepam"}, {"id": "d", "text": "Oral phenobarbital"}]'::jsonb, '["c"]', 'First-line treatment for status epilepticus is a benzodiazepine such as IV lorazepam or diazepam. Valproic acid, phenytoin, and phenobarbital are not the first-line drugs for status epilepticus.'),
  ('seizures', 24, 'A client is receiving IV lorazepam for status epilepticus. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Gum tissue for overgrowth"}, {"id": "b", "text": "Platelet count"}, {"id": "c", "text": "Liver function tests"}, {"id": "d", "text": "Airway status"}]'::jsonb, '["d"]', 'In status epilepticus, the nurse monitors the airway because of the risk of hypoxia and brain damage. Gum overgrowth relates to phenytoin, and liver function and platelets relate to valproic acid.'),
  ('seizures', 25, 'A client who received diazepam is excessively sedated, and the provider orders a reversal agent. Which medication should the nurse prepare?', '[{"id": "a", "text": "Flumazenil"}, {"id": "b", "text": "Phenytoin"}, {"id": "c", "text": "Valproic acid"}, {"id": "d", "text": "Phenobarbital"}]'::jsonb, '["a"]', 'Diazepam is a benzodiazepine, and the reversal agent for benzodiazepines is flumazenil. Phenobarbital is a barbiturate that also causes sedation, so it would not reverse diazepam.'),
  ('seizures', 26, 'A nurse is preparing the room of a client admitted with a seizure disorder. Which equipment should the nurse place at the bedside?', '[{"id": "a", "text": "A padded tongue blade"}, {"id": "b", "text": "Wrist restraints"}, {"id": "c", "text": "Suction and oxygen"}, {"id": "d", "text": "An oral bite block"}]'::jsonb, '["c"]', 'Seizure precautions include suction and oxygen at the bedside. Nothing should be inserted in the mouth during a seizure, and the client should not be restrained.'),
  ('seizures', 27, 'A nurse observes an unlicensed assistive personnel (UAP) setting up seizure precautions. Which action by the UAP requires correction?', '[{"id": "a", "text": "Padding the side rails of the client''s bed"}, {"id": "b", "text": "Taping a tongue blade to the bed for seizures"}, {"id": "c", "text": "Placing the bed in its lowest position"}, {"id": "d", "text": "Removing the client''s restrictive clothing"}]'::jsonb, '["b"]', 'Nothing should be inserted in the client''s mouth during a seizure, so a tongue blade should not be kept for that purpose. Padding side rails, lowering the bed, and removing restrictive clothing are correct seizure precautions.'),
  ('seizures', 28, 'On entering the room of a client on seizure precautions, the nurse finds the bed in its highest position. Which action should the nurse take?', '[{"id": "a", "text": "Leave the bed raised for easier care"}, {"id": "b", "text": "Apply restraints to prevent a fall"}, {"id": "c", "text": "Remove the padding from the side rails"}, {"id": "d", "text": "Lower the bed to its lowest position"}]'::jsonb, '["d"]', 'Seizure precautions include keeping the bed in the lowest position and padding the side rails. Restraining the client is not done.'),
  ('seizures', 29, 'A client on seizure precautions has an IV that infiltrated, and the client has no other IV access. Why should the nurse restart the IV promptly?', '[{"id": "a", "text": "IV access is needed only after the seizure ends"}, {"id": "b", "text": "IV access is not part of seizure precautions"}, {"id": "c", "text": "IV access allows rapid IV benzodiazepines if needed"}, {"id": "d", "text": "IV access replaces the need for bedside suction"}]'::jsonb, '["c"]', 'Secured IV access is part of seizure precautions so that first-line IV benzodiazepines such as lorazepam can be given in status epilepticus. Suction and oxygen are still needed at the bedside.'),
  ('seizures', 30, 'A client wearing eyeglasses begins a tonic-clonic seizure while sitting near a bedside table holding a water pitcher. Which action should the nurse take?', '[{"id": "a", "text": "Remove the glasses and move hazardous items away"}, {"id": "b", "text": "Hold the client''s arms to stop the jerking"}, {"id": "c", "text": "Place a padded spoon between the client''s teeth"}, {"id": "d", "text": "Keep the client lying flat on the back"}]'::jsonb, '["a"]', 'During a seizure, the nurse removes glasses and hazardous items for safety. The client should not be restrained, nothing should be placed in the mouth, and the client should be turned to the side.'),
  ('seizures', 31, 'During a client''s tonic-clonic seizure, a family member tries to hold the client''s arms down. Which statement by the nurse is appropriate?', '[{"id": "a", "text": "''Please hold his legs as well so he does not get hurt.''"}, {"id": "b", "text": "''Please let go; we should not restrain him during a seizure.''"}, {"id": "c", "text": "''Please hold him firmly until the jerking movements stop.''"}, {"id": "d", "text": "''Please put this in his mouth so he does not bite his tongue.''"}]'::jsonb, '["b"]', 'The client must not be restrained during a seizure. Nothing should be inserted in the mouth, even though tongue biting can occur in the tonic phase.'),
  ('seizures', 32, 'A client having a tonic-clonic seizure in bed has saliva collecting in the mouth. How should the nurse position the client?', '[{"id": "a", "text": "On the side"}, {"id": "b", "text": "Flat on the back"}, {"id": "c", "text": "Prone, face down"}, {"id": "d", "text": "Sitting upright"}]'::jsonb, '["a"]', 'During a seizure, the client is turned to a lateral (side) position to protect the airway. Lying flat on the back does not provide this airway protection.'),
  ('seizures', 33, 'A client slumps from a chair to the floor and begins a tonic-clonic seizure. Which action should the nurse take to protect the client''s head?', '[{"id": "a", "text": "Hold the head still with both hands"}, {"id": "b", "text": "Lift the client back into the chair"}, {"id": "c", "text": "Place a bite block in the mouth"}, {"id": "d", "text": "Place a pillow under the head"}]'::jsonb, '["d"]', 'During a seizure, a pillow is placed under the head for protection. Holding the client still is a form of restraint, and nothing should be placed in the mouth.'),
  ('seizures', 34, 'A client''s tonic-clonic seizure has just ended. Which action is the nurse''s priority?', '[{"id": "a", "text": "Ask the client to describe the aura"}, {"id": "b", "text": "Help the client walk to the bathroom"}, {"id": "c", "text": "Assess airway, vital signs, and neuro status"}, {"id": "d", "text": "Give the client oral fluids to drink"}]'::jsonb, '["c"]', 'Postictal care begins with assessing the airway, vital signs, and neurological status. The client should be allowed to rest rather than ambulate during postictal confusion and fatigue.'),
  ('seizures', 35, 'After a client''s seizure, which information is most important for the nurse to document?', '[{"id": "a", "text": "Duration, visitors present, and meal intake"}, {"id": "b", "text": "Duration, movements observed, and level of consciousness"}, {"id": "c", "text": "Movements observed, room temperature, and bed position"}, {"id": "d", "text": "Level of consciousness, visitors present, and meal intake"}]'::jsonb, '["b"]', 'After a seizure, the nurse documents the duration, the movements observed, and the level of consciousness. Visitors, meals, and room temperature do not describe the seizure.'),
  ('seizures', 36, 'A client in the postictal phase is confused and wants to sleep. Which nursing action is appropriate?', '[{"id": "a", "text": "Keep the client awake and walking in the hallway"}, {"id": "b", "text": "Apply restraints until the confusion resolves"}, {"id": "c", "text": "Allow the client to rest and provide reorientation"}, {"id": "d", "text": "Insert an oral airway to protect the tongue"}]'::jsonb, '["c"]', 'Postictal care includes allowing rest and reorientation, since fatigue and confusion are expected. Restraints and objects in the mouth are not part of seizure care.'),
  ('seizures', 37, 'A client taking phenobarbital is drowsy, and the nurse notes that the blood pressure is lower than baseline. How should the nurse interpret these findings?', '[{"id": "a", "text": "Signs that the client is under-medicated"}, {"id": "b", "text": "Signs of an approaching seizure aura"}, {"id": "c", "text": "Expected effects of the ketogenic diet"}, {"id": "d", "text": "Known adverse effects of phenobarbital"}]'::jsonb, '["d"]', 'The nurse watches for sedation and hypotension in clients taking phenobarbital. Under-medication is a seizure trigger and does not explain sedation or low blood pressure.'),
  ('seizures', 38, 'A client has taken phenytoin (Dilantin) for several months. Which adverse effect of this drug should the nurse look for during the oral examination?', '[{"id": "a", "text": "Gingival hyperplasia"}, {"id": "b", "text": "Tooth discoloration"}, {"id": "c", "text": "Dry, cracked lips"}, {"id": "d", "text": "White tongue patches"}]'::jsonb, '["a"]', 'Phenytoin causes gingival hyperplasia, or gum overgrowth, which the nurse assesses during the oral exam. Gum overgrowth is the oral adverse effect listed for phenytoin.'),
  ('seizures', 39, 'The nurse reviews serum phenytoin levels for four clients. Which client''s level is within the therapeutic range?', '[{"id": "a", "text": "Level of 6"}, {"id": "b", "text": "Level of 15"}, {"id": "c", "text": "Level of 25"}, {"id": "d", "text": "Level of 32"}]'::jsonb, '["b"]', 'The therapeutic level for phenytoin is 10–20, so a level of 15 is within range. Levels of 25 and 32 are above range, and a level of 6 is below range.'),
  ('seizures', 40, 'A client who started phenytoin two weeks ago reports a new skin rash. Which action should the nurse take?', '[{"id": "a", "text": "Continue the drug because a rash is expected"}, {"id": "b", "text": "Apply lotion and give the next dose as ordered"}, {"id": "c", "text": "Double the next dose to improve seizure control"}, {"id": "d", "text": "Hold the drug and notify the provider"}]'::jsonb, '["d"]', 'A rash in a client taking phenytoin means the drug should be stopped, so the nurse holds it and notifies the provider. Continuing the drug is unsafe.'),
  ('seizures', 41, 'A client is starting valproic acid. Which laboratory values should the nurse plan to monitor?', '[{"id": "a", "text": "Thyroid function and cortisol"}, {"id": "b", "text": "Hemoglobin A1c and lipid panel"}, {"id": "c", "text": "Liver function and platelets"}, {"id": "d", "text": "Urine specific gravity and creatinine"}]'::jsonb, '["c"]', 'Valproic acid requires monitoring of liver function and platelets. Valproic acid is also associated with GI upset and is teratogenic.'),
  ('seizures', 42, 'A client of childbearing age is prescribed valproic acid. Which teaching point is the priority?', '[{"id": "a", "text": "The drug is teratogenic; discuss pregnancy plans"}, {"id": "b", "text": "The drug causes gum overgrowth; inspect the gums"}, {"id": "c", "text": "The drug is reversed with flumazenil if needed"}, {"id": "d", "text": "The drug has no effect on liver function tests"}]'::jsonb, '["a"]', 'Valproic acid is teratogenic, which is a priority concern for a client of childbearing age. Gum overgrowth is linked to phenytoin, flumazenil reverses benzodiazepines, and valproic acid requires liver function monitoring.'),
  ('seizures', 43, 'A nurse teaches a client scheduled for an EEG. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I will wash my hair and make sure it is dry.''"}, {"id": "b", "text": "''I will drink my usual cup of coffee before the test.''"}, {"id": "c", "text": "''I can eat a meal before the test.''"}, {"id": "d", "text": "''The test is non-invasive.''"}]'::jsonb, '["b"]', 'EEG preparation includes avoiding caffeine and sedatives. The client should have clean, dry hair, may eat, and can be told the test is non-invasive.'),
  ('seizures', 44, 'A client with epilepsy asks how a vagus nerve stimulator works. Which response by the nurse is accurate?', '[{"id": "a", "text": "''It delivers medication directly into the brain.''"}, {"id": "b", "text": "''It records brain waves to diagnose seizures.''"}, {"id": "c", "text": "''It stimulates the muscles to stop the jerking.''"}, {"id": "d", "text": "''It sends electrical pulses via CN X to reduce seizures.''"}]'::jsonb, '["d"]', 'A vagus nerve stimulator is an implanted device that sends electrical pulses via cranial nerve X to reduce seizure frequency. Recording brain waves describes an EEG.'),
  ('seizures', 45, 'The parent of a child with drug-resistant epilepsy asks about the ketogenic diet. Which description by the nurse is accurate?', '[{"id": "a", "text": "Low-fat, high-carbohydrate"}, {"id": "b", "text": "High-protein, low-fat"}, {"id": "c", "text": "High-fat, low-carbohydrate"}, {"id": "d", "text": "Low-sodium, high-fiber"}]'::jsonb, '["c"]', 'The ketogenic diet is a high-fat, low-carb diet used especially in children with drug-resistant epilepsy. A low-fat, high-carbohydrate diet is the opposite.'),
  ('seizures', 46, 'A college student with epilepsy is receiving teaching about seizure triggers. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "''I''ll stay up all night to study before my exams.''"}, {"id": "b", "text": "''I won''t skip any doses of my seizure medication.''"}, {"id": "c", "text": "''I''ll avoid drinking alcohol at parties.''"}, {"id": "d", "text": "''I''ll find ways to manage stress during exams.''"}]'::jsonb, '["a"]', 'Sleep loss is a seizure trigger because fatigue significantly lowers the seizure threshold. Avoiding missed doses, alcohol, and stress all reduce triggers.'),
  ('seizures', 47, 'A client with well-controlled epilepsy is admitted after a breakthrough seizure. He states he stopped taking his medication a week ago because he felt fine. Which trigger most likely contributed?', '[{"id": "a", "text": "Overexertion"}, {"id": "b", "text": "Under-medication"}, {"id": "c", "text": "Hormonal fluctuation"}, {"id": "d", "text": "Visual stimuli"}]'::jsonb, '["b"]', 'Under-medication from missed doses or non-compliance is a seizure trigger and matches this client''s history. Nothing in the history suggests overexertion, hormonal change, or visual stimuli.'),
  ('seizures', 48, 'A client with epilepsy asks whether it is safe to attend a concert with strobe lights and loud music. The nurse explains that these are potential triggers in which category?', '[{"id": "a", "text": "Physical overexertion"}, {"id": "b", "text": "Infection or illness"}, {"id": "c", "text": "Physical trauma"}, {"id": "d", "text": "Visual/auditory stimuli"}]'::jsonb, '["d"]', 'Visual and auditory stimuli such as flashing lights and loud sounds can trigger seizures. The illness trigger refers to infections and fever, and the trauma trigger refers to physical injury.'),
  ('seizures', 49, 'A client with a seizure disorder has a breakthrough seizure, and laboratory results show a low blood glucose level. Which trigger category does this finding represent?', '[{"id": "a", "text": "Electrolyte/metabolic issues"}, {"id": "b", "text": "Infection or illness"}, {"id": "c", "text": "Under-medication"}, {"id": "d", "text": "Physical overexertion"}]'::jsonb, '["a"]', 'Electrolyte and metabolic triggers include low sodium, calcium, or blood glucose. Under-medication refers to missed doses, and illness refers to infections and fever.'),
  ('seizures', 50, 'A client notices that her seizures tend to occur around the time of her menstrual period. Which trigger does the nurse identify?', '[{"id": "a", "text": "Recreational drugs"}, {"id": "b", "text": "Overexertion"}, {"id": "c", "text": "Hormonal fluctuations"}, {"id": "d", "text": "Under-medication"}]'::jsonb, '["c"]', 'Menstrual or hormonal fluctuations are a seizure trigger and fit this pattern. Under-medication refers to missed doses, which the client has not described.'),
  ('sci', 1, 'The nurse is planning bladder care for a client with a T4 spinal cord injury. Which plan is most appropriate?', '[{"id": "a", "text": "Catheterize only when the client reports urgency"}, {"id": "b", "text": "Allow the bladder to fill fully before emptying"}, {"id": "c", "text": "Use intermittent catheterization to prevent overdistension"}, {"id": "d", "text": "Use incontinence pads instead of catheterization"}]'::jsonb, '["c"]', 'Bladder management uses intermittent catheterization and prevents overdistension, which can trigger autonomic dysreflexia. Allowing the bladder to fill fully promotes the overdistension that must be avoided.'),
  ('sci', 2, 'A client with a C3 spinal cord injury shows signs of diaphragm paralysis. Which item should the nurse prepare?', '[{"id": "a", "text": "Supplies for a bowel program"}, {"id": "b", "text": "Sequential compression devices"}, {"id": "c", "text": "An intermittent catheterization kit"}, {"id": "d", "text": "Equipment for ventilator support"}]'::jsonb, '["d"]', 'C3–C5 injuries can paralyze the diaphragm via the phrenic nerve, so the nurse prepares for ventilator support. The other items address bowel, DVT, and bladder needs, which are not the immediate threat.'),
  ('sci', 3, 'The nurse is assessing a client for saddle anesthesia. Which body area should the nurse test for loss of sensation?', '[{"id": "a", "text": "Hands, wrists, and forearms"}, {"id": "b", "text": "Feet, ankles, and lower legs"}, {"id": "c", "text": "Buttocks, inner thighs, and perineum"}, {"id": "d", "text": "Chest, upper back, and shoulders"}]'::jsonb, '["c"]', 'Saddle anesthesia is loss of feeling in the buttocks, inner thighs, and perineum. The other areas are not part of the saddle distribution.'),
  ('sci', 4, 'The nurse is caring for four clients with spinal cord injuries. Which client is at risk for autonomic dysreflexia?', '[{"id": "a", "text": "A client with an injury at L1"}, {"id": "b", "text": "A client with an injury at T4"}, {"id": "c", "text": "A client with cauda equina syndrome at L3"}, {"id": "d", "text": "A client with an injury at T10"}]'::jsonb, '["b"]', 'Autonomic dysreflexia occurs with injuries at T6 and above, so a T4 injury places the client at risk. Injuries at T10, L1, and L3 are below T6.'),
  ('sci', 5, 'A family member of a client with a T2 spinal cord injury asks what most often causes autonomic dysreflexia. Which response by the nurse is correct?', '[{"id": "a", "text": "Constipation"}, {"id": "b", "text": "Tight clothing"}, {"id": "c", "text": "A full bladder"}, {"id": "d", "text": "A pressure ulcer"}]'::jsonb, '["c"]', 'A full bladder is the most common trigger of autonomic dysreflexia. Constipation, tight clothing, and pressure ulcers are also triggers but are less common.'),
  ('sci', 6, 'The nurse is reviewing the history of a client admitted with central cord syndrome. Which mechanism of injury is most consistent with this diagnosis?', '[{"id": "a", "text": "Hyperextension of the neck in an older adult with degenerative changes"}, {"id": "b", "text": "Penetrating stab wound that damages one side of the cord"}, {"id": "c", "text": "Anterior spinal artery occlusion that damages the front of the cord"}, {"id": "d", "text": "Herniated disc compressing nerve roots below the spinal cord"}]'::jsonb, '["a"]', 'Central cord syndrome is caused by hyperextension in older adults with degenerative changes. A stab wound damaging one side of the cord produces Brown-Séquard syndrome instead.'),
  ('sci', 7, 'A client develops sudden spinal cord deficits after occlusion of the anterior spinal artery. The nurse anticipates findings consistent with which syndrome?', '[{"id": "a", "text": "Central cord syndrome"}, {"id": "b", "text": "Posterior cord syndrome"}, {"id": "c", "text": "Anterior cord syndrome"}, {"id": "d", "text": "Cauda equina syndrome"}]'::jsonb, '["c"]', 'Anterior cord syndrome is caused by a flexion injury or anterior spinal artery occlusion that damages the front of the cord. Cauda equina syndrome results from compression of nerve roots below the cord by a disc, tumor, or trauma.'),
  ('sci', 8, 'A nurse is preparing a teaching session on conus medullaris syndrome. Where should the nurse describe the location of injury?', '[{"id": "a", "text": "The tapered end of the spinal cord at L1–L2"}, {"id": "b", "text": "The nerve roots below the end of the spinal cord"}, {"id": "c", "text": "The center of the cervical spinal cord"}, {"id": "d", "text": "One side (half) of the spinal cord"}]'::jsonb, '["a"]', 'Conus medullaris syndrome is an injury at the tapered end of the spinal cord at L1–L2. Nerve roots below the cord are involved in cauda equina syndrome.'),
  ('sci', 9, 'After a motor vehicle crash, a client''s provider wants to identify vertebral fractures. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "MRI"}, {"id": "b", "text": "Reflex testing"}, {"id": "c", "text": "CT scan"}, {"id": "d", "text": "Sensory testing"}]'::jsonb, '["c"]', 'CT is used to evaluate bony injury and vertebral fractures. MRI is best for soft tissue and cord damage rather than bone.'),
  ('sci', 10, 'Two hours after a new cervical spinal cord injury, a client has hypotension, bradycardia, and warm skin. Which condition does the nurse recognize?', '[{"id": "a", "text": "Neurogenic shock"}, {"id": "b", "text": "Autonomic dysreflexia"}, {"id": "c", "text": "Anterior cord syndrome"}, {"id": "d", "text": "Posterior cord syndrome"}]'::jsonb, '["a"]', 'Neurogenic shock presents with hypotension, bradycardia, and warm skin because the sympathetic pathway is disrupted, and it must be differentiated from hypovolemic shock. Autonomic dysreflexia causes hypertension rather than hypotension.'),
  ('sci', 11, 'A gunshot wound has damaged the left half of a client''s spinal cord, producing Brown-Séquard syndrome. Which finding should the nurse expect?', '[{"id": "a", "text": "Loss of pain and temperature sensation on the left side"}, {"id": "b", "text": "Loss of pain and temperature sensation on the right side"}, {"id": "c", "text": "Loss of motor function on the right side"}, {"id": "d", "text": "Loss of proprioception on the right side"}]'::jsonb, '["b"]', 'In Brown-Séquard syndrome, pain and temperature are lost on the side opposite the damage, so a left-sided lesion causes right-sided pain and temperature loss. Motor and proprioception loss occur on the same (left) side, not the right.'),
  ('sci', 12, 'The nurse is assessing a client with a T5 injury who is experiencing autonomic dysreflexia. Which skin finding below the level of injury should the nurse expect?', '[{"id": "a", "text": "Flushed, red skin"}, {"id": "b", "text": "Pale, cold skin"}, {"id": "c", "text": "Sweaty, moist skin"}, {"id": "d", "text": "Warm, pink skin"}]'::jsonb, '["b"]', 'In autonomic dysreflexia, skin below the injury is pale and cold. Flushing and sweating occur above the level of injury, not below.'),
  ('sci', 13, 'A nursing student asks why bladder overdistension is avoided in a client with a T3 spinal cord injury. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It can lead to neurogenic shock"}, {"id": "b", "text": "It can trigger autonomic dysreflexia"}, {"id": "c", "text": "It can cause saddle anesthesia"}, {"id": "d", "text": "It can paralyze the diaphragm"}]'::jsonb, '["b"]', 'Bladder overdistension is a trigger for autonomic dysreflexia in injuries at T6 and above. Neurogenic shock results from sympathetic disruption, not bladder overdistension.'),
  ('sci', 14, 'The emergency department nurse is triaging several clients with suspected spinal cord injuries. Which client is most likely to develop Brown-Séquard syndrome?', '[{"id": "a", "text": "An older adult with a hyperextension injury from a fall"}, {"id": "b", "text": "A client with occlusion of the anterior spinal artery"}, {"id": "c", "text": "A client with a large herniated disc and back pain"}, {"id": "d", "text": "A client with a knife wound penetrating the spinal cord"}]'::jsonb, '["d"]', 'Brown-Séquard syndrome is caused by penetrating trauma such as a gunshot or stab wound that damages one side of the cord. Hyperextension in an older adult is the classic cause of central cord syndrome.'),
  ('sci', 15, 'A client is diagnosed with central cord syndrome after a fall. Which description of the client''s sensory examination should the nurse expect?', '[{"id": "a", "text": "Total sensory loss below the level of the lesion"}, {"id": "b", "text": "Pain and temperature loss on the side opposite the injury"}, {"id": "c", "text": "Sensory loss that is variable from client to client"}, {"id": "d", "text": "Loss of proprioception with intact motor function"}]'::jsonb, '["c"]', 'In central cord syndrome, sensory loss is variable while the arms are weaker than the legs. Total loss below the lesion describes a complete injury, not an incomplete central cord pattern.'),
  ('sci', 16, 'Which client history should most raise the nurse''s suspicion for cauda equina syndrome?', '[{"id": "a", "text": "A hyperextension neck injury in an older adult"}, {"id": "b", "text": "Occlusion of the anterior spinal artery"}, {"id": "c", "text": "A herniated disc compressing nerve roots below the cord"}, {"id": "d", "text": "A flexion injury damaging the front of the cord"}]'::jsonb, '["c"]', 'Cauda equina syndrome results from compression of nerve roots below the spinal cord by a herniated disc, tumor, or trauma. Anterior spinal artery occlusion and flexion injuries cause anterior cord syndrome.'),
  ('sci', 17, 'A client has Brown-Séquard syndrome from a right-sided hemisection of the spinal cord. Which finding does the nurse expect on the client''s right side?', '[{"id": "a", "text": "Loss of pain sensation only"}, {"id": "b", "text": "Loss of temperature sensation only"}, {"id": "c", "text": "Loss of motor function and vibration sense"}, {"id": "d", "text": "Intact motor function with loss of pain sensation"}]'::jsonb, '["c"]', 'The same (ipsilateral) side loses motor function, proprioception, and vibration in Brown-Séquard syndrome. Pain and temperature loss occur on the opposite side, so they would be found on the left.'),
  ('sci', 18, 'An older adult with degenerative changes of the cervical spine falls and hyperextends the neck. The client can walk but has marked weakness in both arms, and the legs are stronger than the arms. The nurse recognizes this pattern as which syndrome?', '[{"id": "a", "text": "Anterior cord syndrome"}, {"id": "b", "text": "Central cord syndrome"}, {"id": "c", "text": "Brown-Séquard syndrome"}, {"id": "d", "text": "Posterior cord syndrome"}]'::jsonb, '["b"]', 'Central cord syndrome follows hyperextension in older adults with degenerative changes and produces arms weaker than legs. Anterior cord syndrome causes motor loss below the injury rather than an upper-greater-than-lower pattern.'),
  ('sci', 19, 'A client with a known herniated disc reports new numbness of the buttocks and inner thighs, new loss of bladder control, and weakness that is worse in the right leg than the left. Which syndrome does the nurse suspect?', '[{"id": "a", "text": "Conus medullaris syndrome"}, {"id": "b", "text": "Cauda equina syndrome"}, {"id": "c", "text": "Posterior cord syndrome"}, {"id": "d", "text": "Brown-Séquard syndrome"}]'::jsonb, '["b"]', 'Cauda equina syndrome presents with asymmetric leg weakness, saddle anesthesia, and loss of bowel/bladder control, often from a herniated disc. Conus medullaris syndrome produces symmetric rather than asymmetric weakness.'),
  ('sci', 20, 'A client is admitted with a spinal cord injury at the C4 level. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Auscultation of bowel sounds"}, {"id": "b", "text": "Respiratory status and breathing effort"}, {"id": "c", "text": "Skin integrity over the sacrum"}, {"id": "d", "text": "Palpation for bladder distension"}]'::jsonb, '["b"]', 'Cervical injuries at C3–C5 can paralyze the diaphragm through the phrenic nerve, making airway and respiratory assessment the priority. Bowel, skin, and bladder care are important but do not take precedence over breathing.'),
  ('sci', 21, 'The nurse is caring for a client with a high thoracic spinal cord injury. Which set of vital sign changes is consistent with autonomic dysreflexia?', '[{"id": "a", "text": "Hypotension and bradycardia"}, {"id": "b", "text": "Hypotension and tachycardia"}, {"id": "c", "text": "Hypertension and tachycardia"}, {"id": "d", "text": "Hypertension and bradycardia"}]'::jsonb, '["d"]', 'Autonomic dysreflexia causes hypertension with bradycardia. Hypotension with bradycardia is the pattern of neurogenic shock.'),
  ('sci', 22, 'A client with a C7 injury develops autonomic dysreflexia. Which sequence of nursing actions is correct?', '[{"id": "a", "text": "Sit upright, find and remove the trigger starting with the catheter, give ordered antihypertensives"}, {"id": "b", "text": "Give ordered antihypertensives, sit upright, then find and remove the trigger"}, {"id": "c", "text": "Check the catheter, lay the client flat, then give ordered antihypertensives"}, {"id": "d", "text": "Remove the trigger, give ordered antihypertensives, then sit the client upright"}]'::jsonb, '["a"]', 'The client is first sat upright to lower blood pressure, then the trigger is found and removed (Foley first), and antihypertensives are given if ordered. Giving antihypertensives before positioning and trigger removal reverses the stated order.'),
  ('sci', 23, 'A nurse educator is reviewing spinal cord injury syndromes with new graduates. Which syndrome should the educator identify as the rarest?', '[{"id": "a", "text": "Central cord syndrome"}, {"id": "b", "text": "Posterior cord syndrome"}, {"id": "c", "text": "Brown-Séquard syndrome"}, {"id": "d", "text": "Cauda equina syndrome"}]'::jsonb, '["b"]', 'Posterior cord syndrome is described as the rarest SCI syndrome. Central cord syndrome is the opposite extreme, being the most common incomplete injury.'),
  ('sci', 24, 'The nurse is establishing a bowel program for a client with a spinal cord injury. Which plan is appropriate?', '[{"id": "a", "text": "High-fiber diet, adequate fluids, and scheduled toileting"}, {"id": "b", "text": "Low-fiber diet, limited fluids, and scheduled toileting"}, {"id": "c", "text": "High-fiber diet, limited fluids, and toileting on request"}, {"id": "d", "text": "Low-fiber diet, adequate fluids, and toileting on request"}]'::jsonb, '["a"]', 'A bowel program includes high fiber, adequate fluids, and scheduled toileting. Limiting fluids or fiber undermines the program, and constipation is also a trigger for autonomic dysreflexia.'),
  ('sci', 25, 'A client is diagnosed with posterior cord syndrome. Which finding should the nurse expect to be preserved?', '[{"id": "a", "text": "Motor function"}, {"id": "b", "text": "Proprioception"}, {"id": "c", "text": "Vibration sense"}, {"id": "d", "text": "Fine touch"}]'::jsonb, '["a"]', 'In posterior cord syndrome, motor function is preserved while proprioception, vibration, and fine touch are lost. Proprioception is lost, which makes it the most tempting but incorrect choice.'),
  ('sci', 26, 'The nurse teaches the family of a client with a T2 spinal cord injury about autonomic dysreflexia. Which finding should the family recognize as a warning sign?', '[{"id": "a", "text": "Pale, cool skin above the level of injury"}, {"id": "b", "text": "Flushing and sweating below the injury"}, {"id": "c", "text": "Rapid heart rate with low blood pressure"}, {"id": "d", "text": "Sudden severe headache"}]'::jsonb, '["d"]', 'A sudden severe headache is a symptom of autonomic dysreflexia, along with hypertension and bradycardia. Flushing and sweating occur above the injury, not below, and pale/cold skin occurs below rather than above.'),
  ('sci', 27, 'A new nurse asks why a client with autonomic dysreflexia is placed in an upright position. Which explanation by the charge nurse is correct?', '[{"id": "a", "text": "It improves drainage of the bladder"}, {"id": "b", "text": "It relieves pressure on the sacrum"}, {"id": "c", "text": "It helps lower the blood pressure"}, {"id": "d", "text": "It helps raise the heart rate"}]'::jsonb, '["c"]', 'Sitting the client upright immediately lowers blood pressure in this hypertensive emergency. Finding the trigger, such as a full bladder, is a separate step after positioning.'),
  ('sci', 28, 'The nurse receives report on four clients. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with sudden saddle anesthesia, new bowel incontinence, and asymmetric leg weakness"}, {"id": "b", "text": "A client with central cord syndrome who has variable sensory loss in the arms"}, {"id": "c", "text": "A client with posterior cord syndrome who has impaired proprioception in the feet"}, {"id": "d", "text": "A client with a spinal cord injury who expresses grief about body image changes"}]'::jsonb, '["a"]', 'Sudden saddle anesthesia with bowel/bladder dysfunction and asymmetric leg weakness indicates cauda equina syndrome, the highest-priority SCI syndrome requiring immediate surgery. The other clients show findings expected for their conditions.'),
  ('sci', 29, 'The nurse needs to reposition a client with a newly suspected spinal cord injury. Which technique should the nurse use?', '[{"id": "a", "text": "Log-roll the client as a unit"}, {"id": "b", "text": "Have the client turn using the side rails"}, {"id": "c", "text": "Raise the head of the bed, then pull up"}, {"id": "d", "text": "Turn the shoulders first, then the hips"}]'::jsonb, '["a"]', 'Spine stabilization includes the log-roll technique for repositioning. Having the client turn independently or turning the shoulders and hips separately does not keep the spine stabilized.'),
  ('sci', 30, 'After a flexion injury, a client has paralysis below the injury and cannot feel pinprick or temperature in the legs, yet can correctly identify the position of the toes and feel a vibrating tuning fork. Which syndrome does this represent?', '[{"id": "a", "text": "Posterior cord syndrome"}, {"id": "b", "text": "Anterior cord syndrome"}, {"id": "c", "text": "Central cord syndrome"}, {"id": "d", "text": "Brown-Séquard syndrome"}]'::jsonb, '["b"]', 'Anterior cord syndrome causes loss of motor function and pain/temperature while touch, vibration, and proprioception are preserved. Posterior cord syndrome is the reverse: motor preserved with proprioception and vibration lost.'),
  ('sci', 31, 'The nurse suspects cauda equina syndrome in a client with sudden saddle anesthesia and bowel and bladder dysfunction. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Scheduling outpatient physical therapy"}, {"id": "b", "text": "Discharge teaching about a bowel program"}, {"id": "c", "text": "Intermittent catheterization and reassessment in a week"}, {"id": "d", "text": "Preparing the client for immediate surgery"}]'::jsonb, '["d"]', 'Cauda equina syndrome is a surgical emergency requiring immediate surgery because delay causes permanent damage. Delaying care for therapy, discharge teaching, or later reassessment risks permanent damage.'),
  ('sci', 32, 'A client with a spinal cord injury moves all extremities with normal strength but cannot tell whether the toes are pointed up or down, cannot feel a vibrating tuning fork, and has lost fine touch. Which syndrome does the nurse recognize?', '[{"id": "a", "text": "Anterior cord syndrome"}, {"id": "b", "text": "Central cord syndrome"}, {"id": "c", "text": "Conus medullaris syndrome"}, {"id": "d", "text": "Posterior cord syndrome"}]'::jsonb, '["d"]', 'Posterior cord syndrome preserves motor function but causes loss of proprioception, vibration, and fine touch. Anterior cord syndrome would cause paralysis with touch, vibration, and proprioception preserved.'),
  ('sci', 33, 'A client asks the nurse what structures are affected in cauda equina syndrome. Which response is accurate?', '[{"id": "a", "text": "The center of the cervical spinal cord"}, {"id": "b", "text": "The front portion of the spinal cord"}, {"id": "c", "text": "The tapered end of the cord at L1–L2"}, {"id": "d", "text": "Nerve roots below the spinal cord at L2 and lower"}]'::jsonb, '["d"]', 'Cauda equina syndrome is compression of nerve roots below the spinal cord at L2 and lower. The tapered end of the cord at L1–L2 is the site of conus medullaris syndrome.'),
  ('sci', 34, 'A nursing student is explaining incomplete spinal cord injury to a client''s family. Which statement by the student is accurate?', '[{"id": "a", "text": "\"All movement and feeling are lost below the injury.\""}, {"id": "b", "text": "\"Only the automatic body functions are affected.\""}, {"id": "c", "text": "\"Incomplete injuries do not cause specific syndromes.\""}, {"id": "d", "text": "\"Some movement or feeling is kept below the injury.\""}]'::jsonb, '["d"]', 'An incomplete injury has partial preservation of motor or sensory function and produces the classic syndromes. Loss of all movement and feeling below the injury describes a complete injury.'),
  ('sci', 35, 'A client with an injury at the L1 level has sudden onset of equal weakness in both lower limbs, loss of feeling in the buttocks and perineum, and areflexia of the bladder and bowel. Which syndrome does the nurse suspect?', '[{"id": "a", "text": "Cauda equina syndrome"}, {"id": "b", "text": "Central cord syndrome"}, {"id": "c", "text": "Conus medullaris syndrome"}, {"id": "d", "text": "Anterior cord syndrome"}]'::jsonb, '["c"]', 'Conus medullaris syndrome involves the tapered end of the cord at L1–L2 with sudden, symmetric lower limb weakness, saddle anesthesia, and bladder/bowel areflexia. Cauda equina syndrome also causes saddle anesthesia but with asymmetric leg weakness below the cord.'),
  ('sci', 36, 'A client with a T5 injury has signs of autonomic dysreflexia after being placed upright. The urinary catheter is patent and draining well. Which finding should the nurse identify as a possible trigger?', '[{"id": "a", "text": "Flushing of the face and neck"}, {"id": "b", "text": "A heart rate that has slowed"}, {"id": "c", "text": "A tight waistband on the client''s pants"}, {"id": "d", "text": "A severe, pounding headache"}]'::jsonb, '["c"]', 'Tight clothing is a trigger of autonomic dysreflexia and should be removed. Flushing, bradycardia, and headache are symptoms of the episode rather than its cause.'),
  ('sci', 37, 'After a spinal cord injury, a client has total loss of motor and sensory function below the level of the lesion. How should the nurse classify this injury?', '[{"id": "a", "text": "Incomplete injury"}, {"id": "b", "text": "Complete injury"}, {"id": "c", "text": "Central cord syndrome"}, {"id": "d", "text": "Posterior cord syndrome"}]'::jsonb, '["b"]', 'A complete injury is total loss of motor and sensory function below the lesion. Incomplete injuries, including the cord syndromes, have partial preservation of motor or sensory function.'),
  ('sci', 38, 'A client is diagnosed with anterior cord syndrome. Which function should the nurse expect to remain intact?', '[{"id": "a", "text": "Proprioception"}, {"id": "b", "text": "Motor function below the injury"}, {"id": "c", "text": "Pain sensation"}, {"id": "d", "text": "Temperature sensation"}]'::jsonb, '["a"]', 'Anterior cord syndrome results in no motor function and no pain/temperature sensation, while touch, vibration, and proprioception are preserved. Motor function below the injury is lost, not intact.'),
  ('sci', 39, 'A client with a T3 injury has signs of autonomic dysreflexia. The nurse has placed the client in an upright position. What should the nurse do next?', '[{"id": "a", "text": "Check the indwelling urinary (Foley) catheter"}, {"id": "b", "text": "Administer an ordered antihypertensive medication"}, {"id": "c", "text": "Return the client to a supine position"}, {"id": "d", "text": "Inspect the sacrum for a pressure ulcer"}]'::jsonb, '["a"]', 'After sitting the client upright, the nurse finds and removes the trigger, checking the Foley catheter first because a full bladder is the most common trigger. Antihypertensives come after trigger removal and only if ordered.'),
  ('sci', 40, 'A client who sustained a spinal cord injury 1 week ago tearfully says, ''I hate what my body looks like now.'' Which nursing action is most appropriate?', '[{"id": "a", "text": "Delay rehabilitation referral until the grief resolves"}, {"id": "b", "text": "Encourage the client to focus on positive topics instead"}, {"id": "c", "text": "Acknowledge the grief and involve the rehabilitation team early"}, {"id": "d", "text": "Avoid discussing body changes until the client is discharged"}]'::jsonb, '["c"]', 'Emotional support addresses the grief reaction and body image changes and involves the rehabilitation team early. Delaying rehabilitation involvement contradicts early involvement.'),
  ('sci', 41, 'A nursing student asks which incomplete spinal cord injury syndrome occurs most often. Which response by the nurse is accurate?', '[{"id": "a", "text": "Posterior cord syndrome"}, {"id": "b", "text": "Brown-Séquard syndrome"}, {"id": "c", "text": "Anterior cord syndrome"}, {"id": "d", "text": "Central cord syndrome"}]'::jsonb, '["d"]', 'Central cord syndrome is the most common incomplete spinal cord injury. Posterior cord syndrome is the rarest of the syndromes, so it is the least likely answer.'),
  ('sci', 42, 'A client is diagnosed with central cord syndrome. Which client statement best reflects the expected deficit pattern?', '[{"id": "a", "text": "\"My hands work fine, but I can''t move my legs.\""}, {"id": "b", "text": "\"I can''t feel heat or pain on one side of my body.\""}, {"id": "c", "text": "\"My legs feel much weaker than my arms do.\""}, {"id": "d", "text": "\"I can walk, but I struggle to feed myself.\""}]'::jsonb, '["d"]', 'Central cord syndrome causes arms weaker than legs, captured by the memory tip ''walking but not feeding.'' Legs weaker than arms is the reverse of the expected pattern.'),
  ('sci', 43, 'Two clients have saddle anesthesia and loss of bowel and bladder control. Which assessment finding would help the nurse distinguish cauda equina syndrome from conus medullaris syndrome?', '[{"id": "a", "text": "Presence of saddle anesthesia"}, {"id": "b", "text": "Asymmetric leg weakness"}, {"id": "c", "text": "Loss of bladder control"}, {"id": "d", "text": "Loss of bowel control"}]'::jsonb, '["b"]', 'Cauda equina syndrome causes asymmetric leg weakness, whereas conus medullaris syndrome causes symmetric lower limb weakness. Saddle anesthesia and bowel/bladder dysfunction occur in both, so they do not distinguish them.'),
  ('sci', 44, 'A client with an acute spinal cord injury develops neurogenic shock. The client''s family asks why the skin is warm even though the blood pressure is low. What underlying cause should the nurse explain?', '[{"id": "a", "text": "An overly full bladder"}, {"id": "b", "text": "Loss of blood volume"}, {"id": "c", "text": "Disruption of the sympathetic pathway"}, {"id": "d", "text": "Occlusion of the anterior spinal artery"}]'::jsonb, '["c"]', 'Neurogenic shock (hypotension, bradycardia, warm skin) results from disruption of the sympathetic pathway. A full bladder is a trigger for autonomic dysreflexia, not the cause of neurogenic shock.'),
  ('sci', 45, 'A client is admitted after a stab wound to the back. Assessment shows loss of motor function, vibration sense, and proprioception on the right side and loss of pain and temperature sensation on the left side. Which syndrome does the nurse suspect?', '[{"id": "a", "text": "Brown-Séquard syndrome"}, {"id": "b", "text": "Anterior cord syndrome"}, {"id": "c", "text": "Central cord syndrome"}, {"id": "d", "text": "Conus medullaris syndrome"}]'::jsonb, '["a"]', 'Brown-Séquard syndrome is a hemisection from penetrating trauma, causing motor, proprioception, and vibration loss on the same side and pain and temperature loss on the opposite side. Anterior cord syndrome causes motor and pain/temperature loss without this split-side pattern.'),
  ('sci', 46, 'A client with a C6 spinal cord injury who is lying in bed suddenly reports a severe, pounding headache. The blood pressure is markedly elevated, the heart rate has slowed, and the face is flushed and sweaty. What is the nurse''s first action?', '[{"id": "a", "text": "Lay the client flat and elevate the legs"}, {"id": "b", "text": "Administer an antihypertensive medication"}, {"id": "c", "text": "Recheck the blood pressure in 15 minutes"}, {"id": "d", "text": "Sit the client upright immediately"}]'::jsonb, '["d"]', 'These findings indicate autonomic dysreflexia, and the first action is to sit the client upright immediately to lower blood pressure. Antihypertensives are given only after the trigger is sought and removed, and only if ordered.'),
  ('sci', 47, 'The nurse teaches the spouse of a client with a T4 injury about preventing autonomic dysreflexia. Which statement by the spouse indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll make sure his clothes are not too tight.\""}, {"id": "b", "text": "\"Constipation will not cause this problem.\""}, {"id": "c", "text": "\"I''ll keep his bladder from getting overfull.\""}, {"id": "d", "text": "\"A pressure sore could set off an episode.\""}]'::jsonb, '["b"]', 'Constipation is a trigger of autonomic dysreflexia, so this statement needs correction. Tight clothing, a full bladder, and pressure ulcers are all correctly identified triggers.'),
  ('sci', 48, 'The nurse is developing a plan to prevent deep vein thrombosis and pressure ulcers in a client with paraplegia. Which intervention should be included?', '[{"id": "a", "text": "Reposition the client every 4 hours"}, {"id": "b", "text": "Reposition only when the client reports discomfort"}, {"id": "c", "text": "Avoid compression devices on the legs"}, {"id": "d", "text": "Apply SCDs and reposition every 2 hours"}]'::jsonb, '["d"]', 'DVT and pressure ulcer prevention includes SCDs, repositioning every 2 hours, and special mattresses. Repositioning every 4 hours or only with discomfort is less frequent than the plan calls for.'),
  ('sci', 49, 'A client is admitted with a suspected spinal cord injury. The provider wants the best study to evaluate damage to the cord and surrounding soft tissue. Which test should the nurse prepare the client for?', '[{"id": "a", "text": "MRI"}, {"id": "b", "text": "CT scan"}, {"id": "c", "text": "Reflex assessment"}, {"id": "d", "text": "Motor strength testing"}]'::jsonb, '["a"]', 'MRI is best for soft tissue and cord damage. CT is used for bony injury and vertebral fractures rather than cord damage.'),
  ('sci', 50, 'A client arrives in the emergency department after a diving accident with a suspected cervical spine injury. Which nursing action takes priority during initial care?', '[{"id": "a", "text": "Auscultate bowel sounds in all quadrants"}, {"id": "b", "text": "Maintain the cervical collar and backboard"}, {"id": "c", "text": "Begin the scheduled bowel program"}, {"id": "d", "text": "Remove the collar to inspect the neck"}]'::jsonb, '["b"]', 'Spine stabilization with a cervical collar and backboard is a nursing priority for suspected spinal injury. Removing the collar would compromise stabilization.'),
  ('stroke', 1, 'The family of a client admitted with a stroke asks the nurse what happens to the brain during a stroke. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "“Electrical activity in the brain becomes disorganized and causes shaking.”"}, {"id": "b", "text": "“Blood flow to part of the brain is blocked or reduced, so brain cells die.”"}, {"id": "c", "text": "“Fluid slowly collects around the brain and compresses healthy tissue.”"}, {"id": "d", "text": "“A brief blockage occurs that never leads to lasting brain damage.”"}]'::jsonb, '["b"]', 'A stroke occurs when blood flow to part of the brain is blocked or reduced, causing brain cells to die. A temporary blockage with no permanent damage describes a TIA, not a stroke.'),
  ('stroke', 2, 'A nursing student asks which type of stroke is most common. Which response by the nurse is accurate?', '[{"id": "a", "text": "Hemorrhagic stroke caused by trauma"}, {"id": "b", "text": "Hemorrhagic stroke from a burst vessel"}, {"id": "c", "text": "Ischemic stroke caused by a blood clot"}, {"id": "d", "text": "Hemorrhagic stroke from an aneurysm"}]'::jsonb, '["c"]', 'Ischemic strokes, caused by a clot blocking flow, account for 87% of strokes. Hemorrhagic strokes, caused by a burst vessel from HTN, aneurysm, or trauma, account for 13%.'),
  ('stroke', 3, 'A client with a history of atrial fibrillation develops sudden facial droop and arm weakness. The nurse recognizes that the most likely type of stroke is:', '[{"id": "a", "text": "hemorrhagic, caused by trauma"}, {"id": "b", "text": "hemorrhagic, caused by hypertension"}, {"id": "c", "text": "hemorrhagic, caused by an aneurysm"}, {"id": "d", "text": "ischemic, caused by a clot"}]'::jsonb, '["d"]', 'Atrial fibrillation is a clot source and a cause of ischemic stroke. Hypertension, aneurysm, and trauma are causes of hemorrhagic stroke.'),
  ('stroke', 4, 'A client''s CT scan confirms a stroke caused by a blood vessel bursting and bleeding into the brain. Which item in the client''s history is a recognized cause of this type of stroke?', '[{"id": "a", "text": "A known cerebral aneurysm"}, {"id": "b", "text": "Carotid atherosclerosis"}, {"id": "c", "text": "Atrial fibrillation"}, {"id": "d", "text": "A recent clot in the heart"}]'::jsonb, '["a"]', 'Hemorrhagic stroke is caused by hypertension, aneurysm, or trauma. Atrial fibrillation and atherosclerosis cause ischemic stroke from clots.'),
  ('stroke', 5, 'A client whose stroke-like symptoms resolved completely within an hour is diagnosed with a transient ischemic attack (TIA). Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "“This was a temporary blockage of blood flow.”"}, {"id": "b", "text": "“Since it went away, my stroke risk is not higher.”"}, {"id": "c", "text": "“It did not cause permanent damage to my brain.”"}, {"id": "d", "text": "“This is a warning sign that a stroke could happen.”"}]'::jsonb, '["b"]', 'A TIA is a temporary blockage with no permanent damage, but it is a warning sign of high risk for a future stroke. Believing the risk is not increased requires further teaching.'),
  ('stroke', 6, 'During a stroke screening, the nurse asks a client to raise both arms in front of the body. One arm drifts downward. Which part of the FAST assessment does this finding represent?', '[{"id": "a", "text": "Face drooping"}, {"id": "b", "text": "Speech difficulty"}, {"id": "c", "text": "Arm weakness"}, {"id": "d", "text": "Time to call 911"}]'::jsonb, '["c"]', 'In FAST, arm weakness is identified when one arm drifts down when raised. Face drooping refers to one side of the face drooping or being uneven.'),
  ('stroke', 7, 'The nurse teaches a client''s family how to respond to stroke warning signs. A family member says, “If I notice my father''s face drooping on one side, I will…” Which completion indicates understanding?', '[{"id": "a", "text": "“…take him to his doctor''s office tomorrow.”"}, {"id": "b", "text": "“…have him lie down and recheck in an hour.”"}, {"id": "c", "text": "“…wait to see if it goes away by itself.”"}, {"id": "d", "text": "“…call 911 immediately.”"}]'::jsonb, '["d"]', 'The T in FAST means time to call 911 and get help immediately, because every second matters. Waiting or rechecking later delays emergency care.'),
  ('stroke', 8, 'A client with hypertension asks what blood pressure goal will help prevent a stroke. Which goal should the nurse reinforce?', '[{"id": "a", "text": "Less than 130/80 mmHg"}, {"id": "b", "text": "Less than 185/110 mmHg"}, {"id": "c", "text": "Less than 160/100 mmHg"}, {"id": "d", "text": "Less than 150/95 mmHg"}]'::jsonb, '["a"]', 'Hypertension is the #1 stroke risk factor, and the prevention goal is BP below 130/80 mmHg. A BP above 185/110 is the tPA contraindication threshold, not a prevention goal.'),
  ('stroke', 9, 'A 60-year-old client with a family history of stroke, a previous TIA, and diabetes mellitus asks which of these risk factors can be changed. The nurse identifies which risk factor as modifiable?', '[{"id": "a", "text": "Age over 55"}, {"id": "b", "text": "Diabetes mellitus"}, {"id": "c", "text": "Previous TIA"}, {"id": "d", "text": "Family history"}]'::jsonb, '["b"]', 'Diabetes mellitus is a modifiable stroke risk factor. Age over 55, family history, and previous TIA are non-modifiable.'),
  ('stroke', 10, 'The nurse reviews the history of a client at risk for stroke. Which risk factor in the client''s history cannot be modified?', '[{"id": "a", "text": "Obesity"}, {"id": "b", "text": "High cholesterol"}, {"id": "c", "text": "Age over 55"}, {"id": "d", "text": "Atrial fibrillation"}]'::jsonb, '["c"]', 'Age over 55 is a non-modifiable stroke risk factor. Obesity, high cholesterol, and atrial fibrillation are listed as modifiable.'),
  ('stroke', 11, 'A client with atrial fibrillation is admitted with an ischemic stroke. The nurse anticipates which diagnostic test to look for clots in the heart?', '[{"id": "a", "text": "Carotid ultrasound"}, {"id": "b", "text": "Coagulation studies"}, {"id": "c", "text": "MRI of the brain"}, {"id": "d", "text": "Echocardiogram"}]'::jsonb, '["d"]', 'An echocardiogram looks for clots in the heart, especially in clients with AFib. Carotid ultrasound evaluates blocked neck arteries.'),
  ('stroke', 12, 'The provider suspects that a client''s ischemic stroke resulted from narrowed arteries in the neck. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "Carotid ultrasound"}, {"id": "b", "text": "Echocardiogram"}, {"id": "c", "text": "Coagulation studies"}, {"id": "d", "text": "Serum cholesterol"}]'::jsonb, '["a"]', 'Carotid ultrasound is used to identify blocked neck arteries. An echocardiogram looks for clots in the heart.'),
  ('stroke', 13, 'A client arrives in the emergency department with facial droop and slurred speech that began 1 hour ago. Which diagnostic test should the nurse anticipate first?', '[{"id": "a", "text": "MRI of the brain"}, {"id": "b", "text": "CT scan of the head"}, {"id": "c", "text": "Echocardiogram"}, {"id": "d", "text": "Carotid ultrasound"}]'::jsonb, '["b"]', 'A CT scan is ordered first because it differentiates ischemic from hemorrhagic stroke and is required before tPA. MRI gives more detail on the extent of damage but is not the first test.'),
  ('stroke', 14, 'After the initial CT scan, the provider orders an MRI for a client with an ischemic stroke. The client asks why another scan is needed. The nurse explains that the MRI:', '[{"id": "a", "text": "checks for clots that formed inside the heart"}, {"id": "b", "text": "must be completed before any tPA can be given"}, {"id": "c", "text": "gives more detail about the extent of brain damage"}, {"id": "d", "text": "looks for blocked arteries in the client''s neck"}]'::jsonb, '["c"]', 'MRI provides more detail on the extent of brain damage. The CT scan, not the MRI, is required before tPA.'),
  ('stroke', 15, 'A client''s ischemic stroke symptoms began 7 hours ago. The CT scan shows no bleeding. The family asks whether the clot-busting drug will be given. Which response by the nurse is accurate?', '[{"id": "a", "text": "“It will be given as soon as the CT results are signed.”"}, {"id": "b", "text": "“It can be given any time within the first 24 hours.”"}, {"id": "c", "text": "“It is given only to clients who have a bleeding stroke.”"}, {"id": "d", "text": "“It is given only within 3 to 4.5 hours of symptom onset.”"}]'::jsonb, '["d"]', 'tPA must be given within 3 to 4.5 hours of symptom onset, so a client 7 hours from onset is outside the window. tPA is for ischemic stroke only and is never given for a hemorrhagic stroke.'),
  ('stroke', 16, 'The nurse is evaluating four clients with stroke symptoms. A CT scan has been completed for each, and none has recent surgery or active bleeding. Which client is a candidate for tPA?', '[{"id": "a", "text": "Ischemic stroke, onset 2 hours ago, BP 158/92"}, {"id": "b", "text": "Hemorrhagic stroke, onset 1 hour ago, BP 170/96"}, {"id": "c", "text": "Ischemic stroke, onset 6 hours ago, BP 150/88"}, {"id": "d", "text": "Ischemic stroke, onset 1 hour ago, BP 196/114"}]'::jsonb, '["a"]', 'tPA is for ischemic stroke only, within 3 to 4.5 hours of onset, and is contraindicated with BP above 185/110. The client 6 hours from onset is outside the window, and the client with BP 196/114 exceeds the BP limit.'),
  ('stroke', 17, 'A client with an acute ischemic stroke that began 90 minutes ago has a CT scan showing no hemorrhage. Just before tPA is to be started, the client''s BP is 198/116. Which action should the nurse take?', '[{"id": "a", "text": "Begin the tPA infusion as prescribed"}, {"id": "b", "text": "Hold the tPA and report the blood pressure"}, {"id": "c", "text": "Start the tPA and recheck the BP afterward"}, {"id": "d", "text": "Give aspirin instead and start the tPA later"}]'::jsonb, '["b"]', 'A BP above 185/110 is a contraindication to tPA, so the nurse should hold the drug and report the BP. Starting tPA despite the elevated BP is unsafe.'),
  ('stroke', 18, 'The nurse reviews the history of a client with an acute ischemic stroke who is being evaluated for tPA. Which finding is a contraindication to tPA?', '[{"id": "a", "text": "Atrial fibrillation"}, {"id": "b", "text": "Diabetes mellitus"}, {"id": "c", "text": "Surgery one week ago"}, {"id": "d", "text": "A previous TIA"}]'::jsonb, '["c"]', 'Recent surgery is a contraindication to tPA, along with hemorrhagic stroke, active bleeding, and BP above 185/110. Atrial fibrillation is a cause of ischemic stroke, not a tPA contraindication.'),
  ('stroke', 19, 'A client is admitted with an acute stroke. Which group of blood tests does the nurse anticipate as part of the diagnostic workup?', '[{"id": "a", "text": "Urine culture, uric acid, and creatinine"}, {"id": "b", "text": "Thyroid levels, liver enzymes, and amylase"}, {"id": "c", "text": "Blood cultures, lactate, and procalcitonin"}, {"id": "d", "text": "Coagulation studies, glucose, and cholesterol"}]'::jsonb, '["d"]', 'Blood tests in stroke diagnosis include coagulation, glucose, and cholesterol. The other panels are not part of the stroke workup.'),
  ('stroke', 20, 'A client''s CT scan confirms a hemorrhagic stroke. The nurse then receives a prescription for tPA. Which action should the nurse take?', '[{"id": "a", "text": "Question the prescription because tPA worsens bleeding"}, {"id": "b", "text": "Give tPA since the client is within the time window"}, {"id": "c", "text": "Give tPA after the blood pressure has been lowered"}, {"id": "d", "text": "Give tPA at a reduced dose to limit bleeding risk"}]'::jsonb, '["a"]', 'tPA must not be given in hemorrhagic stroke because it worsens the bleed. The time window applies only to ischemic stroke.'),
  ('stroke', 21, 'A client received tPA for an ischemic stroke 2 hours ago. Which prescription should the nurse question?', '[{"id": "a", "text": "Neurological checks every 15 minutes"}, {"id": "b", "text": "Intramuscular injection for nausea"}, {"id": "c", "text": "Blood pressure checks every 15 minutes"}, {"id": "d", "text": "Assessment of IV sites for bleeding"}]'::jsonb, '["b"]', 'After tPA, no IM injections are given and the client is watched closely for bleeding. Neuro and BP checks every 15 minutes are expected.'),
  ('stroke', 22, 'The nurse is planning care for a client who has just received tPA. Which intervention is appropriate?', '[{"id": "a", "text": "Insert an indwelling urinary catheter to track output"}, {"id": "b", "text": "Give pain medication by intramuscular injection"}, {"id": "c", "text": "Check blood pressure and neuro status every 15 minutes"}, {"id": "d", "text": "Check vital signs every 4 hours while the client is stable"}]'::jsonb, '["c"]', 'tPA monitoring includes BP and neuro checks every 15 minutes. A Foley catheter and IM injections are avoided after tPA.'),
  ('stroke', 23, 'A client is receiving post-tPA care after an ischemic stroke. Which finding should the nurse report immediately?', '[{"id": "a", "text": "Mild fatigue after a long admission process"}, {"id": "b", "text": "Mild hunger while waiting for a swallow screen"}, {"id": "c", "text": "A request for an extra blanket due to chills"}, {"id": "d", "text": "New bleeding from the gums and the IV site"}]'::jsonb, '["d"]', 'After tPA, the client is monitored closely for bleeding, BP, and neuro changes, so new bleeding must be reported. The other findings do not signal a tPA complication.'),
  ('stroke', 24, 'A client recovering from an ischemic stroke is prescribed clopidogrel. Which client statement indicates understanding of this medication?', '[{"id": "a", "text": "“This medicine helps prevent future clots.”"}, {"id": "b", "text": "“This medicine dissolves my current clot.”"}, {"id": "c", "text": "“This medicine treats bleeding in my brain.”"}, {"id": "d", "text": "“This medicine reverses my blood thinner.”"}]'::jsonb, '["a"]', 'Aspirin or clopidogrel is antiplatelet therapy used to prevent future clots after ischemic stroke. Dissolving the existing clot is the role of tPA.'),
  ('stroke', 25, 'A client''s ischemic stroke is caused by a large vessel occlusion. The provider recommends a catheter-based procedure. Which procedure does the nurse anticipate?', '[{"id": "a", "text": "Hematoma evacuation"}, {"id": "b", "text": "Mechanical thrombectomy"}, {"id": "c", "text": "Aneurysm clipping"}, {"id": "d", "text": "Aneurysm coiling"}]'::jsonb, '["b"]', 'Mechanical thrombectomy is catheter-based clot removal for large vessel occlusion. Hematoma evacuation and clipping or coiling an aneurysm are surgical treatments for hemorrhagic stroke.'),
  ('stroke', 26, 'Testing shows that a client''s ischemic stroke was caused by atrial fibrillation. Which additional therapy does the nurse anticipate for this cause?', '[{"id": "a", "text": "Evacuation of a hematoma"}, {"id": "b", "text": "Stopping all blood thinners"}, {"id": "c", "text": "Anticoagulation therapy"}, {"id": "d", "text": "Reversal of anticoagulation"}]'::jsonb, '["c"]', 'Anticoagulation is used for ischemic stroke when AFib is the cause. Stopping or reversing blood thinners applies to hemorrhagic stroke.'),
  ('stroke', 27, 'A client is admitted with a hemorrhagic stroke. Which intervention does the nurse anticipate as a priority to control the bleeding?', '[{"id": "a", "text": "Administering tPA"}, {"id": "b", "text": "Giving daily aspirin"}, {"id": "c", "text": "Starting a heparin drip"}, {"id": "d", "text": "Lowering blood pressure"}]'::jsonb, '["d"]', 'The priority in hemorrhagic stroke is controlling bleeding, which includes lowering BP to prevent further bleeding. tPA, heparin, and aspirin all worsen hemorrhage.'),
  ('stroke', 28, 'A client who takes warfarin at home is diagnosed with a hemorrhagic stroke. Which action does the nurse anticipate?', '[{"id": "a", "text": "Hold warfarin and prepare to reverse it"}, {"id": "b", "text": "Give the warfarin dose as scheduled"}, {"id": "c", "text": "Change the warfarin to a heparin drip"}, {"id": "d", "text": "Add aspirin to the client''s warfarin"}]'::jsonb, '["a"]', 'In hemorrhagic stroke, all blood thinners are stopped and anticoagulation is reversed if present. Switching to heparin or adding aspirin would worsen the hemorrhage.'),
  ('stroke', 29, 'The nurse reviews the prescriptions for a client with a hemorrhagic stroke. Which prescription should the nurse question?', '[{"id": "a", "text": "An antihypertensive to lower BP"}, {"id": "b", "text": "Daily low-dose aspirin"}, {"id": "c", "text": "An agent to reverse anticoagulation"}, {"id": "d", "text": "Preparation for hematoma evacuation"}]'::jsonb, '["b"]', 'All blood thinners, including aspirin, are stopped in hemorrhagic stroke because they worsen hemorrhage. Lowering BP, reversing anticoagulation, and evacuating the hematoma are expected treatments.'),
  ('stroke', 30, 'A client''s hemorrhagic stroke was caused by a ruptured cerebral aneurysm. Which surgical intervention does the nurse anticipate?', '[{"id": "a", "text": "Infusion of tPA to dissolve the bleed"}, {"id": "b", "text": "Mechanical thrombectomy of the clot"}, {"id": "c", "text": "Clipping or coiling of the aneurysm"}, {"id": "d", "text": "Insertion of a catheter to remove a clot"}]'::jsonb, '["c"]', 'Surgery for hemorrhagic stroke includes evacuating the hematoma and clipping or coiling the aneurysm. Mechanical thrombectomy is catheter-based clot removal for ischemic stroke.'),
  ('stroke', 31, 'A client has right-sided weakness and difficulty speaking and understanding language. The nurse recognizes that these findings suggest a stroke affecting which area?', '[{"id": "a", "text": "Occipital lobe"}, {"id": "b", "text": "Right hemisphere"}, {"id": "c", "text": "Cerebellum"}, {"id": "d", "text": "Left hemisphere"}]'::jsonb, '["d"]', 'A left hemisphere stroke causes right-sided weakness and aphasia. A right hemisphere stroke causes left-sided weakness and neglect.'),
  ('stroke', 32, 'A client who had a stroke eats only the food on the right side of the meal tray and seems unaware of the left arm. The nurse recognizes this finding as:', '[{"id": "a", "text": "left-sided neglect from a right hemisphere stroke"}, {"id": "b", "text": "left-sided neglect from a left hemisphere stroke"}, {"id": "c", "text": "expressive aphasia from a left hemisphere stroke"}, {"id": "d", "text": "agraphia from a right hemisphere stroke"}]'::jsonb, '["a"]', 'Left-sided neglect, being unaware of the left side, occurs with a right hemisphere stroke. A left hemisphere stroke affects the right side and causes aphasia.'),
  ('stroke', 33, 'A client with a right hemisphere stroke repeatedly tries to get out of bed alone and denies having any weakness. Which nursing intervention is the priority?', '[{"id": "a", "text": "Provide a picture board"}, {"id": "b", "text": "Implement fall precautions"}, {"id": "c", "text": "Teach the client to write requests"}, {"id": "d", "text": "Encourage walking without help"}]'::jsonb, '["b"]', 'A right hemisphere stroke causes poor judgment and impulsive behavior, so safety with fall precautions is the priority. Picture boards support communication for aphasia, which is associated with a left hemisphere stroke.'),
  ('stroke', 34, 'The nurse is caring for a client with a left hemisphere stroke. Which behavior does the nurse expect?', '[{"id": "a", "text": "Impulsive actions with denial of limitations"}, {"id": "b", "text": "Denial of weakness on the left side of the body"}, {"id": "c", "text": "Awareness of limitations with frustration"}, {"id": "d", "text": "Ignoring food on the left side of the tray"}]'::jsonb, '["c"]', 'Clients with left brain injury are aware of their limits and may experience depression, anger, and frustration. Impulsivity, denial, and left-sided neglect are associated with right brain injury.'),
  ('stroke', 35, 'A client with a right hemisphere stroke has limited vision in half of the visual field. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Dysarthria"}, {"id": "b", "text": "Agnosia"}, {"id": "c", "text": "Apraxia"}, {"id": "d", "text": "Hemianopia"}]'::jsonb, '["d"]', 'Hemianopia is limited vision in half of the visual field, and homonymous hemianopia is a vision problem of right hemisphere stroke. Agnosia is failure to recognize known objects or people.'),
  ('stroke', 36, 'A client admitted 3 hours ago with an ischemic stroke is alert and asks for a glass of water. Which action should the nurse take first?', '[{"id": "a", "text": "Perform a swallowing screen before any intake"}, {"id": "b", "text": "Offer small sips of water with the HOB raised"}, {"id": "c", "text": "Provide thickened liquids from the meal tray"}, {"id": "d", "text": "Give water through a straw to reduce effort"}]'::jsonb, '["a"]', 'Stroke causes dysphagia with aspiration pneumonia risk, so a swallowing screen must be done before any PO fluids or food. Giving any liquid, even sips or thickened fluids, before the screen is unsafe.'),
  ('stroke', 37, 'A client with a stroke has dysphagia identified on a swallowing screen. Which plan of care is most appropriate?', '[{"id": "a", "text": "Keep the HOB flat, give thin liquids slowly, and delay speech therapy referral"}, {"id": "b", "text": "Keep HOB elevated, give thickened liquids as ordered, and involve speech therapy"}, {"id": "c", "text": "Keep HOB elevated, give thin liquids by straw, and defer speech therapy referral"}, {"id": "d", "text": "Keep the HOB flat, give thickened liquids, and wait until discharge for therapy"}]'::jsonb, '["b"]', 'For dysphagia, the nurse keeps the HOB elevated, gives thickened liquids if ordered, and involves speech therapy to reduce aspiration risk. Lying flat and delaying therapy increase aspiration risk and conflict with early referral.'),
  ('stroke', 38, 'The nurse sees an assistive personnel setting up a breakfast tray for a client admitted with a stroke 2 hours ago. The swallowing screen has not been done. Which action should the nurse take?', '[{"id": "a", "text": "Allow the client to eat while the assistant watches"}, {"id": "b", "text": "Have the assistant feed the client slowly"}, {"id": "c", "text": "Stop the meal until a swallowing screen is completed"}, {"id": "d", "text": "Remove only the thin liquids from the tray"}]'::jsonb, '["c"]', 'The top nursing priority is dysphagia screening before any oral intake because of aspiration pneumonia risk. Feeding slowly or removing only thin liquids still allows intake before screening.'),
  ('stroke', 39, 'A client is brought to the emergency department by a spouse because of sudden slurred speech. Which information is most important for the nurse to obtain and document?', '[{"id": "a", "text": "The date of the last eye exam"}, {"id": "b", "text": "The client''s food allergies"}, {"id": "c", "text": "The time of the client''s last meal"}, {"id": "d", "text": "The exact time the symptoms began"}]'::jsonb, '["d"]', 'Time is brain, so the nurse documents the exact time of symptom onset, which determines the 3 to 4.5 hour tPA window. The other information does not guide emergency stroke treatment.'),
  ('stroke', 40, 'During serial neurological checks, the nurse finds that a client''s Glasgow Coma Scale score has decreased since the last assessment. Which action should the nurse take?', '[{"id": "a", "text": "Report the deterioration immediately"}, {"id": "b", "text": "Recheck the score again in 4 hours"}, {"id": "c", "text": "Document the score and continue care"}, {"id": "d", "text": "Let the client rest without disturbance"}]'::jsonb, '["a"]', 'Serial neuro checks using the GCS are performed, and any deterioration is reported immediately. Delaying or only documenting the change is unsafe.'),
  ('stroke', 41, 'The nurse is communicating with a client who has aphasia after a stroke. Which approach is most appropriate?', '[{"id": "a", "text": "Use detailed and lengthy explanations"}, {"id": "b", "text": "Use simple words and a picture board"}, {"id": "c", "text": "Speak to the family instead of the client"}, {"id": "d", "text": "Speak rapidly to keep the client''s focus"}]'::jsonb, '["b"]', 'Communication support for aphasia includes simple words and picture boards. Lengthy explanations are harder for a client with aphasia to process.'),
  ('stroke', 42, 'The nurse is planning early rehabilitation care for a client who had a stroke. Which plan is appropriate?', '[{"id": "a", "text": "Reposition every 8 hours to promote longer rest"}, {"id": "b", "text": "Delay PT, OT, and speech referrals until discharge"}, {"id": "c", "text": "Reposition every 2 hours and perform ROM exercises"}, {"id": "d", "text": "Avoid ROM exercises until full strength returns"}]'::jsonb, '["c"]', 'Rehabilitation includes early PT/OT/SLP referral, repositioning every 2 hours, and ROM exercises. Delaying referrals contradicts early rehabilitation.'),
  ('stroke', 43, 'After a stroke, a client follows commands accurately and nods appropriately to questions but cannot produce the words to answer, even though facial and tongue muscle strength is normal. The nurse recognizes this as:', '[{"id": "a", "text": "agnosia"}, {"id": "b", "text": "receptive (Wernicke''s) aphasia"}, {"id": "c", "text": "dysarthria"}, {"id": "d", "text": "expressive (Broca''s) aphasia"}]'::jsonb, '["d"]', 'Expressive aphasia, involving Broca''s area, means the client comprehends speech but cannot respond with speech. Dysarthria is unclear speech due to weak muscles, which this client does not have.'),
  ('stroke', 44, 'After a stroke, a client with intact hearing speaks freely but cannot follow simple spoken instructions and responds to questions with unrelated answers. The nurse recognizes this as:', '[{"id": "a", "text": "receptive (Wernicke''s) aphasia"}, {"id": "b", "text": "expressive (Broca''s) aphasia"}, {"id": "c", "text": "dysarthria"}, {"id": "d", "text": "apraxia"}]'::jsonb, '["a"]', 'Receptive aphasia, involving Wernicke''s area, means the client hears the words but cannot understand them. Expressive aphasia involves understanding speech but being unable to produce words.'),
  ('stroke', 45, 'A client who had a stroke chooses words correctly and understands conversation, but the speech is slurred and hard to understand because of weak facial and tongue muscles. The nurse documents this finding as:', '[{"id": "a", "text": "receptive aphasia"}, {"id": "b", "text": "dysarthria"}, {"id": "c", "text": "agraphia"}, {"id": "d", "text": "alexia"}]'::jsonb, '["b"]', 'Dysarthria is the inability to speak clearly due to weak muscles, making speech hard to understand. Receptive aphasia is an inability to understand speech, which this client does not have.'),
  ('stroke', 46, 'A client who had a stroke has normal muscle strength in both arms but cannot comb the hair when asked to do so. The nurse recognizes this finding as:', '[{"id": "a", "text": "agnosia"}, {"id": "b", "text": "dysphagia"}, {"id": "c", "text": "apraxia"}, {"id": "d", "text": "hemianopia"}]'::jsonb, '["c"]', 'Apraxia is the inability to perform voluntary movements even though muscle function is normal. Agnosia is failure to recognize known objects or people.'),
  ('stroke', 47, 'A client who had a stroke is handed a familiar object, such as a fork, and cannot recognize what it is. The nurse documents this finding as:', '[{"id": "a", "text": "apraxia"}, {"id": "b", "text": "agraphia"}, {"id": "c", "text": "dysarthria"}, {"id": "d", "text": "agnosia"}]'::jsonb, '["d"]', 'Agnosia is the failure to understand sensations or recognize known objects or people. Apraxia is the inability to perform voluntary movements despite normal muscle function.'),
  ('stroke', 48, 'A client has had a stroke affecting the brain stem. Which assessment should the nurse monitor most closely based on the functions of this area?', '[{"id": "a", "text": "Breathing and heart rate"}, {"id": "b", "text": "Hearing and learning"}, {"id": "c", "text": "Color perception"}, {"id": "d", "text": "Music and art awareness"}]'::jsonb, '["a"]', 'The brain stem controls breathing, heart rate, and temperature. Color perception is an occipital lobe function, and hearing and learning are temporal lobe functions.'),
  ('stroke', 49, 'A client has had a stroke affecting the cerebellum. Which finding should the nurse expect?', '[{"id": "a", "text": "Loss of color perception"}, {"id": "b", "text": "Impaired balance and coordination"}, {"id": "c", "text": "Loss of hearing"}, {"id": "d", "text": "Inability to feel touch"}]'::jsonb, '["b"]', 'The cerebellum controls balance and coordination. Color perception is an occipital lobe function and hearing is a temporal lobe function.'),
  ('stroke', 50, 'The nurse is assessing a client with a right brain injury from a stroke. Which finding should the nurse expect?', '[{"id": "a", "text": "Agraphia"}, {"id": "b", "text": "Impaired math skills"}, {"id": "c", "text": "Denial about limitations"}, {"id": "d", "text": "Right-side hemiplegia"}]'::jsonb, '["c"]', 'Right brain injury causes denial about limitations, along with left-side weakness and neglect. Agraphia, impaired math skills, and right-side hemiplegia are findings of left brain injury.'),
  ('symp_para', 1, 'A client waiting for test results is anxious and has cool hands and feet. Which mechanism best explains the cool extremities?', '[{"id": "a", "text": "Sympathetic vasoconstriction"}, {"id": "b", "text": "Parasympathetic vasoconstriction"}, {"id": "c", "text": "Sympathetic vasodilation"}, {"id": "d", "text": "Parasympathetic vasodilation"}]'::jsonb, '["a"]', 'The sympathetic "C" includes cold extremities caused by vasoconstriction. Parasympathetic stimulation causes vasodilation.'),
  ('symp_para', 2, 'A client having a panic attack is diaphoretic. Which statement best explains the sweating?', '[{"id": "a", "text": "Parasympathetic stimulation of sweat glands"}, {"id": "b", "text": "Sympathetic stimulation of sweat glands"}, {"id": "c", "text": "Sympathetic inhibition of sweat glands"}, {"id": "d", "text": "Parasympathetic inhibition of sweat glands"}]'::jsonb, '["b"]', 'Sweat glands are stimulated by the sympathetic system, causing diaphoresis; the parasympathetic system has no effect on sweat glands.'),
  ('symp_para', 3, 'A client is resting quietly after eating lunch. Which digestive effect is expected while the parasympathetic system predominates?', '[{"id": "a", "text": "Digestion is inhibited"}, {"id": "b", "text": "Bowel sounds become hypoactive"}, {"id": "c", "text": "Digestion is stimulated"}, {"id": "d", "text": "GI motility decreases"}]'::jsonb, '["c"]', 'The parasympathetic system stimulates digestion, whereas the sympathetic system inhibits it.'),
  ('symp_para', 4, 'During a sudden stress response, which structure releases epinephrine and norepinephrine into the circulation?', '[{"id": "a", "text": "Bladder wall"}, {"id": "b", "text": "Sweat glands"}, {"id": "c", "text": "Bronchial muscle"}, {"id": "d", "text": "Adrenal medulla"}]'::jsonb, '["d"]', 'Under sympathetic stimulation the adrenal medulla releases epinephrine and norepinephrine.'),
  ('symp_para', 5, 'A nurse reviews autonomic control of the adrenal medulla. Which statement is accurate?', '[{"id": "a", "text": "Only the SNS triggers its hormone release"}, {"id": "b", "text": "Only the PNS triggers its hormone release"}, {"id": "c", "text": "Both divisions trigger its hormone release"}, {"id": "d", "text": "Neither division affects its hormone release"}]'::jsonb, '["a"]', 'The sympathetic system causes the adrenal medulla to release epinephrine and norepinephrine; the parasympathetic system has no direct action on it.'),
  ('symp_para', 6, 'A medication mimics the main sympathetic neurotransmitter. Which effect should the nurse anticipate?', '[{"id": "a", "text": "Decreased heart rate"}, {"id": "b", "text": "Increased heart rate"}, {"id": "c", "text": "Increased salivation"}, {"id": "d", "text": "Increased GI motility"}]'::jsonb, '["b"]', 'The SNS neurotransmitter is norepinephrine (adrenergic), and sympathetic stimulation increases heart rate. Decreased heart rate, salivation, and GI motility are PNS effects.'),
  ('symp_para', 7, 'A medication mimics acetylcholine. Which assessment finding would the nurse expect?', '[{"id": "a", "text": "Dilated pupils"}, {"id": "b", "text": "Increased heart rate"}, {"id": "c", "text": "Increased bowel sounds"}, {"id": "d", "text": "Bronchodilation"}]'::jsonb, '["c"]', 'Acetylcholine is the PNS (cholinergic) neurotransmitter, and the PNS stimulates digestion and GI motility. The other options are sympathetic effects.'),
  ('symp_para', 8, 'A drug is classified as a beta-adrenergic agent. The nurse recognizes that it acts on receptors belonging to which division?', '[{"id": "a", "text": "Parasympathetic"}, {"id": "b", "text": "Cholinergic"}, {"id": "c", "text": "Muscarinic"}, {"id": "d", "text": "Sympathetic"}]'::jsonb, '["d"]', 'Sympathetic receptors are adrenergic (alpha and beta). Cholinergic (muscarinic, nicotinic) receptors belong to the parasympathetic system.'),
  ('symp_para', 9, 'A nurse reads that a drug acts at nicotinic receptors. How should these receptors be classified?', '[{"id": "a", "text": "Cholinergic receptors of the PNS"}, {"id": "b", "text": "Adrenergic receptors of the SNS"}, {"id": "c", "text": "Adrenergic receptors of the PNS"}, {"id": "d", "text": "Cholinergic receptors of the SNS"}]'::jsonb, '["a"]', 'Parasympathetic receptors are cholinergic (muscarinic and nicotinic); sympathetic receptors are adrenergic (alpha and beta).'),
  ('symp_para', 10, 'A client is startled by a loud alarm. Which eye finding is expected during this response?', '[{"id": "a", "text": "Pupil constriction (miosis)"}, {"id": "b", "text": "Pupil dilation (mydriasis)"}, {"id": "c", "text": "Increased tearing"}, {"id": "d", "text": "No change in pupil size"}]'::jsonb, '["b"]', 'Sympathetic activation dilates the pupils (mydriasis); pupil constriction (miosis) is parasympathetic.'),
  ('symp_para', 11, 'A nurse assesses a client and notes miosis. This finding is most consistent with stimulation of which division?', '[{"id": "a", "text": "Sympathetic"}, {"id": "b", "text": "Adrenergic"}, {"id": "c", "text": "Parasympathetic"}, {"id": "d", "text": "Beta-adrenergic"}]'::jsonb, '["c"]', 'Pupil constriction (miosis) is a parasympathetic effect. Adrenergic stimulation is sympathetic and dilates the pupils.'),
  ('symp_para', 12, 'A client asks why albuterol relieves an asthma attack. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It blocks beta-2 receptors, dilating the airways.\""}, {"id": "b", "text": "\"It stimulates cholinergic receptors, dilating airways.\""}, {"id": "c", "text": "\"It blocks adrenergic receptors, dilating the airways.\""}, {"id": "d", "text": "\"It stimulates beta-2 receptors, dilating the airways.\""}]'::jsonb, '["d"]', 'Albuterol is a beta-2 agonist that stimulates the SNS, causing bronchodilation. Blocking adrenergic receptors would reduce sympathetic effects.'),
  ('symp_para', 13, 'A client with asthma receives albuterol. Which autonomic division does this medication stimulate?', '[{"id": "a", "text": "Sympathetic"}, {"id": "b", "text": "Parasympathetic"}, {"id": "c", "text": "Both divisions equally"}, {"id": "d", "text": "Neither division"}]'::jsonb, '["a"]', 'Albuterol is a beta-2 adrenergic agonist and stimulates the sympathetic division, opening the airways.'),
  ('symp_para', 14, 'A client receives a cholinergic agonist. Which change in the airways should the nurse anticipate?', '[{"id": "a", "text": "Bronchodilation"}, {"id": "b", "text": "Bronchoconstriction"}, {"id": "c", "text": "Bronchial relaxation"}, {"id": "d", "text": "No airway change"}]'::jsonb, '["b"]', 'Cholinergic agonists stimulate the PNS, and the PNS constricts the bronchi. Bronchodilation is a sympathetic effect.'),
  ('symp_para', 15, 'A client is in a state of extreme fear. Which digestive change is expected?', '[{"id": "a", "text": "Digestion is stimulated"}, {"id": "b", "text": "Bowel sounds become hyperactive"}, {"id": "c", "text": "Digestion is inhibited"}, {"id": "d", "text": "Defecation is promoted"}]'::jsonb, '["c"]', 'The sympathetic system inhibits digestion; stimulating digestion and defecation are parasympathetic effects.'),
  ('symp_para', 16, 'Which mechanism explains how parasympathetic stimulation produces urination?', '[{"id": "a", "text": "It relaxes the bladder wall and contracts the sphincter"}, {"id": "b", "text": "It contracts both the bladder wall and the sphincter"}, {"id": "c", "text": "It relaxes both the bladder wall and the sphincter"}, {"id": "d", "text": "It contracts the bladder wall and relaxes the sphincter"}]'::jsonb, '["d"]', 'The PNS contracts the bladder wall and relaxes the sphincter, allowing urination. The SNS relaxes the bladder wall, causing retention.'),
  ('symp_para', 17, 'A client has been under severe stress for hours and has not voided. Which effect best explains this?', '[{"id": "a", "text": "Sympathetic relaxation of the bladder wall"}, {"id": "b", "text": "Parasympathetic relaxation of the bladder wall"}, {"id": "c", "text": "Sympathetic contraction of the bladder wall"}, {"id": "d", "text": "Parasympathetic contraction of the bladder wall"}]'::jsonb, '["a"]', 'Sympathetic stimulation relaxes the bladder wall, causing urine retention. Bladder wall contraction is a parasympathetic effect that promotes urination.'),
  ('symp_para', 18, 'A client''s blood sugar rises during an emotionally stressful event. Which process does the sympathetic system use to produce this rise?', '[{"id": "a", "text": "Vasodilation"}, {"id": "b", "text": "Glycogenolysis"}, {"id": "c", "text": "Bronchoconstriction"}, {"id": "d", "text": "Lacrimation"}]'::jsonb, '["b"]', 'The sympathetic system increases blood sugar through glycogenolysis.'),
  ('symp_para', 19, 'A nurse reviews the effects of strong parasympathetic stimulation. What effect on blood sugar should be expected?', '[{"id": "a", "text": "A marked increase"}, {"id": "b", "text": "A marked decrease"}, {"id": "c", "text": "No major effect"}, {"id": "d", "text": "An increase via glycogenolysis"}]'::jsonb, '["c"]', 'The parasympathetic system has no major effect on blood sugar; the sympathetic system increases it via glycogenolysis.'),
  ('symp_para', 20, 'A client with hypertension is started on propranolol. Which findings indicate the expected therapeutic response?', '[{"id": "a", "text": "Higher heart rate and higher blood pressure"}, {"id": "b", "text": "Lower heart rate and higher blood pressure"}, {"id": "c", "text": "Higher heart rate and lower blood pressure"}, {"id": "d", "text": "Lower heart rate and lower blood pressure"}]'::jsonb, '["d"]', 'Beta blockers such as propranolol block the SNS, decreasing heart rate and blood pressure.'),
  ('symp_para', 21, 'A nurse categorizes metoprolol by its autonomic action. Which category is correct?', '[{"id": "a", "text": "Sympathetic blocker"}, {"id": "b", "text": "Sympathetic stimulant"}, {"id": "c", "text": "Parasympathetic stimulant"}, {"id": "d", "text": "Parasympathetic blocker"}]'::jsonb, '["a"]', 'Beta blockers such as metoprolol are classified as SNS blockers, decreasing heart rate and blood pressure.'),
  ('symp_para', 22, 'A client receives epinephrine. Which set of findings should the nurse anticipate?', '[{"id": "a", "text": "Decreased HR, decreased BP, bronchodilation"}, {"id": "b", "text": "Increased HR, increased BP, bronchodilation"}, {"id": "c", "text": "Increased HR, decreased BP, bronchoconstriction"}, {"id": "d", "text": "Decreased HR, increased BP, bronchoconstriction"}]'::jsonb, '["b"]', 'Adrenergic agonists such as epinephrine stimulate the SNS, increasing heart rate and blood pressure and causing bronchodilation.'),
  ('symp_para', 23, 'Which pair of medications belongs to the same class of SNS-stimulating drugs?', '[{"id": "a", "text": "Metoprolol and albuterol"}, {"id": "b", "text": "Atropine and epinephrine"}, {"id": "c", "text": "Epinephrine and albuterol"}, {"id": "d", "text": "Bethanechol and propranolol"}]'::jsonb, '["c"]', 'Epinephrine and albuterol are both adrenergic agonists that stimulate the SNS. Metoprolol is a beta blocker, atropine is an anticholinergic, and bethanechol is a cholinergic agonist.'),
  ('symp_para', 24, 'A postoperative client with urinary retention is prescribed bethanechol. Which outcome indicates the drug is effective?', '[{"id": "a", "text": "The client''s mouth is dry"}, {"id": "b", "text": "The client''s heart rate rises"}, {"id": "c", "text": "The client''s pupils dilate"}, {"id": "d", "text": "The client voids"}]'::jsonb, '["d"]', 'Bethanechol is a cholinergic agonist that stimulates the PNS, promoting urination, digestion, and GI motility. Dry mouth and increased heart rate are anticholinergic effects.'),
  ('symp_para', 25, 'A client taking bethanechol is assessed. Which gastrointestinal finding is an expected effect?', '[{"id": "a", "text": "Increased GI motility"}, {"id": "b", "text": "Decreased GI motility"}, {"id": "c", "text": "Inhibited digestion"}, {"id": "d", "text": "Hypoactive bowel sounds"}]'::jsonb, '["a"]', 'Cholinergic agonists such as bethanechol stimulate the PNS, increasing GI motility and digestion. Decreased motility is an anticholinergic and sympathetic effect.'),
  ('symp_para', 26, 'A client receives scopolamine. Which effect on body secretions should the nurse expect?', '[{"id": "a", "text": "Increased secretions"}, {"id": "b", "text": "Decreased secretions"}, {"id": "c", "text": "Increased tearing"}, {"id": "d", "text": "Increased salivation"}]'::jsonb, '["b"]', 'Anticholinergics such as scopolamine block the PNS, decreasing secretions. Increased salivation and tearing are PNS (SLUDD) effects.'),
  ('symp_para', 27, 'The nurse explains how atropine raises the heart rate of a client with bradycardia. Which explanation is accurate?', '[{"id": "a", "text": "It increases parasympathetic vagal tone"}, {"id": "b", "text": "It blocks adrenergic receptors"}, {"id": "c", "text": "It blocks parasympathetic vagal tone"}, {"id": "d", "text": "It mimics acetylcholine at the heart"}]'::jsonb, '["c"]', 'Atropine is anticholinergic; it blocks PNS (vagal tone), which allows the SNS to increase heart rate. Mimicking acetylcholine would slow the heart.'),
  ('symp_para', 28, 'An older adult received atropine and is unable to void several hours later. How should the nurse interpret this?', '[{"id": "a", "text": "A cholinergic drug effect"}, {"id": "b", "text": "A sign of PNS stimulation"}, {"id": "c", "text": "An unrelated new problem"}, {"id": "d", "text": "An expected anticholinergic effect"}]'::jsonb, '["d"]', 'Anticholinergics such as atropine block the PNS, producing urinary retention. PNS stimulation would promote urination instead.'),
  ('symp_para', 29, 'After receiving an anticholinergic medication, a client is assessed. Which bowel finding is expected?', '[{"id": "a", "text": "Decreased bowel sounds"}, {"id": "b", "text": "Hyperactive bowel sounds"}, {"id": "c", "text": "Increased defecation"}, {"id": "d", "text": "Abdominal cramping with diarrhea"}]'::jsonb, '["a"]', 'Anticholinergics block the PNS and decrease GI motility. Increased bowel activity and defecation are PNS effects.'),
  ('symp_para', 30, 'A client has hyperactive bowel sounds and reports urinary urgency. These findings indicate stimulation of which division?', '[{"id": "a", "text": "Sympathetic"}, {"id": "b", "text": "Parasympathetic"}, {"id": "c", "text": "Adrenergic"}, {"id": "d", "text": "Beta-adrenergic"}]'::jsonb, '["b"]', 'Increased bowel sounds plus urinary urgency indicate PNS stimulation, which promotes GI motility and bladder contraction.'),
  ('symp_para', 31, 'A client is receiving a drug that stimulates the parasympathetic system. Which finding is expected?', '[{"id": "a", "text": "Dry mouth"}, {"id": "b", "text": "Urinary retention"}, {"id": "c", "text": "Increased salivation"}, {"id": "d", "text": "Dilated pupils"}]'::jsonb, '["c"]', 'Salivation is the "S" of SLUDD, a parasympathetic effect. Dry mouth, urinary retention, and dilated pupils are sympathetic effects.'),
  ('symp_para', 32, 'A client has excessive tearing after receiving a cholinergic drug. This finding corresponds to which part of the SLUDD mnemonic?', '[{"id": "a", "text": "Salivation"}, {"id": "b", "text": "Urination"}, {"id": "c", "text": "Defecation"}, {"id": "d", "text": "Lacrimation"}]'::jsonb, '["d"]', 'In SLUDD, "L" stands for lacrimation (tears), a parasympathetic effect.'),
  ('symp_para', 33, 'A nurse monitors a client for parasympathetic (SLUDD) effects. Which finding is NOT part of this pattern?', '[{"id": "a", "text": "Dry mouth"}, {"id": "b", "text": "Salivation"}, {"id": "c", "text": "Defecation"}, {"id": "d", "text": "Urination"}]'::jsonb, '["a"]', 'SLUDD lists PNS effects: salivation, lacrimation, urination, digestion, and defecation. Dry mouth is a sympathetic effect.'),
  ('symp_para', 34, 'The nurse teaches about the sympathetic "A-B-C" mnemonic. Which student statement indicates a need for further teaching?', '[{"id": "a", "text": "\"A stands for adrenergic.\""}, {"id": "b", "text": "\"B stands for blood sugar decreasing.\""}, {"id": "c", "text": "\"B includes bronchodilation.\""}, {"id": "d", "text": "\"C includes increased heart rate.\""}]'::jsonb, '["b"]', 'In the sympathetic A-B-C mnemonic, B stands for bronchodilation, BP increase, and blood sugar increase, so a decrease in blood sugar is incorrect.'),
  ('symp_para', 35, 'Which statement best describes the overall role of the sympathetic nervous system?', '[{"id": "a", "text": "It calms the body and conserves energy"}, {"id": "b", "text": "It promotes normal digestion and urination"}, {"id": "c", "text": "It activates the body for emergencies and stress"}, {"id": "d", "text": "It slows the heart during rest"}]'::jsonb, '["c"]', 'The SNS (fight or flight) activates the body for emergencies and stress; calming the body and conserving energy describes the PNS.'),
  ('symp_para', 36, 'Which statement best describes the overall role of the parasympathetic nervous system?', '[{"id": "a", "text": "It prepares the body for emergencies"}, {"id": "b", "text": "It raises blood sugar during stress"}, {"id": "c", "text": "It dilates the pupils during stress"}, {"id": "d", "text": "It calms the body and conserves energy"}]'::jsonb, '["d"]', 'The PNS (rest and digest) calms the body, conserves energy, and promotes normal functions. Preparing for emergencies is the SNS role.'),
  ('symp_para', 37, 'A client preparing to give a speech reports a dry mouth and a racing heart. These findings reflect activation of which division?', '[{"id": "a", "text": "Sympathetic"}, {"id": "b", "text": "Parasympathetic"}, {"id": "c", "text": "Cholinergic"}, {"id": "d", "text": "Muscarinic"}]'::jsonb, '["a"]', 'The SNS (fight or flight) causes increased heart rate and dry mouth. Cholinergic and muscarinic activity is parasympathetic.'),
  ('symp_para', 38, 'A client practices deep relaxation before bed. Which heart rate change is expected as the parasympathetic system predominates?', '[{"id": "a", "text": "Heart rate increases"}, {"id": "b", "text": "Heart rate decreases"}, {"id": "c", "text": "Heart rate is unaffected"}, {"id": "d", "text": "Heart rate becomes irregular"}]'::jsonb, '["b"]', 'The parasympathetic system decreases heart rate; the sympathetic system increases it.'),
  ('symp_para', 39, 'Which mechanism explains a fall in blood pressure during parasympathetic stimulation?', '[{"id": "a", "text": "Vasoconstriction"}, {"id": "b", "text": "Glycogenolysis"}, {"id": "c", "text": "Vasodilation"}, {"id": "d", "text": "Bronchodilation"}]'::jsonb, '["c"]', 'The PNS decreases blood pressure through vasodilation; the SNS increases blood pressure through vasoconstriction.'),
  ('symp_para', 40, 'A client''s blood pressure is elevated during an acute stress reaction. Which mechanism is responsible?', '[{"id": "a", "text": "Vasodilation"}, {"id": "b", "text": "Bronchoconstriction"}, {"id": "c", "text": "Increased GI motility"}, {"id": "d", "text": "Vasoconstriction"}]'::jsonb, '["d"]', 'The SNS increases blood pressure through vasoconstriction; vasodilation lowers blood pressure and is a PNS effect.'),
  ('symp_para', 41, 'A nurse explains the autonomic nervous system to a client. Which statement is accurate?', '[{"id": "a", "text": "Its two branches oppose each other to keep balance"}, {"id": "b", "text": "Its two branches work in the same direction"}, {"id": "c", "text": "It controls only voluntary movement"}, {"id": "d", "text": "It controls heart rate but not pupil size"}]'::jsonb, '["a"]', 'The ANS controls involuntary functions such as heart rate, digestion, respiration, and pupil size, and its two opposing branches keep the body in balance.'),
  ('symp_para', 42, 'Which client is the most appropriate candidate for atropine?', '[{"id": "a", "text": "A client with a rapid heart rate"}, {"id": "b", "text": "A client with a slow heart rate"}, {"id": "c", "text": "A client with urinary retention"}, {"id": "d", "text": "A client with decreased bowel sounds"}]'::jsonb, '["b"]', 'Atropine is an anticholinergic that blocks the PNS to increase heart rate and is used in bradycardia. It causes urinary retention and decreased GI motility, so it would worsen those problems.'),
  ('symp_para', 43, 'A drug blocks the parasympathetic nervous system. Which heart rate change should the nurse expect?', '[{"id": "a", "text": "Decrease"}, {"id": "b", "text": "No change"}, {"id": "c", "text": "Increase"}, {"id": "d", "text": "Irregular slowing"}]'::jsonb, '["c"]', 'Anticholinergics block the PNS and increase heart rate.'),
  ('symp_para', 44, 'A client with asthma has been given albuterol. Which assessment finding best indicates the expected effect?', '[{"id": "a", "text": "Airways narrow with more wheezing"}, {"id": "b", "text": "Bowel sounds become hyperactive"}, {"id": "c", "text": "Pupils become constricted"}, {"id": "d", "text": "Airways open with easier breathing"}]'::jsonb, '["d"]', 'Albuterol stimulates the sympathetic division, causing bronchodilation that opens the airways.'),
  ('symp_para', 45, 'The nurse reviews parasympathetic effects with a student. Which student statement indicates a need for further teaching?', '[{"id": "a", "text": "\"The PNS causes urinary retention.\""}, {"id": "b", "text": "\"The PNS promotes defecation.\""}, {"id": "c", "text": "\"The PNS increases salivation.\""}, {"id": "d", "text": "\"The PNS slows the heart rate.\""}]'::jsonb, '["a"]', 'The PNS promotes urination by contracting the bladder wall; urinary retention is a sympathetic effect.'),
  ('symp_para', 46, 'Which neurotransmitter pairing correctly matches each autonomic division?', '[{"id": "a", "text": "SNS: acetylcholine; PNS: norepinephrine"}, {"id": "b", "text": "SNS: norepinephrine; PNS: acetylcholine"}, {"id": "c", "text": "SNS: acetylcholine; PNS: epinephrine"}, {"id": "d", "text": "SNS and PNS: acetylcholine only"}]'::jsonb, '["b"]', 'The SNS uses norepinephrine (plus epinephrine from the adrenal medulla), and the PNS uses acetylcholine.'),
  ('symp_para', 47, 'A client is frightened during a procedure. Which combination of findings should the nurse expect?', '[{"id": "a", "text": "Decreased heart rate and bronchodilation"}, {"id": "b", "text": "Increased heart rate and bronchoconstriction"}, {"id": "c", "text": "Increased heart rate and bronchodilation"}, {"id": "d", "text": "Decreased heart rate and bronchoconstriction"}]'::jsonb, '["c"]', 'Sympathetic (fight-or-flight) activation increases heart rate and dilates the bronchi; decreased heart rate and bronchoconstriction are PNS effects.'),
  ('symp_para', 48, 'A client receiving a cholinergic agonist reports several loose bowel movements today. How should the nurse interpret this finding?', '[{"id": "a", "text": "An expected sympathetic effect"}, {"id": "b", "text": "An expected anticholinergic effect"}, {"id": "c", "text": "An expected adrenergic effect"}, {"id": "d", "text": "An expected parasympathetic effect"}]'::jsonb, '["d"]', 'Defecation is part of SLUDD, the parasympathetic effects produced by cholinergic stimulation. Anticholinergic and sympathetic effects decrease GI motility.'),
  ('symp_para', 49, 'A medication is described as an adrenergic agonist. Which neurotransmitters does it mimic?', '[{"id": "a", "text": "Norepinephrine and epinephrine"}, {"id": "b", "text": "Acetylcholine and epinephrine"}, {"id": "c", "text": "Acetylcholine alone"}, {"id": "d", "text": "Acetylcholine and norepinephrine"}]'::jsonb, '["a"]', 'In the sympathetic A-B-C mnemonic, A stands for adrenergic (norepinephrine/epinephrine). Acetylcholine is the cholinergic PNS neurotransmitter.'),
  ('symp_para', 50, 'A client is given an anticholinergic. Which category describes this drug''s autonomic action?', '[{"id": "a", "text": "Parasympathetic stimulant"}, {"id": "b", "text": "Parasympathetic blocker"}, {"id": "c", "text": "Sympathetic blocker"}, {"id": "d", "text": "Sympathetic stimulant"}]'::jsonb, '["b"]', 'Anticholinergics such as atropine and scopolamine are classified as PNS blockers; cholinergic agonists stimulate the PNS.'),
  ('vertigo', 1, 'A client with Ménière''s disease asks why salt intake must be limited. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Sodium dries out the inner ear"}, {"id": "b", "text": "Sodium makes nausea worse"}, {"id": "c", "text": "Sodium blocks the effect of meclizine"}, {"id": "d", "text": "Sodium increases fluid retention in the inner ear"}]'::jsonb, '["d"]', 'High sodium increases endolymph fluid retention, so a low-sodium diet reduces endolymph retention. The other explanations are not reasons given for sodium restriction.'),
  ('vertigo', 2, 'The nurse is assessing a client with suspected Ménière''s disease. Which combination of findings represents the classic triad?', '[{"id": "a", "text": "Vertigo, nystagmus, and severe fatigue"}, {"id": "b", "text": "Tinnitus, nausea, and unsteady balance"}, {"id": "c", "text": "Episodic vertigo, tinnitus, and fluctuating unilateral hearing loss"}, {"id": "d", "text": "Ear fullness, vomiting, and bilateral conductive hearing loss"}]'::jsonb, '["c"]', 'The classic triad is episodic vertigo, tinnitus, and fluctuating unilateral sensorineural hearing loss. Nystagmus, nausea, ataxia, and fatigue are additional symptoms during or after episodes, not the triad.'),
  ('vertigo', 3, 'The nurse is reviewing lifestyle triggers with a client who has Ménière''s disease. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I''ll turn my head quickly to test my balance.\""}, {"id": "b", "text": "\"Staying up late won''t change my symptoms.\""}, {"id": "c", "text": "\"Stress has nothing to do with my attacks.\""}, {"id": "d", "text": "\"Getting enough sleep may help reduce attacks.\""}]'::jsonb, '["d"]', 'Fatigue or sleep deprivation is a lifestyle trigger, so adequate sleep may reduce attacks. Rapid head movements and stress are also triggers, making the other statements incorrect.'),
  ('vertigo', 4, 'A client with newly diagnosed Ménière''s disease asks which daily habit may be worsening the symptoms. Which habit should the nurse identify?', '[{"id": "a", "text": "Eating fresh fruit at breakfast"}, {"id": "b", "text": "Taking a short walk after dinner"}, {"id": "c", "text": "Using nicotine gum during the day"}, {"id": "d", "text": "Drinking water throughout the day"}]'::jsonb, '["c"]', 'Tobacco/nicotine is a dietary trigger that worsens Ménière''s symptoms. The other habits are not listed as triggers.'),
  ('vertigo', 5, 'A client with Ménière''s disease is considering surgery after medications have failed. Which procedure is associated with permanent hearing loss?', '[{"id": "a", "text": "Endolymphatic shunt"}, {"id": "b", "text": "Vestibular nerve section"}, {"id": "c", "text": "Electronystagmography"}, {"id": "d", "text": "Labyrinthectomy"}]'::jsonb, '["d"]', 'Labyrinthectomy stops vertigo but causes permanent hearing loss. The endolymphatic shunt and vestibular nerve section both preserve hearing.'),
  ('vertigo', 6, 'The nurse is teaching a client who is starting meclizine for vertigo. Which adverse effect should the nurse include in the teaching?', '[{"id": "a", "text": "Low potassium levels"}, {"id": "b", "text": "Permanent hearing loss"}, {"id": "c", "text": "Increased inner ear fluid"}, {"id": "d", "text": "Drowsiness"}]'::jsonb, '["d"]', 'Meclizine reduces the spinning sensation but causes drowsiness. Potassium monitoring is associated with the diuretic hydrochlorothiazide, not meclizine.'),
  ('vertigo', 7, 'A provider orders an MRI for a client with recurrent vertigo. The client asks why it is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It measures the degree of your hearing loss.\""}, {"id": "b", "text": "\"It rules out tumors, stroke, or other brain causes.\""}, {"id": "c", "text": "\"It records the involuntary movements of your eyes.\""}, {"id": "d", "text": "\"It drains extra fluid from your inner ear.\""}]'::jsonb, '["b"]', 'MRI/CT is used to rule out tumors, stroke, or other CNS pathology. Measuring hearing loss is the purpose of an audiogram.'),
  ('vertigo', 8, 'The nurse has taught a client with Ménière''s disease about lifestyle changes. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''m going to cut back on coffee and soda.\""}, {"id": "b", "text": "\"A glass of wine each night should help me relax.\""}, {"id": "c", "text": "\"I''ll read food labels to check the sodium content.\""}, {"id": "d", "text": "\"I''ve made a plan to quit smoking cigarettes.\""}]'::jsonb, '["b"]', 'Clients with Ménière''s disease should avoid caffeine, alcohol, and tobacco, so nightly wine shows a need for more teaching. Cutting back on coffee and soda, limiting sodium, and quitting smoking are all correct.'),
  ('vertigo', 9, 'A client with Ménière''s disease is scheduled for a vestibular nerve section and asks, ''Will I lose my hearing?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, hearing in that ear will be lost permanently.\""}, {"id": "b", "text": "\"No, this procedure is designed to preserve hearing.\""}, {"id": "c", "text": "\"Yes, hearing will be lost in both of your ears.\""}, {"id": "d", "text": "\"Yes, but only until the balance organs regrow.\""}]'::jsonb, '["b"]', 'Vestibular nerve section cuts the vestibular nerve to stop vertigo signals while preserving hearing. Permanent hearing loss is associated with labyrinthectomy.'),
  ('vertigo', 10, 'During an acute Ménière''s attack, the nurse observes that the client''s eyes are making involuntary rapid movements. How should the nurse document this finding?', '[{"id": "a", "text": "Ataxia"}, {"id": "b", "text": "Tinnitus"}, {"id": "c", "text": "Vertigo"}, {"id": "d", "text": "Nystagmus"}]'::jsonb, '["d"]', 'Nystagmus is involuntary rapid eye movement that can occur during episodes. Ataxia refers to unsteady balance, not eye movement.'),
  ('vertigo', 11, 'A client with Ménière''s disease is reviewing a beverage menu with the nurse. Which beverage should the nurse advise the client to avoid?', '[{"id": "a", "text": "Water"}, {"id": "b", "text": "Low-fat milk"}, {"id": "c", "text": "Iced tea"}, {"id": "d", "text": "Apple juice"}]'::jsonb, '["c"]', 'Caffeine, including coffee, tea, and sodas, is a dietary trigger that worsens Ménière''s symptoms. The other beverages are not listed as triggers.'),
  ('vertigo', 12, 'A client is scheduled for an endolymphatic shunt and asks what the procedure does. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It drains extra fluid from the inner ear, and hearing is preserved.\""}, {"id": "b", "text": "\"It removes the balance organs, and hearing is permanently lost.\""}, {"id": "c", "text": "\"It cuts the hearing nerve, and hearing is permanently lost.\""}, {"id": "d", "text": "\"It removes the balance organs, and hearing is preserved.\""}]'::jsonb, '["a"]', 'An endolymphatic shunt drains excess endolymph fluid from the inner ear and preserves hearing. Removing the balance organs describes labyrinthectomy, which causes permanent hearing loss.'),
  ('vertigo', 13, 'A client with Ménière''s disease asks when corticosteroids might be used. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They are taken daily for life as the first-line drug.\""}, {"id": "b", "text": "\"They may be given during acute episodes if prescribed.\""}, {"id": "c", "text": "\"They are only used after a labyrinthectomy.\""}, {"id": "d", "text": "\"They are given to replace lost potassium.\""}]'::jsonb, '["b"]', 'Corticosteroids may reduce inflammation and are given during acute episodes if prescribed. Meclizine, not a corticosteroid, is the first-line drug.'),
  ('vertigo', 14, 'A client in an acute Ménière''s attack is lying in bed. Which nursing instruction is most appropriate?', '[{"id": "a", "text": "\"Try to keep your head and eyes as still as possible.\""}, {"id": "b", "text": "\"Reading a book may help take your mind off the dizziness.\""}, {"id": "c", "text": "\"Walking in the hallway will help your balance return.\""}, {"id": "d", "text": "\"Turning your head side to side can help it pass sooner.\""}]'::jsonb, '["a"]', 'During acute attacks, head and eye movement should be minimized. Walking during an attack increases fall risk, and rapid head movements are triggers.'),
  ('vertigo', 15, 'The nurse is reinforcing discharge teaching with a client who has Ménière''s disease. Which instruction should the nurse include?', '[{"id": "a", "text": "\"Perform vestibular rehab exercises for balance.\""}, {"id": "b", "text": "\"Increase sodium intake to stabilize ear fluid.\""}, {"id": "c", "text": "\"Change positions quickly to train your balance.\""}, {"id": "d", "text": "\"Stop the diuretic once your symptoms ease.\""}]'::jsonb, '["a"]', 'Patient teaching includes vestibular rehab exercises for balance. Sodium should be restricted, positions changed slowly, and diuretics taken consistently.'),
  ('vertigo', 16, 'A client with Ménière''s disease is prescribed hydrochlorothiazide (HCTZ). Which laboratory value should the nurse monitor?', '[{"id": "a", "text": "Blood glucose"}, {"id": "b", "text": "Hemoglobin"}, {"id": "c", "text": "Potassium"}, {"id": "d", "text": "Platelet count"}]'::jsonb, '["c"]', 'HCTZ reduces endolymph fluid pressure, and electrolytes, specifically potassium, must be monitored. The other values are not identified for monitoring with HCTZ.'),
  ('vertigo', 17, 'The nurse is reviewing self-care during attacks with a client who has Ménière''s disease. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I''ll watch TV to distract myself during an attack.\""}, {"id": "b", "text": "\"I''ll turn off the lights and the TV during an attack.\""}, {"id": "c", "text": "\"I''ll open the blinds for sunlight during an attack.\""}, {"id": "d", "text": "\"I''ll play loud music to cover the ringing in my ear.\""}]'::jsonb, '["b"]', 'Bright lights and loud sounds during attacks worsen symptoms, so a quiet, dark environment is recommended. Television, sunlight, and loud music add light and sound triggers.'),
  ('vertigo', 18, 'The nurse is teaching a client with Ménière''s disease about dietary sodium. Which daily limit should the nurse include?', '[{"id": "a", "text": "Less than 2,000 mg per day"}, {"id": "b", "text": "Less than 4,000 mg per day"}, {"id": "c", "text": "Less than 5,000 mg per day"}, {"id": "d", "text": "No limit while taking a diuretic"}]'::jsonb, '["a"]', 'Teaching includes a low-sodium diet limited to less than 2,000 mg/day to reduce endolymph retention. Taking a diuretic does not remove the need for sodium restriction.'),
  ('vertigo', 19, 'A client with Ménière''s disease has been taking meclizine for 1 week. Which client report best indicates that the medication is effective?', '[{"id": "a", "text": "\"I have been sleeping more than usual.\""}, {"id": "b", "text": "\"I have been urinating more often.\""}, {"id": "c", "text": "\"The spinning feeling has lessened.\""}, {"id": "d", "text": "\"My potassium level was checked.\""}]'::jsonb, '["c"]', 'Meclizine reduces the spinning sensation, so lessened spinning shows effectiveness. Increased sleep reflects its drowsiness side effect rather than therapeutic effect.'),
  ('vertigo', 20, 'The nurse is teaching home safety to a client with recurrent vertigo. Which modification should the nurse recommend?', '[{"id": "a", "text": "Remove throw rugs and other trip hazards"}, {"id": "b", "text": "Add throw rugs to cushion potential falls"}, {"id": "c", "text": "Walk without help to build up balance"}, {"id": "d", "text": "Change positions quickly when getting up"}]'::jsonb, '["a"]', 'Fall prevention includes removing trip hazards and rugs. Adding rugs creates trip hazards, and positions should be changed slowly rather than quickly.'),
  ('vertigo', 21, 'A client with Ménière''s disease reports vertigo, ringing in one ear, and fluctuating hearing loss. Which additional symptom is commonly considered a fourth associated symptom?', '[{"id": "a", "text": "Severe headache"}, {"id": "b", "text": "Ear fullness or pressure"}, {"id": "c", "text": "Facial numbness"}, {"id": "d", "text": "Blurred vision"}]'::jsonb, '["b"]', 'Ear fullness or pressure is added as a fourth associated symptom to the classic triad. Headache, facial numbness, and blurred vision are not listed symptoms of Ménière''s disease.'),
  ('vertigo', 22, 'A client with Ménière''s disease is vomiting repeatedly during an attack. The nurse recognizes that this places the client at increased risk for which complication?', '[{"id": "a", "text": "Permanent hearing loss"}, {"id": "b", "text": "Ear fullness"}, {"id": "c", "text": "Aspiration"}, {"id": "d", "text": "Nystagmus"}]'::jsonb, '["c"]', 'Nausea and vomiting are common during attacks and create an aspiration risk. Permanent hearing loss is associated with labyrinthectomy, not with vomiting.'),
  ('vertigo', 23, 'The nurse is caring for a client admitted during an acute vertigo attack. Which nursing action should the nurse take first?', '[{"id": "a", "text": "Teach the low-sodium diet"}, {"id": "b", "text": "Schedule vestibular rehab"}, {"id": "c", "text": "Review the audiogram results"}, {"id": "d", "text": "Implement fall precautions"}]'::jsonb, '["d"]', 'Falls are the number one safety concern, so fall precautions always come first with vertigo. Diet teaching, rehab, and test review are lower priorities during an acute attack.'),
  ('vertigo', 24, 'The nurse is caring for a client during an acute episode of Ménière''s disease. Which finding should the nurse expect?', '[{"id": "a", "text": "Nausea and vomiting with unsteady balance"}, {"id": "b", "text": "Fever with stiffness of the neck"}, {"id": "c", "text": "Permanent hearing loss in both ears"}, {"id": "d", "text": "Facial droop with slurred speech"}]'::jsonb, '["a"]', 'Nausea, vomiting, and ataxia (unsteady balance) are common during Ménière''s episodes. Hearing loss in Ménière''s is fluctuating and typically one-sided, not permanent in both ears.'),
  ('vertigo', 25, 'The nurse reviews the hearing assessment of a client with Ménière''s disease. Which description of hearing loss is expected?', '[{"id": "a", "text": "Fluctuating, one-sided sensorineural loss"}, {"id": "b", "text": "Constant, two-sided conductive loss"}, {"id": "c", "text": "Fluctuating, two-sided conductive loss"}, {"id": "d", "text": "Constant, one-sided conductive loss"}]'::jsonb, '["a"]', 'The hearing loss of Ménière''s disease is sensorineural, fluctuating, and typically one-sided. Conductive hearing loss is the type Rinne and Weber testing distinguishes from it.'),
  ('vertigo', 26, 'A client with Ménière''s disease asks when surgery becomes an option. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Surgery is done as soon as the diagnosis is made.\""}, {"id": "b", "text": "\"Surgery is done when the hearing loss is mild.\""}, {"id": "c", "text": "\"Surgery is done before any diet changes are tried.\""}, {"id": "d", "text": "\"Surgery is considered when medications have failed.\""}]'::jsonb, '["d"]', 'Surgical options are considered if medications fail. Diet changes and medications are tried first rather than proceeding directly to surgery.'),
  ('vertigo', 27, 'A client newly diagnosed with Ménière''s disease asks what is causing the symptoms. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "A tumor pressing on the hearing nerve"}, {"id": "b", "text": "Excess fluid buildup in the inner ear labyrinth"}, {"id": "c", "text": "Too little fluid within the inner ear labyrinth"}, {"id": "d", "text": "A small stroke in the balance center of the brain"}]'::jsonb, '["b"]', 'Ménière''s disease is caused by excess endolymph fluid buildup in the labyrinth, which interferes with hearing and balance signals. Tumors and stroke are what imaging is used to rule out, not the cause of Ménière''s.'),
  ('vertigo', 28, 'A client with Ménière''s disease describes recurrent spinning episodes. Which episode duration is most consistent with this diagnosis?', '[{"id": "a", "text": "A few seconds at a time"}, {"id": "b", "text": "Constant for several weeks"}, {"id": "c", "text": "Less than one minute"}, {"id": "d", "text": "20 minutes to several hours"}]'::jsonb, '["d"]', 'Episodic vertigo in Ménière''s disease consists of recurrent spinning episodes lasting 20 minutes to several hours. Constant symptoms for weeks do not fit the episodic pattern of the disease.'),
  ('vertigo', 29, 'A client with Ménière''s disease asks when a labyrinthectomy would be considered. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is the first treatment tried after diagnosis.\""}, {"id": "b", "text": "\"It is chosen when keeping your hearing is the goal.\""}, {"id": "c", "text": "\"It is a last resort when other treatments fail.\""}, {"id": "d", "text": "\"It is performed during each acute attack.\""}]'::jsonb, '["c"]', 'Labyrinthectomy removes the labyrinth and is a last resort. It causes permanent hearing loss, so it is not chosen to preserve hearing.'),
  ('vertigo', 30, 'A client with vertigo is preparing to get out of bed in the morning. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Stand up quickly to shorten the time you feel dizzy.\""}, {"id": "b", "text": "\"Sit on the edge of the bed for a moment before standing.\""}, {"id": "c", "text": "\"Turn your head side to side before you get up.\""}, {"id": "d", "text": "\"Stand and walk right away to restore your balance.\""}]'::jsonb, '["b"]', 'Clients should turn slowly and avoid sudden movements, sitting on the edge of the bed before standing. Rapid head movements and position changes are triggers that worsen symptoms.'),
  ('vertigo', 31, 'A client with Ménière''s disease asks, ''Why am I taking a water pill for an ear problem?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It lowers blood pressure to prevent a stroke.\""}, {"id": "b", "text": "\"It controls the nausea and vomiting.\""}, {"id": "c", "text": "\"It sedates you so the spinning stops.\""}, {"id": "d", "text": "\"It reduces fluid pressure in your inner ear.\""}]'::jsonb, '["d"]', 'Diuretics such as HCTZ are used to reduce inner ear fluid pressure. Nausea and vomiting are controlled by antiemetics such as ondansetron and promethazine.'),
  ('vertigo', 32, 'A client with Ménière''s disease reports feeling exhausted for the rest of the day after a vertigo attack. How should the nurse interpret this report?', '[{"id": "a", "text": "It suggests a stroke and needs urgent imaging"}, {"id": "b", "text": "It is an expected symptom after an episode"}, {"id": "c", "text": "It indicates a toxic reaction to the diuretic"}, {"id": "d", "text": "It means a labyrinthectomy is now required"}]'::jsonb, '["b"]', 'Severe fatigue after episodes is listed among the additional symptoms of Ménière''s disease. Labyrinthectomy is a last resort when medications fail, not a response to post-episode fatigue.'),
  ('vertigo', 33, 'A client reports a roaring sound in the left ear. The nurse recognizes this symptom as which part of the Ménière''s triad?', '[{"id": "a", "text": "Vertigo"}, {"id": "b", "text": "Nystagmus"}, {"id": "c", "text": "Tinnitus"}, {"id": "d", "text": "Ataxia"}]'::jsonb, '["c"]', 'Tinnitus is ringing, buzzing, or roaring in the affected ear and is part of the classic triad. Vertigo is a spinning sensation rather than a sound.'),
  ('vertigo', 34, 'A client is scheduled for electronystagmography (ENG) and asks what the test is for. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It evaluates your balance function and eye movements.\""}, {"id": "b", "text": "\"It rules out a tumor or stroke in the brain.\""}, {"id": "c", "text": "\"It separates nerve-type from conductive hearing loss.\""}, {"id": "d", "text": "\"It measures how well you hear low-pitched sounds.\""}]'::jsonb, '["a"]', 'ENG evaluates balance function and nystagmus. Ruling out tumors or stroke is the purpose of MRI/CT, not ENG.'),
  ('vertigo', 35, 'A client with suspected Ménière''s disease has an audiogram. Which result would the nurse expect to see?', '[{"id": "a", "text": "High-frequency hearing loss"}, {"id": "b", "text": "Normal hearing in both ears"}, {"id": "c", "text": "Bilateral conductive hearing loss"}, {"id": "d", "text": "Low-frequency hearing loss"}]'::jsonb, '["d"]', 'The audiogram assesses hearing loss, and low-frequency hearing loss is characteristic of Ménière''s disease. The hearing loss is sensorineural, not conductive.'),
  ('vertigo', 36, 'A client is admitted during an acute Ménière''s attack with severe vertigo. Which nursing priority should guide the plan of care?', '[{"id": "a", "text": "Disturbed sleep pattern"}, {"id": "b", "text": "Imbalanced nutrition"}, {"id": "c", "text": "Risk for falls"}, {"id": "d", "text": "Deficient dietary knowledge"}]'::jsonb, '["c"]', 'Fall precautions are the number one priority with vertigo. Diet teaching and other needs are addressed once safety is ensured.'),
  ('vertigo', 37, 'A client tells the nurse, ''Even when I''m lying perfectly still, it feels like the room is spinning.'' Which term should the nurse use to document this symptom?', '[{"id": "a", "text": "Vertigo"}, {"id": "b", "text": "Tinnitus"}, {"id": "c", "text": "Ataxia"}, {"id": "d", "text": "Nystagmus"}]'::jsonb, '["a"]', 'Vertigo is the false sensation of spinning or motion when the body is actually still. Tinnitus is ringing, buzzing, or roaring in the ear, not a spinning sensation.'),
  ('vertigo', 38, 'The nurse assists with Rinne and Weber tests for a client with hearing loss. What is the purpose of these tests?', '[{"id": "a", "text": "To measure fluid pressure in the inner ear"}, {"id": "b", "text": "To record involuntary rapid eye movements"}, {"id": "c", "text": "To distinguish sensorineural from conductive loss"}, {"id": "d", "text": "To rule out a tumor or stroke in the brain"}]'::jsonb, '["c"]', 'Rinne and Weber tests use a tuning fork to distinguish sensorineural from conductive hearing loss. Recording eye movements is the role of ENG.'),
  ('vertigo', 39, 'A hospitalized client with vertigo asks to use the bathroom. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Allow the client to walk alone if feeling steady"}, {"id": "b", "text": "Assist the client while walking to the bathroom"}, {"id": "c", "text": "Lower the side rails so the client can get up alone"}, {"id": "d", "text": "Encourage the client to walk quickly to the bathroom"}]'::jsonb, '["b"]', 'Fall precautions for vertigo include assisting with ambulation and using side rails. Letting the client walk alone or quickly increases fall risk.'),
  ('vertigo', 40, 'The nurse has taught a client with Ménière''s disease about diuretic therapy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep my lab appointments to check my potassium.\""}, {"id": "b", "text": "\"This pill helps lower the fluid in my inner ear.\""}, {"id": "c", "text": "\"I can stop the water pill when my ears feel better.\""}, {"id": "d", "text": "\"I''ll take the water pill exactly as it is prescribed.\""}]'::jsonb, '["c"]', 'Teaching emphasizes compliance with diuretics, so stopping the medication when symptoms improve is incorrect. Monitoring potassium and understanding that the diuretic reduces inner ear fluid are correct.'),
  ('vertigo', 41, 'A client with Ménière''s disease reports a sensation of pressure deep in the affected ear during attacks. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is an expected associated symptom"}, {"id": "b", "text": "It indicates conductive hearing loss"}, {"id": "c", "text": "It means a labyrinthectomy is needed"}, {"id": "d", "text": "It is an adverse effect of meclizine"}]'::jsonb, '["a"]', 'Pressure or fullness in the affected ear is considered the fourth classic symptom of Ménière''s disease. The hearing loss of Ménière''s is sensorineural, not conductive.'),
  ('vertigo', 42, 'A client with Ménière''s disease calls the clinic and says an attack is starting at home. Which instruction should the nurse give first?', '[{"id": "a", "text": "\"Drive to the emergency department right away.\""}, {"id": "b", "text": "\"Walk around the house to shake off the dizziness.\""}, {"id": "c", "text": "\"Move your head side to side to reset your balance.\""}, {"id": "d", "text": "\"Lie down right away until the attack passes.\""}]'::jsonb, '["d"]', 'Clients should be instructed to lie down during attacks to prevent falls. Walking during an attack increases fall risk, the top safety concern with vertigo.'),
  ('vertigo', 43, 'A client asks the nurse what type of medication meclizine is. Which response is accurate?', '[{"id": "a", "text": "An antihistamine and antivertigo drug"}, {"id": "b", "text": "A benzodiazepine and sedative drug"}, {"id": "c", "text": "A diuretic that removes extra fluid"}, {"id": "d", "text": "An anti-inflammatory steroid drug"}]'::jsonb, '["a"]', 'Meclizine is classified as an antihistamine/antivertigo drug. Diazepam is the benzodiazepine/sedative, and hydrochlorothiazide is the diuretic.'),
  ('vertigo', 44, 'A client is diagnosed with Ménière''s disease. Which medication should the nurse anticipate as first-line treatment for the vertigo?', '[{"id": "a", "text": "Diazepam"}, {"id": "b", "text": "Hydrochlorothiazide"}, {"id": "c", "text": "Meclizine"}, {"id": "d", "text": "A corticosteroid"}]'::jsonb, '["c"]', 'Meclizine is the first-line drug for vertigo and reduces the spinning sensation. Hydrochlorothiazide is a diuretic that reduces endolymph fluid pressure rather than the first-line antivertigo drug.'),
  ('vertigo', 45, 'A client with Ménière''s disease reports that attacks have become more frequent over the past month. Which client statement suggests a lifestyle trigger for the increase?', '[{"id": "a", "text": "\"I''ve been under a lot of stress at work lately.\""}, {"id": "b", "text": "\"I''ve been drinking more water during the day.\""}, {"id": "c", "text": "\"I''ve been sticking closely to my low-salt diet.\""}, {"id": "d", "text": "\"I''ve been getting up from bed more slowly.\""}]'::jsonb, '["a"]', 'Stress and anxiety are lifestyle triggers that worsen Ménière''s symptoms. Following a low-sodium diet and changing positions slowly are recommended measures, not triggers.'),
  ('vertigo', 46, 'A client is vomiting repeatedly during a Ménière''s attack. Which prescribed medication should the nurse administer to control the vomiting?', '[{"id": "a", "text": "Ondansetron"}, {"id": "b", "text": "Hydrochlorothiazide"}, {"id": "c", "text": "A corticosteroid"}, {"id": "d", "text": "Diazepam"}]'::jsonb, '["a"]', 'Antiemetics such as ondansetron and promethazine control nausea and vomiting during attacks. Hydrochlorothiazide is a diuretic that reduces endolymph pressure and does not treat vomiting.'),
  ('vertigo', 47, 'A client with Ménière''s disease asks, ''Once my treatment is finished, will this go away for good?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, once the medication course ends it will not return.\""}, {"id": "b", "text": "\"Yes, most people have only one attack in their lifetime.\""}, {"id": "c", "text": "\"No, attacks tend to come and go, and there is no cure.\""}, {"id": "d", "text": "\"Yes, following a low-sodium diet will cure the disease.\""}]'::jsonb, '["c"]', 'Ménière''s disease is chronic and episodic, with attacks that come and go, and it currently has no cure. A low-sodium diet reduces endolymph retention but does not cure the disease.'),
  ('vertigo', 48, 'A client in an acute Ménière''s attack reports intense nausea. Which action should the nurse take?', '[{"id": "a", "text": "Offer a large meal to settle the stomach"}, {"id": "b", "text": "Keep an emesis basin at the bedside"}, {"id": "c", "text": "Encourage the client to sit in a bright area"}, {"id": "d", "text": "Hold antiemetics until the attack ends"}]'::jsonb, '["b"]', 'During acute attacks, the nurse keeps an emesis basin at the bedside and administers ordered antiemetics. Withholding ordered antiemetics would leave nausea and vomiting uncontrolled.'),
  ('vertigo', 49, 'The nurse is preparing a room for a client experiencing an acute Ménière''s attack. Which room environment is most appropriate?', '[{"id": "a", "text": "A brightly lit room to help orientation"}, {"id": "b", "text": "A room with the television on for distraction"}, {"id": "c", "text": "A room near the busy nurses'' station"}, {"id": "d", "text": "A quiet, darkened room"}]'::jsonb, '["d"]', 'During acute attacks, the client should be in a quiet, dark room. Bright lights and loud sounds during attacks are triggers that worsen symptoms.'),
  ('vertigo', 50, 'A client with acute vertigo receives diazepam. Which nursing action is the priority after administration?', '[{"id": "a", "text": "Monitor the serum potassium level"}, {"id": "b", "text": "Implement safety precautions"}, {"id": "c", "text": "Encourage a high-sodium snack"}, {"id": "d", "text": "Encourage independent ambulation"}]'::jsonb, '["b"]', 'Diazepam is a benzodiazepine and CNS depressant, so safety precautions are required. Potassium monitoring applies to hydrochlorothiazide, not diazepam.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _neuro_seed_map m USING (source_key)
 CROSS JOIN _neuro_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _neuro_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Neurology seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
